// The GP Link Admin roster entry (hello@mygplink.com.au). This is the general
// pool: a GP who is not yet placed at a practice belongs to admin, not to any
// individual RSO. Used both as the app-wide fallback and by the support router.
const GP_ADMIN_RSO_EMAIL = 'hello@mygplink.com.au';
const GP_ADMIN_RSO_USER_ID = (RSO_TEAM.find(function (r) { return r.email === GP_ADMIN_RSO_EMAIL; }) || {}).user_id || null;

// Default RSO when a GP's case has no assigned_va.
//
// Changed 2026-07-30 (owner decision) from Hazel to GP Link Admin: an unplaced
// GP is handled by the admin pool, and only picks up a named RSO once they are
// placed at a practice. Existing cases all carry an explicit assigned_va, so
// this only bites for a brand-new case before anyone is assigned, and for the
// scheduled-call matcher's last-resort pick.
const DEFAULT_RSO_USER_ID = GP_ADMIN_RSO_USER_ID;

// Normalize/merge the RSO roster: prefer DB rows from rso_team; fall back to the
// in-memory RSO_TEAM seed when the table is empty or unreachable (local dev).
// Pure (no DB) so it can be unit-tested; loadRsoTeam() does the fetch.
function mergeRsoRoster(dbRows, seedArray, opts) {
  var includeInactive = !!(opts && opts.includeInactive);
  var rows = Array.isArray(dbRows) ? dbRows : [];
  var source = rows.length ? rows : (Array.isArray(seedArray) ? seedArray : []);
  var fromDb = rows.length > 0;
  return source
    .map(function (r) {
      return {
        user_id: r.user_id || null,
        name: r.name || '',
        email: r.email || '',
        phone: r.phone || '',
        active: (r.active === undefined || r.active === null) ? true : !!r.active,
        on_leave: !!r.on_leave,
        calendly_event_url: r.calendly_event_url || ''
      };
    })
    .filter(function (r) {
      if (!r.user_id) return false;
      // Seed rows are all considered active; only DB rows carry an active flag to filter on.
      if (fromDb && !includeInactive && !r.active) return false;
      return true;
    });
}

// Async: read the editable rso_team table, falling back to the RSO_TEAM seed.
// supabaseDbRequest returns ok:false (503) when Supabase is not configured (local dev),
// in which case we transparently use the seed array.
async function loadRsoTeam(opts) {
  try {
    var res = await supabaseDbRequest('rso_team', 'select=user_id,name,email,phone,active,on_leave,calendly_event_url&order=name.asc', { method: 'GET' });
    if (!res || !res.ok) {
      // Defensive: if the on_leave column has not been migrated yet, retry without it
      // rather than silently falling back to the in-memory seed roster.
      res = await supabaseDbRequest('rso_team', 'select=user_id,name,email,phone,active,calendly_event_url&order=name.asc', { method: 'GET' });
    }
    var rows = (res && res.ok && Array.isArray(res.data)) ? res.data : [];
    return mergeRsoRoster(rows, RSO_TEAM, opts);
  } catch (e) {
    return mergeRsoRoster([], RSO_TEAM, opts);
  }
}

// ── RSO GP-assignment scoping (authorization) ──────────────────────────────────
// A regular admin (role 'admin'/'staff' = an RSO) may only ever SEE or ACT ON GPs
// assigned to them: registration_cases.assigned_rso || assigned_va === their
// rso_team.user_id. Super admins (CEO, role 'super_admin') are NEVER scoped.
// Everything is fail-closed: a non-super admin who cannot be resolved to a roster
// user_id (rsoUserId === null) sees an empty list and is 403'd on every GP detail.

// Match the admin's session email against the rso_team roster → their user_id.
async function resolveAdminRsoUserId(adminCtx) {
  const email = String((adminCtx && adminCtx.email) || '').trim().toLowerCase();
  if (!email) return null;
  const roster = await loadRsoTeam({ includeInactive: true });
  for (let i = 0; i < roster.length; i++) {
    const r = roster[i];
    if (r && r.email && String(r.email).trim().toLowerCase() === email) return r.user_id || null;
  }
  return null;
}

// True when a registration_cases row is assigned to the given RSO user_id.
function caseAssignedToRso(caseRow, rsoUserId) {
  if (!caseRow || !rsoUserId) return false;
  return (caseRow.assigned_rso || caseRow.assigned_va || null) === rsoUserId;
}

// The GP-visibility scope for a request:
//   { superAdmin: true,  rsoUserId: null }     → sees/acts on everything
//   { superAdmin: false, rsoUserId: '<uuid>' } → only cases assigned to rsoUserId
//   { superAdmin: false, rsoUserId: null }     → sees/acts on NOTHING (not on roster)
//
// "View RSO POV": a genuine super-admin may preview a specific RSO's scoped view
// by passing ?pov_rso=<email> (pass the request `url`). This is the ONLY place the
// override is honored and it is gated on the caller actually being a super-admin —
// a regular RSO who sends pov_rso is ignored and still only ever sees their own
// assigned GPs. The preview is faithful: an RSO not on the roster yields an empty
// scope, which is exactly what that RSO would truly see.
async function resolveAdminGpScope(adminCtx, url) {
  const superAdmin = isSuperAdminRole(adminCtx && adminCtx.role);
  if (superAdmin && url && url.searchParams) {
    const povEmail = String(url.searchParams.get('pov_rso') || '').trim().toLowerCase();
    if (povEmail) {
      const povUserId = await resolveAdminRsoUserId({ email: povEmail });
      return { superAdmin: false, rsoUserId: povUserId, povEmail };
    }
  }
  if (superAdmin) return { superAdmin: true, rsoUserId: null };
  return { superAdmin: false, rsoUserId: await resolveAdminRsoUserId(adminCtx) };
}

// Given a resolved scope and a case row, may the admin access it? Super admins: yes.
function gpScopeAllowsCase(scope, caseRow) {
  if (scope && scope.superAdmin) return true;
  return caseAssignedToRso(caseRow, scope && scope.rsoUserId);
}

// May this admin see a TASK? Case-scoping is the default (gpScopeAllowsCase), but a
// task routed to this RSO via registration_tasks.assignee — a candidate "document
// check" whose case is NOT assigned to anyone — is visible to that RSO even though
// the case isn't theirs. Super admins always see everything.
function taskVisibleToRso(scope, task, caseRow) {
  if (gpScopeAllowsCase(scope, caseRow)) return true;
  if (scope && scope.superAdmin) return true;
  // The task-level assignee branch only reveals candidate DOCUMENT CHECKS
  // (flagged_doc / doc_review) routed to this RSO on an otherwise-unassigned case.
  // Other task types must not surface via assignee alone — e.g. email_triage is
  // auto-assigned to the default RSO (Hazel) even on unassigned cases, so honoring
  // its assignee here would wrongly leak it into her "Document checks" list.
  var isDocCheckTask = !!(task && (task.task_type === 'flagged_doc' || task.task_type === 'doc_review'));
  return !!(isDocCheckTask && task.assignee && scope && scope.rsoUserId && task.assignee === scope.rsoUserId);
}

// Fetch a single registration_cases row's assignment fields by case id (for
// per-GP detail/mutation endpoints that receive a case_id). Returns null on miss.
async function fetchCaseAssignmentById(caseId) {
  const id = String(caseId || '').trim();
  if (!id) return null;
  const r = await supabaseDbRequest('registration_cases',
    'select=id,user_id,assigned_rso,assigned_va&id=eq.' + encodeURIComponent(id) + '&limit=1');
  return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
}

// Same, resolved by the GP's user_id (for endpoints that receive a user_id).
async function fetchCaseAssignmentByUserId(userId) {
  const uid = String(userId || '').trim();
  if (!uid) return null;
  const r = await supabaseDbRequest('registration_cases',
    'select=id,user_id,assigned_rso,assigned_va&user_id=eq.' + encodeURIComponent(uid) + '&limit=1');
  return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
}

// Same, resolved by a registration_tasks.id (for per-task detail/mutation endpoints).
async function fetchCaseAssignmentByTaskId(taskId) {
  const tid = String(taskId || '').trim();
  if (!tid) return null;
  const tr = await supabaseDbRequest('registration_tasks',
    'select=case_id&id=eq.' + encodeURIComponent(tid) + '&limit=1');
  const caseId = (tr.ok && Array.isArray(tr.data) && tr.data[0]) ? tr.data[0].case_id : null;
  return caseId ? fetchCaseAssignmentById(caseId) : null;
}

// Guard for a per-GP detail/mutation endpoint: resolves the caller's scope and the
// target case, and sends a 403 (returning false) when a non-super admin tries to
// reach a GP not assigned to them. `caseRow` needs only assigned_rso/assigned_va.
// Returns true when access is allowed (caller proceeds).
async function ensureAdminCaseAccess(adminCtx, caseRow, res) {
  const scope = await resolveAdminGpScope(adminCtx);
  if (gpScopeAllowsCase(scope, caseRow)) return true;
  sendJson(res, 403, { ok: false, message: 'This GP is not assigned to you.' });
  return false;
}

// Task-aware access guard. Like ensureAdminCaseAccess, but also allows the caller
// when they are the TASK's assignee — i.e. an un-placed-candidate document check
// routed to them (whose case is unassigned, so pure case-scoping would 403). Used
// by per-task action endpoints (e.g. document preview) so the routed RSO can act on
// the check they were shown. `caseRow` needs only assigned_rso/assigned_va.
async function ensureAdminTaskAccess(adminCtx, taskId, res) {
  const scope = await resolveAdminGpScope(adminCtx);
  const tid = String(taskId || '').trim();
  const tr = tid ? await supabaseDbRequest('registration_tasks',
    'select=case_id,assignee&id=eq.' + encodeURIComponent(tid) + '&limit=1') : { ok: false };
  const task = (tr.ok && Array.isArray(tr.data) && tr.data[0]) ? tr.data[0] : null;
  const caseRow = task && task.case_id ? await fetchCaseAssignmentById(task.case_id) : null;
  if (task && taskVisibleToRso(scope, task, caseRow)) return true;
  sendJson(res, 403, { ok: false, message: 'This GP is not assigned to you.' });
  return false;
}

// The set of GP user_ids whose case is assigned to this RSO — used to scope the
// dashboard candidate list (built from user records, not case rows).
async function fetchAssignedCaseUserIds(rsoUserId) {
  const set = new Set();
  if (!rsoUserId) return set;
  const r = await supabaseDbRequest('registration_cases',
    'select=user_id&or=(assigned_rso.eq.' + encodeURIComponent(rsoUserId) + ',assigned_va.eq.' + encodeURIComponent(rsoUserId) + ')');
  if (r.ok && Array.isArray(r.data)) r.data.forEach(function (row) { if (row.user_id) set.add(row.user_id); });
  return set;
}

// Shallow-copy the dashboard aggregate with its per-GP arrays (candidates +
// verificationQueue) filtered to the given user_id set, so a non-super admin's
// dashboard only exposes their assigned GPs. Super admins never call this.
function scopeDashboardToUserIds(dashboard, userIdSet) {
  if (!dashboard || typeof dashboard !== 'object') return dashboard;
  const keep = function (item) { return !!item && userIdSet.has(item.userId); };
  const out = Object.assign({}, dashboard);
  if (Array.isArray(dashboard.candidates)) out.candidates = dashboard.candidates.filter(keep);
  if (Array.isArray(dashboard.verificationQueue)) out.verificationQueue = dashboard.verificationQueue.filter(keep);
  return out;
}

// Resolve the RSO (registration_tasks.assignee UUID) for a GP's case: prefer the
// case's assigned_va, else default to Hazel. knownAssignedVa: pass the loaded value
// if available; undefined triggers a lookup, null/value is used as-is.
async function resolveCaseRsoAssignee(caseId, knownAssignedVa) {
  if (!caseId) return null;
  let assignedVa = knownAssignedVa;
  if (assignedVa === undefined) {
    const r = await supabaseDbRequest('registration_cases', 'id=eq.' + encodeURIComponent(caseId) + '&select=assigned_va', { method: 'GET' });
    assignedVa = (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0].assigned_va : null;
  }
  return assignedVa || DEFAULT_RSO_USER_ID;
}

// ── Who owns this GP's support conversation? (2026-07-30, owner decision) ───
//
// Not placed at a practice  → the GP Link Admin pool (hello@mygplink.com.au).
// Placed at a practice      → the RSO assigned to their case.
//
// "Placed" means a row in `placements` — the formal record written when a
// placement is recorded — NOT merely a practice_name on the case. That was the
// owner's explicit choice: a practice name gets set while a placement is still
// being negotiated, so it would hand a GP over too early.
//
// This deliberately does NOT rewrite registration_cases.assigned_va. It decides
// who the support conversation and its task belong to; case assignment stays a
// human decision. That is what keeps "don't touch GPs already placed and
// assigned" true — an RSO already looking after a placed GP is never displaced,
// and the rule only ever takes effect for placements recorded from now on.
const PLACEMENT_DEAD_STATUSES = new Set(['cancelled', 'canceled', 'withdrawn', 'ended', 'terminated', 'failed']);

async function resolveSupportRsoForUser(userId, knownCase) {
  const out = { placed: false, rsoUserId: GP_ADMIN_RSO_USER_ID, caseRow: knownCase || null };
  if (!userId || !isSupabaseDbConfigured()) return out;
  try {
    if (!out.caseRow) {
      const c = await supabaseDbRequest('registration_cases',
        'select=id,user_id,stage,substage,assigned_va,assigned_rso&user_id=eq.'
        + encodeURIComponent(userId) + '&order=created_at.desc&limit=1');
      out.caseRow = (c.ok && Array.isArray(c.data) && c.data[0]) ? c.data[0] : null;
    }
    // `placements` is additive DDL — a non-ok response means the table is not
    // there yet, which reads as "not placed" rather than throwing.
    const p = await supabaseDbRequest('placements',
      'select=id,status&user_id=eq.' + encodeURIComponent(userId) + '&limit=20');
    const rows = (p.ok && Array.isArray(p.data)) ? p.data : [];
    // Status filtered in JS, not in the query: the table is empty today so the
    // vocabulary is unverified, and an unknown/null status must still count as
    // placed rather than being silently dropped by a server-side NOT IN.
    out.placed = rows.some(function (r) {
      return !PLACEMENT_DEAD_STATUSES.has(String((r && r.status) || '').trim().toLowerCase());
    });
    if (out.placed && out.caseRow) {
      out.rsoUserId = out.caseRow.assigned_va || out.caseRow.assigned_rso || GP_ADMIN_RSO_USER_ID;
    }
  } catch (err) {
    // Fail to the admin pool: an unrouted GP reaching admin is recoverable,
    // a thrown error that blocks them from messaging at all is not.
    console.error('[support-rso] resolve failed:', err && err.message);
  }
  return out;
}
let _domainApiAccessTokenCache = new Map();

// ── Google Drive integration ──
const GOOGLE_SERVICE_ACCOUNT_EMAIL = String(process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL || '').trim();
function normalizeServiceAccountKey(raw) {
  if (!raw) return '';
  var s = String(raw);
  // Strip surrounding single/double quotes that are sometimes pasted by accident
  s = s.replace(/^\s*["']/, '').replace(/["']\s*$/, '');
  // Convert literal \n escape sequences to real newlines
  s = s.replace(/\\n/g, '\n');
  // Strip carriage returns (Windows line endings break OpenSSL 3 PEM decoder)
  s = s.replace(/\r/g, '');
  // Strip zero-width / BOM characters that can sneak in from copy-paste
  s = s.replace(/[\u200B-\u200D\uFEFF]/g, '');
  return s.trim();
}
const GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY = normalizeServiceAccountKey(process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY);
const GOOGLE_DRIVE_ROOT_FOLDER_ID = String(process.env.GOOGLE_DRIVE_ROOT_FOLDER_ID || '').trim();
const GOOGLE_DRIVE_IMPERSONATE_EMAIL = String(process.env.GOOGLE_DRIVE_IMPERSONATE_EMAIL || '').trim();
const GOOGLE_DRIVE_BACKUP_FOLDER_ID_1 = String(process.env.GOOGLE_DRIVE_BACKUP_FOLDER_ID_1 || '').trim();
const GOOGLE_DRIVE_BACKUP_FOLDER_ID_2 = String(process.env.GOOGLE_DRIVE_BACKUP_FOLDER_ID_2 || '').trim();

function isGoogleDriveConfigured() {
  return !!(GOOGLE_SERVICE_ACCOUNT_EMAIL && GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY && GOOGLE_DRIVE_ROOT_FOLDER_ID);
}

let _googleDriveClient = null;
async function getGoogleDriveClient() {
  if (_googleDriveClient) return _googleDriveClient;
  if (!isGoogleDriveConfigured()) return null;
  const { google } = require('googleapis');
  const jwtOpts = {
    email: GOOGLE_SERVICE_ACCOUNT_EMAIL,
    key: GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY,
    scopes: ['https://www.googleapis.com/auth/drive']
  };
  if (GOOGLE_DRIVE_IMPERSONATE_EMAIL) jwtOpts.subject = GOOGLE_DRIVE_IMPERSONATE_EMAIL;
  const auth = new google.auth.JWT(jwtOpts);
  await auth.authorize();
  _googleDriveClient = google.drive({ version: 'v3', auth });
  return _googleDriveClient;
}

async function createGoogleDriveFolder(folderName, parentFolderId) {
  const drive = await getGoogleDriveClient();
  if (!drive) return null;
  try {
    const res = await drive.files.create({
      requestBody: {
        name: folderName,
        mimeType: 'application/vnd.google-apps.folder',
        parents: [parentFolderId || GOOGLE_DRIVE_ROOT_FOLDER_ID]
      },
      fields: 'id,name,webViewLink'
    });
    // Make folder accessible by anyone with the link
    try {
      await drive.permissions.create({
        fileId: res.data.id,
        requestBody: { role: 'reader', type: 'anyone' }
      });
    } catch (e) { console.error('[GoogleDrive] folder share error:', e.message); }
    return res.data;
  } catch (err) {
    console.error('[GoogleDrive] createFolder error:', err.message, err.code, err.status, JSON.stringify(err.errors || []));
    return null;
  }
}

async function uploadToGoogleDrive(folderId, fileName, buffer, mimeType) {
  const drive = await getGoogleDriveClient();
  if (!drive) throw new Error('Google Drive client not available');
  try {
    const res = await drive.files.create({
      requestBody: {
        name: fileName,
        parents: [folderId]
      },
      media: {
        mimeType: mimeType || 'application/pdf',
        body: require('stream').Readable.from(buffer)
      },
      fields: 'id,name,webViewLink'
    });
    // Make file viewable by anyone with the link so admin preview works
    try {
      await drive.permissions.create({
        fileId: res.data.id,
        requestBody: { role: 'reader', type: 'anyone' }
      });
    } catch (e) { console.error('[GoogleDrive] share error:', e.message); }
    return res.data;
  } catch (err) {
    console.error('[GoogleDrive] upload error:', err.message);
    throw err;
  }
}

async function deleteGoogleDriveFile(fileId) {
  if (!fileId) return false;
  const drive = await getGoogleDriveClient();
  if (!drive) return false;
  try {
    await drive.files.delete({ fileId: fileId });
    return true;
  } catch (err) {
    if (err.code === 404) return true; // already deleted
    console.error('[GoogleDrive] delete error:', err.message);
    return false;
  }
}

// Create a folder WITHOUT public 'anyone' access; share read with the owner so they can browse.
async function createPrivateDriveFolder(folderName, parentFolderId) {
  const drive = await getGoogleDriveClient();
  if (!drive) return null;
  const folder = await drive.files.create({
    requestBody: { name: folderName, mimeType: 'application/vnd.google-apps.folder', parents: [parentFolderId] },
    fields: 'id,name,webViewLink', supportsAllDrives: true,
  });
  try {
    await drive.permissions.create({
      fileId: folder.data.id, sendNotificationEmail: false, supportsAllDrives: true,
      requestBody: { type: 'user', role: 'reader', emailAddress: GP_OWNER_EMAIL },
    });
  } catch (e) { console.error('[Drive] owner share (folder) failed:', e.message); }
  return folder.data;
}

// Ensure Users/Candidates/Archived exist under the root; cache their ids.
async function ensureLifecycleFolders() {
  if (!isGoogleDriveConfigured()) return null;
  if (_lifecycleFolderCache) return _lifecycleFolderCache;
  const drive = await getGoogleDriveClient();
  if (!drive) return null;
  const out = {};
  for (const key of Object.keys(LIFECYCLE_FOLDER_NAMES)) {
    const name = LIFECYCLE_FOLDER_NAMES[key];
    const q = "name='" + name + "' and mimeType='application/vnd.google-apps.folder' and '"
      + GOOGLE_DRIVE_ROOT_FOLDER_ID + "' in parents and trashed=false";
    const res = await drive.files.list({ q, fields: 'files(id,name)', pageSize: 1, supportsAllDrives: true, includeItemsFromAllDrives: true });
    if (res.data.files && res.data.files[0]) { out[key] = res.data.files[0].id; continue; }
    const created = await createPrivateDriveFolder(name, GOOGLE_DRIVE_ROOT_FOLDER_ID);
    out[key] = created ? created.id : null;
  }
  _lifecycleFolderCache = out;
  return out;
}

// Move a folder/file under a new parent (removing all current parents).
async function moveDriveFolder(folderId, toParentId) {
  if (!folderId || !toParentId) return false;
  const drive = await getGoogleDriveClient();
  if (!drive) return false;
  try {
    const cur = await drive.files.get({ fileId: folderId, fields: 'parents', supportsAllDrives: true });
    const prev = (cur.data.parents || []).join(',');
    await drive.files.update({ fileId: folderId, addParents: toParentId, removeParents: prev,
      fields: 'id,parents', supportsAllDrives: true });
    return true;
  } catch (e) { console.error('[Drive] move folder failed:', e.message); return false; }
}

// Apply per-document sharing. Removes any 'anyone' permission first.
async function applyDriveDocPermissions(fileId, mode) {
  const drive = await getGoogleDriveClient();
  if (!drive || !fileId) return;
  try {
    const perms = await drive.permissions.list({ fileId, fields: 'permissions(id,type)', supportsAllDrives: true });
    for (const p of (perms.data.permissions || [])) {
      if (p.type === 'anyone') { try { await drive.permissions.delete({ fileId, permissionId: p.id, supportsAllDrives: true }); } catch (e) {} }
    }
  } catch (e) { console.error('[Drive] perm list failed:', e.message); }
  try {
    if (mode === 'id_private') {
      await drive.permissions.create({ fileId, sendNotificationEmail: false, supportsAllDrives: true,
        requestBody: { type: 'user', role: 'reader', emailAddress: GP_OWNER_EMAIL } });
    } else {
      // Domain sharing may be unavailable for a service account on My Drive — best-effort, then ALWAYS
      // share with the named @mygplink.com.au team accounts so access holds regardless.
      try {
        await drive.permissions.create({ fileId, sendNotificationEmail: false, supportsAllDrives: true,
          requestBody: { type: 'domain', role: 'reader', domain: GP_TEAM_DOMAIN } });
      } catch (domainErr) {}
      try {
        const rso = await supabaseDbRequest('rso_team', 'select=email');
        const emails = (rso.ok && Array.isArray(rso.data) ? rso.data : [])
          .map(r => r && r.email).filter(e => e && /@mygplink\.com\.au$/i.test(e));
        for (const em of emails) {
          try { await drive.permissions.create({ fileId, sendNotificationEmail: false, supportsAllDrives: true,
            requestBody: { type: 'user', role: 'reader', emailAddress: em } }); } catch (e) {}
        }
      } catch (e) { console.error('[Drive] team email share failed:', e.message); }
    }
  } catch (e) { console.error('[Drive] apply perms failed:', e.message); }
}

// Upload a file privately (no 'anyone'); then apply the document permission mode.
async function uploadPrivateToGoogleDrive(folderId, fileName, buffer, mimeType, mode) {
  const drive = await getGoogleDriveClient();
  if (!drive) return null;
  const { Readable } = require('stream');
  const media = { mimeType: mimeType || 'application/octet-stream', body: Readable.from(buffer) };
  const file = await drive.files.create({
    requestBody: { name: fileName, parents: [folderId] }, media,
    fields: 'id,name,webViewLink', supportsAllDrives: true,
  });
  await applyDriveDocPermissions(file.data.id, mode);
  return file.data;
}

async function ensureGPDriveFolder(caseId, gpFirstName, gpLastName) {
  if (!isGoogleDriveConfigured()) return null;
  const caseRes = await supabaseDbRequest('registration_cases', 'select=google_drive_folder_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
  if (caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] && caseRes.data[0].google_drive_folder_id) {
    return caseRes.data[0].google_drive_folder_id;
  }
  const folderName = 'Dr ' + [(gpFirstName || ''), (gpLastName || '')].join(' ').trim();
  const _lifecycle = await ensureLifecycleFolders();
  const _parentId = (_lifecycle && _lifecycle.users) ? _lifecycle.users : GOOGLE_DRIVE_ROOT_FOLDER_ID;
  const folder = await createPrivateDriveFolder(folderName, _parentId);
  if (folder && folder.id) {
    await supabaseDbRequest('registration_cases', 'id=eq.' + encodeURIComponent(caseId), {
      method: 'PATCH',
      body: { google_drive_folder_id: folder.id }
    });
    return folder.id;
  }
  return null;
}

async function reconcileGpDrive(caseId) {
  try {
    if (!isGoogleDriveConfigured() || !caseId) return;
    const caseRes = await supabaseDbRequest('registration_cases',
      'select=id,user_id,google_drive_folder_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
    const rc = caseRes.ok && caseRes.data && caseRes.data[0] ? caseRes.data[0] : null;
    if (!rc) return;
    const userId = rc.user_id;

    // account + placement status
    const stRes = await supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const state = (stRes.ok && stRes.data && stRes.data[0] && typeof stRes.data[0].state === 'object') ? stRes.data[0].state : {};
    let career = state.gp_career_state; if (typeof career === 'string') { try { career = JSON.parse(career); } catch (e) { career = {}; } }
    career = career || {};
    const placementSecured = career.career_secured === true || career.secured === true ||
      (Array.isArray(career.applications) && career.applications.some(a => a && a.isPlacementSecured === true));

    // profile (for folder name + ID + authoritative account_status — archive writes it to user_profiles)
    const profRes = await supabaseDbRequest('user_profiles',
      'select=first_name,last_name,id_copy_name,id_copy_data_url,account_status&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const prof = (profRes.ok && profRes.data && profRes.data[0]) ? profRes.data[0] : {};
    const accountStatus = String(prof.account_status || state.account_status || '').toLowerCase();
    const targetStage = stageForCase({ accountStatus, placementSecured });

    // ensure personal folder exists (creates under Users if new)
    let folderId = rc.google_drive_folder_id;
    if (!folderId) { folderId = await ensureGPDriveFolder(caseId, prof.first_name || '', prof.last_name || ''); }
    if (!folderId) return;

    const drive = await getGoogleDriveClient();
    if (!drive) return;

    // move to correct lifecycle parent if the folder is not already under it (location derived from Drive — no DB column)
    const lifecycle = await ensureLifecycleFolders();
    if (lifecycle && lifecycle[targetStage]) {
      try {
        const meta = await drive.files.get({ fileId: folderId, fields: 'parents', supportsAllDrives: true });
        const curParent = meta && meta.data && Array.isArray(meta.data.parents) ? meta.data.parents[0] : null;
        if (curParent !== lifecycle[targetStage]) await moveDriveFolder(folderId, lifecycle[targetStage]);
      } catch (e) { console.error('[reconcileGpDrive] parent check failed:', e.message); }
    }

    // Mirror accepted registration documents into the personal folder with team-only sharing.
    // Prepared GP-Link docs (gplink_pack) are GP-facing via existing links — leave their sharing untouched.
    const PREPARED_DOC_KEYS = new Set(['sppa_00', 'section_g', 'position_description', 'offer_contract', 'supervisor_cv']);
    const docsRes = await supabaseDbRequest('user_documents',
      'select=id,document_key,file_name,status,storage_bucket,storage_path,file_url,mime_type,google_drive_file_id&user_id=eq.' + encodeURIComponent(userId));
    const docs = (docsRes.ok && Array.isArray(docsRes.data)) ? docsRes.data : [];
    for (const d of docs) {
      if (!isAcceptedStatus(d.status)) continue;
      if (PREPARED_DOC_KEYS.has(d.document_key)) continue;
      try {
        if (d.google_drive_file_id) {
          // already in Drive (the normal approval path uploads as 'anyone') — re-secure to team-only
          await applyDriveDocPermissions(d.google_drive_file_id, 'team_domain');
          continue;
        }
        const path = d.storage_path || d.file_url; if (!path) continue;
        const dl = await supabaseStorageDownloadObject(d.storage_bucket || SUPABASE_DOCUMENT_BUCKET, path);
        if (!dl || !dl.buffer) continue;
        const up = await uploadPrivateToGoogleDrive(folderId, d.file_name || (d.document_key + '.pdf'), dl.buffer, d.mime_type || dl.mimeType || 'application/pdf', 'team_domain');
        if (up && up.id) await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(d.id), { method: 'PATCH', body: { google_drive_file_id: up.id } });
      } catch (e) { console.error('[reconcileGpDrive] doc mirror failed:', d.document_key, e.message); }
    }

    // mirror ID (hello@-only), once — into the per-document "ID" subfolder. Idempotent: check
    // BOTH the candidate root (legacy location, before organise) AND the ID subfolder, so once
    // organizeCaseDrive moves the ID into its folder we never re-upload a duplicate. (The previous
    // root-only check duplicated the ID on every view once the sweep moved it out of root.)
    if (prof.id_copy_data_url) {
      try {
        const idFolderId = await ensureDocTypeSubfolder(folderId, driveDocFolders.ID_FOLDER, null);
        const rootList = await drive.files.list({ q: "'" + folderId + "' in parents and trashed=false", fields: 'files(id,name)', pageSize: 200, supportsAllDrives: true, includeItemsFromAllDrives: true });
        const idFolderList = idFolderId ? await drive.files.list({ q: "'" + idFolderId + "' in parents and trashed=false", fields: 'files(id,name)', pageSize: 50, supportsAllDrives: true, includeItemsFromAllDrives: true }) : { data: { files: [] } };
        const allIdCandidates = (rootList.data.files || []).concat(idFolderList.data.files || []);
        const hasId = allIdCandidates.some(f => /^ID — /.test(f.name || ''));
        if (!hasId) {
          const comma = prof.id_copy_data_url.indexOf(',');
          const head = prof.id_copy_data_url.substring(0, comma);
          const mime = (head.match(/data:([^;]+)/) || [])[1] || 'application/octet-stream';
          const buf = Buffer.from(prof.id_copy_data_url.substring(comma + 1), 'base64');
          const ext = (mime.split('/')[1] || 'bin').replace('jpeg', 'jpg');
          // Upload straight into the ID subfolder when available (else root; the sweep relocates it).
          await uploadPrivateToGoogleDrive(idFolderId || folderId, 'ID — ' + (prof.id_copy_name || ('identity.' + ext)), buf, mime, 'id_private');
        }
      } catch (e) { console.error('[reconcileGpDrive] ID mirror failed:', e.message); }
    }

    // Organise all files into per-document subfolders (cheap safety net — idempotent).
    try { await organizeCaseDrive(caseId); } catch (e) { console.error('[reconcileGpDrive] organize failed:', e.message); }
  } catch (err) { console.error('[reconcileGpDrive] error:', err.message); }
}

// ── Drive per-document subfolder helpers ──────────────────────────────────────

// Find-or-create a subfolder named `folderName` under `candidateFolderId`.
// Uses a Map cache (pass a new Map() per request) to avoid redundant lookups.
// Folders are created via createPrivateDriveFolder — shared owner-only (GP_OWNER_EMAIL),
// matching the candidate folder itself. Individual files keep their own sharing on move
// (team-shared docs stay team-visible; the ID file stays id_private), so this is correct for
// the ID folder too without a special case.
async function ensureDocTypeSubfolder(candidateFolderId, folderName, cache) {
  if (cache && cache.has(folderName)) return cache.get(folderName);
  var drive = await getGoogleDriveClient();
  if (!drive) return null;
  try {
    var q = "'" + candidateFolderId + "' in parents" +
      " and name = '" + folderName.replace(/'/g, "\\'") + "'" +
      " and mimeType = 'application/vnd.google-apps.folder'" +
      " and trashed = false";
    var listRes = await drive.files.list({ q: q, fields: 'files(id)', pageSize: 1, supportsAllDrives: true, includeItemsFromAllDrives: true });
    var existing = listRes.data.files && listRes.data.files[0];
    var folderId = existing ? existing.id : null;
    if (!folderId) {
      var created = await createPrivateDriveFolder(folderName, candidateFolderId);
      folderId = created ? created.id : null;
    }
    if (cache && folderId) cache.set(folderName, folderId);
    return folderId;
  } catch (e) {
    console.error('[ensureDocTypeSubfolder] failed for "' + folderName + '":', e.message);
    return null;
  }
}

// Move driveFileId into targetFolderId. Idempotent: if already there, return false (no-op).
// Returns true if the file was actually moved, false otherwise.
async function placeDriveFileInFolder(drive, driveFileId, targetFolderId) {
  try {
    var meta = await drive.files.get({ fileId: driveFileId, fields: 'parents', supportsAllDrives: true });
    var parents = (meta.data && Array.isArray(meta.data.parents)) ? meta.data.parents : [];
    if (parents.indexOf(targetFolderId) !== -1) return false; // already in target
    await drive.files.update({
      fileId: driveFileId,
      addParents: targetFolderId,
      removeParents: parents.join(','),
      supportsAllDrives: true,
      fields: 'id,parents'
    });
    return true;
  } catch (e) {
    console.error('[placeDriveFileInFolder] failed for file', driveFileId, '→', targetFolderId + ':', e.message);
    return false;
  }
}

// Move one Drive file into its document-type subfolder under the case's candidate folder.
// Best-effort: never throws into the caller. Returns true if the move occurred.
async function fileDocOnDrive(caseId, docKey, driveFileId) {
  try {
    if (!isGoogleDriveConfigured() || !caseId || !driveFileId) return false;
    var candidateFolderId = await ensureGPDriveFolder(caseId, null, null);
    if (!candidateFolderId) return false;
    var folderName = driveDocFolders.folderNameForDoc(docKey);
    var subFolderId = await ensureDocTypeSubfolder(candidateFolderId, folderName, null);
    if (!subFolderId) return false;
    var drive = await getGoogleDriveClient();
    if (!drive) return false;
    return await placeDriveFileInFolder(drive, driveFileId, subFolderId);
  } catch (e) {
    console.error('[fileDocOnDrive] failed for case', caseId, 'docKey', docKey + ':', e.message);
    return false;
  }
}

// Build a case's Drive-file → docKey maps from the DB. idToDocKey/docKeyToId from the UNION of
// user_documents + practice_pack_child tasks + task_documents + practice_doc_ops; `expected` is the
// set of GP-Link doc keys the case actually has (a practice_doc_ops/task row), used to corroborate
// FILENAME matches so an unrelated id-less file is never promoted into a GP-Link doc folder/card.
async function buildCaseDriveIdMap(caseId, userId) {
  var idToDocKey = {}, docKeyToId = {}, expected = new Set();
  function add(id, key) { if (id && key) { idToDocKey[id] = key; if (!docKeyToId[key]) docKeyToId[key] = id; } }
  try {
    if (userId) {
      var ud = await supabaseDbRequest('user_documents', 'select=document_key,google_drive_file_id&user_id=eq.' + encodeURIComponent(userId) + '&google_drive_file_id=neq.');
      (ud.ok && Array.isArray(ud.data) ? ud.data : []).forEach(function (d) { add(d.google_drive_file_id, d.document_key); });
    }
    var t = await supabaseDbRequest('registration_tasks', 'select=id,related_document_key,google_drive_file_id&case_id=eq.' + encodeURIComponent(caseId) + '&task_type=eq.practice_pack_child');
    var taskIdToDocKey = {};
    (t.ok && Array.isArray(t.data) ? t.data : []).forEach(function (x) {
      if (x.related_document_key) { expected.add(x.related_document_key); if (x.id) taskIdToDocKey[x.id] = x.related_document_key; }
      add(x.google_drive_file_id, x.related_document_key);
    });
    var td = await supabaseDbRequest('task_documents', 'select=google_drive_file_id,task_id&case_id=eq.' + encodeURIComponent(caseId) + '&is_current=eq.true&google_drive_file_id=neq.');
    (td.ok && Array.isArray(td.data) ? td.data : []).forEach(function (x) { if (taskIdToDocKey[x.task_id]) add(x.google_drive_file_id, taskIdToDocKey[x.task_id]); });
    var ops = await supabaseDbRequest('practice_doc_ops', 'select=document_key,google_drive_file_id&case_id=eq.' + encodeURIComponent(caseId));
    (ops.ok && Array.isArray(ops.data) ? ops.data : []).forEach(function (o) { if (o.document_key) { expected.add(o.document_key); add(o.google_drive_file_id, o.document_key); } });
  } catch (e) { console.error('[buildCaseDriveIdMap] error:', e.message); }
  return { idToDocKey: idToDocKey, docKeyToId: docKeyToId, expected: expected };
}

// Resolve a Drive file → docKey the SAME way for filing (organizeCaseDrive) and display
// (gp-documents) so they can never disagree: stored id first, then the sensitive "ID — …" name,
// then the filename heuristic. requireCorroboration gates the filename branch so only docs the
// case actually expects (practice_doc_ops/task row) are filed/bound by name — never a stray file.
function resolveDriveFileDocKey(file, idMap, opts) {
  opts = opts || {};
  if (file && file.mimeType === 'application/vnd.google-apps.folder') return null; // never resolve a folder
  if (idMap && idMap.idToDocKey && file && file.id && idMap.idToDocKey[file.id]) return idMap.idToDocKey[file.id];
  var name = (file && file.name) || '';
  if (/^ID — /.test(name)) return 'id_document';
  var fk = driveDocFolders.docKeyForFilename(name);
  if (!fk) return null;
  if (opts.requireCorroboration && idMap && idMap.expected && !idMap.expected.has(fk)) return null;
  return fk;
}
// True when the file's docKey came from a stored id / the ID-name rule (NOT a filename guess).
function isStrongDriveDocMatch(file, idMap) {
  if (idMap && idMap.idToDocKey && file && file.id && idMap.idToDocKey[file.id]) return true;
  return /^ID — /.test((file && file.name) || '');
}

// Sweep one case's Drive folder and organise files into per-document subfolders. Idempotent and
// column-free: it re-evaluates files at the candidate ROOT and inside the "Other Files" folder (the
// recovery source — a real doc previously dumped there is moved back into its real folder) and
// leaves files already in their correct per-document folder untouched. Truly-unmatched files → Other
// Files. Loop-free: resolveDriveFileDocKey depends only on the file's id/name (not its current
// folder), so the target is sweep-invariant and a move fires only when current folder != target.
async function organizeCaseDrive(caseId) {
  if (!isGoogleDriveConfigured() || !caseId) return { moved: 0, skipped: 0 };
  var moved = 0, skipped = 0;
  var FOLDER_MIME = 'application/vnd.google-apps.folder';
  try {
    var candidateFolderId = await ensureGPDriveFolder(caseId, null, null);
    if (!candidateFolderId) return { moved: 0, skipped: 0 };
    var drive = await getGoogleDriveClient();
    if (!drive) return { moved: 0, skipped: 0 };

    // Root children: seed the folder cache from existing subfolders; collect root files as candidates.
    var rootRes = await drive.files.list({ q: "'" + candidateFolderId + "' in parents and trashed = false", fields: 'files(id,name,mimeType)', pageSize: 200, supportsAllDrives: true, includeItemsFromAllDrives: true });
    var rootChildren = rootRes.data.files || [];
    var folderCache = new Map(); // folderName -> id
    var candidates = [];         // { id, name, currentFolderName, currentFolderId }
    var otherFolderId = null;
    rootChildren.forEach(function (f) {
      if (f.mimeType === FOLDER_MIME) {
        folderCache.set(f.name, f.id);
        if (f.name === driveDocFolders.OTHER_FILES_FOLDER) otherFolderId = f.id;
      } else {
        candidates.push({ id: f.id, name: f.name, currentFolderName: '', currentFolderId: candidateFolderId });
      }
    });

    // Recovery source: the "Other Files" subfolder is where the earlier (id-only) sweep dumped real
    // docs that had no stored Drive id. Re-evaluate its files so any that NOW resolve (by id or a
    // corroborated filename) get moved back into their proper folder.
    if (otherFolderId) {
      try {
        var ofRes = await drive.files.list({ q: "'" + otherFolderId + "' in parents and trashed = false", fields: 'files(id,name,mimeType)', pageSize: 200, supportsAllDrives: true, includeItemsFromAllDrives: true });
        (ofRes.data.files || []).forEach(function (f) {
          if (f.mimeType !== FOLDER_MIME) candidates.push({ id: f.id, name: f.name, currentFolderName: driveDocFolders.OTHER_FILES_FOLDER, currentFolderId: otherFolderId });
        });
      } catch (ofe) { console.error('[organizeCaseDrive] Other Files list error:', ofe.message); }
    }

    var caseRes = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
    var userId = caseRes.ok && caseRes.data && caseRes.data[0] ? caseRes.data[0].user_id : null;
    var idMap = await buildCaseDriveIdMap(caseId, userId);

    // Resolve every candidate up-front. A file matched ONLY by filename (no stored id / not an ID
    // file) is a WEAK match — count weak matches per docKey so we never physically file an AMBIGUOUS
    // one into a doc folder (two id-less files claiming the same key → we can't tell which is real,
    // so leave both unmatched/visible in Other Files rather than guess + misplace a decoy).
    var resolvedCandidates = candidates.map(function (cf) {
      var dk = resolveDriveFileDocKey(cf, idMap, { requireCorroboration: true });
      return { cf: cf, docKey: dk, strong: isStrongDriveDocMatch(cf, idMap) };
    });
    var weakKeyCount = {};
    resolvedCandidates.forEach(function (r) { if (r.docKey && !r.strong) weakKeyCount[r.docKey] = (weakKeyCount[r.docKey] || 0) + 1; });

    for (var ci = 0; ci < resolvedCandidates.length; ci++) {
      var cf = resolvedCandidates[ci].cf;
      var docKey = resolvedCandidates[ci].docKey;
      var strong = resolvedCandidates[ci].strong;
      try {
        if (docKey && !strong && weakKeyCount[docKey] > 1) docKey = null; // ambiguous filename match → don't file by name
        var targetName = docKey ? driveDocFolders.folderNameForDoc(docKey) : driveDocFolders.OTHER_FILES_FOLDER;
        if (cf.currentFolderName === targetName) { skipped++; continue; } // already in the right folder
        var targetId = await ensureDocTypeSubfolder(candidateFolderId, targetName, folderCache);
        if (!targetId || targetId === cf.currentFolderId) { skipped++; continue; }
        var didMove = await placeDriveFileInFolder(drive, cf.id, targetId);
        if (didMove) moved++; else skipped++;
      } catch (fe) { console.error('[organizeCaseDrive] file move error:', fe.message); skipped++; }
    }

    console.log('[organizeCaseDrive] case', caseId, '— moved:', moved, 'skipped:', skipped);
    return { moved: moved, skipped: skipped };
  } catch (e) {
    console.error('[organizeCaseDrive] error for case', caseId + ':', e.message);
    return { moved: 0, skipped: 0 };
  }
}

// ─────────────────────────────────────────────────────────────────────────────

function buildMailtoLink(to, subject, body) {
  return 'mailto:' + encodeURIComponent(to) + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
}

function buildPositionDescriptionPrompt(practiceName, roleTitle, location) {
  return 'Generate a professional position description for a General Practitioner joining ' + practiceName + ' in ' + location + ' for the role of ' + roleTitle + '. Include: practice overview, key responsibilities, supervision arrangements, working hours expectations, and professional development opportunities. Return well-structured HTML using <h2>, <h3>, <p>, <ul>, and <li> tags only. Do not include <html>, <head>, or <body> wrapper tags.';
}

// ── Zoom Call Scheduling helpers ──────────────────────────
const CALL_STATUS_TO_TASK_STATUS = {
  invited: 'waiting_on_gp',
  booked: 'waiting',
  completed: 'completed',
  cancelled: 'waiting_on_gp', // cancelled keeps the task open as "needs rebooking" (see unified call task design)
  no_show: 'waiting_on_gp'
};

function mapCallStatusToTaskStatus(callStatus) {
  return CALL_STATUS_TO_TASK_STATUS[callStatus] || 'open';
}

// GP-driven call failures (no-show or GP cancellation) get one rebooking grace;
// the 2nd failure auto-closes the linked task. Returns the new running count and
// whether the task should be auto-cancelled. Keep in sync with server-test-helpers.js.
function computeCallFailureOutcome(prevFailedCount) {
  const newCount = (Number(prevFailedCount) || 0) + 1;
  return { newCount, autoClose: newCount >= 2 };
}

function generateCorrelationToken() {
  return require('crypto').randomBytes(16).toString('hex');
}

// baseUrl: optional per-RSO Calendly event link so the assigned RSO hosts the meeting.
// Falls back to the global CALENDLY_EVENT_URL when blank (e.g. before RSO links are set).
function buildCalendlyBookingUrl(correlationToken, baseUrl) {
  const base = String(baseUrl || '').trim() || CALENDLY_EVENT_URL;
  if (!base) return '';
  const sep = base.includes('?') ? '&' : '?';
  return base + sep + 'utm_source=gplink&utm_medium=registration_call&utm_content=call_' + correlationToken;
}

// Pick which RSO hosts a scheduled call. Pure (no DB) so it can be unit-tested.
// Keep IDENTICAL to the copy in server-test-helpers.js.
// opts: { explicitEmail, isCeo, caseAssigneeUserId }
//   - An explicit RSO email is ONLY honored for a CEO/super-admin requester.
//   - Otherwise (or when no honored email matches) fall back to the GP's assigned RSO.
function pickScheduledCallRso(roster, opts) {
  const list = Array.isArray(roster) ? roster : [];
  const email = opts && opts.isCeo ? String(opts.explicitEmail || '').trim().toLowerCase() : '';
  let rso = email ? list.find(r => String(r.email || '').toLowerCase() === email) : null;
  if (!rso && opts && opts.caseAssigneeUserId) rso = list.find(r => r.user_id === opts.caseAssigneeUserId) || null;
  return rso || null;
}

// From/Reply-To options so an invite email is sent on behalf of the assigned RSO. We can only set
// the From address for an @mygplink.com.au RSO (verified Resend domain); otherwise keep the GP Link
// From and set Reply-To so replies still reach the RSO. Pure; keep IDENTICAL to server-test-helpers.js.
function buildRsoEmailFromOpts(rso) {
  const opts = {};
  const addr = rso && rso.email ? String(rso.email).trim() : '';
  if (addr) {
    if (/@mygplink\.com\.au$/i.test(addr)) opts.from = { email: addr, name: (rso.name || 'GP Link') + ' (GP Link)' };
    opts.replyTo = addr;
  }
  return opts;
}

// Decide whether the GP attended a Zoom call from the past-meeting participant list. The host
// (the assigned RSO) is excluded by matching email (or name when the host joined without an email);
// any other participant means the GP showed up. Pure; keep IDENTICAL to server-test-helpers.js.
function classifyCallAttendance(participants, rso) {
  const list = Array.isArray(participants) ? participants : [];
  const rsoEmail = String((rso && rso.email) || '').trim().toLowerCase();
  const rsoName = String((rso && rso.name) || '').trim().toLowerCase();
  const nonHost = list.filter(function (p) {
    const email = String((p && (p.email || p.user_email)) || '').trim().toLowerCase();
    const name = String((p && (p.name || p.user_name)) || '').trim().toLowerCase();
    if (rsoEmail && email === rsoEmail) return false;        // the RSO / host
    if (!email && rsoName && name === rsoName) return false;  // host joined without a linked email
    return true;
  });
  return nonHost.length > 0 ? 'attended' : 'no_show';
}

// A booked call is a no-show CANDIDATE once its end time (+grace) has passed and it has neither been
// completed nor already flagged. Pure; keep IDENTICAL to server-test-helpers.js.
function isNoShowCandidate(call, nowMs, graceMinutes) {
  if (!call || call.status !== 'booked') return false;
  if (!call.scheduled_at || call.completed_at || call.no_show_at) return false;
  const start = Date.parse(call.scheduled_at);
  if (!Number.isFinite(start)) return false;
  const dur = Number(call.duration_minutes || 30);
  const grace = Number(graceMinutes == null ? 15 : graceMinutes);
  return (start + (dur + grace) * 60000) < Number(nowMs);
}

function buildScheduledCallInsertPayload(input = {}) {
  const nowIso = input.nowIso || new Date().toISOString();
  return {
    case_id: input.caseId,
    user_id: input.userId,
    stage: input.stage,
    status: 'invited',
    admin_notes: input.adminNotes || null,
    meeting_reason: input.meetingReason || null,
    origin_task_id: input.originTaskId || null,
    correlation_token: input.correlationToken,
    calendly_booking_url: input.bookingUrl,
    calendly_event_type_uri: input.calendlyEventTypeUri || null,
    duration_minutes: Number(input.durationMinutes || 30),
    assigned_rso_email: input.assignedRsoEmail || null,
    assigned_rso_name: input.assignedRsoName || null,
    summary_status: 'not_requested',
    created_by: input.createdBy || 'admin',
    created_at: nowIso,
    updated_at: nowIso
  };
}

// Pure builder/validator for rso_team writes (create or update). No DB access so it
// can be unit-tested. Keep IDENTICAL to the copy in server-test-helpers.js.
// In 'update' mode only the supplied fields are included (partial PATCH); in 'create'
// mode required fields are enforced and sensible defaults are applied.
function buildRsoWritePayload(input = {}, opts = {}) {
  const mode = opts.mode === 'update' ? 'update' : 'create';
  const create = mode === 'create';
  const errors = [];
  const out = {};
  function has(k) { return Object.prototype.hasOwnProperty.call(input, k); }

  // NAME
  if (create || has('name')) {
    const name = String(input.name == null ? '' : input.name).trim();
    if (create && !name) errors.push('Name is required.');
    if (name || create) out.name = name;
  }

  // EMAIL
  if (create || has('email')) {
    const email = String(input.email == null ? '' : input.email).trim().toLowerCase();
    const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (create && !email) errors.push('Email is required.');
    else if (email && !emailOk) errors.push('Email is not a valid email address.');
    if (email || create) out.email = email;
  }

  // PHONE
  if (has('phone')) out.phone = String(input.phone == null ? '' : input.phone).trim();
  else if (create) out.phone = '';

  // ACTIVE
  if (has('active')) out.active = !!input.active;
  else if (create) out.active = true;

  // ON LEAVE (G2a) — column on rso_team; roster selection refuses on-leave targets.
  if (has('on_leave') || has('onLeave')) out.on_leave = !!(has('on_leave') ? input.on_leave : input.onLeave);
  else if (create) out.on_leave = false;

  // CALENDLY
  if (create || has('calendlyEventUrl') || has('calendly_event_url')) {
    const raw = input.calendlyEventUrl != null ? input.calendlyEventUrl : input.calendly_event_url;
    const url = String(raw == null ? '' : raw).trim();
    if (url && !/^https:\/\/calendly\.com\//i.test(url)) errors.push('Calendly link must start with https://calendly.com/');
    out.calendly_event_url = url || null;
  }

  // USER_ID (create only)
  if (create) {
    const userId = String(input.userId || input.user_id || '').trim();
    if (!userId) errors.push('user_id is required.');
    out.user_id = userId;
  }

  // MAILBOX (va_gmail) — NOT an rso_team column: it lives in va_gmail_accounts, so it is
  // validated here but returned separately (vaGmail) for the endpoint to upsert.
  // undefined = not supplied; '' = supplied blank (endpoints treat as no change).
  // Only @mygplink.com.au inboxes can be impersonated for outbound sending (domain-wide
  // delegation), so anything else is rejected up front instead of silently not working.
  let vaGmail;
  if (has('va_gmail') || has('vaGmail')) {
    const rawMb = has('va_gmail') ? input.va_gmail : input.vaGmail;
    const mb = String(rawMb == null ? '' : rawMb).trim().toLowerCase();
    if (mb && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mb)) errors.push('Mailbox is not a valid email address.');
    else if (mb && !/@mygplink\.com\.au$/.test(mb)) errors.push('Mailbox must be an @mygplink.com.au address.');
    vaGmail = mb;
  }

  out.updated_at = input.nowIso || new Date().toISOString();
  return { valid: errors.length === 0, errors, payload: out, vaGmail };
}

// G2a: link an RSO to their Gmail mailbox (va_gmail_accounts row). Used by the
// admin RSO create/update endpoints when a mailbox (va_gmail) is supplied.
// - Refuses a mailbox already linked to a DIFFERENT team member.
// - Updates the existing row in place when the RSO already has one (user_id is the
//   stable link the sender-identity + Gmail label pipeline reads), else inserts.
// - Best-effort starts a Gmail watch on the inbox so replies get processed.
// Returns { ok, error?, unchanged? }.
async function upsertRsoMailbox(rsoUserId, mailboxEmail, displayName) {
  var email = String(mailboxEmail || '').trim().toLowerCase();
  if (!rsoUserId || !email) return { ok: false, error: 'Missing RSO id or mailbox.' };
  var taken = await supabaseDbRequest('va_gmail_accounts',
    'select=user_id&email_address=eq.' + encodeURIComponent(email) + '&user_id=neq.' + encodeURIComponent(rsoUserId) + '&limit=1', { method: 'GET' });
  if (taken.ok && Array.isArray(taken.data) && taken.data.length > 0) {
    return { ok: false, error: 'That mailbox is already linked to another team member.' };
  }
  var existing = await supabaseDbRequest('va_gmail_accounts',
    'select=id,email_address,display_name&user_id=eq.' + encodeURIComponent(rsoUserId) + '&limit=1', { method: 'GET' });
  var row = (existing.ok && Array.isArray(existing.data) && existing.data[0]) ? existing.data[0] : null;
  var write;
  if (row) {
    var sameEmail = String(row.email_address || '').trim().toLowerCase() === email;
    var sameName = !displayName || String(row.display_name || '') === String(displayName);
    if (sameEmail && sameName) return { ok: true, unchanged: true };
    var patchBody = { email_address: email };
    if (displayName) patchBody.display_name = String(displayName);
    write = await supabaseDbRequest('va_gmail_accounts', 'user_id=eq.' + encodeURIComponent(rsoUserId), {
      method: 'PATCH', body: patchBody, headers: { Prefer: 'return=representation' }
    });
  } else {
    write = await supabaseDbRequest('va_gmail_accounts', '', {
      method: 'POST',
      body: { user_id: rsoUserId, email_address: email, display_name: String(displayName || email), watch_active: true },
      headers: { Prefer: 'return=representation' }
    });
  }
  if (!write.ok) {
    // Most likely the va_gmail_accounts.user_id FK (auth.users): an RSO row created
    // before the person has a real GP Link account cannot hold a mailbox link yet.
    return { ok: false, error: 'Could not save the mailbox link. If this RSO has never signed in, they need a GP Link account first.' };
  }
  try { await setupGmailWatch(email); } catch (watchErr) {
    console.error('[upsertRsoMailbox] Gmail watch setup failed (mailbox saved):', watchErr && watchErr.message);
  }
  return { ok: true };
}

// ── Gmail Label Management on VA assignment ──
// Extracted verbatim from the single-case PUT /api/admin/case handler (G2a) so the
// bulk-reassign endpoint runs the SAME per-case side-effects. Archives the old owner's
// working label, copies message history, creates labels for the new owner, and backfills
// existing GP threads. reassigningToArchive: new owner is GP Link Admin (hello@) — hand
// off by archiving only (hello@ is never provisioned a watched mailbox).
// Returns { emailTransferred, emailTransferError }:
// null = no transfer attempted; true = succeeded; false = failed (see emailTransferError).
async function transferCaseEmailOwnership(caseId, newAssignedVa, oldAssignedVa, reassigningToArchive) {
  var emailTransferred = null;
  var emailTransferError = null;
  if (newAssignedVa) {
    if (reassigningToArchive) {
      // GP Link Admin (master archive / hello@) now owns the case. hello@ is never
      // Gmail-watched and already mirrors every case email (silent copies on the hello@
      // sub-label), so there is no VA mailbox to provision — just hand off cleanly by
      // archiving the previous RSO's working label.
      try {
        if (oldAssignedVa && oldAssignedVa !== newAssignedVa) {
          var oldVaArcRes = await supabaseDbRequest('va_gmail_accounts',
            'select=email_address&user_id=eq.' + encodeURIComponent(oldAssignedVa) + '&limit=1');
          var oldVaArc = oldVaArcRes.ok && oldVaArcRes.data && oldVaArcRes.data[0] ? oldVaArcRes.data[0] : null;
          if (oldVaArc) await archiveLabelForVA(oldVaArc.email_address, caseId);
        }
        // Ownership moved to GP Link Admin; the master archive already holds the history.
        emailTransferred = true;
      } catch (arcErr) {
        console.error('[Gmail Labels] Handoff to GP Link Admin failed:', arcErr.message);
        emailTransferred = false;
        emailTransferError = String(arcErr && arcErr.message || arcErr).slice(0, 300);
      }
    } else try {
        var labelCaseRes = await supabaseDbRequest('registration_cases',
          'select=user_id,practice_name,practice_contact,gmail_label_id,gmail_label_hello_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
        var labelCase = labelCaseRes.ok && labelCaseRes.data && labelCaseRes.data[0] ? labelCaseRes.data[0] : null;
        if (!labelCase) throw new Error('Case not found for label setup');

        var gpProfileRes = await supabaseDbRequest('user_profiles',
          'select=first_name,last_name&user_id=eq.' + encodeURIComponent(labelCase.user_id) + '&limit=1');
        var gpProfile = gpProfileRes.ok && gpProfileRes.data && gpProfileRes.data[0] ? gpProfileRes.data[0] : {};
        var gpName = [(gpProfile.first_name || ''), (gpProfile.last_name || '')].join(' ').trim() || 'Unknown';

        var vaAccRes = await supabaseDbRequest('va_gmail_accounts',
          'select=email_address,display_name&user_id=eq.' + encodeURIComponent(newAssignedVa) + '&limit=1');
        var vaAcc = vaAccRes.ok && vaAccRes.data && vaAccRes.data[0] ? vaAccRes.data[0] : null;
        if (!vaAcc) {
          // RSO-driven reassignments are guarded upstream (resolveRsoReassignmentTarget),
          // so this only fires for legacy direct assigned_va writes with no mailbox.
          console.log('[Gmail Labels] No VA Gmail account registered for user', newAssignedVa, '— skipping label setup');
          throw new Error('skip');
        }

        // Archive old VA's label if this is a reassignment
        var historyMessages = [];
        if (oldAssignedVa && oldAssignedVa !== newAssignedVa) {
          var oldVaRes = await supabaseDbRequest('va_gmail_accounts',
            'select=email_address&user_id=eq.' + encodeURIComponent(oldAssignedVa) + '&limit=1');
          var oldVaAcc = oldVaRes.ok && oldVaRes.data && oldVaRes.data[0] ? oldVaRes.data[0] : null;
          if (oldVaAcc && labelCase.gmail_label_id) {
            await archiveLabelForVA(oldVaAcc.email_address, caseId);

            // Copy email history to new VA
            var oldGmail = await getGmailClient(oldVaAcc.email_address);
            if (oldGmail) {
              try {
                var oldMsgs = await oldGmail.users.messages.list({
                  userId: oldVaAcc.email_address, labelIds: [labelCase.gmail_label_id], maxResults: 100
                });
                var msgList = (oldMsgs.data && oldMsgs.data.messages) || [];
                for (var mIdx = 0; mIdx < msgList.length; mIdx++) {
                  var rawMsg = await oldGmail.users.messages.get({
                    userId: oldVaAcc.email_address, id: msgList[mIdx].id, format: 'raw'
                  });
                  if (rawMsg.data && rawMsg.data.raw) {
                    historyMessages.push(Buffer.from(rawMsg.data.raw, 'base64'));
                  }
                }
              } catch (copyErr) {
                console.error('[Gmail Labels] History fetch failed:', copyErr.message);
              }
            }

            // Move hello@ sub-label to new VA's folder
            if (labelCase.gmail_label_hello_id) {
              var newHelloName = buildHelloLabelName(vaAcc.display_name, gpName, labelCase.practice_name || '');
              await renameGmailLabel(MASTER_ARCHIVE_EMAIL, labelCase.gmail_label_hello_id, newHelloName);
            }
          }
        }

        // Create labels for the new VA
        var result = await createLabelsForCase(caseId, vaAcc.email_address, vaAcc.display_name, gpName, labelCase.practice_name || '');
        // Core label/mailbox transfer succeeded (backfill below is best-effort) (#12).
        emailTransferred = true;

        // Insert history messages into new VA's label (reassignment)
        if (historyMessages && historyMessages.length > 0 && result.vaLabelId) {
          for (var hi = 0; hi < historyMessages.length; hi++) {
            await insertSilentCopy(vaAcc.email_address, result.vaLabelId, historyMessages[hi]);
          }
          console.log('[Gmail Labels] Copied', historyMessages.length, 'history messages to new VA');
        }

        // Backfill: search VA's inbox for existing emails matching this GP
        // Only matches GP email directly, then labels all messages in those threads
        // (so practice emails in the same conversation are included)
        if (result.vaLabelId) {
          try {
            var gpEmailRes = await supabaseDbRequest('user_profiles',
              'select=email&user_id=eq.' + encodeURIComponent(labelCase.user_id) + '&limit=1');
            var gpEmail = gpEmailRes.ok && gpEmailRes.data && gpEmailRes.data[0] ? gpEmailRes.data[0].email : '';

            if (gpEmail) {
              var vaGmail = await getGmailClient(vaAcc.email_address);
              if (vaGmail) {
                // Search for emails directly involving the GP
                var searchRes = await vaGmail.users.messages.list({
                  userId: vaAcc.email_address, q: 'from:' + gpEmail + ' OR to:' + gpEmail, maxResults: 50
                });
                var gpMsgs = (searchRes.data && searchRes.data.messages) || [];

                // Collect unique thread IDs from GP emails
                var gpThreadIds = {};
                for (var si = 0; si < gpMsgs.length; si++) {
                  var msgMeta = await vaGmail.users.messages.get({
                    userId: vaAcc.email_address, id: gpMsgs[si].id, format: 'metadata', metadataHeaders: ['From']
                  });
                  if (msgMeta.data && msgMeta.data.threadId) {
                    gpThreadIds[msgMeta.data.threadId] = true;
                  }
                }

                // Label all messages in those threads (includes practice replies in same thread)
                var labeledCount = 0;
                var threadKeys = Object.keys(gpThreadIds);
                for (var ti = 0; ti < threadKeys.length; ti++) {
                  try {
                    var threadRes = await vaGmail.users.threads.get({
                      userId: vaAcc.email_address, id: threadKeys[ti], format: 'minimal'
                    });
                    var threadMsgs = (threadRes.data && threadRes.data.messages) || [];
                    for (var tmi = 0; tmi < threadMsgs.length; tmi++) {
                      await applyGmailLabel(vaAcc.email_address, threadMsgs[tmi].id, result.vaLabelId);
                      labeledCount++;
                      // Copy to hello@
                      if (result.helloLabelId) {
                        try {
                          var rawM = await vaGmail.users.messages.get({
                            userId: vaAcc.email_address, id: threadMsgs[tmi].id, format: 'raw'
                          });
                          if (rawM.data && rawM.data.raw) {
                            await insertSilentCopy(MASTER_ARCHIVE_EMAIL, result.helloLabelId, Buffer.from(rawM.data.raw, 'base64'));
                          }
                        } catch (hErr) { /* skip */ }
                      }
                    }
                  } catch (thErr) { /* skip thread errors */ }
                }
                if (labeledCount > 0) {
                  console.log('[Gmail Labels] Backfilled', labeledCount, 'emails across', threadKeys.length, 'threads for', gpName);
                }
              }
            }
          } catch (backfillErr) {
            console.error('[Gmail Labels] Backfill failed:', backfillErr.message);
          }
        }
    } catch (err) {
      console.error('[Gmail Labels] Label creation on assignment failed:', err.message);
      // 'skip' is the intentional no-mailbox sentinel (not a real transfer failure);
      // every other throw is a genuine failure surfaced to the caller (#12).
      if (err && err.message === 'skip') {
        emailTransferred = false;
        emailTransferError = 'No Gmail mailbox registered for the new owner; labels not transferred.';
      } else {
        emailTransferred = false;
        emailTransferError = String(err && err.message || err).slice(0, 300);
      }
    }
  }
  return { emailTransferred: emailTransferred, emailTransferError: emailTransferError };
}

function getScheduledCallRegistrationTaskId(callRecord) {
  if (!callRecord || typeof callRecord !== 'object') return null;
  return callRecord.registration_task_id || callRecord.task_id || null;
}

function buildScheduledCallNotificationPatch(waResult = {}, emailResult = {}, options = {}) {
  const nowIso = options.nowIso || new Date().toISOString();
  const whatsappMessageId = waResult.messageId || waResult.message_id || waResult.id || null;
  const emailMessageId = emailResult.messageId || emailResult.message_id || emailResult.id || null;
  const notificationChannels = {
    whatsapp: {
      requested: !!options.whatsappRequested,
      sent: !!waResult.ok,
      message_id: whatsappMessageId
    },
    email: {
      requested: !!options.emailRequested,
      sent: !!emailResult.ok,
      message_id: emailMessageId
    }
  };
  if (waResult.error) notificationChannels.whatsapp.error = String(waResult.error).slice(0, 500);
  if (emailResult.error) notificationChannels.email.error = String(emailResult.error).slice(0, 500);
  const patch = {
    invite_sent_at: nowIso,
    notification_channels: notificationChannels,
    whatsapp_message_id: whatsappMessageId,
    email_message_id: emailMessageId,
    updated_at: nowIso
  };
  if (options.resendCount !== undefined) patch.resend_count = options.resendCount;
  return patch;
}

function normalizeScheduledCallForApi(callRecord) {
  if (!callRecord || typeof callRecord !== 'object') return callRecord;
  return {
    ...callRecord,
    booking_url: callRecord.calendly_booking_url || callRecord.booking_url || '',
    task_id: getScheduledCallRegistrationTaskId(callRecord),
    calendly_event_url: callRecord.calendly_event_uri || callRecord.calendly_event_url || ''
  };
}

// Collapse superseded / duplicate meetings for the CEO "Meetings" tab so a reschedule or a
// double-booking never renders twice. When a GP reschedules or re-books the public Calendly
// consultation link the old scheduled_calls row can survive as a second status='booked' row
// (Calendly's cancel webhook can be lost or arrive out of order) — this leaves exactly one row
// per meeting on screen. Pure (no DB); order of the kept rows is preserved.
//
// Rule: group rows by (person + meeting_kind + application_id). "Person" is user_id when set,
// otherwise the lowercased invitee_email; rows with neither are unidentifiable and always kept.
// Within a group that has any ACTIVE (invited/booked) row, keep only the single most-recently-
// booked active row, drop the other actives, and drop cancelled siblings (the superseded slot) —
// but keep completed / no_show rows as genuine history. Groups with no active row (a standalone
// cancellation, a past no-show, a completed call) are left intact.
// Keep IDENTICAL to the copy in server-test-helpers.js.
function dedupeMeetingRowsForDisplay(rows) {
  if (!Array.isArray(rows)) return [];
  const ACTIVE = { invited: 1, booked: 1 };
  function groupKey(r) {
    const uid = r.user_id ? 'u:' + r.user_id : '';
    const em = uid ? '' : String(r.invitee_email || '').trim().toLowerCase();
    if (!uid && !em) return null; // unidentifiable → never grouped, always kept
    return (uid || 'e:' + em) + '|' + (r.meeting_kind || 'consultation') + '|' + (r.application_id || '');
  }
  function ts(r) {
    const v = Date.parse(r.booked_at || r.scheduled_at || r.updated_at || r.created_at || '');
    return Number.isFinite(v) ? v : 0;
  }
  // Winning active row per group = the most recent booking action.
  const winners = {};
  rows.forEach(function (r) {
    const k = groupKey(r);
    if (!k || !ACTIVE[r.status]) return;
    if (!winners[k] || ts(r) > ts(winners[k])) winners[k] = r;
  });
  return rows.filter(function (r) {
    const k = groupKey(r);
    if (!k) return true;                        // unidentifiable → keep
    const winner = winners[k];
    if (!winner) return true;                   // group is pure history → keep as-is
    if (ACTIVE[r.status]) return r === winner;  // among actives, keep only the winner
    if (r.status === 'cancelled') return false; // superseded old slot → hide
    return true;                                // completed / no_show → real history, keep
  });
}

function verifyCalendlySignature(signatureHeader, rawBody, secret) {
  if (!signatureHeader || !secret) return false;
  const timestampCandidates = [];
  const signatures = [];
  for (const pair of signatureHeader.split(',')) {
    const idx = pair.indexOf('=');
    if (idx <= 0) continue;
    const key = pair.slice(0, idx).trim();
    const val = pair.slice(idx + 1).trim();
    if (key === 't' && val) timestampCandidates.push(val);
    if (key === 'v1' && val) signatures.push(val);
  }
  const timestamp = timestampCandidates[0];
  if (!timestamp || signatures.length === 0) return false;
  const timestampNumber = Number(timestamp);
  if (!Number.isFinite(timestampNumber)) return false;
  // Calendly sends Unix seconds in the t= value. Keep millisecond support for
  // locally generated legacy test signatures, but preserve the original string
  // in the signed payload.
  const timestampMs = timestampNumber < 10000000000 ? timestampNumber * 1000 : timestampNumber;
  const age = Date.now() - timestampMs;
  if (age > 5 * 60 * 1000 || age < -60 * 1000) return false;
  const crypto = require('crypto');
  const bodyBuffer = Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(String(rawBody || ''), 'utf8');
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(timestamp + '.', 'utf8');
  hmac.update(bodyBuffer);
  const expectedBuf = Buffer.from(hmac.digest('hex'), 'hex');
  return signatures.some((signature) => {
    if (!/^[a-f0-9]{64}$/i.test(signature)) return false;
    const candidateBuf = Buffer.from(signature, 'hex');
    return candidateBuf.length === expectedBuf.length && crypto.timingSafeEqual(candidateBuf, expectedBuf);
  });
}

function verifyZoomWebhookSignature(timestamp, rawBody, signature, secret) {
  if (!timestamp || !signature || !secret) return false;
  const message = 'v0:' + timestamp + ':' + rawBody;
  const expected = 'v0=' + require('crypto').createHmac('sha256', secret).update(message).digest('hex');
  if (expected.length !== signature.length) return false;
  return require('crypto').timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
}

function buildZoomValidationResponse(plainToken, secret) {
  const encryptedToken = require('crypto').createHmac('sha256', secret).update(plainToken).digest('hex');
  return { plainToken, encryptedToken };
}

async function checkAndRecordWebhookEvent(provider, eventId, eventType, payload) {
  if (!eventId) return false;
  const existing = await supabaseDbRequest('webhook_events', 'provider=eq.' + encodeURIComponent(provider) + '&event_id=eq.' + encodeURIComponent(eventId) + '&select=id', { method: 'GET' });
  if (existing.ok && Array.isArray(existing.data) && existing.data.length > 0) return true;
  const redactedPayload = payload ? { event: payload.event, created_at: payload.created_at } : null;
  const inserted = await supabaseDbRequest('webhook_events', '', {
    method: 'POST',
    headers: { Prefer: 'return=minimal' },
    body: { provider, event_id: eventId, event_type: eventType, payload: redactedPayload }
  });
  if (!inserted.ok && inserted.status === 409) return true;
  return false;
}

// Read-only half of checkAndRecordWebhookEvent — checks for an existing
// dedupe marker without recording one. Lets a caller defer the record step
// until after its own side effect (e.g. a DB insert) has succeeded, so a
// failed side effect stays retryable instead of getting silently swallowed
// by a marker that was written too early.
async function hasRecordedWebhookEvent(provider, eventId) {
  if (!eventId) return false;
  const existing = await supabaseDbRequest('webhook_events', 'provider=eq.' + encodeURIComponent(provider) + '&event_id=eq.' + encodeURIComponent(eventId) + '&select=id', { method: 'GET' });
  return existing.ok && Array.isArray(existing.data) && existing.data.length > 0;
}
// ── End Zoom Call Scheduling helpers ──────────────────────

async function deliverToMyDocuments(userId, caseId, docKey, fileName, buffer, mimeType, opts) {
  const results = { userDoc: null, driveFile: null };

  // 1. Upsert into user_documents
  const existing = await supabaseDbRequest('user_documents', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&document_key=eq.' + encodeURIComponent(docKey) + '&limit=1');
  const docRecord = {
    user_id: userId,
    document_key: docKey,
    file_name: fileName,
    status: 'approved',
    reviewed_at: new Date().toISOString()
  };
  if (existing.ok && Array.isArray(existing.data) && existing.data[0]) {
    await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(existing.data[0].id), { method: 'PATCH', body: docRecord });
    results.userDoc = existing.data[0].id;
  } else {
    const ins = await supabaseDbRequest('user_documents', '', { method: 'POST', body: [docRecord] });
    if (ins.ok && Array.isArray(ins.data) && ins.data[0]) results.userDoc = ins.data[0].id;
  }

  // 2. Upload to Google Drive
  const folderId = await ensureGPDriveFolder(caseId, null, null);
  if (folderId && buffer) {
    const driveFile = await uploadToGoogleDrive(folderId, fileName, buffer, mimeType || 'application/pdf');
    if (driveFile) {
      results.driveFile = driveFile.id;
      // File into its document-type subfolder (best-effort).
      fileDocOnDrive(caseId, docKey, driveFile.id).catch(function () {});
    }
  }

  // Notify the GP by email that a document was delivered to their account (best-effort,
  // deep-linked). Callers can opt out with opts.notifyGp === false.
  if (!opts || opts.notifyGp !== false) {
    notifyGpDocumentDelivered(userId, docKey, fileName).catch(function () {});
  }
  return results;
}

// Friendly labels for the "document delivered" email (falls back to the file name / cleaned key).
var DELIVERED_DOC_LABELS = {
  sppa_00: 'SPPA-00 (Supervised Practice Plan)',
  section_g: 'Section G (Supervised Practice Goals)',
  offer_contract: 'Offer / Contract',
  position_description: 'Position Description',
  supervisor_cv: 'Supervisor CV',
  cv_signed_dated: 'Signed CV',
  criminal_history: 'Criminal History Check'
};
function _deliveredDocLabel(docKey, fileName) {
  if (DELIVERED_DOC_LABELS[docKey]) return DELIVERED_DOC_LABELS[docKey];
  if (/^alt_supervisor_cv/i.test(String(docKey || ''))) return 'Alternate Supervisor CV';
  var fn = String(fileName || '').replace(/\.[a-z0-9]+$/i, '').trim();
  if (fn) return fn;
  return String(docKey || 'document').replace(/_/g, ' ');
}

// Email the GP that a document has been delivered to their account, with an "Open Document" button
// that deep-links straight to that document. The link is to /pages/ahpra.html?doc=<key>; if the GP
// isn't signed in, the auth bounce preserves the full path+query as ?next (buildSigninRedirect /
// auth-guard.js), so after login they land back on the document — it doesn't break on sign-in.
// Best-effort: never throws; call sites fire-and-forget.
async function notifyGpDocumentDelivered(userId, docKey, fileName) {
  try {
    if (!userId) return;
    var label = _deliveredDocLabel(docKey, fileName);
    var deepLink = APP_BASE_URL + '/pages/ahpra.html?doc=' + encodeURIComponent(String(docKey || ''));
    await sendGpNotificationEmail(userId,
      label + ' added to your documents, GP Link',
      'A new document is ready, {{name}}',
      'Your ' + label + ' has been added to your GP Link account by our team. You can view and download it any time from your documents, just tap the button below and it will take you straight there.',
      'Open Document',
      deepLink,
      'Questions? Reply to this email or message us on WhatsApp at +61 494 391 968.'
    );
  } catch (e) { console.error('[doc-notify] failed for', docKey, e && e.message); }
}

// Helper: upload SPPA-00 PDF to Google Drive and update the task_document row with Drive refs
// Replaces existing SPPA-00 file in Drive if one exists (avoids duplicates)
async function _uploadSppaDocToDrive(caseId, taskDocId, buffer, fileName) {
  if (!isGoogleDriveConfigured()) return null;
  try {
    var folderId = await ensureGPDriveFolder(caseId, null, null);
    if (!folderId) return null;
    var drive = await getGoogleDriveClient();
    if (!drive) return null;
    // Check for existing SPPA-00 file in this folder
    var existingFiles = await drive.files.list({
      q: "'" + folderId + "' in parents and name contains 'SPPA-00' and trashed = false",
      fields: 'files(id,name)', pageSize: 5
    });
    var existingFile = (existingFiles.data.files || [])[0];
    var driveFile;
    if (existingFile) {
      // Replace existing file content and rename
      var updateRes = await drive.files.update({
        fileId: existingFile.id,
        requestBody: { name: fileName },
        media: { mimeType: 'application/pdf', body: require('stream').Readable.from(buffer) },
        fields: 'id,name,webViewLink'
      });
      driveFile = updateRes.data;
      console.log('[SPPA Drive] Replaced existing file:', existingFile.name, '→', fileName);
    } else {
      // No existing file — create new
      driveFile = await uploadToGoogleDrive(folderId, fileName, buffer, 'application/pdf');
    }
    if (!driveFile || !driveFile.id) return null;
    var driveUrl = 'https://drive.google.com/file/d/' + driveFile.id + '/view';
    if (taskDocId) {
      await supabaseDbRequest('task_documents', 'id=eq.' + encodeURIComponent(taskDocId), {
        method: 'PATCH', body: { google_drive_file_id: driveFile.id, google_drive_url: driveUrl }
      });
    }
    // File the SPPA-00 into its document subfolder (best-effort).
    fileDocOnDrive(caseId, 'sppa_00', driveFile.id).catch(function () {});
    return { id: driveFile.id, url: driveUrl, webViewLink: driveFile.webViewLink };
  } catch (err) {
    console.error('[SPPA Drive] upload failed:', err.message);
    return null;
  }
}

// Helper: disambiguate which GP an email from a multi-GP practice contact is about
// Returns the matched case object or null if ambiguous
async function _disambiguatePracticeEmail(appRows, emailMeta) {
  // First: get GP names for all candidates
  var candidates = [];
  for (var app of appRows) {
    var profileRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(app.user_id) + '&limit=1');
    var profile = (profileRes.ok && profileRes.data && profileRes.data[0]) ? profileRes.data[0] : {};
    var gpName = [(profile.first_name || ''), (profile.last_name || '')].join(' ').trim();
    var caseRes = await supabaseDbRequest('registration_cases', 'select=id,stage,user_id&user_id=eq.' + encodeURIComponent(app.user_id) + '&status=eq.active&limit=1');
    var gpCase = (caseRes.ok && caseRes.data && caseRes.data[0]) ? caseRes.data[0] : null;
    if (gpCase) candidates.push({ case: gpCase, gpName: gpName, userId: app.user_id });
  }
  if (candidates.length === 0) return null;
  if (candidates.length === 1) return candidates[0].case;

  // Quick check: does the email subject or body mention a specific GP name?
  var emailText = ((emailMeta.subject || '') + ' ' + (emailMeta.bodyText || '')).toLowerCase();
  var nameMatches = candidates.filter(function(c) {
    var parts = c.gpName.toLowerCase().split(/\s+/).filter(function(p) { return p.length > 2; });
    // Match if last name appears in email text
    var lastName = parts[parts.length - 1] || '';
    return lastName && emailText.indexOf(lastName) > -1;
  });
  if (nameMatches.length === 1) {
    console.log('[Gmail] Disambiguated practice email to', nameMatches[0].gpName, 'via name mention in email');
    return nameMatches[0].case;
  }

  // Thread-based: check if this email's threadId matches any task for any candidate
  if (emailMeta.threadId) {
    for (var cand of candidates) {
      var threadCheck = await supabaseDbRequest('task_messages',
        'select=task_id&gmail_thread_id=eq.' + encodeURIComponent(emailMeta.threadId) + '&case_id=eq.' + encodeURIComponent(cand.case.id) + '&limit=1');
      if (threadCheck.ok && Array.isArray(threadCheck.data) && threadCheck.data.length > 0) {
        console.log('[Gmail] Disambiguated practice email to', cand.gpName, 'via thread match');
        return cand.case;
      }
    }
  }

  // AI fallback: ask Claude to determine which GP based on email content
  if (process.env.ANTHROPIC_API_KEY && candidates.length <= 5) {
    try {
      var budgetOk = await checkAnthropicBudget();
      if (budgetOk) {
        var gpList = candidates.map(function(c, i) { return (i + 1) + '. Dr ' + c.gpName; }).join('\n');
        var prompt = 'An email was received from a practice contact. This practice has multiple GPs. Determine which GP this email is about.\n\n'
          + 'GPs at this practice:\n' + gpList + '\n\n'
          + 'Email subject: ' + (emailMeta.subject || '(none)') + '\n'
          + 'Email body: ' + (emailMeta.bodyText || '').substring(0, 2000) + '\n'
          + 'Attachment filenames: ' + (emailMeta.attachments || []).map(function(a) { return a.filename; }).join(', ') + '\n\n'
          + 'Return JSON only: {"matched_gp_index": 1-based index or null, "confidence": 0.0-1.0, "reason": "brief"}\n'
          + 'If you cannot determine which GP, return matched_gp_index: null.';
        var controller = new AbortController();
        var timeout = setTimeout(function() { controller.abort(); }, 15000);
        var aiRes = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST', signal: controller.signal,
          headers: { 'x-api-key': process.env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
          body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: 200, temperature: 0, messages: [{ role: 'user', content: prompt }] })
        });
        clearTimeout(timeout);
        var aiData = await aiRes.json();
        if (typeof recordAnthropicSpend === 'function' && aiData.usage) {
          recordAnthropicSpend(aiData.usage.input_tokens || 0, aiData.usage.output_tokens || 0, aiData.usage.cache_read_input_tokens || 0, aiData.usage.cache_creation_input_tokens || 0);
        }
        var aiText = aiData.content && aiData.content[0] ? aiData.content[0].text : '';
        var aiMatch = aiText.match(/\{[\s\S]*\}/);
        if (aiMatch) {
          var aiResult = JSON.parse(aiMatch[0]);
          if (aiResult.matched_gp_index && aiResult.confidence > 0.6) {
            var idx = aiResult.matched_gp_index - 1;
            if (idx >= 0 && idx < candidates.length) {
              console.log('[Gmail] AI disambiguated practice email to', candidates[idx].gpName, '(confidence:', aiResult.confidence, ', reason:', aiResult.reason, ')');
              return candidates[idx].case;
            }
          }
        }
      }
    } catch (aiErr) { console.error('[Gmail] AI disambiguation error:', aiErr.message); }
  }

  // Deep context: pull recent email history with this practice and use Opus for strong disambiguation
  if (process.env.ANTHROPIC_API_KEY && candidates.length <= 10) {
    try {
      var budgetOk2 = await checkAnthropicBudget();
      if (budgetOk2) {
        var practiceEmail = (emailMeta.sender || '').replace(/^.*<([^>]+)>.*$/, '$1').trim().toLowerCase();
        // Fetch last 10 sent + 10 received task_messages involving this practice email across all candidate cases
        var caseIds = candidates.map(function(c) { return c.case.id; });
        var recentMsgsRes = await supabaseDbRequest('task_messages',
          'select=case_id,direction,sender,recipient,subject,body_text,created_at'
          + '&case_id=in.(' + caseIds.map(function(id) { return '"' + id + '"'; }).join(',') + ')'
          + '&channel=eq.email'
          + '&order=created_at.desc&limit=20');
        var recentMsgs = (recentMsgsRes.ok && Array.isArray(recentMsgsRes.data)) ? recentMsgsRes.data : [];
        // Also get recent messages where sender/recipient matches the practice email
        var practiceThreadMsgs = recentMsgs.filter(function(m) {
          var s = (m.sender || '').toLowerCase();
          var r = (m.recipient || '').toLowerCase();
          return s.indexOf(practiceEmail) > -1 || r.indexOf(practiceEmail) > -1 || true; // include all case emails for context
        });
        // Map case_id to GP name for context
        var caseToGp = {};
        candidates.forEach(function(c) { caseToGp[c.case.id] = c.gpName; });
        var historyLines = practiceThreadMsgs.slice(0, 20).reverse().map(function(m) {
          var gpLabel = caseToGp[m.case_id] ? ' [GP: ' + caseToGp[m.case_id] + ']' : '';
          var dir = m.direction === 'outbound' ? 'SENT' : 'RECEIVED';
          return dir + gpLabel + ' | ' + (m.created_at || '').substring(0, 16) + ' | Subject: ' + (m.subject || '(none)') + ' | ' + (m.body_text || '').substring(0, 300);
        });

        var gpList2 = candidates.map(function(c, i) { return (i + 1) + '. Dr ' + c.gpName; }).join('\n');
        var deepPrompt = 'You are an expert at determining which GP a practice email is about. '
          + 'This practice has multiple GPs registered with us. A new email has arrived and we need to match it to the correct GP.\n\n'
          + 'GPs at this practice:\n' + gpList2 + '\n\n'
          + '--- RECENT EMAIL HISTORY WITH THIS PRACTICE (oldest first) ---\n'
          + (historyLines.length > 0 ? historyLines.join('\n') : '(no previous email history)')
          + '\n--- END HISTORY ---\n\n'
          + '--- NEW EMAIL (needs matching) ---\n'
          + 'From: ' + (emailMeta.sender || '') + '\n'
          + 'Subject: ' + (emailMeta.subject || '(none)') + '\n'
          + 'Body: ' + (emailMeta.bodyText || '').substring(0, 3000) + '\n'
          + 'Attachments: ' + (emailMeta.attachments || []).map(function(a) { return a.filename; }).join(', ') + '\n'
          + '--- END NEW EMAIL ---\n\n'
          + 'Based on the conversation history and the new email content, which GP is this email about?\n'
          + 'Look for: name mentions, references to previous conversations, document names, context clues.\n\n'
          + 'Return JSON only: {"matched_gp_index": 1-based index or null, "confidence": 0.0-1.0, "reason": "explain your reasoning"}\n'
          + 'Only return null if you genuinely cannot determine which GP after considering all context.';

        var ctrl2 = new AbortController();
        var to2 = setTimeout(function() { ctrl2.abort(); }, 30000);
        var opusRes = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST', signal: ctrl2.signal,
          headers: { 'x-api-key': process.env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
          body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: 300, temperature: 0, messages: [{ role: 'user', content: deepPrompt }] })
        });
        clearTimeout(to2);
        var opusData = await opusRes.json();
        if (typeof recordAnthropicSpend === 'function' && opusData.usage) {
          recordAnthropicSpend(opusData.usage.input_tokens || 0, opusData.usage.output_tokens || 0, opusData.usage.cache_read_input_tokens || 0, opusData.usage.cache_creation_input_tokens || 0);
        }
        var opusText = opusData.content && opusData.content[0] ? opusData.content[0].text : '';
        var opusMatch = opusText.match(/\{[\s\S]*\}/);
        if (opusMatch) {
          var opusResult = JSON.parse(opusMatch[0]);
          if (opusResult.matched_gp_index && opusResult.confidence > 0.5) {
            var oidx = opusResult.matched_gp_index - 1;
            if (oidx >= 0 && oidx < candidates.length) {
              console.log('[Gmail] Opus deep-context disambiguated practice email to', candidates[oidx].gpName,
                '(confidence:', opusResult.confidence, ', reason:', opusResult.reason, ')');
              return candidates[oidx].case;
            }
          }
        }
        console.log('[Gmail] Opus deep-context could not disambiguate:', opusText.substring(0, 200));
      }
    } catch (opusErr) { console.error('[Gmail] Opus disambiguation error:', opusErr.message); }
  }

  // Cannot disambiguate — log warning and return null (email will fall to standard triage)
  console.warn('[Gmail] Could not disambiguate practice email from', emailMeta.sender, '— practice has', candidates.length, 'GPs:', candidates.map(function(c) { return c.gpName; }).join(', '));
  return null;
}

// ── Practice contact resolution ───────────────────────────────────────────────
// Every "email the practice" surface (the document-request composer, its nudge and
// revision variants, the SPPA-00 pack, the AHPRA conflict letter) needs the same thing:
// the address and name of the contact at the practice where this GP is placed.
// lib/practice-contact.js documents the two traps — placements are not all status
// 'hired', and hand-created ones leave the contact columns NULL. Route every lookup
// through these two helpers so a fix lands everywhere at once.

// Fill blank contact columns on already-fetched placed applications from the linked
// practices row. Split out from the fetch so a caller that scans placements table-wide
// (rather than by user id) gets the same fallback.
async function hydratePlacedApplicationRows(placedRows) {
  if (!Array.isArray(placedRows) || !placedRows.length) return placedRows || [];

  // Only rows still missing an address cost the extra lookups below. Both go through
  // supabaseDbRequestByIds so a large caseload chunks instead of building one oversized
  // in.(...) URL — the failure mode that silently 400'd the CEO task views.
  const rolePracticeById = {};
  const pendingRoles = practiceContactLib.pendingRoleIds(placedRows);
  if (pendingRoles.length) {
    const roleRows = await supabaseDbRequestByIds('career_roles', pendingRoles,
      function (inList) { return 'select=id,practice_id&id=in.(' + inList + ')&limit=' + SUPABASE_IN_CHUNK_SIZE; });
    roleRows.forEach(function (r) { if (r && r.practice_id) rolePracticeById[r.id] = r.practice_id; });
  }
  const practiceById = {};
  const pendingPractices = practiceContactLib.pendingPracticeIds(placedRows, rolePracticeById);
  if (pendingPractices.length) {
    const pracRows = await supabaseDbRequestByIds('practices', pendingPractices,
      function (inList) { return 'select=id,contact_name,contact_email&id=in.(' + inList + ')&limit=' + SUPABASE_IN_CHUNK_SIZE; });
    pracRows.forEach(function (p) { if (p && p.id) practiceById[p.id] = p; });
  }
  return practiceContactLib.applyPracticeContactFallback(placedRows, practiceById, rolePracticeById);
}

// Placed gp_applications rows for these GPs, with blank contact columns filled in from
// the linked practices row. Extra columns can be appended for callers that need them.
async function fetchPlacedApplicationRows(userIds, extraColumns) {
  const placedIds = [...new Set((Array.isArray(userIds) ? userIds : []).filter(Boolean))];
  if (!placedIds.length || !isSupabaseDbConfigured()) return [];
  const placedCols = practiceContactLib.PLACED_APPLICATION_COLUMNS + (extraColumns ? ',' + extraColumns : '');
  const placedRes = await supabaseDbRequest('gp_applications',
    'select=' + placedCols + '&' + practiceContactLib.PLACED_APPLICATION_FILTER +
    '&user_id=in.(' + placedIds.map(encodeURIComponent).join(',') + ')');
  return hydratePlacedApplicationRows((placedRes.ok && Array.isArray(placedRes.data)) ? placedRes.data : []);
}

// { email, name } for one GP's placement, or null when there is genuinely no address —
// so callers can fall through to their own next source rather than render an empty "To".
async function resolvePlacedPracticeContact(userId) {
  if (!userId) return null;
  const placedRows = await fetchPlacedApplicationRows([userId]);
  return practiceContactLib.toPracticeContact(practiceContactLib.pickPlacedApplication(placedRows));
}

// Helper: create placeholder alt supervisor CV entries when SPPA-00 reveals alt supervisors
// Creates user_documents (pending) and updates gp_prepared_docs state (ready: false → "Preparing")
async function _createAltSupervisorCvPlaceholders(caseId, altSupervisorNames) {
  if (!altSupervisorNames || altSupervisorNames.length === 0) return;
  try {
    var caseRes = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
    var userId = (caseRes.ok && caseRes.data && caseRes.data[0]) ? caseRes.data[0].user_id : null;
    if (!userId) return;

    for (var i = 0; i < altSupervisorNames.length; i++) {
      var docKey = 'alt_supervisor_cv_' + (i + 1);
      var label = altSupervisorNames[i] + ' — CV';
      // Check if already exists
      var existing = await supabaseDbRequest('user_documents', 'select=id,status&user_id=eq.' + encodeURIComponent(userId) + '&document_key=eq.' + encodeURIComponent(docKey) + '&limit=1');
      if (existing.ok && Array.isArray(existing.data) && existing.data[0]) {
        // Already exists — don't overwrite if approved
        if (existing.data[0].status === 'approved') continue;
      } else {
        // Create pending placeholder
        await supabaseDbRequest('user_documents', '', {
          method: 'POST', body: [{ user_id: userId, document_key: docKey, file_name: label, status: 'pending' }]
        });
      }
    }

    // Update gp_prepared_docs state so MyDocuments shows "Preparing" for alt CVs
    var stateRes = await supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    var fullState = (stateRes.ok && Array.isArray(stateRes.data) && stateRes.data[0] && stateRes.data[0].state) ? stateRes.data[0].state : {};
    if (typeof fullState === 'string') try { fullState = JSON.parse(fullState); } catch (e) { fullState = {}; }
    var prepState = fullState.gp_prepared_docs;
    if (typeof prepState === 'string') try { prepState = JSON.parse(prepState); } catch (e) { prepState = {}; }
    if (!prepState || typeof prepState !== 'object') prepState = { docs: {} };
    if (!prepState.docs) prepState.docs = {};
    for (var j = 0; j < altSupervisorNames.length; j++) {
      var dk = 'alt_supervisor_cv_' + (j + 1);
      if (!prepState.docs[dk] || !prepState.docs[dk].ready) {
        prepState.docs[dk] = { url: '', fileName: altSupervisorNames[j] + ' — CV', ready: false, supervisorName: altSupervisorNames[j] };
      }
    }
    prepState.updatedAt = new Date().toISOString();
    fullState.gp_prepared_docs = JSON.stringify(prepState);
    await supabaseDbRequest('user_state', 'user_id=eq.' + encodeURIComponent(userId), {
      method: 'PATCH', body: { state: fullState, updated_at: new Date().toISOString() }
    });
    console.log('[SPPA] Created alt supervisor CV placeholders for', altSupervisorNames.length, 'supervisor(s)');
  } catch (err) {
    console.error('[SPPA] Alt supervisor CV placeholder creation error:', err.message);
  }
}

// Helper: when a returned SPPA-00 names alternate supervisor(s) whose signed CV GP Link does NOT
// yet hold, create an admin task carrying a SUGGESTED (pre-filled) email so the RSO can review and
// SEND it to the practice manually from the dashboard composer. It does NOT auto-send. Idempotent
// by three guards: (1) an in-process per-case lock so two overlapping triggers (Gmail push, hourly
// reconcile, manual "pull reply now") can't both create a task; (2) an open alt_supervisor_cv_request
// task already exists; (3) the CV is already in hand — arrived with the form (tagged on the SPPA
// task) or already on the GP's profile. Deliberately does NOT write the SPPA task's metadata, to
// avoid racing the concurrent completeness-check verdict. `sppaTask` must carry
// { id, case_id, metadata, gmail_thread_id }.
var _altCvRequestInflight = {};
async function _ensureAltSupervisorCvRequest(caseId, sppaTask, altNames) {
  if (!caseId || !sppaTask || !sppaTask.id || !Array.isArray(altNames) || altNames.length === 0) return;
  if (_altCvRequestInflight[caseId]) return; // a request task for this case is already being created
  _altCvRequestInflight[caseId] = true;
  try {
    var meta = sppaTask.metadata;
    if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch (e) { meta = {}; } }
    if (!meta || typeof meta !== 'object') meta = {};

    // Don't double-create if an open request task already exists for this case.
    var existingReq = await supabaseDbRequest('registration_tasks',
      'select=id&case_id=eq.' + encodeURIComponent(caseId) + '&task_type=eq.alt_supervisor_cv_request&status=neq.completed&limit=1');
    if (existingReq.ok && Array.isArray(existingReq.data) && existingReq.data.length > 0) return;

    // If every named alternate's CV already arrived with the form, there is nothing to request.
    var heldCvs = await supabaseDbRequest('task_documents',
      'select=id&task_id=eq.' + encodeURIComponent(sppaTask.id) + '&category=eq.alt_supervisor_cv&is_current=eq.true');
    var heldCount = (heldCvs.ok && Array.isArray(heldCvs.data)) ? heldCvs.data.length : 0;
    if (heldCount >= altNames.length) return;

    var caseRes = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
    var userId = (caseRes.ok && caseRes.data && caseRes.data[0]) ? caseRes.data[0].user_id : null;

    // Alternates whose signed CV is already on the GP's profile need no chase.
    var onFileNames = [];
    if (userId) {
      var udRes = await supabaseDbRequest('user_documents',
        'select=file_name,status&user_id=eq.' + encodeURIComponent(userId) + '&document_key=like.alt_supervisor_cv_%25&status=in.(approved,uploaded)');
      if (udRes.ok && Array.isArray(udRes.data)) {
        onFileNames = udRes.data.map(function (d) { return String(d.file_name || '').replace(/\s*[—-]\s*CV\s*$/i, '').trim(); }).filter(Boolean);
      }
    }
    var altReqLib = require('./lib/sppa-alt-supervisor-request.js');
    var needed = altReqLib.altSupervisorsNeedingCv(altNames, onFileNames);
    if (needed.length === 0) return;

    // Practice contact (same precedence as /sppa-send-to-practice: where we sent the pack, else the
    // placed application's contact, else the practice record's own).
    var practiceEmail = String(meta.sent_to_practice_email || '').trim();
    var practiceName = 'Practice Contact';
    if (userId) {
      var appContactRow = await resolvePlacedPracticeContact(userId);
      if (appContactRow) {
        if (!practiceEmail) practiceEmail = appContactRow.email;
        if (appContactRow.name) practiceName = appContactRow.name;
      }
    }
    if (!practiceEmail) { console.warn('[SPPA] alt-CV request skipped — no practice email for case', caseId); return; }

    // GP display name (mirror /sppa-send-to-practice).
    var gpName = '';
    if (userId) {
      var profRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
      var prof = (profRes.ok && profRes.data && profRes.data[0]) ? profRes.data[0] : {};
      gpName = ((prof.first_name || '') + ' ' + (prof.last_name || '')).trim();
    }
    if (!gpName) gpName = String(meta.candidate_name || 'the candidate').trim();

    var rsoName = '';
    try { rsoName = await resolveCaseSenderName(caseId); } catch (e) {}
    var emailContent = altReqLib.buildAltCvRequestEmail({
      gpName: gpName, altNames: needed, contactName: practiceName, rsoSignoffName: rsoName || ''
    });

    // Do NOT auto-send. Create an admin task carrying a SUGGESTED (pre-filled) email for the RSO to
    // review and SEND manually from the dashboard composer (the generic /api/admin/email/send). The
    // task's existence is the idempotency guard for later triggers; it stays open until the
    // practice's CV arrives (auto-match closes it) or the RSO delivers it.
    await supabaseDbRequest('registration_tasks', '', {
      method: 'POST', headers: { Prefer: 'return=minimal' },
      body: [{
        case_id: caseId, task_type: 'alt_supervisor_cv_request', related_document_key: 'sppa_00',
        related_stage: 'ahpra',
        title: 'Request alternate supervisor CV from practice',
        description: 'Send the practice a request for the signed CV(s): ' + needed.join(', '),
        status: 'open', priority: 'normal',
        gmail_thread_id: sppaTask.gmail_thread_id || null,
        metadata: {
          sppa_task_id: sppaTask.id,
          alt_supervisor_names: needed,
          practice_email: practiceEmail,
          practice_contact_name: practiceName,
          suggested_subject: emailContent.subject,
          suggested_body: emailContent.bodyHtml,
          created_at: new Date().toISOString()
        }
      }]
    });
    await _logCaseEvent(caseId, sppaTask.id, 'system',
      'Created task to request alternate supervisor CV(s) from practice (RSO to review + send): ' + needed.join(', '), practiceEmail, 'system');
    console.log('[SPPA] Created alt supervisor CV request task for case', caseId, '→', needed.join(', '));
  } catch (err) {
    console.error('[SPPA] _ensureAltSupervisorCvRequest error:', err.message);
  } finally {
    delete _altCvRequestInflight[caseId];
  }
}

// ── AHPRA conflict-of-interest letter task ──────────────────────────────────
// Creates a single admin task (ahpra_conflict_letter) pre-filled with a
// suggested email to the medical practice asking them to send a conflict-
// management statement directly to the AHPRA officer. Idempotent: always safe
// to call; the first guard is the inflight lock, then an open-task existence
// check, then the shouldEnsureConflictLetter gate.
var _ahpraConflictLetterInflight = {};
async function _ensureAhpraConflictLetter(caseId, opts) {
  opts = opts || {};
  if (!caseId) return null;
  if (_ahpraConflictLetterInflight[caseId]) {
    try { return await _ahpraConflictLetterInflight[caseId]; } catch (e) { return null; }
  }
  var _clPromise = (async function () {
    try {
      // 1) Reuse any existing open task (idempotency guard).
      var existingTask = await supabaseDbRequest('registration_tasks',
        'select=id,metadata,status&case_id=eq.' + encodeURIComponent(caseId) +
        '&task_type=eq.ahpra_conflict_letter&status=neq.completed&limit=1');
      if (existingTask.ok && Array.isArray(existingTask.data) && existingTask.data[0]) {
        var existingTask0 = existingTask.data[0];
        var existingMeta = existingTask0.metadata;
        if (typeof existingMeta === 'string') { try { existingMeta = JSON.parse(existingMeta); } catch (e) { existingMeta = {}; } }
        existingMeta = existingMeta || {};
        if (opts.officerRequestMessageId && !existingMeta.officer_request_message_id) {
          existingMeta.officer_request_message_id = opts.officerRequestMessageId;
          await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(existingTask0.id),
            { method: 'PATCH', body: { metadata: existingMeta } });
        }
        return existingTask0;
      }
      // 2) Read conflict flag + supervisor name from the SPPA-00 task.
      var sppaRes = await supabaseDbRequest('registration_tasks',
        'select=metadata&case_id=eq.' + encodeURIComponent(caseId) +
        '&task_type=eq.practice_pack_child&related_document_key=eq.sppa_00&limit=1');
      var sMeta = (sppaRes.ok && sppaRes.data && sppaRes.data[0]) ? sppaRes.data[0].metadata : null;
      if (typeof sMeta === 'string') { try { sMeta = JSON.parse(sMeta); } catch (e) { sMeta = {}; } }
      sMeta = sMeta || {};
      var officerEmail = String(opts.officerEmail || '').trim();
      if (!shouldEnsureConflictLetter({ hasConflict: sMeta.is_conflict === true, officerEmail: officerEmail })) return null;
      // 3) Case → user_id + practice_name.
      var caseRow2 = await supabaseDbRequest('registration_cases',
        'select=user_id,practice_name&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
      var cRow = (caseRow2.ok && caseRow2.data && caseRow2.data[0]) ? caseRow2.data[0] : {};
      var userId = cRow.user_id || null;
      var practiceName = String(cRow.practice_name || sMeta.practice_owner_name || '').trim();
      // 4) GP display name from user_profiles (mirror alt-CV path).
      var gpName = '';
      if (userId) {
        var profRes2 = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
        var prof2 = (profRes2.ok && profRes2.data && profRes2.data[0]) ? profRes2.data[0] : {};
        gpName = ((prof2.first_name || '') + ' ' + (prof2.last_name || '')).trim();
      }
      if (!gpName) gpName = String(sMeta.candidate_name || 'the candidate').trim();
      // 5) Practice contact (same precedence as alt-CV path).
      var practiceEmail = '';
      var practiceContactName = 'Practice Contact';
      if (userId) {
        // gp_applications has NO practice_name column — asking for it 400'd the whole
        // query, so practiceEmail stayed empty and this letter was ALWAYS skipped.
        // Practice name comes from career_roles, never here.
        var appContact2 = await resolvePlacedPracticeContact(userId);
        if (appContact2) {
          practiceEmail = appContact2.email;
          if (appContact2.name) practiceContactName = appContact2.name;
        }
      }
      if (!practiceEmail) { console.warn('[ahpra-conflict-letter] skipped — no practice email for case', caseId); return null; }
      // 6) RSO CC mailbox + signoff name (same helpers as alt-CV path).
      var ccEmail = '';
      try { ccEmail = await resolveCaseSenderEmail(caseId); } catch (e) {}
      var rsoSignoffName2 = '';
      try { rsoSignoffName2 = await resolveCaseSenderName(caseId); } catch (e) {}
      // 7) Build suggested email + create admin task.
      var officerName = String(opts.officerName || sMeta.ahpra_officer_name || '').trim();
      var conflictEmail = buildConflictLetterEmail({
        gpName: gpName, supervisorName: sMeta.supervisor_name || '',
        practiceName: practiceName, contactName: practiceContactName,
        officerName: officerName, officerEmail: officerEmail, ccEmail: ccEmail, rsoSignoffName: rsoSignoffName2
      });
      var conflictTaskMeta = {
        suggested_subject: conflictEmail.subject, suggested_body: conflictEmail.bodyHtml,
        practice_email: practiceEmail, practice_contact_name: practiceContactName,
        ahpra_officer_name: officerName, ahpra_officer_email: officerEmail,
        cc_mailbox: ccEmail, gp_name: gpName, supervisor_name: sMeta.supervisor_name || '',
        practice_name: practiceName
      };
      if (opts.officerRequestMessageId) conflictTaskMeta.officer_request_message_id = opts.officerRequestMessageId;
      var conflictTask = await _createRegTask(caseId, {
        task_type: 'ahpra_conflict_letter',
        title: 'Conflict of interest — ask practice to email AHPRA officer',
        source_trigger: opts.officerRequestMessageId ? 'officer_request' : 'officer_assigned',
        related_stage: 'ahpra', related_document_key: 'sppa_00', status: 'open', priority: 'high',
        metadata: conflictTaskMeta, _actor: 'system'
      });
      console.log('[ahpra-conflict-letter] Created conflict-letter task for case', caseId);
      return conflictTask;
    } catch (e) { console.error('[ahpra-conflict-letter] ensure failed:', e.message); return null; }
  })();
  _ahpraConflictLetterInflight[caseId] = _clPromise;
  try { return await _clPromise; }
  finally { delete _ahpraConflictLetterInflight[caseId]; }
}

/**
 * Deliver matched alternate-supervisor CV(s) onto the case: create the
 * alt_supervisor_cv_review task + task_documents + inbound task_message + case
 * event, and close the open alt_supervisor_cv_request chase task. Shared by BOTH
 * the realtime Gmail path and the deterministic backstop (recoverAltSupervisorCvReply)
 * so the two can never diverge.
 *
 * IDEMPOTENCY (the key guard): the FIRST action is a (case_id, gmail_message_id)
 * task_messages lookup. If this Gmail message was already delivered, we DO NOT create
 * a second review task / duplicate docs — we reuse the existing review task and STILL
 * re-issue the (idempotent) request-close PATCH, so a partially-applied prior delivery
 * (review task created but close failed) self-heals on the next pass.
 *
 * matchedCvs entries: { filename, mimeType, b64, cvName, matchedSupervisor, confidence }.
 * Returns { review_task_id, deduped? }.
 */
async function _deliverAltSupervisorCvMatch(caseId, sppaTaskId, matchedCvs, emailMeta, gmailMsgId, mailbox) {
  if (!caseId || !Array.isArray(matchedCvs) || matchedCvs.length === 0) return { review_task_id: null };
  emailMeta = emailMeta || {};
  var _closeRequest = async function () {
    await supabaseDbRequest('registration_tasks',
      'case_id=eq.' + encodeURIComponent(caseId) + '&task_type=eq.alt_supervisor_cv_request&status=neq.completed',
      { method: 'PATCH', body: { status: 'completed', completed_at: new Date().toISOString(), updated_at: new Date().toISOString() } }).catch(function () {});
  };
  // 1) Idempotency FIRST — if this message is already ingested for the case, reuse + self-heal.
  if (gmailMsgId) {
    var _dup = await supabaseDbRequest('task_messages',
      'select=task_id&case_id=eq.' + encodeURIComponent(caseId) + '&gmail_message_id=eq.' + encodeURIComponent(gmailMsgId) + '&limit=1');
    if (_dup.ok && Array.isArray(_dup.data) && _dup.data[0]) {
      await _closeRequest(); // self-heal: ensure the request task is closed even if a prior pass missed it
      return { review_task_id: _dup.data[0].task_id || null, deduped: true };
    }
  }
  // 2) Create the review task.
  var _reviewRes = await supabaseDbRequest('registration_tasks', '', {
    method: 'POST', headers: { Prefer: 'return=representation' },
    body: [{
      case_id: caseId, task_type: 'alt_supervisor_cv_review', related_document_key: 'sppa_00',
      title: 'Review alternate supervisor CV(s)',
      description: matchedCvs.map(function (c) { return c.cvName + ' → ' + c.matchedSupervisor; }).join(', '),
      status: 'open', priority: 'normal',
      metadata: {
        sppa_task_id: sppaTaskId || null,
        matched_cvs: matchedCvs.map(function (c) { return { cvName: c.cvName, matchedSupervisor: c.matchedSupervisor, confidence: c.confidence, filename: c.filename }; })
      }
    }]
  });
  var _reviewTask = (_reviewRes.ok && _reviewRes.data && _reviewRes.data[0]) ? _reviewRes.data[0] : null;
  if (!_reviewTask) return { review_task_id: null };
  // 3) Store CV(s) as task_documents.
  for (var _i = 0; _i < matchedCvs.length; _i++) {
    var _mc = matchedCvs[_i];
    await supabaseDbRequest('task_documents', '', {
      method: 'POST', body: [{
        task_id: _reviewTask.id, case_id: caseId,
        filename: _mc.filename, mime_type: _mc.mimeType, size_bytes: Math.ceil((_mc.b64 || '').length * 3 / 4),
        version: 1, is_current: true, uploaded_by: 'email_auto_alt_cv',
        attachment_url: 'data:' + (_mc.mimeType || 'application/octet-stream') + ';base64,' + (_mc.b64 || ''),
        category: 'alt_supervisor_cv'
      }]
    });
  }
  // 4) Record the inbound message + case event.
  await supabaseDbRequest('task_messages', '', {
    method: 'POST', body: [{
      task_id: _reviewTask.id, case_id: caseId, direction: 'inbound', channel: 'email',
      sender: emailMeta.sender || '', recipient: emailMeta.to || mailbox || '', subject: emailMeta.subject || '',
      body_text: (emailMeta.bodyText || '').substring(0, 50000), body_html: emailMeta.bodyHtml || null,
      rfc822_message_id: emailMeta.rfc822MessageId || null, rfc822_references: emailMeta.rfc822References || null, cc: emailMeta.cc || null,
      gmail_message_id: gmailMsgId || null, gmail_thread_id: emailMeta.threadId || null,
      attachments: JSON.stringify((emailMeta.attachments || []).map(function (a) { return a && a.filename; }).filter(Boolean)),
      is_document_delivery: true, ai_match_confidence: matchedCvs[0].confidence
    }]
  });
  await _logCaseEvent(caseId, _reviewTask.id, 'system',
    matchedCvs.length + ' alt supervisor CV(s) received from practice — review needed',
    matchedCvs.map(function (c) { return c.cvName + ' matched to ' + c.matchedSupervisor; }).join('; '), 'system');
  // 5) Close the open request chase task (idempotent).
  await _closeRequest();
  return { review_task_id: _reviewTask.id };
}

// Helper: update gp_prepared_docs state so My Documents shows a GP LINK doc as "Ready"
async function _updatePreparedDocsState(userId, docKey, driveFileId, fileName) {
  const driveUrl = driveFileId ? 'https://drive.google.com/file/d/' + driveFileId + '/view' : '';
  const stateRes = await supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  let fullState = (stateRes.ok && Array.isArray(stateRes.data) && stateRes.data[0] && stateRes.data[0].state) ? stateRes.data[0].state : {};
  if (typeof fullState === 'string') try { fullState = JSON.parse(fullState); } catch { fullState = {}; }
  let prepState = fullState.gp_prepared_docs;
  if (typeof prepState === 'string') try { prepState = JSON.parse(prepState); } catch { prepState = {}; }
  if (!prepState || typeof prepState !== 'object') prepState = { docs: {} };
  if (!prepState.docs) prepState.docs = {};
  prepState.docs[docKey] = { url: driveUrl, fileName: fileName || '', ready: true, uploadedAt: new Date().toISOString() };
  prepState.updatedAt = new Date().toISOString();
  fullState.gp_prepared_docs = JSON.stringify(prepState);
  await supabaseDbRequest('user_state', 'user_id=eq.' + encodeURIComponent(userId), {
    method: 'PATCH', body: { state: fullState, updated_at: new Date().toISOString() }
  });
}

// ── Contract AI utilities ──

async function diffContracts(oldBuffer, oldMime, newBuffer, newMime) {
  if (!process.env.ANTHROPIC_API_KEY) return '';

  function docBlock(buf, mime) {
    var data = buf.toString('base64');
    var normalizedMime = mime;
    if (mime === 'image/heic' || mime === 'image/heif') normalizedMime = 'image/jpeg';
    if (mime === 'application/pdf') {
      return { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: data } };
    } else if (normalizedMime.startsWith('image/')) {
      return { type: 'image', source: { type: 'base64', media_type: normalizedMime, data: data } };
    } else if (mime === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      return { type: 'document', source: { type: 'base64', media_type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', data: data } };
    } else {
      return { type: 'document', source: { type: 'base64', media_type: mime, data: data } };
    }
  }

  try {
    var contentBlocks = [
      { type: 'text', text: 'PREVIOUS VERSION:' },
      docBlock(oldBuffer, oldMime),
      { type: 'text', text: 'NEW VERSION:' },
      docBlock(newBuffer, newMime),
      { type: 'text', text: 'Compare the two contract versions above and provide a concise summary of the key differences. Focus on changes to terms, conditions, dates, amounts, parties, or any other material changes. Be brief and specific.' }
    ];

    var controller = new AbortController();
    var timeout = setTimeout(function () { controller.abort(); }, 90000);
    var resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: ANTHROPIC_MODEL,
        max_tokens: 500,
        messages: [{ role: 'user', content: contentBlocks }]
      })
    });
    clearTimeout(timeout);

    if (!resp.ok) {
      console.error('[ContractDiff] API error', resp.status);
      return '';
    }

    var respJson = await resp.json();
    var text = (respJson.content && respJson.content[0] && respJson.content[0].text) || '';
    var trimmed = text.trim();
    console.log('[ContractDiff] diff length:', trimmed.length);
    return trimmed;
  } catch (e) {
    console.error('[ContractDiff] error:', e.message);
    return '';
  }
}

// ── Task 11: AI contract review vs Zoom-summary terms ──
// Compares an uploaded practice employment contract against (1) what was
// actually discussed in the interview (the Zoom meeting_summary — the
// SOURCE OF TRUTH when it exists, superseding the advertised listing) and
// (2) the advertised/offer terms. Writes the verdict onto the
// career_contracts row (ai_review, ai_review_status, terms_context) so both
// the practice-facing flow and a CEO re-run endpoint can read it back.
//
// Never throws — every failure path (no API key, file missing, API error,
// bad JSON) still PATCHes ai_review_status:'error' with a usable stub
// ai_review so the row is never left half-written and callers never have to
// special-case a thrown error.
function _contractAiBlankExtractedTerms() {
  return {
    billing_split: null,
    base_or_guarantee: null,
    sessions_per_week: null,
    start_date: null,
    leave: null,
    restraint: null,
    other: []
  };
}

async function aiReviewCareerContract(contractRow) {
  var contract = contractRow && typeof contractRow === 'object' ? contractRow : {};
  var contractId = String(contract.id || '').trim();

  async function persist(reviewObj, status, termsContext) {
    if (!contractId || !isSupabaseDbConfigured()) return;
    try {
      await supabaseDbRequest('career_contracts', 'id=eq.' + encodeURIComponent(contractId), {
        method: 'PATCH',
        headers: { Prefer: 'return=minimal' },
        body: { ai_review: reviewObj, ai_review_status: status, terms_context: termsContext, updated_at: new Date().toISOString() }
      });
    } catch (e) {
      console.error('[contract-ai] persist failed for contract', contractId, ':', e && e.message);
    }
  }

  // ── Gather comparison context up front — used both for the prompt and
  // (via terms_context) so a CEO reviewing the verdict can see exactly what
  // was compared without re-deriving it. Each lookup is independently
  // guarded so one missing source (e.g. Zoom never configured) never blocks
  // the others.
  var interviewSummary = null;
  try {
    if (contract.application_id) {
      var ivRes = await supabaseDbRequest('scheduled_calls',
        'select=meeting_summary&application_id=eq.' + encodeURIComponent(String(contract.application_id)) +
        '&meeting_kind=eq.interview&status=eq.completed&order=scheduled_at.desc&limit=1');
      var ivRow = (ivRes.ok && Array.isArray(ivRes.data) && ivRes.data[0]) ? ivRes.data[0] : null;
      var ivSummary = ivRow && typeof ivRow.meeting_summary === 'string' ? ivRow.meeting_summary.trim() : '';
      interviewSummary = ivSummary || null;
    }
  } catch (e) { console.error('[contract-ai] interview summary lookup failed:', e && e.message); }

  var offerTerms = null;
  try {
    if (contract.application_id) {
      var offerRow = await atsOffersStore.getAtsOfferByApplication(String(contract.application_id));
      if (offerRow) {
        offerTerms = {
          billing_split: offerRow.billing_split || null,
          compensation_range: offerRow.compensation_range || null,
          compensation_note: offerRow.compensation_note || null,
          sessions_per_week: offerRow.sessions_per_week || null,
          start_date: offerRow.start_date || null
        };
      }
    }
  } catch (e) { console.error('[contract-ai] offer terms lookup failed:', e && e.message); }

  var listingTerms = null;
  try {
    if (contract.career_role_id) {
      var roleRow = await getCareerRoleRowById(contract.career_role_id);
      if (roleRow) {
        var gpLinkMeta = getCareerRoleGpLinkMeta(roleRow);
        listingTerms = {
          title: roleRow.title || null,
          billing_model: roleRow.billing_model || null,
          publicIntro: gpLinkMeta.publicIntro || null,
          publicBenefits: Array.isArray(gpLinkMeta.publicBenefits) ? gpLinkMeta.publicBenefits : []
        };
      }
    }
  } catch (e) { console.error('[contract-ai] listing terms lookup failed:', e && e.message); }

  // If no interview summary exists, comparison is against the advertised/
  // offer terms only — deterministic, never left to the model to get right.
  var interviewTermsAvailable = !!interviewSummary;
  var termsContext = { interview_summary: interviewSummary, offer_terms: offerTerms, listing_terms: listingTerms };

  // No API key configured (local dev / preview without the secret) — never
  // explode; store a clearly-labelled stub so the UI has something sane to
  // show and CEOs know a real review hasn't run yet.
  if (!process.env.ANTHROPIC_API_KEY) {
    var noKeyReview = {
      overall: 'unreadable',
      summary: 'AI review unavailable — no API key configured.',
      extracted_terms: _contractAiBlankExtractedTerms(),
      discrepancies: [],
      interview_terms_available: interviewTermsAvailable
    };
    await persist(noKeyReview, 'error', termsContext);
    return { ai_review_status: 'error', ai_review: noKeyReview };
  }

  // Download the contract file itself.
  var fileObj = null;
  try {
    if (contract.contract_bucket && contract.contract_path) {
      fileObj = await supabaseStorageDownloadObject(contract.contract_bucket, contract.contract_path);
    }
  } catch (e) { console.error('[contract-ai] contract download failed:', e && e.message); }

  if (!fileObj || !fileObj.buffer || !fileObj.buffer.length) {
    var noFileReview = {
      overall: 'unreadable',
      summary: 'Could not read the uploaded contract file.',
      extracted_terms: _contractAiBlankExtractedTerms(),
      discrepancies: [],
      interview_terms_available: interviewTermsAvailable
    };
    await persist(noFileReview, 'error', termsContext);
    return { ai_review_status: 'error', ai_review: noFileReview };
  }

  function docBlock(buf, mime) {
    var data = buf.toString('base64');
    var normalizedMime = String(mime || contract.contract_mime || 'application/pdf').trim() || 'application/pdf';
    return { type: 'document', source: { type: 'base64', media_type: normalizedMime, data: data } };
  }

  var promptText = 'You are checking an employment contract a practice uploaded for a GP placement.\n' +
    'Compare the contract against (1) the terms discussed in the interview (the Zoom\n' +
    'meeting summary below) and (2) the advertised job terms. Where interview terms\n' +
    'and the advertised terms differ, THE INTERVIEW TERMS SUPERSEDE the listing.\n' +
    'If no interview summary is provided, compare against the advertised/offer terms\n' +
    'only and set interview_terms_available=false.\n' +
    'Respond with ONLY JSON matching: {overall, summary, extracted_terms:{...}, discrepancies:[...], interview_terms_available}';

  var contentBlocks = [
    { type: 'text', text: 'EMPLOYMENT CONTRACT (uploaded by the practice):' },
    docBlock(fileObj.buffer, contract.contract_mime || fileObj.mimeType),
    { type: 'text', text: 'INTERVIEW SUMMARY (Zoom meeting — supersedes the advertised terms where they differ):\n' + (interviewSummary || '(No interview summary is available for this application.)') },
    { type: 'text', text: 'OFFER RECORD (the offer GP Link sent to the candidate):\n' + JSON.stringify(offerTerms || {}) },
    { type: 'text', text: 'ADVERTISED JOB LISTING TERMS:\n' + JSON.stringify(listingTerms || {}) },
    { type: 'text', text: promptText }
  ];

  var reviewResult;
  var status;
  try {
    var controller = new AbortController();
    // Must stay below vercel.json functions maxDuration (60s) so the
    // abort/error path actually runs — the platform would otherwise kill the
    // invocation before a 90s timeout could ever fire, silently skipping the
    // persisted 'error' status and CEO notification.
    var timeout = setTimeout(function () { controller.abort(); }, 45000);
    var resp;
    try {
      resp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        signal: controller.signal,
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: ANTHROPIC_SCAN_MODEL,
          max_tokens: 1500,
          // No temperature — ANTHROPIC_SCAN_MODEL defaults to claude-opus-4-8,
          // which REJECTS temperature/top_p/top_k with a 400. Every other
          // scan caller already omits it; this one must too.
          messages: [{ role: 'user', content: contentBlocks }]
        })
      });
    } finally {
      clearTimeout(timeout);
    }

    if (!resp || !resp.ok) {
      throw new Error('Anthropic API error ' + (resp && resp.status));
    }
    var respJson = await resp.json();
    var text = (respJson.content && respJson.content[0] && respJson.content[0].text) || '';
    var cleaned = text.trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();
    var parsed = JSON.parse(cleaned);
    if (!parsed || typeof parsed !== 'object') throw new Error('AI response was not a JSON object');

    var overallRaw = parsed.overall;
    var overall = ['aligned', 'minor_gaps', 'major_discrepancies', 'unreadable'].indexOf(overallRaw) !== -1 ? overallRaw : 'unreadable';
    reviewResult = {
      overall: overall,
      summary: String(parsed.summary || ''),
      extracted_terms: Object.assign(_contractAiBlankExtractedTerms(), (parsed.extracted_terms && typeof parsed.extracted_terms === 'object') ? parsed.extracted_terms : {}),
      discrepancies: Array.isArray(parsed.discrepancies) ? parsed.discrepancies : [],
      // Deterministic, not left to the model: true only when a real
      // interview summary actually existed to compare against.
      interview_terms_available: interviewTermsAvailable
    };
    status = 'done';
  } catch (e) {
    console.error('[contract-ai] review error for contract', contractId, ':', e && e.message);
    reviewResult = {
      overall: 'unreadable',
      summary: 'AI review failed: ' + (e && e.message ? e.message : 'unknown error'),
      extracted_terms: _contractAiBlankExtractedTerms(),
      discrepancies: [],
      interview_terms_available: interviewTermsAvailable
    };
    status = 'error';
  }

  await persist(reviewResult, status, termsContext);
  return { ai_review_status: status, ai_review: reviewResult };
}

