// Delivered offer/contract documents (GP_LINK_DOCUMENT_META source 'gplink_pack').
// Kept as a SEPARATE set from PREPARED_DOCUMENT_KEYS on purpose: these are
// delivered BY the GP Link team (deliverToMyDocuments / POST /api/ats/offer),
// never uploaded by the GP, so they are readable through GET
// /api/prepared-documents + its /download endpoint WITHOUT ever becoming a
// "You prepare" upload slot — the PUT/DELETE handlers and the upload pages keep
// validating against PREPARED_DOCUMENT_KEYS only.
const OFFER_DOCUMENT_KEYS = new Set(['offer_contract']);
const ONBOARDING_DOCUMENT_KEYS = new Set([
  'onboarding_specialist_qualification',
  'onboarding_cct_certificate',
  'onboarding_primary_med_degree'
]);
const ACCOUNT_CAREER_DOCUMENT_COUNTRY = 'AU';
const ACCOUNT_CAREER_DOCUMENT_MAX_FILE_BYTES = 10 * 1024 * 1024;
const ACCOUNT_CAREER_DOCUMENT_ALLOWED_MIME_TYPES = new Set([
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
]);
const ACCOUNT_CAREER_DOCUMENT_TYPES = Object.freeze({
  cv: { key: 'cv_signed_dated', label: 'Most current CV', zohoCategory: 'Resume', fallbackFileName: 'resume.pdf' },
  coverLetter: { key: 'career_cover_letter', label: 'Cover letter', zohoCategory: 'Cover Letter', fallbackFileName: 'cover-letter.pdf' }
});
const ACCOUNT_CAREER_DOCUMENT_KEYS = new Set(
  Object.values(ACCOUNT_CAREER_DOCUMENT_TYPES).map((entry) => entry.key)
);

function getAccountCareerDocumentType(value) {
  const normalized = String(value || '').trim();
  return Object.prototype.hasOwnProperty.call(ACCOUNT_CAREER_DOCUMENT_TYPES, normalized)
    ? normalized
    : '';
}

function getAccountCareerDocumentTypeByKey(key) {
  const normalizedKey = String(key || '').trim();
  return Object.keys(ACCOUNT_CAREER_DOCUMENT_TYPES).find((type) => {
    return ACCOUNT_CAREER_DOCUMENT_TYPES[type].key === normalizedKey;
  }) || '';
}

function inferAccountCareerDocumentMimeType(fileName, mimeType) {
  const rawMime = String(mimeType || '').trim().toLowerCase();
  if (ACCOUNT_CAREER_DOCUMENT_ALLOWED_MIME_TYPES.has(rawMime)) return rawMime;
  const normalizedName = String(fileName || '').trim().toLowerCase();
  if (normalizedName.endsWith('.pdf')) return 'application/pdf';
  if (normalizedName.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  if (normalizedName.endsWith('.doc')) return 'application/msword';
  return rawMime || 'application/octet-stream';
}

function buildAccountCareerDocumentLocalSignature(row) {
  if (!row || typeof row !== 'object') return '';
  return [
    String(row.file_name || '').trim(),
    String(row.updated_at || '').trim(),
    String(row.mime_type || '').trim(),
    String(row.file_size || '').trim()
  ].join('|');
}

function normalizeDocumentCountry(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return '';
  if (raw === 'uk' || raw === 'gb' || raw === 'united kingdom') return 'uk';
  if (raw === 'ie' || raw === 'ireland') return 'ie';
  if (raw === 'nz' || raw === 'new zealand') return 'nz';
  return '';
}

// Which country's document set a GP's cards and uploads belong to. Kept as one
// shared resolver because user_documents rows are keyed by
// (user_id, document_key, country_code): a caller that resolves the country even
// slightly differently writes a row the reading card never looks up, so the
// upload silently vanishes. State values can also arrive double-stringified
// (e.g. "\"United Kingdom\""). Defaults to 'uk'.
function resolveGpDocumentCountry(profileCountry, stateCountry) {
  let raw = profileCountry || stateCountry || 'uk';
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      if (typeof parsed === 'string') raw = parsed;
    } catch (e) { /* not JSON-wrapped — use the raw value */ }
  }
  return normalizeDocumentCountry(raw) || 'uk';
}

function sanitizeStoredDocumentPayload(body, allowedKeys) {
  const input = body && typeof body === 'object' ? body : {};
  const country = normalizeDocumentCountry(input.country);
  const key = sanitizeUserString(input.key, 120);
  const fileName = sanitizeUserString(input.fileName, 240);
  const mimeType = sanitizeUserString(input.mimeType, 160);
  const fileSize = Math.max(0, Math.min(Number(input.fileSize || 0), 25 * 1024 * 1024));
  const fileDataUrl = typeof input.fileDataUrl === 'string' ? input.fileDataUrl.trim() : '';
  if (!country || !key || !(allowedKeys instanceof Set) || !allowedKeys.has(key)) return null;
  if (!fileName || !mimeType || !fileDataUrl) return null;
  if (!fileDataUrl.startsWith('data:') || !/;base64,/i.test(fileDataUrl)) return null;
  if (fileDataUrl.length > PREPARED_DOCUMENT_MAX_DATA_URL_LENGTH) return null;
  return {
    country,
    key,
    fileName,
    mimeType,
    fileSize,
    fileDataUrl,
    updatedAt: new Date().toISOString()
  };
}

function sanitizePreparedDocumentPayload(body) {
  return sanitizeStoredDocumentPayload(body, PREPARED_DOCUMENT_KEYS);
}

function sanitizeOnboardingDocumentPayload(body) {
  return sanitizeStoredDocumentPayload(body, ONBOARDING_DOCUMENT_KEYS);
}

function sanitizeStoragePathSegment(value, maxLen = 120) {
  return String(value || '')
    .trim()
    .slice(0, maxLen)
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'file';
}

function encodeSupabaseObjectPath(objectPath) {
  return String(objectPath || '')
    .split('/')
    .filter(Boolean)
    .map((segment) => encodeURIComponent(segment))
    .join('/');
}

function parseDataUrlPayload(dataUrl) {
  const raw = String(dataUrl || '').trim();
  const match = raw.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return null;
  try {
    return {
      mimeType: match[1] || 'application/octet-stream',
      buffer: Buffer.from(match[2], 'base64')
    };
  } catch (err) {
    return null;
  }
}

function buildPreparedDocumentStoragePath(userId, country, key) {
  return [
    'users',
    sanitizeStoragePathSegment(userId, 80),
    'prepared-documents',
    sanitizeStoragePathSegment(country, 20),
    sanitizeStoragePathSegment(key, 120),
    'current'
  ].join('/');
}

function buildOnboardingDocumentStoragePath(userId, country, key) {
  return [
    'users',
    sanitizeStoragePathSegment(userId, 80),
    'onboarding-documents',
    sanitizeStoragePathSegment(country, 20),
    sanitizeStoragePathSegment(key, 120),
    'current'
  ].join('/');
}

function buildAccountCareerDocumentStoragePath(userId, key) {
  return [
    'users',
    sanitizeStoragePathSegment(userId, 80),
    'account-career-documents',
    sanitizeStoragePathSegment(ACCOUNT_CAREER_DOCUMENT_COUNTRY, 20).toLowerCase(),
    sanitizeStoragePathSegment(key, 120),
    'current'
  ].join('/');
}

// Careers profile gate (Task 3) — CV / cover-letter storage path. Unlike the
// account-career path above (fixed 'current' suffix, one object ever), each
// upload here gets its own timestamped object name so a rejected/replaced
// upload never clobbers bytes still referenced by an in-flight signed URL;
// the user_documents row (see saveCareerProfileDocument) is what actually
// tracks "current" via its own upsert.
function buildCareerProfileDocumentStoragePath(userId, key, fileName) {
  return [
    'account-career',
    sanitizeStoragePathSegment(ACCOUNT_CAREER_DOCUMENT_COUNTRY, 20).toLowerCase(),
    sanitizeStoragePathSegment(userId, 80),
    sanitizeStoragePathSegment(key, 60),
    `${Date.now()}-${sanitizeStoragePathSegment(fileName, 140)}`
  ].join('/');
}

function sanitizeAccountCareerDocumentPayload(body) {
  const input = body && typeof body === 'object' ? body : {};
  const type = getAccountCareerDocumentType(input.type);
  const config = type ? ACCOUNT_CAREER_DOCUMENT_TYPES[type] : null;
  const fileName = sanitizeUserString(input.fileName, 240);
  const mimeType = inferAccountCareerDocumentMimeType(input.fileName, sanitizeUserString(input.mimeType, 160));
  const fileSize = Math.max(0, Math.min(Number(input.fileSize || 0), ACCOUNT_CAREER_DOCUMENT_MAX_FILE_BYTES));
  const fileDataUrl = typeof input.fileDataUrl === 'string' ? input.fileDataUrl.trim() : '';
  if (!config || !fileName || !mimeType || !fileDataUrl) return null;
  if (!ACCOUNT_CAREER_DOCUMENT_ALLOWED_MIME_TYPES.has(mimeType)) return null;
  if (!fileDataUrl.startsWith('data:') || !/;base64,/i.test(fileDataUrl)) return null;
  const parsed = parseDataUrlPayload(fileDataUrl);
  const parsedMimeType = parsed && typeof parsed.mimeType === 'string'
    ? parsed.mimeType.toLowerCase()
    : '';
  if (!parsed) return null;
  if (parsedMimeType && parsedMimeType !== mimeType && parsedMimeType !== 'application/octet-stream') return null;
  if (!parsed.buffer || parsed.buffer.length === 0 || parsed.buffer.length > ACCOUNT_CAREER_DOCUMENT_MAX_FILE_BYTES) return null;
  return {
    type,
    key: config.key,
    label: config.label,
    fileName,
    mimeType,
    fileSize: parsed.buffer.length,
    fileDataUrl,
    updatedAt: new Date().toISOString()
  };
}

async function supabaseStorageUploadObject(bucket, objectPath, dataUrl, mimeType) {
  if (!isSupabaseDbConfigured()) return false;
  const parsed = parseDataUrlPayload(dataUrl);
  if (!parsed) return false;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await fetch(`${SUPABASE_URL}/storage/v1/object/${encodeURIComponent(bucket)}/${encodeSupabaseObjectPath(objectPath)}`, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
        'Content-Type': mimeType || parsed.mimeType || 'application/octet-stream',
        'x-upsert': 'true'
      },
      body: parsed.buffer
    }).catch(() => null);

    return !!(response && response.ok);
  } finally {
    clearTimeout(timeout);
  }
}

// Mint a short-lived signed upload URL so the BROWSER can PUT a file straight to
// Supabase Storage, bypassing Vercel's ~4.5 MB serverless request-body limit
// (a base64-in-JSON upload of a multi-MB scanned contract is rejected before the
// function even runs). Returns an absolute URL the browser PUTs the raw file to.
async function supabaseStorageCreateSignedUploadUrl(bucket, objectPath, options = {}) {
  if (!isSupabaseDbConfigured()) return '';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const signHeaders = {
      apikey: SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`
    };
    // Allow overwriting an existing object (e.g. re-uploading / replacing an
    // offer contract that was already stored). Without x-upsert, Supabase's
    // sign endpoint returns 409 "The resource already exists" and the upload
    // can never be prepared.
    if (options && options.upsert) signHeaders['x-upsert'] = 'true';
    const response = await fetch(`${SUPABASE_URL}/storage/v1/object/upload/sign/${encodeURIComponent(bucket)}/${encodeSupabaseObjectPath(objectPath)}`, {
      method: 'POST',
      signal: controller.signal,
      headers: signHeaders
    }).catch(() => null);
    if (!response || !response.ok) return '';
    const data = await response.json().catch(() => null);
    if (!data || typeof data.url !== 'string' || !data.url) return '';
    // data.url is a relative path like "/object/upload/sign/<bucket>/<path>?token=..."
    return `${SUPABASE_URL}/storage/v1${data.url}`;
  } catch (err) {
    return '';
  } finally {
    clearTimeout(timeout);
  }
}

async function supabaseStorageDeleteObject(bucket, objectPath) {
  if (!isSupabaseDbConfigured()) return false;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await fetch(`${SUPABASE_URL}/storage/v1/object/${encodeURIComponent(bucket)}/${encodeSupabaseObjectPath(objectPath)}`, {
      method: 'DELETE',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`
      }
    }).catch(() => null);
    return !!(response && response.ok);
  } finally {
    clearTimeout(timeout);
  }
}

async function supabaseStorageCreateSignedUrl(bucket, objectPath, fileName) {
  if (!isSupabaseDbConfigured()) return '';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await fetch(`${SUPABASE_URL}/storage/v1/object/sign/${encodeURIComponent(bucket)}/${encodeSupabaseObjectPath(objectPath)}`, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        expiresIn: 60 * 60,
        download: fileName || undefined
      })
    }).catch(() => null);
    if (!response || !response.ok) return '';
    const payload = await response.json().catch(() => null);
    const signedPath = payload && typeof payload.signedURL === 'string'
      ? payload.signedURL
      : (payload && typeof payload.signedUrl === 'string' ? payload.signedUrl : '');
    if (!signedPath) return '';
    return signedPath.startsWith('http') ? signedPath : `${SUPABASE_URL}/storage/v1${signedPath}`;
  } finally {
    clearTimeout(timeout);
  }
}

function buildSupabaseStoragePublicUrl(bucket, objectPath) {
  const bucketName = String(bucket || '').trim();
  const pathName = String(objectPath || '').trim();
  if (!SUPABASE_URL || !bucketName || !pathName) return '';
  return `${SUPABASE_URL}/storage/v1/object/public/${encodeURIComponent(bucketName)}/${encodeSupabaseObjectPath(pathName)}`;
}

// Storage objects answer on two hosts: the Supabase PROJECT host
// (<ref>.supabase.co) and the configured custom domain. Rows written by scripts
// running off a local .env stored the project host, so listings served images
// from a third-party-looking domain that is trivially blocked by iOS content
// blockers / Private Relay / corporate DNS — the practice photos then render as
// broken thumbnails with nothing wrong server-side (the URL still returns 200).
//
// Rewriting to SUPABASE_URL's origin serves every image from the same
// first-party domain the app already talks to, so nothing outside our control
// gets a say. No-op when SUPABASE_URL is the project host anyway (local/dev).
function normalizeSupabaseStorageUrl(value) {
  const raw = String(value || '').trim();
  if (!raw || !CSP_SUPABASE_ORIGIN) return raw;
  let parsed;
  try { parsed = new URL(raw); } catch { return raw; }
  if (!/(^|\.)supabase\.co$/i.test(parsed.host)) return raw;
  if (!parsed.pathname.startsWith('/storage/v1/')) return raw;
  if (parsed.origin === CSP_SUPABASE_ORIGIN) return raw;
  return CSP_SUPABASE_ORIGIN + parsed.pathname + parsed.search;
}

function mapPreparedDocumentRow(row, signedUrl = '') {
  if (!row || typeof row !== 'object') return null;
  return {
    fileName: typeof row.file_name === 'string' ? row.file_name : '',
    mimeType: typeof row.mime_type === 'string' ? row.mime_type : '',
    fileSize: Math.max(0, Number(row.file_size || 0)),
    storageBucket: typeof row.storage_bucket === 'string' ? row.storage_bucket : SUPABASE_DOCUMENT_BUCKET,
    storagePath: typeof row.storage_path === 'string' && row.storage_path
      ? row.storage_path
      : (typeof row.file_url === 'string' ? row.file_url : ''),
    downloadUrl: signedUrl,
    updatedAt: typeof row.updated_at === 'string' ? row.updated_at : null,
    // Authoritative review status (so the GP's "You Prepare" view reflects an RSO
    // approval/rejection instead of staying on the locally-cached "under review").
    status: toStatusLabel(row.status, !!(row.storage_path || row.file_url)),
    rejection_reason: row.rejection_reason || '',
    // Validity window (F3): null for docs without one. The GP card renders
    // "Valid until / Expires in N days / Expired" from this.
    expires_at: typeof row.expires_at === 'string' ? row.expires_at : null,
    ai_classification_confidence: row.ai_classification_confidence != null ? row.ai_classification_confidence : null,
    ai_classification_result: row.ai_classification_result || '',
    google_drive_file_id: row.google_drive_file_id || ''
  };
}

function buildPreparedDocumentDownloadUrl(country, key) {
  return `/api/prepared-documents/download?country=${encodeURIComponent(country)}&key=${encodeURIComponent(key)}`;
}

function buildOnboardingDocumentDownloadUrl(country, key) {
  return `/api/onboarding-documents/download?country=${encodeURIComponent(country)}&key=${encodeURIComponent(key)}`;
}

function buildAccountCareerDocumentDownloadUrl(type) {
  return `/api/account-career-documents/download?type=${encodeURIComponent(type)}`;
}

// Where an admin-filed candidate document belongs: the GP behind `caseId`, the
// country their "Prepared by Candidate" cards are rendered from, and the Storage
// path both are keyed to. Shared by the sign-upload and finalize steps so the
// bytes and the row can never end up under different countries.
// Returns null when the case (or its user) can't be resolved.
async function resolveCandidateDocTarget(caseId, docKey) {
  if (!caseId || !docKey || !isSupabaseDbConfigured()) return null;
  const caseRes = await supabaseDbRequest('registration_cases',
    'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
  const userId = (caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0]) ? caseRes.data[0].user_id : '';
  if (!userId) return null;
  const country = await resolveGpDocumentCountryForUser(userId);
  return { userId, country, storagePath: buildPreparedDocumentStoragePath(userId, country, docKey) };
}

// The GP's document country, from their profile/state. Extracted so the upload
// target, the documents list and the document PREVIEW all resolve it identically
// — a divergence here files or reads a document under a country the other side
// never looks at, and the upload then "vanishes" with no error.
async function resolveGpDocumentCountryForUser(userId) {
  if (!userId || !isSupabaseDbConfigured()) return 'uk';
  const [profRes, stateRes] = await Promise.all([
    supabaseDbRequest('user_profiles', 'select=registration_country&user_id=eq.' + encodeURIComponent(userId) + '&limit=1'),
    supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1')
  ]);
  const prof = (profRes.ok && Array.isArray(profRes.data) && profRes.data[0]) ? profRes.data[0] : {};
  let state = (stateRes.ok && Array.isArray(stateRes.data) && stateRes.data[0]) ? stateRes.data[0].state : null;
  if (typeof state === 'string') { try { state = JSON.parse(state); } catch (e) { state = null; } }
  if (!state || typeof state !== 'object') state = {};
  return resolveGpDocumentCountry(prof.registration_country, state.gp_selected_country);
}

