async function getPreparedDocumentsForUser(userId, _email, country) {
  const normalizedCountry = normalizeDocumentCountry(country);
  if (!normalizedCountry || !isSupabaseDbConfigured()) return { country: normalizedCountry, docs: {}, updatedAt: null };
  const rows = await listPreparedDocumentRows(userId, normalizedCountry);
  const docs = {};
  let updatedAt = null;
  for (const row of rows) {
    docs[row.document_key] = mapPreparedDocumentRow(row, buildPreparedDocumentDownloadUrl(normalizedCountry, row.document_key));
    if (row.updated_at && (!updatedAt || row.updated_at > updatedAt)) updatedAt = row.updated_at;
  }
  return {
    country: normalizedCountry,
    docs,
    updatedAt
  };
}

async function savePreparedDocumentForUser(userId, _email, payload) {
  if (!payload || !userId || !isSupabaseDbConfigured()) return null;
  const storagePath = buildPreparedDocumentStoragePath(userId, payload.country, payload.key);
  const uploaded = await supabaseStorageUploadObject(SUPABASE_DOCUMENT_BUCKET, storagePath, payload.fileDataUrl, payload.mimeType);
  if (!uploaded) return null;
  return upsertPreparedDocumentRow(userId, payload, storagePath);
}

// Record a prepared document that is ALREADY sitting at `storagePath`. Split out
// of savePreparedDocumentForUser so the admin upload can put the bytes in Storage
// via a signed URL (no request-body size limit) and still produce an identical
// row — one writer, so the two paths can't drift apart.
async function upsertPreparedDocumentRow(userId, payload, storagePath) {
  if (!payload || !userId || !storagePath || !isSupabaseDbConfigured()) return null;

  // F3 expiry capture: an explicit expiry (GP-entered or AI-extracted) wins;
  // otherwise renewal-sensitive doc types get the default validity window.
  // A fresh upload always restarts the nudge window (expiry_nudged_at reset).
  const saveBody = {
    user_id: userId,
    country_code: payload.country,
    document_key: payload.key,
    // A doctor's own upload lands 'uploaded' and waits for review. An admin
    // filing it has already eyeballed it, so that path passes 'approved'.
    status: payload.status || 'uploaded',
    file_name: payload.fileName,
    file_url: storagePath,
    updated_at: payload.updatedAt
  };
  // Record WHERE and WHAT, not just the name. Readers are split between
  // `storage_path` and `file_url` (some check storage_path alone), and the row
  // was landing with mime_type '' and file_size 0 — so a filed document reported
  // no type and no size to every downstream consumer (Drive mirror, AHPRA pack,
  // the doctor's own documents list).
  saveBody.storage_path = storagePath;
  saveBody.storage_bucket = SUPABASE_DOCUMENT_BUCKET;
  if (payload.mimeType) saveBody.mime_type = payload.mimeType;
  if (Number.isFinite(Number(payload.fileSize)) && Number(payload.fileSize) > 0) {
    saveBody.file_size = Number(payload.fileSize);
  }
  // Stamp WHEN it was reviewed, never WHO: `reviewed_by` is a uuid column, so
  // writing an admin's email there fails the whole upsert with a 22P02 and the
  // upload 502s. The admin who filed it is named in review_notes instead.
  if (payload.reviewedAt) saveBody.reviewed_at = payload.reviewedAt;
  const explicitExpiry = sanitizeExpiryDateIso(payload.expiresAt);
  const defaultExpiry = defaultDocumentExpiryIso(payload.key, payload.updatedAt);
  if (explicitExpiry || defaultExpiry) {
    saveBody.expires_at = explicitExpiry || defaultExpiry;
    saveBody.expiry_nudged_at = null;
  }

  let result = await supabaseDbRequest(
    'user_documents',
    'on_conflict=user_id,document_key,country_code',
    {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates,return=representation' },
      body: [saveBody]
    }
  );
  // Deploy-order safety: if the F3 expiry migration hasn't been applied yet the
  // new columns 400 the whole upsert — retry without them so uploads never break.
  if ((!result.ok || !Array.isArray(result.data) || result.data.length === 0) && ('expires_at' in saveBody)) {
    delete saveBody.expires_at;
    delete saveBody.expiry_nudged_at;
    result = await supabaseDbRequest(
      'user_documents',
      'on_conflict=user_id,document_key,country_code',
      {
        method: 'POST',
        headers: { Prefer: 'resolution=merge-duplicates,return=representation' },
        body: [saveBody]
      }
    );
  }
  if (!result.ok || !Array.isArray(result.data) || result.data.length === 0) return null;
  const row = result.data[0];
  return mapPreparedDocumentRow(row, buildPreparedDocumentDownloadUrl(payload.country, payload.key));
}

// ── Delivered offer documents (OFFER_DOCUMENT_KEYS) ──────────────────────────
// Offer/contract rows are written by deliverToMyDocuments (no country_code, and
// historically no storage path — Drive only) or by POST /api/ats/offer (which
// now also uploads to Supabase Storage and records file_url). They are looked
// up by user + key WITHOUT the country filter the prepared-by-you docs use.
async function getOfferDocumentRow(userId, key) {
  const normalizedKey = sanitizeUserString(key, 120);
  if (!normalizedKey || !OFFER_DOCUMENT_KEYS.has(normalizedKey) || !userId || !isSupabaseDbConfigured()) return null;
  const result = await supabaseDbRequest(
    'user_documents',
    `select=*&user_id=eq.${encodeURIComponent(userId)}&document_key=eq.${encodeURIComponent(normalizedKey)}&limit=1`
  );
  if (!result.ok || !Array.isArray(result.data) || result.data.length === 0) return null;
  return result.data[0];
}

// Map of delivered offer docs for the GET /api/prepared-documents response.
// Merged in at the ROUTE level only — /api/ahpra/document-readiness and the
// upload flows keep calling getPreparedDocumentsForUser directly, so nothing
// new appears in the AHPRA pack or the "You prepare" slots (the download pack
// already surfaces offer docs via /api/gplink-docs-status).
async function getOfferDocumentsForUser(userId, country) {
  const docs = {};
  if (!userId || !isSupabaseDbConfigured()) return docs;
  for (const key of OFFER_DOCUMENT_KEYS) {
    const row = await getOfferDocumentRow(userId, key);
    if (!row) continue;
    const status = String(row.status || '');
    if (status !== 'approved' && status !== 'uploaded' && status !== 'received') continue;
    docs[key] = mapPreparedDocumentRow(row, buildPreparedDocumentDownloadUrl(country || 'uk', key));
  }
  return docs;
}

// Resolve the downloadable target for a delivered offer doc, covering BOTH
// storage shapes:
//   1. row.file_url is a Supabase Storage path → signed URL (existing flow);
//   2. delivered via deliverToMyDocuments (no storage path) → the Drive file id
//      on the row, or the Drive URL _updatePreparedDocsState recorded in the
//      user_state gp_prepared_docs KV.
// Returns a redirectable URL string, or '' when nothing is stored anywhere.
async function resolveOfferDocumentDownloadUrl(userId, key) {
  const row = await getOfferDocumentRow(userId, key);
  if (!row) return '';
  const mapped = mapPreparedDocumentRow(row);
  const storagePath = mapped && mapped.storagePath ? String(mapped.storagePath) : '';
  if (storagePath && !/^https?:/i.test(storagePath) && !storagePath.startsWith('data:')) {
    const signedUrl = await supabaseStorageCreateSignedUrl(
      mapped.storageBucket || SUPABASE_DOCUMENT_BUCKET,
      storagePath,
      mapped.fileName || ''
    );
    if (signedUrl) return signedUrl;
    // fall through to the Drive shapes when signing fails
  }
  if (row.google_drive_file_id) return 'https://drive.google.com/file/d/' + row.google_drive_file_id + '/view';
  if (/^https?:/i.test(storagePath)) return storagePath;
  try {
    const stateRes = await supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    let fullState = (stateRes.ok && Array.isArray(stateRes.data) && stateRes.data[0] && stateRes.data[0].state) ? stateRes.data[0].state : {};
    if (typeof fullState === 'string') try { fullState = JSON.parse(fullState); } catch { fullState = {}; }
    let prepState = fullState.gp_prepared_docs;
    if (typeof prepState === 'string') try { prepState = JSON.parse(prepState); } catch { prepState = {}; }
    const kvDoc = prepState && prepState.docs && typeof prepState.docs === 'object' ? prepState.docs[key] : null;
    if (kvDoc && typeof kvDoc.url === 'string' && /^https?:/i.test(kvDoc.url)) return kvDoc.url;
  } catch (e) { /* fall through */ }
  return '';
}

async function deletePreparedDocumentForUser(userId, _email, country, key) {
  const normalizedCountry = normalizeDocumentCountry(country);
  const normalizedKey = sanitizeUserString(key, 120);
  if (!normalizedCountry || !PREPARED_DOCUMENT_KEYS.has(normalizedKey) || !userId || !isSupabaseDbConfigured()) return false;
  const existing = await getPreparedDocumentRow(userId, normalizedCountry, normalizedKey);
  if (!existing) return true;
  const mapped = mapPreparedDocumentRow(existing);
  const deletedObject = mapped && mapped.storagePath
    ? await supabaseStorageDeleteObject(mapped.storageBucket || SUPABASE_DOCUMENT_BUCKET, mapped.storagePath)
    : true;
  const deletedRow = await supabaseDbRequest(
    'user_documents',
    `user_id=eq.${encodeURIComponent(userId)}&country_code=eq.${encodeURIComponent(normalizedCountry)}&document_key=eq.${encodeURIComponent(normalizedKey)}`,
    { method: 'DELETE' }
  );
  return deletedObject && deletedRow.ok;
}

