// Practice-facing local time label for booked interviews (status endpoint).
function formatPracticeStatusTimeLabel(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  try {
    return d.toLocaleString('en-AU', {
      weekday: 'short', day: 'numeric', month: 'short', year: 'numeric',
      hour: 'numeric', minute: '2-digit', timeZone: 'Australia/Sydney', timeZoneName: 'short'
    });
  } catch (e) {
    return d.toISOString();
  }
}

// Enumerate incomplete-onboarding GPs: active accounts, not staff, that haven't
// finished the 5-step wizard. Shared by the hourly cron (/api/cron/onboarding-nudge)
// and the CEO onboarding-incomplete waitlist endpoint — do not duplicate this logic.
// Excludes GPs who already have a gp_applications row: they're real candidates
// in the ATS pipeline (the funnel already keeps them in their own bucket — see
// /api/ceo/candidates + /api/ceo/pipeline-summary) and must not also appear on
// the onboarding waitlist or get chase emails.
// Returns [{ userId, email, name, country, lastActiveMs, lastStep, completed }].
async function enumerateIncompleteOnboardingGps() {
  var onbNow = Date.now();
  var onbGps = [];
  var onbHasAppsIds = {}; // key = user_id or (lowercased) email of any GP with >=1 gp_applications row
  if (isSupabaseDbConfigured()) {
    var onbAdminIds = await getAdminUserIdSet();
    var onbProfRes = await supabaseDbRequest('user_profiles',
      'select=user_id,email,first_name,last_name,account_status,onboarding_completed_at,registration_country,created_at,updated_at' +
      // Every GP who signed up but never finished the wizard sits here until they
      // finish or are purged, so this fills faster than total GP count — a big
      // ad campaign can park thousands. Past the cap they'd never be nudged.
      '&onboarding_completed_at=is.null&limit=10000');
    var onbProfs = (onbProfRes.ok && Array.isArray(onbProfRes.data)) ? onbProfRes.data : [];
    onbProfs = onbProfs.filter(function (p) {
      var st = String(p.account_status || 'active').toLowerCase();
      return st === 'active' && p.user_id && !onbAdminIds.has(p.user_id) && p.email;
    });
    // user_state for completion double-check + last-active + currentStep (chunked)
    var onbStateMap = {};
    for (var onbI = 0; onbI < onbProfs.length; onbI += 100) {
      var onbChunk = onbProfs.slice(onbI, onbI + 100).map(function (p) { return '"' + String(p.user_id).replace(/"/g, '') + '"'; }).join(',');
      var onbStRes = await supabaseDbRequest('user_state', 'select=user_id,state,updated_at&user_id=in.(' + encodeURIComponent(onbChunk) + ')&limit=200');
      (((onbStRes.ok && onbStRes.data) || [])).forEach(function (s) { onbStateMap[s.user_id] = s; });
    }
    onbProfs.forEach(function (p) {
      var sRow = onbStateMap[p.user_id] || null;
      var sObj = (sRow && sRow.state && typeof sRow.state === 'object') ? sRow.state : {};
      var ob = sObj.gp_onboarding;
      if (typeof ob === 'string') { try { ob = JSON.parse(ob); } catch (e) { ob = null; } }
      ob = (ob && typeof ob === 'object') ? ob : {};
      var completed = !!(ob.completedAt || sObj.gp_onboarding_complete || p.onboarding_completed_at);
      var lastActive = (sRow && sRow.updated_at) || p.updated_at || p.created_at || null;
      onbGps.push({
        userId: p.user_id,
        email: String(p.email || '').toLowerCase(),
        name: [(p.first_name || ''), (p.last_name || '')].join(' ').trim(),
        country: p.registration_country || '',
        lastActiveMs: lastActive ? new Date(lastActive).getTime() : onbNow,
        lastStep: (ob.currentStep != null ? Number(ob.currentStep) : 0),
        completed: completed
      });
    });
    // GPs with any gp_applications row are real ATS candidates, not waitlist
    // (same limit=5000 the /api/ceo/candidates + pipeline-summary funnel uses).
    var onbAppsRes = await supabaseDbRequest('gp_applications', 'select=user_id&limit=5000');
    (((onbAppsRes.ok && onbAppsRes.data) || [])).forEach(function (a) { if (a && a.user_id) onbHasAppsIds[String(a.user_id)] = true; });
  } else {
    // Local-JSON mode: users + userState keyed by email.
    Object.keys(dbState.users || {}).forEach(function (em) {
      var u = dbState.users[em] || {};
      var stWrap = (dbState.userState && dbState.userState[em]) || {};
      var sObj = stWrap.state || stWrap || {};
      var ob = sObj.gp_onboarding;
      if (typeof ob === 'string') { try { ob = JSON.parse(ob); } catch (e) { ob = null; } }
      ob = (ob && typeof ob === 'object') ? ob : {};
      var completed = !!(ob.completedAt || sObj.gp_onboarding_complete);
      var acct = String(sObj.account_status || 'active').toLowerCase();
      if (acct !== 'active') return;
      var lastActive = stWrap.updatedAt || u.updatedAt || u.createdAt || null;
      onbGps.push({
        userId: u.supabaseUserId || em,
        email: em,
        name: [(u.firstName || ''), (u.lastName || '')].join(' ').trim(),
        country: u.registrationCountry || '',
        lastActiveMs: lastActive ? new Date(lastActive).getTime() : onbNow,
        lastStep: (ob.currentStep != null ? Number(ob.currentStep) : 0),
        completed: completed
      });
    });
    // Exclude staff in local mode via configured admin + monitored VA emails
    // (Supabase mode already excludes admins via getAdminUserIdSet() above).
    var onbAdminEmails = String(process.env.SUPER_ADMIN_EMAILS || '').toLowerCase() + ',' + String(process.env.ADMIN_EMAILS || '').toLowerCase()
      + ',' + MONITORED_VA_EMAILS.map(function (e) { return String(e || '').toLowerCase(); }).join(',');
    onbGps = onbGps.filter(function (g) { return onbAdminEmails.indexOf(g.email) === -1; });
    // GPs with any application on their local atsCandidates row are real ATS
    // candidates, not waitlist. Local users are keyed by email, so match by
    // BOTH user_id and email fallback (mirrors the Supabase gp_applications check).
    (dbState.atsCandidates || []).forEach(function (c) {
      if (c && Array.isArray(c.apps) && c.apps.length > 0) {
        if (c.user_id) onbHasAppsIds[String(c.user_id)] = true;
        if (c.email) onbHasAppsIds[String(c.email).toLowerCase()] = true;
      }
    });
  }
  onbGps = onbGps.filter(function (g) { return !onbHasAppsIds[String(g.userId)] && !onbHasAppsIds[String(g.email || '').toLowerCase()]; });
  return onbGps;
}

async function listOnboardingReminders() {
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('onboarding_reminders', 'select=*&limit=5000');
    return (r.ok && Array.isArray(r.data)) ? r.data : [];
  }
  var out = [];
  var map = dbState.onboardingReminders || {};
  Object.keys(map).forEach(function (k) { out.push(map[k]); });
  return out;
}

// Upsert by user_id on both backends (local map key = lowercased user_id,
// email fallback only when user_id is missing). patch always includes email.
async function upsertOnboardingReminder(userId, patch) {
  var nowIso = new Date().toISOString();
  var body = Object.assign({}, patch, { updated_at: nowIso });
  if (isSupabaseDbConfigured()) {
    var q = 'select=id&user_id=eq.' + encodeURIComponent(String(userId));
    var existing = await supabaseDbRequest('onboarding_reminders', q);
    if (existing.ok && Array.isArray(existing.data) && existing.data[0]) {
      await supabaseDbRequest('onboarding_reminders', 'id=eq.' + encodeURIComponent(existing.data[0].id), { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: body });
    } else {
      await supabaseDbRequest('onboarding_reminders', '', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: [Object.assign({ user_id: userId, created_at: nowIso }, body)] });
    }
    return;
  }
  if (!dbState.onboardingReminders) dbState.onboardingReminders = {};
  // Key by user_id first (stable — a pre-emptive opt-out row written with a null
  // email must be the SAME row a later cron write with a real email lands on),
  // falling back to email only when no user_id is known.
  var key = String(userId || (patch && patch.email) || '').trim().toLowerCase();
  var prev = dbState.onboardingReminders[key] || { user_id: userId, created_at: nowIso, steps_sent: [], unsubscribed: false, stopped: false };
  dbState.onboardingReminders[key] = Object.assign({}, prev, body, { user_id: prev.user_id || userId });
  saveDbState();
}

// Send one nudge. row = onboarding_reminders row. Returns sendEmail's result.
async function sendOnboardingNudgeEmail(row, stepIndex, stepsLeft) {
  if (!isEmailConfigured()) return { ok: false, error: 'Email not configured' };
  var to = String((row && row.email) || '').trim();
  if (!to) return { ok: false, error: 'No email on reminder row' };
  // Phase 6 F4 (G6): nudges are non-critical — respect the GP's "email nudges"
  // preference. Transactional mail is NOT routed through here and never checks.
  if (!(await allowsNonCriticalNotification(to, 'emailNudges'))) {
    return { ok: false, skipped: true, optedOut: true, error: 'Recipient opted out of nudge emails' };
  }
  var firstName = String((row && row.name) || '').split(' ')[0] || '';
  var copy = onboardingNudge.copyForStep(stepIndex, { name: firstName || 'there', stepsLeft: stepsLeft });
  var step = (row && row.last_step != null && row.last_step >= 0 && row.last_step < 5) ? row.last_step : 0;
  var ctaUrl = APP_BASE_URL + '/pages/onboarding.html?step=' + step;
  var unsubUrl = APP_BASE_URL + '/api/onboarding-reminders/unsubscribe?u=' + encodeURIComponent(String((row && row.user_id) || '')) + '&t=' + onbUnsubToken(row && row.user_id);
  var footer = '<a href="' + unsubUrl + '" style="color:#8a94a6;font-size:11px;text-decoration:underline">Unsubscribe from these reminders</a>';
  // NOTE: buildCareerEmailHtml already wraps `body` in its own <p> tag, so pass
  // copy.body as plain text here (not pre-wrapped) — matches the working call
  // pattern in sendGpNotificationEmail just above.
  var html = buildCareerEmailHtml({
    title: copy.title,
    body: copy.body,
    ctaText: 'Continue where you left off',
    ctaUrl: ctaUrl,
    footer: footer
  });
  return sendEmail({
    to: to,
    subject: copy.subject,
    html: html,
    // Nudges are marketing-class mail: bounced/complained recipients are
    // skipped via the email_suppression list (Phase 6 C3).
    category: 'marketing',
    text: copy.body + '\n\nContinue: ' + ctaUrl + '\n\nUnsubscribe: ' + unsubUrl,
    // List-Unsubscribe-Post (RFC 8058) tells Gmail/Yahoo's native "Unsubscribe"
    // affordance to POST to the List-Unsubscribe URL instead of just showing a
    // link, handled by the POST branch on /api/onboarding-reminders/unsubscribe,
    // which reads u/t from the URL's own query params.
    headers: { 'List-Unsubscribe': '<' + unsubUrl + '>', 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
  });
}

/**
 * Check a document name against profile name AND previously verified document names.
 * Returns { match: 'exact'|'fuzzy'|'mismatch'|'unknown', matchedAgainst: string|null }
 */
function crossCheckDocumentName(docName, profileName, verifiedNames) {
  if (!docName) return { match: 'unknown', matchedAgainst: null };

  // Check against profile name first
  if (profileName) {
    const profileMatch = matchNames(docName, profileName);
    if (profileMatch === 'mismatch') return { match: 'mismatch', matchedAgainst: 'profile' };
    if (profileMatch !== 'unknown') return { match: profileMatch, matchedAgainst: 'profile' };
    return { match: 'unknown', matchedAgainst: 'profile' };
  }

  // Check against previously verified document names
  for (const prevName of (verifiedNames || [])) {
    const docMatch = matchNames(docName, prevName);
    if (docMatch !== 'mismatch') {
      return { match: docMatch, matchedAgainst: 'previous_document' };
    }
  }

  // Nothing matched
  if (!profileName && (!verifiedNames || verifiedNames.length === 0)) {
    return { match: 'unknown', matchedAgainst: null };
  }
  return { match: 'mismatch', matchedAgainst: null };
}

const CSP_SUPABASE_ORIGIN = SUPABASE_URL ? new URL(SUPABASE_URL).origin : '';
// Storage objects are reachable on TWO hosts: the project host
// (<ref>.supabase.co) and any Supabase custom domain. Production runs
// SUPABASE_URL=https://login.mygplink.com.au, so CSP_SUPABASE_ORIGIN only ever
// whitelisted the custom domain — while career_roles.header_image_url rows were
// written with the project host by scripts run against a local .env. Result:
// 24 of 64 job listings had their hero image silently blocked by CSP (the other
// 38 point at upload.wikimedia.org, which is why only *some* cards looked broken).
// Whitelisting the project-host wildcard covers both spellings of the same
// bucket. img-src only — this grants no script or connect privilege.
const CSP_SUPABASE_STORAGE_SOURCES = ' https://*.supabase.co';
const GOOGLE_MAPS_CSP_SCRIPT_SOURCES = " https://*.googleapis.com https://*.gstatic.com *.google.com https://*.ggpht.com *.googleusercontent.com blob: 'unsafe-eval'";
const GOOGLE_MAPS_CSP_CONNECT_SOURCES = " https://*.googleapis.com *.google.com https://*.gstatic.com data: blob:";
const GOOGLE_MAPS_CSP_IMAGE_SOURCES = ' https://*.googleapis.com https://*.gstatic.com *.google.com *.googleusercontent.com data:';
// Keyless job-advert map (Leaflet + CARTO/OSM raster tiles). Used instead of
// Google Maps for the suburb pin because the Google browser key is restricted
// to specific referrer domains (breaks on preview.mygplink.com.au etc.) and
// isn't authorized for Geocoding. Leaflet CSS/JS load from jsdelivr (already in
// script-src); the raster tiles are plain <img> requests to CARTO/OSM.
const KEYLESS_MAP_CSP_STYLE_SOURCES = ' https://cdn.jsdelivr.net';
const KEYLESS_MAP_CSP_IMAGE_SOURCES = ' https://*.basemaps.cartocdn.com https://*.tile.openstreetmap.org';
const SECURITY_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'SAMEORIGIN',
  'X-XSS-Protection': '1; mode=block',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(self), microphone=(), geolocation=()',
  'Content-Security-Policy': [
    "default-src 'self'",
    // /start's Calendly embed loads assets.calendly.com's widget script and iframes calendly.com — see script-src/frame-src below.
    `script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net https://assets.calendly.com${CSP_SUPABASE_ORIGIN ? ' ' + CSP_SUPABASE_ORIGIN : ''}${GOOGLE_MAPS_CSP_SCRIPT_SOURCES}`,
    `style-src 'self' 'unsafe-inline' https://fonts.googleapis.com${KEYLESS_MAP_CSP_STYLE_SOURCES}`,
    "font-src 'self' https://fonts.gstatic.com",
    // Housing/relocation listing images (career page Relocation Explorer):
    // Domain API media comes back on *.domainstatic.com.au + bucket-api.domain.com.au
    // (see pickDomainImageUrl/resizeDomainImageUrl), the built-in fallback listings
    // use images.unsplash.com (buildLifestyleImage + career.html seeds), and the
    // seeded Homely listings use www.homely.com.au.
    `img-src 'self' data: blob:${CSP_SUPABASE_ORIGIN ? ' ' + CSP_SUPABASE_ORIGIN : ''}${CSP_SUPABASE_STORAGE_SOURCES}${GOOGLE_MAPS_CSP_IMAGE_SOURCES}${KEYLESS_MAP_CSP_IMAGE_SOURCES} https://upload.wikimedia.org https://commons.wikimedia.org https://*.wikimedia.org https://*.domainstatic.com.au https://bucket-api.domain.com.au https://images.unsplash.com https://www.homely.com.au`,
    `connect-src 'self'${CSP_SUPABASE_ORIGIN ? ' ' + CSP_SUPABASE_ORIGIN : ''}${GOOGLE_MAPS_CSP_CONNECT_SOURCES}`,
    "media-src 'self' blob:",
    "frame-src 'self' blob: *.google.com https://scribehow.com https://calendly.com",
    "worker-src 'self' blob:",
    "frame-ancestors 'self'",
    "base-uri 'self'",
    "form-action 'self'"
  ].join('; '),
  'X-Permitted-Cross-Domain-Policies': 'none'
};

const PUBLIC_CONFIG_CACHE_HEADERS = {
  'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400'
};
// Per-user API responses (career applications, interviews, roles). `private` keeps
// them out of shared/CDN caches, BUT a browser's own HTTP cache keys on the URL alone —
// so without `Vary: Cookie` it would serve account A's response to account B's identical
// request in the SAME browser (a shared/clinic computer, or two logins in one browser)
// for up to max-age/stale-while-revalidate. Root cause of the 2026-07-09 "Smith Miller
// tab shows Helen Wazalski's career page" mix-up. `Vary: Cookie` folds the session cookie
// into the cache key, so each account only ever reads its own cached copy.
const PRIVATE_METADATA_CACHE_HEADERS = {
  'Cache-Control': 'private, max-age=60, stale-while-revalidate=300',
  'Vary': 'Cookie'
};

// Same privacy rules, but never cached. Used for responses that carry state the
// doctor CHANGES from the page they're looking at — an AI match they can accept
// or decline. With max-age=60/stale-while-revalidate=300 the browser answers the
// post-accept reload from its own cache with the PRE-accept body, so the match
// buttons reappear as though the accept never happened (owner report
// 2026-07-29). Static role copy keeps the cached headers above.
const PRIVATE_VOLATILE_HEADERS = {
  'Cache-Control': 'no-store',
  'Vary': 'Cookie'
};

function isStackTraceResponseKey(key) {
  var normalized = String(key || '').replace(/[-\s]+/g, '_').toLowerCase();
  return normalized === 'stack' ||
    normalized === 'error_stack' ||
    normalized === 'stack_trace' ||
    normalized === 'stacktrace' ||
    normalized.endsWith('_stack');
}

function sanitizeJsonResponseData(value, depth, seen) {
  if (value === null || typeof value !== 'object') return value;
  if (value instanceof Date) return value;
  if (Buffer.isBuffer(value)) return value;
  if (depth > 12) return '[redacted-depth-limit]';
  seen = seen || new WeakSet();
  if (seen.has(value)) return '[redacted-circular]';
  seen.add(value);
  if (Array.isArray(value)) {
    return value.map(function (item) {
      return sanitizeJsonResponseData(item, depth + 1, seen);
    });
  }
  var output = {};
  Object.keys(value).forEach(function (key) {
    if (isStackTraceResponseKey(key)) {
      output[key] = '[redacted]';
      return;
    }
    output[key] = sanitizeJsonResponseData(value[key], depth + 1, seen);
  });
  return output;
}

function sendJson(res, status, data, headers = {}) {
  const body = JSON.stringify(sanitizeJsonResponseData(data, 0));
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
    ...SECURITY_HEADERS,
    ...(NODE_ENV === 'production' ? { 'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload' } : {}),
    ...headers
  });
  res.end(body);
}

function getCookies(req) {
  const raw = req.headers.cookie || '';
  return raw.split(';').reduce((acc, pair) => {
    const idx = pair.indexOf('=');
    if (idx === -1) return acc;
    const key = pair.slice(0, idx).trim();
    const val = pair.slice(idx + 1).trim();
    if (key) {
      try {
        acc[key] = decodeURIComponent(val);
      } catch (err) {
        // Skip malformed cookie values
      }
    }
    return acc;
  }, {});
}

function getRequestHostname(req) {
  const host = String(req.headers.host || '').trim().toLowerCase();
  if (!host) return '';
  return host.split(':')[0];
}

function getHostFromHeaderValue(value) {
  if (typeof value !== 'string' || !value.trim()) return '';
  try {
    const parsed = new URL(value);
    return parsed.hostname.trim().toLowerCase();
  } catch (err) {
    return '';
  }
}

function isTrustedSameOriginRequest(req) {
  const requestHost = getRequestHostname(req);
  if (!requestHost) return false;

  const originHost = getHostFromHeaderValue(req.headers.origin);
  if (originHost) return originHost === requestHost;

  const refererHost = getHostFromHeaderValue(req.headers.referer);
  if (refererHost) return refererHost === requestHost;

  return NODE_ENV !== 'production';
}

function isMutationMethod(method) {
  return method === 'POST' || method === 'PUT' || method === 'PATCH' || method === 'DELETE';
}

function enforceMutationOrigin(req, res) {
  if (!ENFORCE_SAME_ORIGIN || !isMutationMethod(req.method)) return true;
  if (isTrustedSameOriginRequest(req)) return true;
  sendJson(res, 403, { ok: false, message: 'Blocked by same-origin policy.' });
  return false;
}

function isLoopbackHostname(hostname) {
  return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1';
}

function normalizeAdminRole(value) {
  const role = String(value || '').trim().toLowerCase().replace(/-/g, '_');
  if (role === 'staff' || role === 'admin' || role === 'super_admin' || role === 'consultant') return role;
  return '';
}

function hasAdminPortalAccess(role) {
  return normalizeAdminRole(role) !== '';
}

function isSuperAdminRole(role) {
  return normalizeAdminRole(role) === 'super_admin';
}

// The identity document is viewable by CEO (super_admin) and ATS users
// (consultant) only — never RSOs. ATS surfaces gate via requireAtsSession; admin
// surfaces gate with this predicate.
function canViewIdentity(ctx) { return isSuperAdminRole(ctx && ctx.role); }

function getAdminRoleLabel(role) {
  const normalized = normalizeAdminRole(role);
  if (normalized === 'super_admin') return 'Super Admin';
  if (normalized === 'staff') return 'Staff Admin';
  if (normalized === 'consultant') return 'Consultant';
  if (normalized === 'admin') return 'Admin';
  return 'Admin';
}

function getConfiguredAdminRoleForEmail(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return '';
  if (SUPER_ADMIN_EMAILS.has(normalizedEmail)) return 'super_admin';
  if (ADMIN_EMAILS.has(normalizedEmail)) return 'admin';
  // Checked AFTER the super/admin lists so those always win for a shared email.
  if (CONSULTANT_EMAILS.has(normalizedEmail)) return 'consultant';
  return '';
}

function getAdminHostScope(req) {
  const hostname = getRequestHostname(req);
  if (!hostname) return '';
  if (SUPER_ADMIN_ALLOWED_HOSTS.has(hostname)) return 'super_admin';
  if (PREVIEW_SUPER_ADMIN_HOSTS.has(hostname)) return 'super_admin';
  if (ADMIN_ALLOWED_HOSTS.has(hostname)) return 'admin';
  if (NODE_ENV !== 'production' && isLoopbackHostname(hostname)) return 'local';
  return '';
}

// Base URL for links INTO the CEO dashboard (ops emails).
//
// The dashboard is served ONLY on the super-admin host scope — see the
// `/pages/ceo-dashboard.html` guard, which respondNotFound()s anywhere else.
// APP_BASE_URL is the DOCTOR-facing host (app.mygplink.com.au), so every ops
// email that deep-linked with APP_BASE_URL handed hello@ a 404 (owner report
// 2026-07-30, verified against production). Build them from the configured
// super-admin host instead, and fall back to APP_BASE_URL only when nothing is
// configured (local/dev), where the guard admits loopback anyway.
function getSuperAdminBaseUrl() {
  const host = Array.from(SUPER_ADMIN_ALLOWED_HOSTS)[0] || '';
  if (!host) return APP_BASE_URL;
  return /^https?:\/\//i.test(host) ? host : ('https://' + host);
}

// Module-level HTML escape for email bodies. There are several function-local
// `esc` helpers in this file but no shared one, so anything built at top level
// (or in a function that doesn't declare its own) needs this — a bare `esc`
// there is a ReferenceError at send time, i.e. a silently lost email.
const escEmailHtml = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Deep link to one candidate's ATS card. `case=` is read on load by
// pages/ceo-dashboard.html, which opens that candidate's drawer.
function buildCeoCandidateUrl(caseId) {
  const id = String(caseId || '').trim();
  return getSuperAdminBaseUrl() + '/pages/ceo-dashboard' + (id ? ('?case=' + encodeURIComponent(id)) : '');
}

function getAdminHostLabel(scope) {
  if (scope === 'super_admin') return 'CEO / Super Admin';
  if (scope === 'admin') return 'Employee Admin';
  if (scope === 'local') return 'Local Admin';
  return 'Admin';
}

function doesAdminRoleMatchHost(role, hostScope) {
  const normalizedRole = normalizeAdminRole(role);
  if (!normalizedRole) return false;
  // The CEO / super-admin host admits super admins AND consultants (the ATS
  // surface lives there). Consultants are still fenced to the ATS routes by
  // requireAdminSession/requireAtsSession — matching the host is necessary
  // but not sufficient.
  if (hostScope === 'super_admin') return normalizedRole === 'super_admin' || normalizedRole === 'consultant';
  // The employee admin host never serves consultants (they get ATS only).
  if (hostScope === 'admin') return normalizedRole !== 'consultant';
  return hostScope === 'local';
}

function getAdminRoleFromSession(session) {
  const storedRole = normalizeAdminRole(session && session.userProfile && session.userProfile.adminRole);
  if (storedRole) return storedRole;
  return getConfiguredAdminRoleForEmail(getSessionEmail(session));
}

function isAllowedAdminHost(req) {
  return !!getAdminHostScope(req);
}

function randomToken(size = 32) {
  return crypto.randomBytes(size).toString('hex');
}

function hashOtp(key, code) {
  return crypto.createHmac('sha256', SECRET).update(`${key}|${code}`).digest('hex');
}

function hashToken(token) {
  return crypto.createHash('sha256').update(String(token || '')).digest('hex');
}

function base64UrlEncode(input) {
  return Buffer.from(String(input), 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function base64UrlDecode(input) {
  const normalized = String(input || '').replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '==='.slice((normalized.length + 3) % 4);
  return Buffer.from(padded, 'base64').toString('utf8');
}

// Token signature (NOT password hashing — passwords use scrypt, see hashPassword)
var _macFn = crypto['createHmac'].bind(crypto);
function hmacSign(data) { return _macFn('sha512', SECRET).update(data).digest('hex'); }

function createSignedSessionToken(userProfile, expiresAt, sessionEpoch) {
  // Phase 6 F4 (security L2): tokens optionally carry the user's session epoch.
  // Only embed a POSITIVE epoch — epoch 0 (the default for every user until
  // they first trigger a revoke) is expressed by OMITTING the claim, so tokens
  // for never-revoked users are byte-identical to pre-F4 tokens.
  const epochNum = Math.floor(Number(sessionEpoch));
  const claims = { userProfile, expiresAt };
  if (Number.isFinite(epochNum) && epochNum > 0) claims.epoch = epochNum;
  const payload = base64UrlEncode(JSON.stringify(claims));
  return `${payload}.${hmacSign(payload)}`;
}

function parseSignedSessionToken(token) {
  const raw = String(token || '');
  const dotIdx = raw.lastIndexOf('.');
  if (dotIdx <= 0) return null;
  const payload = raw.slice(0, dotIdx);
  const signature = raw.slice(dotIdx + 1);
  // Try sha512 first (current), fall back to sha256 (legacy tokens)
  const expected512 = hmacSign(payload);
  let sigValid = signature.length === expected512.length && crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected512, 'utf8'));
  if (!sigValid) {
    const expected256 = crypto.createHmac('sha256', SECRET).update(payload).digest('hex');
    sigValid = signature.length === expected256.length && crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected256, 'utf8'));
  }
  if (!sigValid) return null;

  try {
    const parsed = JSON.parse(base64UrlDecode(payload));
    if (!parsed || typeof parsed !== 'object') return null;
    if (!parsed.userProfile || typeof parsed.userProfile !== 'object') return null;
    if (typeof parsed.expiresAt !== 'number') return null;
    if (parsed.expiresAt <= now()) return null;
    // A token with no epoch claim (every pre-F4 session) parses as epoch 0.
    const tokenEpoch = Math.floor(Number(parsed.epoch));
    return {
      userProfile: parsed.userProfile,
      expiresAt: parsed.expiresAt,
      epoch: Number.isFinite(tokenEpoch) && tokenEpoch > 0 ? tokenEpoch : 0
    };
  } catch (err) {
    return null;
  }
}

// ── Phase 6 F4: per-user session epoch ("sign out of all devices") ──────────
// Stored in public.user_session_epoch (Supabase) / dbState.sessionEpochs
// (local JSON), keyed by lowercased email. A gp_session token is REJECTED only
// when the user's KNOWN stored epoch is greater than the epoch embedded in the
// token. Everything else fails open by design so deploying this can never
// mass-log-out live users:
//   • token has no epoch claim  → treated as epoch 0 (all pre-F4 sessions)
//   • user has no stored row    → stored epoch 0 → 0 > 0 is false → valid
//   • store unreadable / table missing (pre-migration) → treated as unknown → valid
// Only an explicit revoke (sign-out-all, account deletion, password change,
// email change) writes a stored epoch > 0, and only then do older tokens die.
const SESSION_EPOCH_CACHE_TTL_MS = Number(process.env.SESSION_EPOCH_CACHE_TTL_MS || 60 * 1000);
const _sessionEpochCache = new Map(); // email -> { epoch, fetchedAt }

function cacheSessionEpoch(email, epoch) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return;
  const num = Math.floor(Number(epoch));
  _sessionEpochCache.set(key, { epoch: Number.isFinite(num) && num > 0 ? num : 0, fetchedAt: Date.now() });
}

// Synchronous, cache-only check used inside getSession(). Returns true ONLY
// when we positively know the stored epoch is newer than the token's. A cache
// miss returns false (valid) — handleApi warms the cache per request, so API
// calls are enforced; anything reached before a warm cache simply behaves like
// pre-F4 (fail-open, never a surprise logout).
function isSessionEpochRevokedSync(email, tokenEpoch) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return false;
  const entry = _sessionEpochCache.get(key);
  if (!entry) return false;
  return entry.epoch > (Number(tokenEpoch) || 0);
}

async function getStoredSessionEpoch(email) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return 0;
  const cached = _sessionEpochCache.get(key);
  if (cached && Date.now() - cached.fetchedAt < SESSION_EPOCH_CACHE_TTL_MS) return cached.epoch;
  let epoch = 0;
  try {
    if (isSupabaseDbConfigured()) {
      const r = await supabaseDbRequest('user_session_epoch', 'select=epoch&email=eq.' + encodeURIComponent(key) + '&limit=1');
      if (!r.ok) {
        // Pre-migration table / transient failure: keep any stale cached value
        // (never let an error look like a revoke) and treat unknown as 0.
        return cached ? cached.epoch : 0;
      }
      const row = Array.isArray(r.data) ? r.data[0] : null;
      epoch = row && Number.isFinite(Number(row.epoch)) ? Math.floor(Number(row.epoch)) : 0;
    } else {
      const map = dbState.sessionEpochs && typeof dbState.sessionEpochs === 'object' ? dbState.sessionEpochs : {};
      epoch = Number.isFinite(Number(map[key])) ? Math.floor(Number(map[key])) : 0;
    }
  } catch (err) {
    return cached ? cached.epoch : 0;
  }
  cacheSessionEpoch(key, epoch);
  return epoch;
}

// Bump the user's epoch → every previously-issued token (lower epoch) becomes
// invalid at its next validation. Returns the new epoch, or null on failure
// (callers must NOT claim sessions were revoked when this returns null).
async function bumpSessionEpoch(email) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return null;
  // Fresh read (bypass cache) so concurrent bumps still move forward.
  let current = 0;
  try {
    if (isSupabaseDbConfigured()) {
      const r = await supabaseDbRequest('user_session_epoch', 'select=epoch&email=eq.' + encodeURIComponent(key) + '&limit=1');
      if (r.ok && Array.isArray(r.data) && r.data[0]) current = Math.floor(Number(r.data[0].epoch)) || 0;
      const next = current + 1;
      const w = await supabaseDbRequest('user_session_epoch', 'on_conflict=email', {
        method: 'POST',
        headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
        body: [{ email: key, epoch: next, updated_at: new Date().toISOString() }]
      });
      if (!w.ok) return null;
      cacheSessionEpoch(key, next);
      return next;
    }
    if (!dbState.sessionEpochs || typeof dbState.sessionEpochs !== 'object') dbState.sessionEpochs = {};
    current = Math.floor(Number(dbState.sessionEpochs[key])) || 0;
    const nextLocal = current + 1;
    dbState.sessionEpochs[key] = nextLocal;
    saveDbState();
    cacheSessionEpoch(key, nextLocal);
    return nextLocal;
  } catch (err) {
    console.error('[session-epoch] bump failed for', key, err && err.message);
    return null;
  }
}

// Warm the epoch cache for the requesting user so the synchronous check in
// getSession() is authoritative for this request. Cheap: one cookie parse +
// at most one DB read per user per SESSION_EPOCH_CACHE_TTL_MS per instance.
async function preloadSessionEpochForRequest(req) {
  try {
    const cookies = getCookies(req);
    const token = cookies[COOKIE_NAME];
    if (!token) return;
    const signed = parseSignedSessionToken(token);
    if (!signed) return;
    const email = signed.userProfile && typeof signed.userProfile.email === 'string'
      ? signed.userProfile.email.trim().toLowerCase() : '';
    if (!email) return;
    await getStoredSessionEpoch(email);
  } catch (err) { /* fail-open by design */ }
}

// Issue a GP session embedding the user's CURRENT stored epoch, so a fresh
// login after a revoke stays valid while older tokens are rejected.
async function issueGpSession(res, userProfile) {
  const email = userProfile && typeof userProfile.email === 'string'
    ? userProfile.email.trim().toLowerCase() : '';
  let epoch = 0;
  if (email) {
    try { epoch = await getStoredSessionEpoch(email); } catch (err) { epoch = 0; }
  }
  setSession(res, userProfile, epoch);
}

function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = crypto.scryptSync(String(password || ''), salt, 64).toString('hex');
  return `scrypt$${salt}$${derived}`;
}

function verifyPassword(password, storedHash) {
  if (typeof storedHash !== 'string' || !storedHash.startsWith('scrypt$')) return false;
  const parts = storedHash.split('$');
  if (parts.length !== 3) return false;
  const salt = parts[1];
  const expectedHex = parts[2];
  const derivedHex = crypto.scryptSync(String(password || ''), salt, 64).toString('hex');
  const expectedBuf = Buffer.from(expectedHex, 'hex');
  const derivedBuf = Buffer.from(derivedHex, 'hex');
  if (expectedBuf.length !== derivedBuf.length) return false;
  return crypto.timingSafeEqual(expectedBuf, derivedBuf);
}

function isStrongPassword(password) {
  const value = String(password || '');
  if (value.length < 12 || value.length > 128) return false;
  if (!/[a-z]/.test(value)) return false;
  if (!/[A-Z]/.test(value)) return false;
  if (!/[0-9]/.test(value)) return false;
  if (!/[^A-Za-z0-9]/.test(value)) return false;
  return true;
}

// ---------------------------------------------------------------------------
// OAuth 2.0 access & refresh token helpers
// ---------------------------------------------------------------------------
function createOAuthAccessToken(userProfile) {
  const expiresAt = now() + OAUTH_ACCESS_TTL_MS;
  const payload = base64UrlEncode(JSON.stringify({ sub: userProfile.email, profile: userProfile, expiresAt, type: 'access' }));
  return { token: `${payload}.${hmacSign(payload)}`, expiresAt, expiresIn: Math.floor(OAUTH_ACCESS_TTL_MS / 1000) };
}

function parseOAuthAccessToken(token) {
  const raw = String(token || '');
  const dotIdx = raw.lastIndexOf('.');
  if (dotIdx <= 0) return null;
  const payload = raw.slice(0, dotIdx);
  const signature = raw.slice(dotIdx + 1);
  // Try sha512 first (current), fall back to sha256 (legacy tokens)
  const expected512 = hmacSign(payload);
  let sigValid = signature.length === expected512.length && crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected512, 'utf8'));
  if (!sigValid) {
    const expected256 = crypto.createHmac('sha256', SECRET).update(payload).digest('hex');
    sigValid = signature.length === expected256.length && crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected256, 'utf8'));
  }
  if (!sigValid) return null;

  try {
    const parsed = JSON.parse(base64UrlDecode(payload));
    if (!parsed || typeof parsed !== 'object') return null;
    if (parsed.type !== 'access') return null;
    if (typeof parsed.expiresAt !== 'number') return null;
    if (parsed.expiresAt <= now()) return { expired: true, profile: parsed.profile };
    return { expired: false, profile: parsed.profile };
  } catch {
    return null;
  }
}

function createOAuthRefreshToken(email) {
  const tokenValue = crypto.randomBytes(32).toString('hex');
  const tokenHash = crypto.createHash('sha256').update(tokenValue).digest('hex');
  dbState.refreshTokens[tokenHash] = {
    email: String(email).trim().toLowerCase(),
    createdAt: now(),
    expiresAt: now() + OAUTH_REFRESH_TTL_MS,
  };
  saveDbState();
  return tokenValue;
}

function consumeOAuthRefreshToken(tokenValue) {
  const tokenHash = crypto.createHash('sha256').update(String(tokenValue || '')).digest('hex');
  const entry = dbState.refreshTokens[tokenHash];
  if (!entry) return null;
  // Always delete the token (single-use rotation)
  delete dbState.refreshTokens[tokenHash];
  saveDbState();
  if (entry.expiresAt <= now()) return null;
  return entry;
}

function revokeOAuthRefreshToken(tokenValue) {
  const tokenHash = crypto.createHash('sha256').update(String(tokenValue || '')).digest('hex');
  delete dbState.refreshTokens[tokenHash];
  saveDbState();
}

function revokeAllRefreshTokensForEmail(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return 0;
  let count = 0;
  for (const tokenHash of Object.keys(dbState.refreshTokens)) {
    if (dbState.refreshTokens[tokenHash] && dbState.refreshTokens[tokenHash].email === normalizedEmail) {
      delete dbState.refreshTokens[tokenHash];
      count++;
    }
  }
  if (count > 0) saveDbState();
  return count;
}

function getBearerToken(req) {
  const auth = req.headers.authorization || '';
  if (auth.startsWith('Bearer ')) return auth.slice(7).trim();
  return null;
}

function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;

    req.on('data', (chunk) => {
      total += chunk.length;
      if (total > MAX_JSON_BODY_BYTES) {
        reject(new Error('Payload too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const raw = Buffer.concat(chunks).toString('utf8').trim();
        resolve(raw ? JSON.parse(raw) : {});
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });

    req.on('error', reject);
  });
}

/**
 * Read raw body bytes — preserves bytes for HMAC-SHA256 webhook verification.
 * Unlike readJsonBody, this does NOT parse; caller must parse manually.
 */
function readRawBody(req, maxBytes) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    const limit = maxBytes || MAX_JSON_BODY_BYTES;
    req.on('data', (chunk) => {
      total += chunk.length;
      if (total > limit) {
        reject(new Error('Payload too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

/**
 * Normalise a phone number to E.164 format (best-effort).
 * Assumes Australian (+61) local numbers if no country code prefix is present.
 */
function normalizePhone(phone) {
  if (!phone || typeof phone !== 'string') return '';
  const digits = phone.replace(/[^\d+]/g, '');
  if (digits.startsWith('+')) return digits;
  // Australian local format: 04xxxxxxxx → +614xxxxxxxx
  if (digits.startsWith('0') && digits.length === 10) return '+61' + digits.slice(1);
  if (digits.length >= 10 && digits.length <= 15) return '+' + digits;
  return digits;
}

/**
 * Verify a DoubleTick HMAC-SHA256 webhook signature using timing-safe comparison.
 * Returns false (not an exception) so callers can log + reject with 401.
 */
function validateDoubleTickSignature(rawBody, signatureHeader) {
  if (!DOUBLETICK_WEBHOOK_SECRET) return false;
  if (!signatureHeader || typeof signatureHeader !== 'string') return false;
  try {
    const expected = crypto
      .createHmac('sha256', DOUBLETICK_WEBHOOK_SECRET)
      .update(rawBody)
      .digest('hex');
    // Header may arrive as "sha256=<hex>" or bare hex
    const incoming = signatureHeader.replace(/^sha256=/, '');
    const incomingBuf = Buffer.from(incoming, 'hex');
    const expectedBuf = Buffer.from(expected, 'hex');
    // Lengths must match before timingSafeEqual to avoid a TypeError
    if (incomingBuf.length !== expectedBuf.length) return false;
    return crypto.timingSafeEqual(incomingBuf, expectedBuf);
  } catch {
    return false;
  }
}

// Per-phone AI classification spend tracker: { phone: { date, totalCostUsd } }
const dtClassifyPhoneSpend = {};
const DT_CLASSIFY_PHONE_DAILY_LIMIT_USD = 0.001;
// Haiku pricing: $0.80/M input, $4/M output
const HAIKU_INPUT_COST_PER_TOKEN = 0.80 / 1000000;
const HAIKU_OUTPUT_COST_PER_TOKEN = 4 / 1000000;

function checkDtPhoneBudget(phone) {
  const today = new Date().toISOString().slice(0, 10);
  const entry = dtClassifyPhoneSpend[phone];
  if (!entry || entry.date !== today) return true;
  return entry.totalCostUsd < DT_CLASSIFY_PHONE_DAILY_LIMIT_USD;
}

function recordDtPhoneSpend(phone, inputTokens, outputTokens) {
  const today = new Date().toISOString().slice(0, 10);
  if (!dtClassifyPhoneSpend[phone] || dtClassifyPhoneSpend[phone].date !== today) {
    dtClassifyPhoneSpend[phone] = { date: today, totalCostUsd: 0 };
  }
  dtClassifyPhoneSpend[phone].totalCostUsd += (inputTokens * HAIKU_INPUT_COST_PER_TOKEN) + (outputTokens * HAIKU_OUTPUT_COST_PER_TOKEN);
}

/**
 * Use AI to classify whether a DoubleTick message is a question or help request.
 * Falls back to keyword matching if AI is unavailable or over budget.
 * Rate-limited to $0.001/phone/day for AI classification calls.
 */
async function classifyDoubleTickMessage(messageBody, fromPhone) {
  // Fast keyword pre-check — obvious help/question messages skip the AI call
  const HELP_PATTERNS = [/\bhelp\b/i, /\bneed help\b/i, /\bassist\b/i, /\bsupport\b/i, /\bstuck\b/i, /\bproblem\b/i, /\bissue\b/i, /\bquestion\b/i, /\bshould\s+I\b/i, /\bcan\s+I\b/i, /\bdo\s+I\b/i, /\bhow\s+(do|can|to)\b/i, /\bwhat\s+(do|should|can)\b/i, /\bwhen\s+(do|should|can|will)\b/i, /\bwhere\s+(do|should|can)\b/i, /\?\s*$/];
  if (HELP_PATTERNS.some((p) => p.test(messageBody))) return true;

  // Skip AI if not configured, over global budget, or over per-phone budget
  // Default to TRUE (treat as help request) — missing a message is worse than a false positive
  if (!ANTHROPIC_API_KEY || !(await checkAnthropicBudget()) || !checkDtPhoneBudget(fromPhone)) {
    return true;
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 30000);
  try {
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: ANTHROPIC_MODEL,
        max_tokens: 4,
        messages: [{
          role: 'user',
          content: 'You are a message classifier for a GP (doctor) registration support service. GPs message us on WhatsApp when they need guidance. Determine if the following message is ANY of: a question, request for guidance, help request, complaint, expression of confusion, or asking what to do next. Be INCLUSIVE — when in doubt, say YES. Only say NO for purely social messages like "thanks", "ok", "goodbye", or messages that clearly need no response. Reply with exactly YES or NO.\n\nMessage: ' + messageBody.slice(0, 500)
        }]
      })
    });
    if (!resp.ok) {
      console.warn('[doubletick-webhook] AI classify failed:', resp.status, '— defaulting to help request');
      return true;
    }
    const result = await resp.json();
    const answer = (result.content && result.content[0] && result.content[0].text || '').trim().toUpperCase();
    const usage = result.usage || {};
    // Record against both global and per-phone budgets
    recordAnthropicSpend(usage.input_tokens || 0, usage.output_tokens || 0, usage.cache_read_input_tokens || 0, usage.cache_creation_input_tokens || 0);
    recordDtPhoneSpend(fromPhone, usage.input_tokens || 0, usage.output_tokens || 0);
    // Only ignore if AI explicitly says NO — ambiguous or empty answers default to help request
    return answer !== 'NO';
  } catch (err) {
    console.warn('[doubletick-webhook] AI classify error:', err && err.message, '— defaulting to help request');
    return true;
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Validate and sanitize fields from a DoubleTick webhook payload.
 * Returns a sanitized object or null if required fields are missing/invalid.
 *
 * DoubleTick payload format (MESSAGE_RECEIVED):
 *   { from: "61400000001", message: { type: "TEXT", text: "..." }, messageId: "...", dtMessageId: "...", contact: { name: "..." } }
 *
 * Security controls applied here:
 *   - messageBody capped at DOUBLETICK_MESSAGE_BODY_MAX_LEN (4096)
 *   - fromPhone stripped of non-numeric characters
 *   - conversationUrl allow-listed to https://app.doubletick.io/ origin
 *   - messageId restricted to alphanumeric + dash/underscore (idempotency key)
 */
function sanitizeDoubleTickPayload(body) {
  if (!body || typeof body !== 'object') return null;

  // Extract message text: DoubleTick nests it under message.text (TEXT) or message.caption (media)
  const msg = body.message && typeof body.message === 'object' ? body.message : null;
  const rawMessageBody = msg
    ? (typeof msg.text === 'string' ? msg.text : (typeof msg.caption === 'string' ? msg.caption : null))
    : null;
  const messageBody = typeof rawMessageBody === 'string'
    ? rawMessageBody.slice(0, DOUBLETICK_MESSAGE_BODY_MAX_LEN)
    : null;

  // Phone: DoubleTick uses "from"
  const rawPhone = typeof body.from === 'string' ? body.from : null;
  const fromPhone = typeof rawPhone === 'string'
    ? rawPhone.replace(/[^\d+\-() ]/g, '').slice(0, 30)
    : null;

  // Contact name from DoubleTick's contact object
  const contactName = (body.contact && typeof body.contact.name === 'string')
    ? body.contact.name.replace(/[<>]/g, '').slice(0, 200)
    : null;

  // Allow-list: conversation URL must start with the DoubleTick app origin (not sent by default)
  const rawUrl = typeof body.conversation_url === 'string' ? body.conversation_url.trim() : '';
  const conversationUrl = rawUrl.startsWith(DOUBLETICK_CONVERSATION_URL_PREFIX) ? rawUrl : null;

  // Idempotency key: DoubleTick uses "messageId" or "dtMessageId"
  const rawMsgId = typeof body.dtMessageId === 'string'
    ? body.dtMessageId
    : (typeof body.messageId === 'string' ? body.messageId : null);
  const messageId = typeof rawMsgId === 'string'
    ? rawMsgId.replace(/[^a-zA-Z0-9_\-]/g, '').slice(0, 128)
    : null;

  if (!fromPhone || !messageBody) return null;
  return { messageBody, fromPhone, contactName, conversationUrl, messageId };
}

/**
 * POST /api/webhooks/doubletick
 * Handles inbound DoubleTick WhatsApp message webhooks.
 *
 * IMPORTANT: Register this handler in the main request router BEFORE
 * same-origin enforcement (ENFORCE_SAME_ORIGIN) because DoubleTick delivers
 * from an external origin. Example registration (place before same-origin block):
 *
 *   if (method === 'POST' && pathname === '/api/webhooks/doubletick') {
 *     return handleDoubleTickWebhook(req, res);
 *   }
 *
 * Disabled (returns 503) when DOUBLETICK_WEBHOOK_SECRET is not configured.
 *
 * Auth: DoubleTick does not provide HMAC signing. Instead, append the secret
 * as a query parameter in the webhook URL registered in DoubleTick:
 *   ${APP_BASE_URL}/api/webhooks/doubletick?secret=YOUR_SECRET
 */
async function handleDoubleTickWebhook(req, res) {
  if (!DOUBLETICK_WEBHOOK_SECRET) {
    console.warn('[doubletick-webhook] DOUBLETICK_WEBHOOK_SECRET not set — webhook disabled');
    sendJson(res, 503, { ok: false, message: 'Webhook not configured' });
    return;
  }

  // Verify shared secret from URL query parameter (timing-safe comparison)
  const reqUrl = new URL(req.url, 'http://localhost');
  const providedSecret = reqUrl.searchParams.get('secret') || '';
  const secretBuf = Buffer.from(DOUBLETICK_WEBHOOK_SECRET);
  const providedBuf = Buffer.from(providedSecret);
  if (secretBuf.length !== providedBuf.length || !crypto.timingSafeEqual(secretBuf, providedBuf)) {
    console.warn('[doubletick-webhook] Invalid secret from IP:', getClientIp(req));
    sendJson(res, 401, { ok: false, message: 'Unauthorized' });
    return;
  }

  // Rate-limit by source IP (60 req/min) — prevents flood from a compromised account
  const ip = getClientIp(req);
  const allowed = await checkRateLimitWindow(
    `doubletick_webhook:${ip}`,
    DOUBLETICK_WEBHOOK_RATE_MAX,
    DOUBLETICK_WEBHOOK_RATE_WINDOW_MS
  );
  if (!allowed) {
    sendJson(res, 429, { ok: false, message: 'Too many requests' });
    return;
  }

  // Parse JSON body
  let body;
  try {
    body = await readJsonBody(req);
  } catch {
    sendJson(res, 400, { ok: false, message: 'Invalid JSON' });
    return;
  }

  // Validate and sanitize all fields; reject on missing required fields
  const payload = sanitizeDoubleTickPayload(body);
  if (!payload) {
    console.warn('[doubletick-webhook] Sanitize rejected payload — keys:', body ? Object.keys(body).join(', ') : 'null');
    sendJson(res, 400, { ok: false, message: 'Missing required fields: from, message.text' });
    return;
  }

  const { messageBody, fromPhone, contactName, conversationUrl, messageId } = payload;

  // Store message for reconciliation
  if (isSupabaseDbConfigured()) {
    const phoneClean = fromPhone.replace(/[^0-9]/g, '');
    let dtCaseId = null;
    let dtUserId = null;

    // Try to match phone to a user profile (fuzzy last-9-digit match on both phone columns)
    if (phoneClean.length >= 9) {
      const phoneSuffix = phoneClean.slice(-9);
      const userLookup = await supabaseDbRequest('user_profiles',
        'select=id,user_id&or=(phone.ilike.*' + phoneSuffix + ',phone_number.ilike.*' + phoneSuffix + ')&limit=1');
      if (userLookup.ok && Array.isArray(userLookup.data) && userLookup.data.length > 0) {
        dtUserId = userLookup.data[0].user_id;
        const caseLookup = await supabaseDbRequest('registration_cases',
          'user_id=eq.' + dtUserId + '&select=id');
        if (caseLookup.ok && Array.isArray(caseLookup.data) && caseLookup.data.length > 0) {
          dtCaseId = caseLookup.data[0].id;
        }
      }
    }

    await supabaseDbRequest('doubletick_messages', '', {
      method: 'POST',
      body: [{
        case_id: dtCaseId,
        user_id: dtUserId,
        from_phone: fromPhone,
        contact_name: contactName || null,
        message_body: (messageBody || '').substring(0, 2000),
        message_type: (body.message && body.message.type) || 'TEXT',
        direction: 'inbound',
        doubletick_message_id: messageId || null,
        conversation_url: conversationUrl || null
      }]
    }).catch(err => console.error('[DT] Message storage failed:', err.message));
  }

  // Use AI to determine if the message is a question or help request
  const isHelpRequest = await classifyDoubleTickMessage(messageBody, fromPhone);
  if (!isHelpRequest) {
    sendJson(res, 200, { ok: true, action: 'ignored' });
    return;
  }

  try {
    // Idempotency: skip if we've already handled this exact message. Check BOTH
    // where a message can land: as its own task (first message) OR folded into an
    // existing ticket's task_messages (a grouped message). Without the second
    // check, a webhook redelivery of a grouped message would fold it again.
    if (messageId && isSupabaseDbConfigured()) {
      const existing = await supabaseDbRequest(
        'registration_tasks',
        'select=id&doubletick_message_id=eq.' + encodeURIComponent(messageId) + '&limit=1'
      );
      if (existing.ok && Array.isArray(existing.data) && existing.data.length > 0) {
        sendJson(res, 200, { ok: true, action: 'duplicate_ignored' });
        return;
      }
      const existingMsg = await supabaseDbRequest(
        'task_messages',
        'select=id&doubletick_message_id=eq.' + encodeURIComponent(messageId) + '&limit=1'
      );
      if (existingMsg.ok && Array.isArray(existingMsg.data) && existingMsg.data.length > 0) {
        sendJson(res, 200, { ok: true, action: 'duplicate_ignored' });
        return;
      }
    }

    // Resolve GP by phone — try exact match first (fast), then fuzzy suffix match (flexible)
    const normalizedPhone = normalizePhone(fromPhone);
    const localPhone = normalizedPhone.startsWith('+61')
      ? '0' + normalizedPhone.slice(3)
      : (fromPhone.startsWith('61') && fromPhone.length === 11 ? '0' + fromPhone.slice(2) : null);
    const phoneDigits = fromPhone.replace(/[^0-9]/g, '');
    const bareNumber = phoneDigits.length > 9 ? phoneDigits.slice(-9) : phoneDigits; // e.g. 406281243
    let gpProfile = null;
    if (isSupabaseDbConfigured()) {
      // Try exact match on multiple formats (handles most stored formats)
      for (const pv of [...new Set([normalizedPhone, fromPhone, localPhone, bareNumber, '0' + bareNumber].filter(Boolean))]) {
        for (const col of ['phone_number', 'phone']) {
          const r = await supabaseDbRequest(
            'user_profiles',
            'select=user_id,first_name,last_name,email,phone_number,phone&' + col + '=eq.' + encodeURIComponent(pv) + '&limit=1'
          );
          if (r.ok && Array.isArray(r.data) && r.data.length > 0) { gpProfile = r.data[0]; break; }
        }
        if (gpProfile) break;
      }
      // Fallback: fuzzy suffix match (handles spaces, formatting differences)
      if (!gpProfile && phoneDigits.length >= 9) {
        const suffix = phoneDigits.slice(-9);
        const r = await supabaseDbRequest(
          'user_profiles',
          'select=user_id,first_name,last_name,email,phone_number,phone&or=(phone.ilike.*' + suffix + ',phone_number.ilike.*' + suffix + ')&limit=1'
        );
        if (r.ok && Array.isArray(r.data) && r.data.length > 0) { gpProfile = r.data[0]; }
      }
    }

    // Find the most recent active registration case for this GP
    let activeCase = null;
    if (gpProfile && isSupabaseDbConfigured()) {
      const cr = await supabaseDbRequest(
        'registration_cases',
        'select=id,stage,substage,user_id,assigned_va&user_id=eq.' + encodeURIComponent(gpProfile.user_id) + '&status=not.eq.closed&order=created_at.desc&limit=1'
      );
      if (cr.ok && Array.isArray(cr.data) && cr.data.length > 0) activeCase = cr.data[0];
    }

    // If GP profile found but no active case, create one so the message isn't lost
    if (!activeCase && gpProfile && isSupabaseDbConfigured()) {
      activeCase = await _ensureRegCase(gpProfile.user_id);
      if (activeCase) console.log('[doubletick-webhook] Created registration case for', gpProfile.user_id);
    }

    // Backstop: make sure the DoubleTick chat is owned by the RSO who actually
    // owns this GP (closes the brief "unassigned, visible to all" window on
    // first inbound). Best-effort, fire-and-forget.
    //
    // Routed through resolveSupportRsoForUser (2026-07-30) rather than reading
    // assigned_va directly, so an INBOUND message lands on the same officer the
    // in-app WhatsApp button hands off to. Reading assigned_va here while the
    // button used the placed/unplaced rule would have let the two disagree —
    // the GP taps the button, gets routed to admin, then their first message
    // re-assigns the chat to someone else.
    if (activeCase && fromPhone) {
      const dtRouted = await resolveSupportRsoForUser(activeCase.user_id, activeCase)
        .catch(function () { return { rsoUserId: activeCase.assigned_va || null }; });
      if (dtRouted && dtRouted.rsoUserId) {
        syncCaseChatAssignment({ gpPhone: fromPhone, assignedVaUserId: dtRouted.rsoUserId })
          .catch(function (e) { console.error('[doubletick-assign] webhook backstop failed:', e && e.message); });
      }
    }

    const gpName = gpProfile
      ? [(gpProfile.first_name || ''), (gpProfile.last_name || '')].join(' ').trim()
      : (contactName || '');

    // Check for pending nudges — if GP is replying after a nudge, activate the chat and record the reply
    let isNudgeReply = false;
    if (gpProfile && isSupabaseDbConfigured()) {
      const nudgeRes = await supabaseDbRequest(
        'user_nudges',
        'select=id,title&user_id=eq.' + encodeURIComponent(gpProfile.user_id) + '&status=in.(pending,delivered)&order=created_at.desc&limit=5'
      );
      const pendingNudges = nudgeRes.ok && Array.isArray(nudgeRes.data) ? nudgeRes.data : [];
      if (pendingNudges.length > 0) {
        isNudgeReply = true;
        // Activate all pending nudges as chat threads and insert the WhatsApp reply as a message
        for (const n of pendingNudges) {
          await supabaseDbRequest('user_nudges', 'id=eq.' + encodeURIComponent(n.id), {
            method: 'PATCH',
            headers: { Prefer: 'return=minimal' },
            body: { status: 'active', read_at: new Date().toISOString() }
          });
          await supabaseDbRequest('nudge_chat_messages', '', {
            method: 'POST',
            body: [{ nudge_id: n.id, sender_type: 'user', sender_email: '', message: messageBody || '(WhatsApp reply)' }]
          });
        }
        console.log('[doubletick-webhook] Activated', pendingNudges.length, 'nudge chat(s) for', gpProfile.user_id);
      }
    }

    // Stage label map for human-readable VA task titles (DoubleTick webhook help tasks)
    const _dtStageLabel = activeCase
      ? (({ myintealth: 'MyIntealth', amc: 'AMC', career: 'Career', ahpra: 'AHPRA', visa: 'Visa', pbs: 'PBS', commencement: 'Commencement' })[activeCase.stage] || (activeCase.stage || 'Registration'))
      : 'New enquiry';
    const taskTitle = isNudgeReply
      ? 'Reply to nudge — ' + _dtStageLabel
      : activeCase
        ? 'GP requested WhatsApp help — ' + _dtStageLabel
        : 'WhatsApp enquiry from ' + (gpName || fromPhone);
    // For unregistered contacts, include phone + contact name in description so VA can respond
    const taskDescription = activeCase
      ? messageBody.slice(0, 500)
      : (gpName ? gpName + ' (' + fromPhone + ')' : fromPhone) + '\n\n' + messageBody.slice(0, 500);
    const taskPayload = {
      case_id: activeCase ? activeCase.id : null,
      task_type: 'whatsapp_help',
      title: taskTitle,
      description: taskDescription,
      priority: activeCase ? 'normal' : 'low',
      status: 'open',
      source_trigger: 'doubletick_webhook',
      related_stage: activeCase ? (activeCase.stage || '') : '',
      related_substage: activeCase ? (activeCase.substage || '') : '',
      doubletick_conversation_url: conversationUrl || null,
      doubletick_message_id: messageId || null,
      due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
    };

    if (isSupabaseDbConfigured()) {
      // If no conversation URL from the payload, fetch it from DoubleTick embed API
      if (!taskPayload.doubletick_conversation_url && DOUBLETICK_API_KEY) {
        try {
          const dtResult = await fetchDoubleTickCustomerId(fromPhone);
          if (dtResult.url) {
            const webUrl = embedUrlToWebUrl(dtResult.url);
            taskPayload.doubletick_conversation_url = webUrl || dtResult.url;
          }
        } catch (e) { console.warn('[doubletick-webhook] Failed to fetch conversation URL:', e.message); }
      }

      // ── Grouping (sliding 24h, per contact) ──────────────────────────────
      // Same person + same channel (WhatsApp) within the window → fold this
      // message into that person's existing OPEN ticket instead of spawning a
      // new one. The contact is keyed by their DoubleTick conversation (per
      // phone), with a case_id fallback for registered GPs. Each fold bumps
      // updated_at so the window slides with the conversation.
      const _waSince = new Date(Date.now() - SUPPORT_GROUP_WINDOW_MS).toISOString();
      let _waGroupTarget = null;
      const _waOpen = '&status=in.(open,in_progress,waiting)';
      if (taskPayload.doubletick_conversation_url) {
        const g = await supabaseDbRequest('registration_tasks',
          'select=id,case_id&task_type=eq.whatsapp_help' + _waOpen +
          '&doubletick_conversation_url=eq.' + encodeURIComponent(taskPayload.doubletick_conversation_url) +
          '&updated_at=gte.' + encodeURIComponent(_waSince) + '&order=updated_at.desc&limit=1');
        if (g.ok && Array.isArray(g.data) && g.data.length > 0) _waGroupTarget = g.data[0];
      }
      if (!_waGroupTarget && activeCase) {
        const g2 = await supabaseDbRequest('registration_tasks',
          'select=id,case_id&task_type=eq.whatsapp_help' + _waOpen +
          '&case_id=eq.' + encodeURIComponent(activeCase.id) +
          '&updated_at=gte.' + encodeURIComponent(_waSince) + '&order=updated_at.desc&limit=1');
        if (g2.ok && Array.isArray(g2.data) && g2.data.length > 0) _waGroupTarget = g2.data[0];
      }
      if (_waGroupTarget) {
        await supabaseDbRequest('task_messages', '', {
          method: 'POST', body: [{
            task_id: _waGroupTarget.id, case_id: _waGroupTarget.case_id || (activeCase ? activeCase.id : null),
            direction: 'inbound', channel: 'whatsapp', sender: fromPhone,
            body_text: (messageBody || '').substring(0, 2000), doubletick_message_id: messageId || null,
            created_at: new Date().toISOString()
          }]
        }).catch(err => console.error('[doubletick-webhook] group message insert failed:', err && err.message));
        await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(_waGroupTarget.id),
          { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: { updated_at: new Date().toISOString() } });
        console.log('[doubletick-webhook] Grouped WhatsApp message into existing ticket', _waGroupTarget.id);
        sendJson(res, 200, { ok: true, action: 'task_appended' });
        return;
      }

      const tRes = await supabaseDbRequest(
        'registration_tasks',
        '',
        { method: 'POST', headers: { Prefer: 'return=representation' }, body: [taskPayload] }
      );
      if (!tRes.ok) {
        // Internal error — do not expose details to webhook caller
        console.error('[doubletick-webhook] Failed to create task');
        sendJson(res, 500, { ok: false, message: 'Internal error' });
        return;
      }
    }

    sendJson(res, 200, { ok: true, action: 'task_created' });
  } catch (err) {
    // Never expose stack traces or internal details to the webhook caller
    console.error('[doubletick-webhook] Unexpected error:', err && err.message);
    sendJson(res, 500, { ok: false, message: 'Internal error' });
  }
}

/**
 * GET/POST /api/webhooks/facebook-lead
 * GET: FB Lead Ads webhook verification handshake.
 * POST: Facebook (or Zapier-relayed) lead delivery -> creates a prospective
 * practice row + sends the practice a themed intake email.
 *
 * Disabled (POST returns 503) when FB_LEAD_WEBHOOK_SECRET is not configured.
 * Auth: shared secret as a query parameter (timing-safe comparison), same
 * pattern as the DoubleTick webhook above:
 *   ${APP_BASE_URL}/api/webhooks/facebook-lead?secret=YOUR_SECRET
 */
async function handleFacebookLeadWebhook(req, res) {
  const reqUrl = new URL(req.url, 'http://localhost');

  if (req.method === 'GET') {
    const mode = reqUrl.searchParams.get('hub.mode') || '';
    const verifyToken = reqUrl.searchParams.get('hub.verify_token') || '';
    const challenge = reqUrl.searchParams.get('hub.challenge') || '';
    const expectedToken = process.env.FB_LEAD_VERIFY_TOKEN || '';
    if (mode === 'subscribe' && expectedToken && verifyToken === expectedToken) {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end(challenge);
      return;
    }
    sendJson(res, 403, { ok: false, message: 'Verification failed' });
    return;
  }

  if (req.method !== 'POST') {
    sendJson(res, 405, { ok: false, message: 'Method not allowed' });
    return;
  }

  if (!process.env.FB_LEAD_WEBHOOK_SECRET) {
    console.warn('[fb-lead-webhook] FB_LEAD_WEBHOOK_SECRET not set — webhook disabled');
    sendJson(res, 503, { ok: false, message: 'Webhook not configured' });
    return;
  }

  // Verify shared secret from URL query parameter (timing-safe comparison)
  const providedSecret = reqUrl.searchParams.get('secret') || '';
  const secretBuf = Buffer.from(process.env.FB_LEAD_WEBHOOK_SECRET);
  const providedBuf = Buffer.from(providedSecret);
  if (secretBuf.length !== providedBuf.length || !crypto.timingSafeEqual(secretBuf, providedBuf)) {
    console.warn('[fb-lead-webhook] Invalid secret from IP:', getClientIp(req));
    sendJson(res, 401, { ok: false, message: 'Unauthorized' });
    return;
  }

  // Rate-limit by source IP (30 req/hour) — prevents flood from a leaked URL
  const ip = getClientIp(req);
  const allowed = await checkRateLimitWindow(`fb_lead_webhook:${ip}`, 30, 60 * 60 * 1000);
  if (!allowed) {
    sendJson(res, 429, { ok: false, message: 'Too many requests' });
    return;
  }

  let body;
  try {
    body = await readJsonBody(req);
  } catch {
    sendJson(res, 400, { ok: false, message: 'Invalid JSON' });
    return;
  }

  // GP lead-gen forms (Meta-ads GP funnel): allow-listed form IDs route to
  // site_enquiries as consult leads instead of the practice pipeline.
  const gpFormIds = consultLead.parseGpFormIds(process.env.FB_GP_LEAD_FORM_IDS);
  const gpLead = gpFormIds.length ? consultLead.normalizeFacebookGpLead(body, gpFormIds) : null;
  if (gpLead) {
    if (await hasRecordedWebhookEvent('facebook_lead', gpLead.leadId)) {
      sendJson(res, 200, { ok: true, action: 'duplicate_ignored' }); return;
    }
    const gpRow = buildConsultLeadRow({
      name: gpLead.name || gpLead.email, email: gpLead.email, phone: gpLead.phone,
      isGp: gpLead.isGp === true, country: gpLead.country, question: gpLead.question,
      source: 'meta_lead_ad', leadId: gpLead.leadId, ip: ip,
      userAgent: req.headers['user-agent']
    });
    const gpStored = await insertSiteEnquiryRow(gpRow);
    if (!gpStored) { sendJson(res, 500, { ok: false, error: 'store_failed' }); return; }
    // Record the dedupe marker only after the store succeeds — recording
    // after the store (not before) means a failed store is retryable; a
    // race here duplicates a lead at worst, never loses one.
    await checkAndRecordWebhookEvent('facebook_lead', gpLead.leadId, 'gp_lead', {
      event: 'gp_lead', created_at: new Date().toISOString()
    });
    // Speed-to-lead: owner alert (uses SITE_ENQUIRY_NOTIFY_EMAIL; no-op if unset)
    await maybeNotifySiteEnquiry(gpRow);
    // Magic link so they can book with zero re-typing (qualified leads only)
    if (gpRow.metadata.consult.qualified) {
      try { await sendConsultMagicLinkEmail(gpRow); }
      catch (e) { console.error('[fb-gp-lead] magic-link email failed:', e.message); }
    }
    sendJson(res, 200, { ok: true, kind: 'gp_lead', lead_id: gpRow.id });
    return;
  }

  const lead = practicePipeline.normalizeFacebookLeadPayload(body);
  if (!lead) {
    sendJson(res, 400, { ok: false, error: 'unrecognized_payload' });
    return;
  }

  const isDuplicate = await checkAndRecordWebhookEvent('facebook_lead', lead.leadId, 'lead', {
    event: 'lead',
    created_at: new Date().toISOString()
  });
  if (isDuplicate) {
    sendJson(res, 200, { ok: true, action: 'duplicate_ignored' });
    return;
  }

  try {
    var pracRow = {
      name: lead.practice_name || (lead.contact_name ? lead.contact_name + "'s practice" : 'New practice lead'),
      location_city: lead.location || '', location_state: '', location_country: 'Australia',
      practice_type: '', contact_name: lead.contact_name || '', contact_email: lead.contact_email || '',
      contact_phone: lead.contact_phone || '', ahpra_number: '',
      source: 'facebook_lead', is_active: true, created_by: 'facebook_lead_webhook',
      stage: 'prospective', website: lead.website || '',
      dpa: typeof lead.dpa === 'boolean' ? lead.dpa : null,
      intake_token: practicePipeline.generateIntakeToken(),
      agreement_status: 'unsigned',
      metadata: { fb_lead: lead, fb_raw: body }
    };

    var created = await atsInsertPracticeRow(pracRow);
    var degraded = false;
    if (!created && isSupabaseDbConfigured()) {
      // Missing-column tolerance: the practice_client_pipeline migration
      // (20260705100000) may not be applied yet. Retry with only the
      // original practices columns so the webhook never 500s on lagging DDL.
      console.error('[fb-lead] practices pipeline columns missing — run migration 20260705100000');
      var legacyRow = {
        name: pracRow.name,
        location_city: pracRow.location_city,
        location_state: pracRow.location_state,
        location_country: pracRow.location_country,
        practice_type: pracRow.practice_type,
        contact_name: pracRow.contact_name,
        contact_email: pracRow.contact_email,
        contact_phone: pracRow.contact_phone,
        ahpra_number: pracRow.ahpra_number,
        source: 'manual',
        is_active: true,
        created_by: pracRow.created_by
      };
      created = await atsInsertPracticeRow(legacyRow);
      degraded = true;
    }

    if (!created) {
      sendJson(res, 500, { ok: false, message: 'Failed to save practice lead' });
      return;
    }

    if (degraded) {
      // The legacy row has no intake_token column and no metadata column to
      // fall back to, so any token we generate here can't be persisted —
      // sending the intake email would hand the practice a dead link. Skip
      // the send entirely until the migration is applied and the practice
      // can be re-sent a working intake email from the admin dashboard.
      console.error('[fb-lead] intake token not persistable — run migration 20260705100000, then use Resend intake email');
    } else {
      // Await the send BEFORE responding: on Vercel the function can be killed
      // right after res.end(), so a fire-and-forget Resend call may silently
      // never complete (same constraint the Gmail webhook documents). Still
      // best-effort — the .catch means a failed email never fails the webhook.
      await sendPracticeIntakeEmail(created).catch(function (e) {
        console.error('[fb-lead] intake email send failed:', e && e.message);
      });
    }

    var response = { ok: true, practice_id: created.id };
    if (degraded) response.degraded = true;
    sendJson(res, 200, response);
  } catch (err) {
    console.error('[fb-lead-webhook] Unexpected error:', err && err.message);
    sendJson(res, 500, { ok: false, message: 'Internal error' });
  }
}

/**
 * Sends the themed "your GP is waiting" intake email to a practice contact,
 * ensuring the row has an intake_token (generating + persisting one if it
 * doesn't) and recording metadata.intake_email_last_sent_at on success.
 * Best-effort for the caller ({ok:false} never throws), but fail-CLOSED on
 * token persistence: an unpersisted token can never match
 * findPracticeByIntakeToken, so emailing it would hand the practice a link
 * that always shows "This link has expired".
 */
async function sendPracticeIntakeEmail(practice) {
  if (!practice) return { ok: false };
  var token = practice.intake_token || (practice.metadata && practice.metadata.intake_token);
  if (!token) {
    token = practicePipeline.generateIntakeToken();
    var patchedMeta = Object.assign({}, practice.metadata || {}, { intake_token: token });
    var patched = await atsUpdatePracticeRow(practice.id, { metadata: patchedMeta }).catch(function () { return null; });
    if (!patched) {
      // Abort — see the fail-closed note above. (Previously this proceeded
      // with the in-memory token and the recipient got a dead link.)
      console.error('[practice-intake] intake token persist failed for practice', practice.id, '— intake email NOT sent');
      return { ok: false, error: 'intake_token_not_persisted' };
    }
    practice = patched;
  }

  var intakeUrl = APP_BASE_URL + '/pages/practice-intake?token=' + encodeURIComponent(token);
  var copy = practicePipeline.buildIntakeEmailCopy({
    practiceName: practice.name,
    contactName: practice.contact_name,
    intakeUrl: intakeUrl,
    logoUrl: APP_BASE_URL + '/media/images/gp-link-logo.png'
  });

  var result = await sendEmail({
    to: practice.contact_email,
    subject: copy.subject,
    html: buildCareerEmailHtml(copy),
    from: { email: GP_OWNER_EMAIL, name: 'GP Link' }
  });

  if (result && result.ok) {
    var current = await atsGetPracticeRow(practice.id).catch(function () { return null; });
    var mergedMeta = Object.assign({}, (current && current.metadata) || practice.metadata || {}, {
      intake_email_last_sent_at: new Date().toISOString()
    });
    await atsUpdatePracticeRow(practice.id, { metadata: mergedMeta }).catch(function (e) {
      console.error('[fb-lead] failed to record intake_email_last_sent_at:', e && e.message);
    });
  }

  return result;
}

/**
 * Returns the practice's intake token, generating and persisting one (via the
 * metadata stash — same dual-location convention sendPracticeIntakeEmail and
 * findPracticeByIntakeToken already use) when the row doesn't have one yet.
 * Best-effort persistence: on a failed patch the fresh token is still
 * returned so the email link keeps working wherever the patch DID land;
 * '' is only returned when there is no practice row at all.
 */
async function ensurePracticeIntakeToken(practice) {
  if (!practice) return '';
  var token = practice.intake_token || (practice.metadata && practice.metadata.intake_token);
  if (token) return token;
  token = practicePipeline.generateIntakeToken();
  var patchedMeta = Object.assign({}, practice.metadata || {}, { intake_token: token });
  var patched = await atsUpdatePracticeRow(practice.id, { metadata: patchedMeta }).catch(function () { return null; });
  if (!patched) {
    console.warn('[practice-status] could not persist generated intake_token for practice', practice.id);
  }
  return token;
}

/**
 * Looks up a practice row by its intake token (used by the token-authed
 * GET/POST /api/practice-intake routes and reused by later pipeline tasks).
 * Tokens live either in the dedicated `intake_token` column (new pipeline
 * migration 20260705100000) or, when that migration isn't applied yet,
 * inside `metadata.intake_token` — same dual-location convention the FB
 * webhook's `sendPracticeIntakeEmail` already reads. Returns the row or null;
 * never throws.
 */
async function findPracticeByIntakeToken(token) {
  if (!token) return null;

  if (isSupabaseDbConfigured()) {
    var byColumn = await supabaseDbRequest('practices', 'select=*&intake_token=eq.' + encodeURIComponent(token) + '&limit=1');
    if (byColumn.ok && Array.isArray(byColumn.data) && byColumn.data[0]) {
      return byColumn.data[0];
    }
    // The intake_token column may not exist yet (migration not applied) —
    // fall back to filtering on the metadata JSON column. Note metadata is
    // ALSO added by migration 20260705100000 (it is not on the original
    // practices table), so this fallback only helps when that migration
    // partially applied (e.g. metadata landed before intake_token, or a
    // stale row was written directly to metadata by older code).
    var byMetadata = await supabaseDbRequest('practices', 'select=*&metadata->>intake_token=eq.' + encodeURIComponent(token) + '&limit=1');
    if (byMetadata.ok && Array.isArray(byMetadata.data) && byMetadata.data[0]) {
      return byMetadata.data[0];
    }
    return null;
  }

  var rows = dbState.atsPractices || [];
  return rows.find(function (p) {
    var t = p.intake_token || (p.metadata && p.metadata.intake_token);
    return t && t === token;
  }) || null;
}

function joinDialPhone(countryDial, phoneNumber) {
  const digits = String(phoneNumber || '').replace(/\D/g, '');
  return `${String(countryDial || '').trim()}${digits}`;
}

function maskEmail(email) {
  const [name = '', domain = ''] = String(email || '').split('@');
  if (!name || !domain) return 'your email';
  const prefix = name.slice(0, 2);
  return `${prefix}${'*'.repeat(Math.max(name.length - 2, 1))}@${domain}`;
}

function maskPhone(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  if (!digits) return 'your phone';
  const tail = digits.slice(-2);
  return `••••••${tail}`;
}

function keyForOtp(method, email, countryDial, phoneNumber) {
  if (method === 'sms') return `sms:${joinDialPhone(countryDial, phoneNumber)}`;
  return `email:${String(email || '').trim().toLowerCase()}`;
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim());
}

function isValidPhone(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  return digits.length >= 6 && digits.length <= 20;
}

function getClientIp(req) {
  // On Vercel the true client IP is in x-vercel-forwarded-for — Vercel's edge
  // overwrites any client-supplied copy, so it cannot be spoofed. Prefer it,
  // then x-real-ip. Only fall back to the (client-controllable) leftmost
  // x-forwarded-for token off-platform (local/dev/tests), where there is no
  // trusted proxy in front. Trusting the leftmost XFF in prod let an attacker
  // set a fresh IP per request and defeat EVERY per-IP rate limit.
  const vercelIp = req.headers['x-vercel-forwarded-for'];
  if (typeof vercelIp === 'string' && vercelIp.length > 0) return vercelIp.split(',')[0].trim();
  const realIp = req.headers['x-real-ip'];
  if (typeof realIp === 'string' && realIp.length > 0) return realIp.split(',')[0].trim();
  const xff = req.headers['x-forwarded-for'];
  if (typeof xff === 'string' && xff.length > 0) return xff.split(',')[0].trim();
  return req.socket.remoteAddress || 'unknown';
}

// ── Atomic rate-limit counter ───────────────────────────────────────────────
// The JS below USED to read the counter, decide, then write it back as two
// separate PostgREST calls. That is a read-modify-write race: 200 simultaneous
// login attempts all read count=0, all pass, and all write count=1 — so 200
// attempts recorded as ONE, making the real limit (limit x parallelism). At a
// handful of users nobody sends parallel requests; at 1000 concurrent doctors
// the app already serves that concurrency, so the limiter was going decorative
// exactly as it started to matter.
//
// public.rate_limit_hit (migration 20260730090000) does the whole increment in
// one statement, so concurrent callers serialise on the row lock. Verified
// against prod: 40 simultaneous calls with max=5 -> exactly 5 allowed, counts
// 1..40 with no duplicates.
//
// Returns { ok, allowed }. `ok:false` means we could not reach the counter at
// all — callers must treat that as DENY (see the note in checkRateLimitWindow).
async function rateLimitHitAtomic(runtimeKey, maxCount, windowMs) {
  const result = await supabaseDbRequest('rpc/rate_limit_hit', '', {
    method: 'POST',
    body: { p_key: runtimeKey, p_max: maxCount, p_window_ms: windowMs }
  });
  if (result.ok && result.data && typeof result.data === 'object') {
    return { ok: true, allowed: result.data.allowed !== false };
  }
  // PostgREST answers 404/PGRST202 when the function is missing (e.g. the
  // migration has not been applied to this database yet). That is a deploy
  // ordering problem, not an attack, so fall back to the legacy path rather
  // than locking every user out of sign-in.
  const code = result.data && result.data.code;
  const missing = result.status === 404 || code === 'PGRST202' || code === '42883';
  return { ok: false, allowed: false, missing };
}

async function checkRateLimit(rateKey) {
  const ts = now();
  if (isSupabaseDbConfigured()) {
    const runtimeKey = `ratelimit:${rateKey}`;
    const atomic = await rateLimitHitAtomic(runtimeKey, RATE_MAX_SEND, RATE_WINDOW_MS);
    if (atomic.ok) return atomic.allowed;
    // Counter unreachable. Deny — see checkRateLimitWindow for the reasoning.
    if (!atomic.missing) return false;

    const existing = await getRuntimeKv(runtimeKey);
    const current = existing && existing.value && typeof existing.value === 'object'
      ? existing.value
      : null;
    if (!current || ts - Number(current.windowStart || 0) > RATE_WINDOW_MS) {
      await setRuntimeKv(runtimeKey, { windowStart: ts, count: 1 }, ts + RATE_WINDOW_MS + 60 * 1000);
      return true;
    }
    if (Number(current.count || 0) >= RATE_MAX_SEND) return false;
    await setRuntimeKv(runtimeKey, { windowStart: Number(current.windowStart || ts), count: Number(current.count || 0) + 1 }, Number(current.windowStart || ts) + RATE_WINDOW_MS + 60 * 1000);
    return true;
  }

  const current = dbState.rateLimits[rateKey];
  if (!current || ts - current.windowStart > RATE_WINDOW_MS) {
    dbState.rateLimits[rateKey] = { windowStart: ts, count: 1 };
    saveDbState();
    return true;
  }
  if (current.count >= RATE_MAX_SEND) {
    return false;
  }
  current.count += 1;
  dbState.rateLimits[rateKey] = current;
  saveDbState();
  return true;
}

async function checkRateLimitWindow(rateKey, maxCount, windowMs) {
  const ts = now();
  if (isSupabaseDbConfigured()) {
    const runtimeKey = `authratelimit:${rateKey}`;
    const atomic = await rateLimitHitAtomic(runtimeKey, maxCount, windowMs);
    if (atomic.ok) return atomic.allowed;
    // The counter is unreachable (timeout / PostgREST error). This used to
    // return TRUE here — getRuntimeKv answers null on failure, which the code
    // below cannot tell apart from "no attempts yet" — so every auth rate limit
    // switched itself OFF during exactly the database stress that 1000
    // concurrent users makes routine. Deny instead: this guards sign-in,
    // signup and password reset, and if Supabase is unreachable those cannot
    // succeed anyway, so failing closed costs a user nothing they had.
    if (!atomic.missing) return false;

    const existing = await getRuntimeKv(runtimeKey);
    const current = existing && existing.value && typeof existing.value === 'object'
      ? existing.value
      : null;
    if (!current || ts - Number(current.windowStart || 0) > windowMs) {
      await setRuntimeKv(runtimeKey, { windowStart: ts, count: 1 }, ts + windowMs + 60 * 1000);
      return true;
    }
    if (Number(current.count || 0) >= maxCount) return false;
    await setRuntimeKv(runtimeKey, { windowStart: Number(current.windowStart || ts), count: Number(current.count || 0) + 1 }, Number(current.windowStart || ts) + windowMs + 60 * 1000);
    return true;
  }

  const current = dbState.rateLimits[rateKey];
  if (!current || ts - current.windowStart > windowMs) {
    dbState.rateLimits[rateKey] = { windowStart: ts, count: 1 };
    saveDbState();
    return true;
  }
  if (current.count >= maxCount) return false;
  current.count += 1;
  dbState.rateLimits[rateKey] = current;
  saveDbState();
  return true;
}

// Non-mutating read of a checkRateLimitWindow(...) counter, for reporting
// "attempts remaining" to a client without spending an attempt. Mirrors
// checkRateLimitWindow's storage exactly (runtime_kv in Supabase mode,
// dbState.rateLimits locally) but never writes.
async function peekRateLimitRemaining(rateKey, maxCount, windowMs) {
  const ts = now();
  if (isSupabaseDbConfigured()) {
    const runtimeKey = `authratelimit:${rateKey}`;
    const existing = await getRuntimeKv(runtimeKey);
    const current = existing && existing.value && typeof existing.value === 'object' ? existing.value : null;
    if (!current || ts - Number(current.windowStart || 0) > windowMs) return maxCount;
    return Math.max(0, maxCount - Number(current.count || 0));
  }
  const current = dbState.rateLimits[rateKey];
  if (!current || ts - current.windowStart > windowMs) return maxCount;
  return Math.max(0, maxCount - current.count);
}

async function enforceAuthRateLimit(req, res, scope) {
  const key = `auth:${scope}:${getClientIp(req)}`;
  const allowed = await checkRateLimitWindow(key, AUTH_RATE_MAX_ATTEMPTS, AUTH_RATE_WINDOW_MS);
  if (allowed) return true;
  sendJson(res, 429, { ok: false, message: 'Too many authentication attempts. Please try again later.' });
  return false;
}

// ── Per-ACCOUNT admin login lockout (Phase 6 C3, audit M5) ──────────────────
// enforceAuthRateLimit above is per-IP, so admin credentials could be
// brute-forced across rotating IPs. These helpers add a per-account failure
// counter (runtime_kv key admin_login_fails_<emailhash>, dbState.rateLimits in
// local dev): after ADMIN_ACCOUNT_LOCK_MAX_FAILS bad-password attempts within
// the window, the ACCOUNT is locked for an escalating backoff (15m, 30m, 60m…
// capped at 4h). LOCKOUT-SAFE: the lock is purely time-based (lockedUntil) —
// it always auto-expires, no admin can be locked permanently — and a locked
// account is rejected BEFORE the password check, so the MFA step-up flow is
// never reached (and never interfered with) while locked. A successful
// password login clears the counter. Every state read fails OPEN: a KV outage
// must never lock every admin out.
const ADMIN_ACCOUNT_LOCK_MAX_FAILS = Math.max(1, parseInt(process.env.ADMIN_ACCOUNT_LOCK_MAX_FAILS || '5', 10) || 5);
const ADMIN_ACCOUNT_LOCK_WINDOW_MS = Math.max(60 * 1000, parseInt(process.env.ADMIN_ACCOUNT_LOCK_WINDOW_MS || '', 10) || 15 * 60 * 1000);
const ADMIN_ACCOUNT_LOCK_BASE_MS = Math.max(60 * 1000, parseInt(process.env.ADMIN_ACCOUNT_LOCK_BASE_MS || '', 10) || 15 * 60 * 1000);
const ADMIN_ACCOUNT_LOCK_MAX_MS = 4 * 60 * 60 * 1000;

function adminLoginFailKey(email) {
  const hash = crypto.createHash('sha256').update(String(email || '').trim().toLowerCase()).digest('hex').slice(0, 40);
  return 'admin_login_fails_' + hash;
}

async function readAdminLoginFailRecord(email) {
  const key = adminLoginFailKey(email);
  if (isSupabaseDbConfigured()) {
    const existing = await getRuntimeKv(key);
    return existing && existing.value && typeof existing.value === 'object' ? existing.value : null;
  }
  const rec = dbState.rateLimits[key];
  return rec && typeof rec === 'object' ? rec : null;
}

async function writeAdminLoginFailRecord(email, record) {
  const key = adminLoginFailKey(email);
  if (isSupabaseDbConfigured()) {
    // Keep the row alive past the lock so escalation (locks count) survives,
    // then let runtime_kv expiry garbage-collect it.
    const expiresAt = Math.max(Number(record.lockedUntil || 0), now() + ADMIN_ACCOUNT_LOCK_WINDOW_MS) + 24 * 60 * 60 * 1000;
    await setRuntimeKv(key, record, expiresAt);
    return;
  }
  dbState.rateLimits[key] = record;
  saveDbState();
}

async function clearAdminLoginFailures(email) {
  try {
    const key = adminLoginFailKey(email);
    if (isSupabaseDbConfigured()) { await deleteRuntimeKv(key); return; }
    if (dbState.rateLimits[key]) { delete dbState.rateLimits[key]; saveDbState(); }
  } catch (err) {
    console.error('[admin lockout] clear failed (ignored):', err && err.message);
  }
}

async function getAdminAccountLockState(email) {
  try {
    const rec = await readAdminLoginFailRecord(email);
    const ts = now();
    if (rec && Number(rec.lockedUntil || 0) > ts) {
      return { locked: true, retryAfterMs: Number(rec.lockedUntil) - ts };
    }
    return { locked: false, retryAfterMs: 0 };
  } catch (err) {
    console.error('[admin lockout] state read failed (failing OPEN):', err && err.message);
    return { locked: false, retryAfterMs: 0 };
  }
}

// Record one bad-password attempt. Returns { justLocked, lockMs } so the
// caller can audit-log the moment a lock is applied.
async function registerAdminLoginFailure(email) {
  try {
    const ts = now();
    let rec = await readAdminLoginFailRecord(email);
    if (!rec || typeof rec !== 'object') rec = { count: 0, firstAt: ts, lockedUntil: 0, locks: 0 };
    // Expired lock → auto-unlocked: fresh window, keep `locks` for escalation.
    if (Number(rec.lockedUntil || 0) && Number(rec.lockedUntil) <= ts) {
      rec.count = 0; rec.firstAt = ts; rec.lockedUntil = 0;
    }
    // Stale window → start counting again.
    if (ts - Number(rec.firstAt || 0) > ADMIN_ACCOUNT_LOCK_WINDOW_MS) {
      rec.count = 0; rec.firstAt = ts;
    }
    rec.count = Number(rec.count || 0) + 1;
    let justLocked = false;
    let lockMs = 0;
    if (rec.count >= ADMIN_ACCOUNT_LOCK_MAX_FAILS) {
      const priorLocks = Number(rec.locks || 0);
      lockMs = Math.min(ADMIN_ACCOUNT_LOCK_BASE_MS * Math.pow(2, priorLocks), ADMIN_ACCOUNT_LOCK_MAX_MS);
      rec.lockedUntil = ts + lockMs;
      rec.locks = priorLocks + 1;
      rec.count = 0;
      rec.firstAt = ts;
      justLocked = true;
    }
    await writeAdminLoginFailRecord(email, rec);
    return { justLocked, lockMs };
  } catch (err) {
    console.error('[admin lockout] failure tracking error (ignored):', err && err.message);
    return { justLocked: false, lockMs: 0 };
  }
}

function setSession(res, userProfile, sessionEpoch) {
  const expiresAt = now() + SESSION_TTL_MS;
  const token = createSignedSessionToken(userProfile, expiresAt, sessionEpoch);

  const secureCookie = process.env.COOKIE_SECURE
    ? process.env.COOKIE_SECURE === 'true'
    : NODE_ENV === 'production';

  const cookie = [
    `${COOKIE_NAME}=${encodeURIComponent(token)}`,
    'Path=/',
    'HttpOnly',
    'SameSite=Strict',
    `Max-Age=${Math.floor(SESSION_TTL_MS / 1000)}`
  ];
  if (secureCookie) cookie.push('Secure');

  res.setHeader('Set-Cookie', cookie.join('; '));
}

function setAdminSession(res, userProfile) {
  const expiresAt = now() + ADMIN_SESSION_TTL_MS;
  const token = createSignedSessionToken(userProfile, expiresAt);

  const secureCookie = process.env.COOKIE_SECURE
    ? process.env.COOKIE_SECURE === 'true'
    : NODE_ENV === 'production';

  const cookie = [
    `${ADMIN_COOKIE_NAME}=${encodeURIComponent(token)}`,
    'Path=/',
    'HttpOnly',
    'SameSite=Strict',
    `Max-Age=${Math.floor(ADMIN_SESSION_TTL_MS / 1000)}`
  ];
  if (secureCookie) cookie.push('Secure');

  res.setHeader('Set-Cookie', cookie.join('; '));
}

function clearSession(res, req) {
  const cookies = getCookies(req);
  const token = cookies[COOKIE_NAME];
  if (token) {
    // Legacy local-session cleanup for pre-stateless cookie tokens.
    const tokenHash = hashToken(token);
    if (dbState.sessions[tokenHash]) {
      delete dbState.sessions[tokenHash];
      saveDbState();
    }
  }
  const secureCookie = process.env.COOKIE_SECURE
    ? process.env.COOKIE_SECURE === 'true'
    : NODE_ENV === 'production';
  const cookie = [`${COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0`];
  if (secureCookie) cookie.push('Secure');
  res.setHeader('Set-Cookie', cookie.join('; '));
}

function clearAdminSession(res) {
  const secureCookie = process.env.COOKIE_SECURE
    ? process.env.COOKIE_SECURE === 'true'
    : NODE_ENV === 'production';
  const cookie = [`${ADMIN_COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0`];
  if (secureCookie) cookie.push('Secure');
  res.setHeader('Set-Cookie', cookie.join('; '));
}

// ── Admin two-factor authentication (TOTP) — Phase 6 C1 (audit S1) ─────────
// LOCKOUT-SAFE BY DESIGN: enrolment is opt-in per admin. Login only demands a
// TOTP code when an ACTIVE admin_mfa row exists for that email. An un-enrolled
// admin (including the owner) always logs in with password alone — even when
// REQUIRE_ADMIN_MFA is set, which merely flags mfaEnrolmentRequired so the UI
// can nag; it NEVER blocks. Lost device → single-use backup codes complete
// login and can disable 2FA entirely.

const ADMIN_MFA_CHALLENGE_TTL_MS = Number(process.env.ADMIN_MFA_CHALLENGE_TTL_MS || 5 * 60 * 1000);
const ADMIN_MFA_SETUP_TTL_MS = Number(process.env.ADMIN_MFA_SETUP_TTL_MS || 15 * 60 * 1000);
const ADMIN_MFA_BACKUP_CODE_COUNT = 8;

// Read at request time (not boot) so ops can flip the flag without a redeploy
// and tests can exercise both branches in one server boot.
function isAdminMfaGloballyRequired() {
  return /^(1|true|yes|on)$/i.test(String(process.env.REQUIRE_ADMIN_MFA || '').trim());
}

function hashAdminBackupCode(code) {
  const normalized = String(code || '').toUpperCase().replace(/[\s-]/g, '');
  return crypto.createHmac('sha256', SECRET).update(`admin_mfa_backup|${normalized}`).digest('hex');
}

// 8 codes like "K7PQ-4MZ2" — unambiguous alphabet (no 0/O/1/I/L/S/5/B/8).
function generateAdminBackupCodes(count = ADMIN_MFA_BACKUP_CODE_COUNT) {
  const alphabet = 'ACDEFGHJKMNPQRTUVWXYZ234679';
  const codes = [];
  for (let i = 0; i < count; i++) {
    let raw = '';
    for (let j = 0; j < 8; j++) raw += alphabet[crypto.randomInt(alphabet.length)];
    codes.push(`${raw.slice(0, 4)}-${raw.slice(4)}`);
  }
  return codes;
}

// Dual-mode row access: Supabase admin_mfa table in production, dbState.adminMfa
// map in local JSON mode (loadDbState preserves unknown keys via `...parsed`).
// Returns { ok, record }. `ok:false` means the lookup FAILED and we do not know
// whether this admin has a second factor — which is not the same as "no second
// factor", and must never be treated as such. getAdminMfaRecord below keeps the
// old null-on-anything shape for the enrolment/management call sites that only
// ever read it after a successful login.
async function readAdminMfaRecord(email) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return { ok: true, record: null };
  if (isSupabaseDbConfigured()) {
    const res = await supabaseDbRequest('admin_mfa', `admin_email=eq.${encodeURIComponent(key)}&limit=1`);
    if (!res.ok) return { ok: false, record: null };
    const row = Array.isArray(res.data) && res.data.length > 0 ? res.data[0] : null;
    return { ok: true, record: row };
  }
  const rec = (dbState.adminMfa || {})[key];
  return { ok: true, record: rec ? { admin_email: key, ...rec } : null };
}

async function getAdminMfaRecord(email) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return null;
  if (isSupabaseDbConfigured()) {
    const res = await supabaseDbRequest('admin_mfa', `admin_email=eq.${encodeURIComponent(key)}&limit=1`);
    if (res.ok && Array.isArray(res.data) && res.data.length > 0) return res.data[0];
    return null;
  }
  const rec = (dbState.adminMfa || {})[key];
  return rec ? { admin_email: key, ...rec } : null;
}

async function saveAdminMfaRecord(email, fields) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return false;
  const row = { admin_email: key, updated_at: new Date().toISOString(), ...fields };
  if (isSupabaseDbConfigured()) {
    const res = await supabaseDbRequest('admin_mfa', 'on_conflict=admin_email', {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
      body: [row]
    });
    if (res.ok) return true;
    // Fail-open for pre-migration databases: last_totp_step (TOTP replay
    // tracking, migration 20260706160000) may not exist yet. Retry without it
    // so enrolment/login keep working exactly as before the hardening.
    if (Object.prototype.hasOwnProperty.call(row, 'last_totp_step')) {
      const { last_totp_step, ...withoutStep } = row;
      const retry = await supabaseDbRequest('admin_mfa', 'on_conflict=admin_email', {
        method: 'POST',
        headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
        body: [withoutStep]
      });
      if (retry.ok) return true;
      console.error('[MFA] admin_mfa upsert failed', retry.status);
      return false;
    }
    console.error('[MFA] admin_mfa upsert failed', res.status);
    return false;
  }
  dbState.adminMfa = dbState.adminMfa && typeof dbState.adminMfa === 'object' ? dbState.adminMfa : {};
  dbState.adminMfa[key] = { ...(dbState.adminMfa[key] || {}), ...row };
  saveDbState();
  return true;
}

// Compare-and-set update on the admin_mfa row, versioned on updated_at.
// Returns true only when the row was still at expectedUpdatedAt when the write
// landed — the guard that makes backup-code consumption and TOTP replay
// tracking safe against two near-simultaneous logins. The new updated_at is
// forced strictly greater than the old one so two writes in the same
// millisecond can never look like the same version.
//
// Residual window (documented per review): PostgREST offers no true
// transactional primitive through this REST path, so the check is a filtered
// PATCH — if a writer changes the row and restores the identical updated_at
// (never happens with the +1ms bump), the guard could be fooled. In local JSON
// mode the check-and-write below is fully synchronous on the single-threaded
// event loop, so it IS atomic.
async function updateAdminMfaIfUnchanged(email, expectedUpdatedAt, fields) {
  const key = String(email || '').trim().toLowerCase();
  if (!key) return false;
  const prevMs = Date.parse(String(expectedUpdatedAt || '')) || 0;
  const newUpdatedAt = new Date(Math.max(Date.now(), prevMs + 1)).toISOString();
  if (isSupabaseDbConfigured()) {
    const versionFilter = expectedUpdatedAt
      ? `updated_at=eq.${encodeURIComponent(String(expectedUpdatedAt))}`
      : 'updated_at=is.null';
    const query = `admin_email=eq.${encodeURIComponent(key)}&${versionFilter}`;
    const doPatch = (body) => supabaseDbRequest('admin_mfa', query, {
      method: 'PATCH',
      headers: { Prefer: 'return=representation' },
      body
    });
    let res = await doPatch({ ...fields, updated_at: newUpdatedAt });
    if (!res.ok && Object.prototype.hasOwnProperty.call(fields, 'last_totp_step')) {
      // Pre-migration fail-open: retry without the replay-tracking column.
      const { last_totp_step, ...withoutStep } = fields;
      res = await doPatch({ ...withoutStep, updated_at: newUpdatedAt });
    }
    // ok + at least one returned row = our precondition held and we won.
    return !!(res.ok && Array.isArray(res.data) && res.data.length > 0);
  }
  // Local JSON mode: no await between check and write → atomic per event loop.
  const rec = dbState.adminMfa && typeof dbState.adminMfa === 'object' ? dbState.adminMfa[key] : null;
  if (!rec) return false;
  if (String(rec.updated_at || '') !== String(expectedUpdatedAt || '')) return false;
  Object.assign(rec, fields, { updated_at: newUpdatedAt });
  saveDbState();
  return true;
}

// Atomically spend ONE backup code (audit hardening #2). Re-fetches the row,
// verifies the hash is still present, and writes back guarded by the
// updated_at version; loses of the race retry once against fresh state — the
// loser then sees the code already gone and is refused. A given code can
// therefore be spent only once even under two near-simultaneous requests.
async function consumeAdminBackupCode(email, code) {
  const candidateHash = hashAdminBackupCode(code);
  for (let attempt = 0; attempt < 2; attempt++) {
    const fresh = await getAdminMfaRecord(email);
    if (!fresh || !fresh.totp_secret || fresh.disabled) return false;
    const storedHashes = Array.isArray(fresh.backup_codes) ? fresh.backup_codes.map(String) : [];
    let matched = false;
    const remaining = [];
    for (const hash of storedHashes) {
      if (!matched && timingSafeEqualStrings(hash, candidateHash)) { matched = true; continue; }
      remaining.push(hash);
    }
    if (!matched) return false;
    const won = await updateAdminMfaIfUnchanged(email, fresh.updated_at || null, {
      backup_codes: remaining,
      last_used_at: new Date().toISOString()
    });
    if (won) return true;
    // Lost a concurrent write — loop re-reads and re-checks the code.
  }
  return false;
}

// Short-lived signed tokens for the two half-open states. Payload shapes are
// deliberately DIFFERENT from { userProfile, expiresAt } so neither token can
// ever be replayed as a gp_admin_session cookie (parseSignedSessionToken
// rejects them), and both carry a purpose tag checked on parse.
function createSignedPurposeToken(purpose, data, ttlMs) {
  const payload = base64UrlEncode(JSON.stringify({ purpose, data, exp: now() + ttlMs }));
  return `${payload}.${hmacSign(payload)}`;
}

function parseSignedPurposeToken(token, purpose) {
  const raw = String(token || '');
  const dotIdx = raw.lastIndexOf('.');
  if (dotIdx <= 0) return null;
  const payload = raw.slice(0, dotIdx);
  const signature = raw.slice(dotIdx + 1);
  const expected = hmacSign(payload);
  const sigValid = signature.length === expected.length
    && crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected, 'utf8'));
  if (!sigValid) return null;
  try {
    const parsed = JSON.parse(base64UrlDecode(payload));
    if (!parsed || typeof parsed !== 'object') return null;
    if (parsed.purpose !== purpose) return null;
    if (typeof parsed.exp !== 'number' || parsed.exp <= now()) return null;
    if (!parsed.data || typeof parsed.data !== 'object') return null;
    return parsed.data;
  } catch (err) {
    return null;
  }
}

// ── Phase 6 D1b: practice one-click action tokens ───────────────────────────
// Signed links in the submit-to-practice intro email let the practice respond
// with one click (accept / decline / request an interview). Reuses the SAME
// HMAC-with-AUTH_SECRET purpose-token scheme as the MFA challenge tokens
// (createSignedPurposeToken/parseSignedPurposeToken): unforgeable, expiring,
// and purpose-tagged so a practice-action token can never be replayed as a
// session cookie, an MFA token, or any other purpose token (and vice versa).
const PRACTICE_ACTION_TOKEN_PURPOSE = 'practice_action';
const PRACTICE_ACTION_VALUES = ['accept', 'decline', 'request_interview'];

function makePracticeActionToken(opts) {
  const applicationId = String((opts && opts.applicationId) || '').trim();
  const action = String((opts && opts.action) || '').trim();
  if (!applicationId) throw new Error('makePracticeActionToken: applicationId is required');
  if (PRACTICE_ACTION_VALUES.indexOf(action) === -1) throw new Error('makePracticeActionToken: invalid action ' + action);
  const expDaysRaw = opts && opts.expDays;
  const expDays = (typeof expDaysRaw === 'number' && Number.isFinite(expDaysRaw) && expDaysRaw > 0) ? expDaysRaw : 30;
  return createSignedPurposeToken(PRACTICE_ACTION_TOKEN_PURPOSE, { applicationId, action }, expDays * 24 * 60 * 60 * 1000);
}

// → { ok:true, applicationId, action } or { ok:false } (tampered / expired /
// wrong purpose / malformed — deliberately indistinguishable to the caller).
function verifyPracticeActionToken(token) {
  const data = parseSignedPurposeToken(token, PRACTICE_ACTION_TOKEN_PURPOSE);
  if (!data) return { ok: false };
  const applicationId = String(data.applicationId || '').trim();
  const action = String(data.action || '').trim();
  if (!applicationId || PRACTICE_ACTION_VALUES.indexOf(action) === -1) return { ok: false };
  return { ok: true, applicationId, action };
}

// ── Task 9/10: post-interview practice decision tokens ──────────────────────
// Same purpose-token scheme as the practice-action tokens above. Minted by
// sendPostInterviewDecisionEmail (Task 9) into the "how did the interview
// go?" email fired the instant an interview completes; consumed by Task 10's
// GET/POST /pages/practice-offer.html endpoints. The payload is deliberately
// JUST { applicationId } — no action baked in — because the SAME token backs
// BOTH links; which one was clicked is carried by the page's own ?intent=
// query param (offer/decline), not the signed payload.
const POST_INTERVIEW_TOKEN_PURPOSE = 'post_interview_decision';
const POST_INTERVIEW_TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days — mirrors PRACTICE_ACTION_TOKEN's default expDays

// ── Task 10: contract-upload tokens ─────────────────────────────────────────
// Minted when a practice extends an offer (POST /api/practice/offer/decision
// action:'extend_offer') and handed to the practice-offer page so it can PUT
// the employment contract straight to Storage without a login. Payload is JUST
// { contractId } — deliberately DIFFERENT from the post_interview token's
// { applicationId } so the two can never be swapped: the upload endpoints
// (sign-upload / finalize) accept ONLY this purpose, and the decision endpoint
// accepts ONLY the post_interview purpose. A cross-purpose token fails
// parseSignedPurposeToken's purpose check and is rejected as invalid.
const CONTRACT_UPLOAD_TOKEN_PURPOSE = 'contract_upload';
const CONTRACT_UPLOAD_TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

// ── Task 14: contract consent tokens ────────────────────────────────────────
// Minted when the CEO releases a changes_requested contract to the practice
// for email consent (POST /api/ceo/contract/change-decision action:
// 'release_to_practice'). Payload is JUST { contractId } — same shape as
// CONTRACT_UPLOAD_TOKEN_PURPOSE's payload, but a DIFFERENT purpose string, so
// a consent token can never drive the upload endpoints (sign-upload/finalize)
// and an upload token can never drive the consent endpoints — each is
// rejected by parseSignedPurposeToken's purpose check as if it were garbage.
const CONTRACT_CONSENT_TOKEN_PURPOSE = 'contract_consent';
const CONTRACT_CONSENT_TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

// ── Phase 6 F4: verified email change ───────────────────────────────────────
// Same purpose-token scheme: unforgeable, expiring, single-purpose. The token
// is minted at request time and only ever emailed to the NEW address, so
// possession proves control of the new inbox.
const EMAIL_CHANGE_TOKEN_PURPOSE = 'email_change';
const EMAIL_CHANGE_TOKEN_TTL_MS = Number(process.env.EMAIL_CHANGE_TOKEN_TTL_MS || 60 * 60 * 1000);

// Is this address already attached to any account? Checks user_profiles (and
// the auth system best-effort) in Supabase mode, dbState maps locally.
async function isChangeEmailAddressTaken(candidateEmail) {
  const key = String(candidateEmail || '').trim().toLowerCase();
  if (!key) return true;
  if (isSupabaseDbConfigured()) {
    try {
      const r = await supabaseDbRequest('user_profiles', 'select=user_id&email=eq.' + encodeURIComponent(key) + '&limit=1');
      if (r.ok && Array.isArray(r.data) && r.data.length > 0) return true;
    } catch (err) { /* fall through to auth check */ }
    try {
      // Best-effort GoTrue lookup; shape varies by version so only a positive
      // match counts. Failures do NOT block (user_profiles is the source of truth).
      const a = await supabaseAuthAdminRequest('admin/users?email=' + encodeURIComponent(key));
      const users = a.ok && a.data && Array.isArray(a.data.users) ? a.data.users : [];
      if (users.some((u) => String((u && u.email) || '').trim().toLowerCase() === key)) return true;
    } catch (err) { /* ignore */ }
    return false;
  }
  return !!(dbState.users[key] || dbState.userProfiles[key]);
}

// Apply a VERIFIED email change. Order is deliberate: the auth-system email
// (what the user signs in with) changes FIRST and any failure there aborts the
// whole operation with nothing modified — so a partial failure can never lock
// the user out. App-side rows then update best-effort (profile lookups also
// fall back to user_id, so a missed row degrades gracefully, never locks out).
// Finally every session for the OLD address is revoked via the epoch bump.
async function applyVerifiedEmailChange({ userId, oldEmail, newEmail }) {
  const oldKey = String(oldEmail || '').trim().toLowerCase();
  const newKey = String(newEmail || '').trim().toLowerCase();
  const warnings = [];
  if (!oldKey || !newKey) return { ok: false, message: 'Invalid email change request.' };

  if (isSupabaseDbConfigured()) {
    const uid = String(userId || '').trim() || await getSupabaseUserIdByEmail(oldKey);
    if (!uid) return { ok: false, message: 'Could not resolve your account. Nothing was changed.' };

    // 1) Auth system first — abort entirely if this fails.
    const authRes = await supabaseAuthAdminRequest('admin/users/' + encodeURIComponent(uid), {
      method: 'PUT',
      body: { email: newKey, email_confirm: true }
    });
    if (!authRes.ok) {
      console.error('[change-email] auth update failed:', authRes.status, JSON.stringify(authRes.data || {}).slice(0, 200));
      return { ok: false, message: 'Could not update the sign-in system. Nothing was changed — your current email still works.' };
    }

    // 2) App-side rows (best-effort; profile reads fall back to user_id).
    const emailPatches = [
      ['user_profiles', 'user_id=eq.' + encodeURIComponent(uid)],
      ['onboarding_reminders', 'user_id=eq.' + encodeURIComponent(uid)],
      ['notification_preferences', 'email=eq.' + encodeURIComponent(oldKey)]
    ];
    for (const [table, filter] of emailPatches) {
      try {
        const pr = await supabaseDbRequest(table, filter, {
          method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: { email: newKey }
        });
        if (!pr.ok) warnings.push(table + ' not updated (' + pr.status + ')');
      } catch (err) { warnings.push(table + ' not updated (' + (err && err.message) + ')'); }
    }
  } else {
    // Local JSON mode: move the email-keyed records.
    if (dbState.users[oldKey]) {
      dbState.users[newKey] = { ...dbState.users[oldKey], email: newKey, updatedAt: new Date().toISOString() };
      delete dbState.users[oldKey];
    }
    if (dbState.userProfiles[oldKey]) {
      dbState.userProfiles[newKey] = { ...dbState.userProfiles[oldKey], email: newKey };
      delete dbState.userProfiles[oldKey];
    }
    if (dbState.userState && dbState.userState[oldKey]) {
      dbState.userState[newKey] = dbState.userState[oldKey];
      delete dbState.userState[oldKey];
    }
    if (dbState.notificationPrefs && dbState.notificationPrefs[oldKey]) {
      dbState.notificationPrefs[newKey] = dbState.notificationPrefs[oldKey];
      delete dbState.notificationPrefs[oldKey];
    }
    saveDbState();
  }

  // 3) Kill every session issued for the old address (they embed the old
  //    email, so bumping the old key's epoch invalidates all of them). OAuth
  //    refresh tokens for the old address are revoked too — otherwise a device
  //    holding one could mint a fresh session after the change (F4).
  revokeAllRefreshTokensForEmail(oldKey);
  const bumped = await bumpSessionEpoch(oldKey);
  if (bumped == null) warnings.push('session revoke failed — old sessions may live until expiry');
  return { ok: true, warnings };
}

// F4 hardening: an email-change confirm token is bound to the login address it
// was issued for. Once the account's CURRENT auth email is no longer the
// token's oldEmail (the token was already used, or a newer change moved the
// email on), the token is dead — otherwise a stale A→B link sitting in inbox B
// could be replayed within its 1h TTL to drag the login email back to B after
// the owner had already moved it elsewhere (re-takeover chain). Returns true
// when the token should be REJECTED.
async function isEmailChangeTokenStale({ userId, oldEmail }) {
  const key = String(oldEmail || '').trim().toLowerCase();
  if (!key) return true;
  const uid = String(userId || '').trim();
  if (isSupabaseDbConfigured()) {
    try {
      // Auth system is the source of truth for the CURRENT login email.
      const a = await supabaseAuthAdminRequest('admin/users?email=' + encodeURIComponent(key));
      const users = a.ok && a.data && Array.isArray(a.data.users) ? a.data.users : [];
      const match = users.find((u) => String((u && u.email) || '').trim().toLowerCase() === key);
      if (match) return uid ? String(match.id || '') !== uid : false;
    } catch (err) { /* GoTrue shape varies — fall through to the profile check */ }
    try {
      const pid = await getSupabaseUserIdByEmail(key);
      if (pid) return uid ? String(pid) !== uid : false;
    } catch (err) { /* fall through */ }
    return true; // old email no longer attached to this account → token is dead
  }
  return !(dbState.users[key] || dbState.userProfiles[key]);
}

// TOTP first, then single-use backup code (consumed on success). Returns
// { ok, method } and persists consumption + last_used_at.
//
// TOTP replay rejection (audit hardening #3): the HOTP counter (timestep) of
// every ACCEPTED token is persisted in last_totp_step, and a token whose step
// is <= the last accepted one is refused — so the same 6-digit code can never
// be accepted twice, while the ±1-step window still tolerates clock skew for
// FRESH codes. Pre-migration rows have no last_totp_step column/value → the
// check fails open to the previous behavior until the migration lands.
// The write is CAS-guarded so two simultaneous logins with the same token
// cannot both record the same step and both win.
async function verifyAdminMfaCode(record, code) {
  const secret = record && record.totp_secret ? String(record.totp_secret) : '';
  if (!secret) return { ok: false, method: null };
  const input = String(code || '').trim();
  const matchedStep = adminTotp.matchTotpStep(secret, input, { window: 1 });
  if (matchedStep !== null) {
    for (let attempt = 0; attempt < 2; attempt++) {
      // Fresh read: the caller's record may predate a concurrent acceptance.
      const fresh = await getAdminMfaRecord(record.admin_email);
      if (!fresh || !fresh.totp_secret || fresh.disabled) return { ok: false, method: null };
      const lastStep = Number(fresh.last_totp_step);
      if (Number.isFinite(lastStep) && matchedStep <= lastStep) {
        return { ok: false, method: null }; // replayed / older token
      }
      const won = await updateAdminMfaIfUnchanged(record.admin_email, fresh.updated_at || null, {
        last_used_at: new Date().toISOString(),
        last_totp_step: matchedStep
      });
      if (won) return { ok: true, method: 'totp' };
      // Lost a concurrent write — re-read and re-check the step once.
    }
    return { ok: false, method: null };
  }
  const consumed = await consumeAdminBackupCode(record.admin_email, input);
  if (consumed) return { ok: true, method: 'backup_code' };
  return { ok: false, method: null };
}

function getSession(req) {
  const cookies = getCookies(req);
  const token = cookies[COOKIE_NAME];
  if (!token) return null;

  const signedSession = parseSignedSessionToken(token);
  if (signedSession) {
    // Phase 6 F4 session kill-switch: reject only when the KNOWN stored epoch
    // outruns the token's. Unknown/uncached epoch → valid (fail-open, so the
    // deploy itself can never log anyone out — see isSessionEpochRevokedSync).
    const epochEmail = signedSession.userProfile && typeof signedSession.userProfile.email === 'string'
      ? signedSession.userProfile.email.trim().toLowerCase() : '';
    if (epochEmail && isSessionEpochRevokedSync(epochEmail, signedSession.epoch || 0)) return null;
    return signedSession;
  }

  // Backward compatibility: previously-issued server-side session tokens.
  const tokenHash = hashToken(token);
  const session = dbState.sessions[tokenHash];
  if (!session) return null;
  if (session.expiresAt <= now()) {
    delete dbState.sessions[tokenHash];
    saveDbState();
    return null;
  }
  return session;
}

function getAdminSession(req) {
  const cookies = getCookies(req);
  const token = cookies[ADMIN_COOKIE_NAME];
  if (!token) return null;
  const signedSession = parseSignedSessionToken(token);
  return signedSession || null;
}

function requireSession(req, res) {
  const session = getSession(req);
  if (!session) {
    sendJson(res, 401, { ok: false, authenticated: false });
    return null;
  }
  return session;
}

function getSessionEmail(session) {
  const email = session && session.userProfile && typeof session.userProfile.email === 'string'
    ? session.userProfile.email.trim().toLowerCase()
    : '';
  return email || null;
}

const TEMPORARY_BYPASS_LOCK_EMAILS = {
  // Khaleed's "crypto" test GP account bypass removed 2026-07-24 now that he is past
  // onboarding — he navigates the app as a real GP with all registration gateways enforced.
  'smithmiller1234@gmail.com': '2026-09-30T23:59:59.000Z'
};

function isBypassLockEmail(email) {
  const normalized = String(email || '').trim().toLowerCase();
  if (!normalized) return false;
  const configured = new Set(
    String(process.env.BYPASS_LOCK_EMAILS || 'hello@mygplink.com.au')
      .split(',').map(function(e){ return e.trim().toLowerCase(); }).filter(Boolean)
  );
  if (configured.has(normalized)) return true;
  const expiresAt = Date.parse(TEMPORARY_BYPASS_LOCK_EMAILS[normalized] || '');
  return Number.isFinite(expiresAt) && Date.now() < expiresAt;
}

function shouldProtectPath(pathname) {
  if (AUTH_DISABLED) return false;
  return (
    pathname === '/' ||
    pathname === '/pages/index.html' ||
    pathname === '/pages/myinthealth.html' ||
    pathname === '/pages/amc.html' ||
    pathname === '/pages/my-documents.html' ||
    pathname === '/pages/account.html' ||
    pathname === '/pages/support-cases.html' ||
    pathname.startsWith('/registration/')
  );
}

// Build a /pages/signin redirect that preserves where the user was trying to go,
// so deep links (e.g. a document re-upload link from an email) survive the
// unauthenticated sign-in bounce. pages/signin.html reads ?next= and returns the
// user there after login. Only safe internal /pages/ destinations are preserved
// (mirrors the client-side validation in signin.html); the default dashboard and
// the sign-in page itself are never used as the next target.
function buildSigninRedirect(url) {
  try {
    var rawPath = url && url.pathname ? url.pathname : '';
    var rawSearch = url && url.search ? url.search : '';
    var parsed = new URL(rawPath + rawSearch, 'http://internal');
    // Drop app-shell embed params so next points at a clean top-level page;
    // the app shell re-wraps it after login.
    parsed.searchParams.delete('gp_shell');
    parsed.searchParams.delete('gp_shell_static');
    var dest = parsed.pathname + parsed.search;
    if (/^\/pages\//.test(dest) &&
        !/^\/\//.test(dest) &&
        dest.indexOf('/pages/index') !== 0 &&
        dest.indexOf('/pages/signin') !== 0) {
      return '/pages/signin?next=' + encodeURIComponent(dest);
    }
  } catch (e) {}
  return '/pages/signin';
}

function mapRegistrationPath(pathname) {
  const parts = String(pathname || '').split('/').filter(Boolean);
  if (parts.length < 3 || parts[0] !== 'registration') return null;

  const step = parts[1].toLowerCase();
  if (step === 'myintealth' || step === 'myinthealth') return '/pages/myinthealth.html';
  if (step === 'amc') return '/pages/amc.html';
  if (step === 'ahpra' || step === 'specialist-registration') return '/pages/ahpra.html';
  return null;
}

// ── Server-side stage access gate ──
// Maps page paths to registration stages. If a user has admin-set overrides,
// the server enforces them — prevents direct URL navigation to locked stages.
const PAGE_STAGE_MAP = {
  '/pages/myinthealth.html': 'myintealth',
  '/pages/amc.html': 'amc',
  '/pages/career.html': 'career',
  '/pages/ahpra.html': 'ahpra',
  '/pages/visa.html': 'visa',
  '/pages/pbs.html': 'pbs',
  '/pages/commencement.html': 'commencement'
};

// ── Vaulted stages ──
// Registration stages temporarily shelved from the GP journey. A vaulted stage
// is blocked from direct page access (isStageAccessAllowed below bounces it to
// the dashboard) — the client mirror is VAULTED in js/journey-stages.js, which
// hides it from the stepper / registration dropdown / mobile sheet. To restore a
// stage, remove it from BOTH sets. (The admin/CEO STAGE_ORDER tracking is left
// intact — vaulting only affects the GP-facing journey.)
const VAULTED_STAGES = new Set(['commencement']);

// Pure stage-gate decision (testable). Visa, AHPRA and Career are ALWAYS accessible:
// visa = the always-on 482→186 info page (docs/deferred-visa-application.md); AHPRA
// renders its own prerequisite gateway; Career is placement context. Every other stage
// honours gp_registration_return_overrides — a stage absent from the overrides (or no
// overrides at all) follows natural progression and is allowed.
function stageGateDecision(stage, overrides, isBypass) {
  if (!stage) return true;
  if (VAULTED_STAGES.has(stage)) return false; // vaulted — blocked for everyone, incl. bypass
  if (stage === 'career' || stage === 'ahpra' || stage === 'visa') return true;
  if (isBypass) return true;
  if (!overrides || typeof overrides !== 'object') return true;
  if (!(stage in overrides)) return true;
  return overrides[stage] === true;
}

async function isStageAccessAllowed(email, pathname) {
  var stage = PAGE_STAGE_MAP[pathname];
  if (!stage) return true; // Not a gated page
  // Vaulted stages are blocked for EVERYONE (incl. bypass emails) — this sits
  // before the always-allowed / bypass short-circuits below so /pages/commencement
  // bounces to the dashboard while the stage is shelved. See VAULTED_STAGES above.
  if (VAULTED_STAGES.has(stage)) return false;
  // Always-accessible stages — short-circuit before any DB read. visa MUST be here:
  // stage-advance writes overrides.visa=false for every GP before the visa stage
  // (visa is STAGE_ORDER index 5), yet the journey's Visa card is always unlocked, so
  // without this the card dead-ends on /pages/index via the shell-iframe redirect.
  if (stage === 'career' || stage === 'ahpra' || stage === 'visa') return true;

  if (isBypassLockEmail(email)) return true;

  var userState = null;
  if (isSupabaseDbConfigured()) {
    var row = await getSupabaseUserStateByEmail(email);
    userState = row && row.state ? row.state : null;
  } else {
    userState = dbState.userState[email] || null;
  }

  if (!userState) return true; // New user, no state yet

  var overrides = userState.gp_registration_return_overrides;
  if (typeof overrides === 'string') try { overrides = JSON.parse(overrides); } catch(e) { overrides = null; }

  return stageGateDecision(stage, overrides, false);
}

function isAppShellSupportedPath(pathname) {
  return APP_SHELL_SUPPORTED_PATHS.has(String(pathname || ''));
}

function shouldServeAppShell(requestUrl, pathname) {
  if (!isAppShellSupportedPath(pathname)) return false;
  if (pathname === '/pages/app-shell.html') return false;
  if (requestUrl.searchParams.get(APP_SHELL_STATIC_PARAM) === '1') return false;
  return requestUrl.searchParams.get(APP_SHELL_EMBED_PARAM) !== APP_SHELL_EMBED_VALUE;
}

function buildStaticEtag(stat) {
  return `W/"${Number(stat.size || 0).toString(16)}-${Math.floor(Number(stat.mtimeMs || 0)).toString(16)}"`;
}

function hasMatchingEtag(headerValue, etag) {
  if (typeof headerValue !== 'string' || !headerValue || !etag) return false;
  if (headerValue.trim() === '*') return true;
  return headerValue
    .split(',')
    .map((value) => value.trim())
    .some((value) => value === etag);
}

function isNotModified(req, etag, stat) {
  if (hasMatchingEtag(req.headers['if-none-match'], etag)) {
    return true;
  }

  const ifModifiedSince = req.headers['if-modified-since'];
  if (typeof ifModifiedSince !== 'string' || !ifModifiedSince) {
    return false;
  }

  const sinceMs = Date.parse(ifModifiedSince);
  if (!Number.isFinite(sinceMs)) {
    return false;
  }

  return Math.floor(Number(stat.mtimeMs || 0) / 1000) * 1000 <= sinceMs;
}

function getStaticCacheControl(req, pathname, ext) {
  if (ext === '.html') return 'private, no-cache';
  if (pathname === '/sw.js') return 'no-cache';
  if (pathname.startsWith('/media/')) return 'public, max-age=31536000, immutable';

  const requestUrl = String(req.url || '');
  if ((ext === '.js' || ext === '.css' || ext === '.json' || ext === '.svg') && /[?&]v=[^&]+/i.test(requestUrl)) {
    return 'public, max-age=31536000, immutable';
  }

  if (ext === '.js' || ext === '.css' || ext === '.json' || ext === '.svg') {
    return 'public, max-age=3600, must-revalidate';
  }

  return 'public, max-age=3600';
}

function sanitizeFilePath(pathname) {
  let decoded;
  try {
    decoded = decodeURIComponent(pathname.split('?')[0]);
  } catch (err) {
    return null; // Malformed URI encoding
  }
  // Reject null bytes (path traversal vector)
  if (decoded.indexOf('\0') !== -1) return null;
  const target = decoded === '/' ? '/pages/index.html' : decoded;
  const normalized = path.posix.normalize(String(target).replace(/\\/g, '/'));
  const relative = normalized.replace(/^\/+/, '');
  if (!relative || relative.startsWith('..')) return null;
  const resolved = path.resolve(process.cwd(), relative);
  // Ensure resolved path is within cwd (defense-in-depth)
  if (!resolved.startsWith(process.cwd() + path.sep) && resolved !== process.cwd()) return null;
  return resolved;
}

function getStaticCompressionEncoding(req) {
  const value = String(req.headers['accept-encoding'] || '').toLowerCase();
  if (value.includes('br')) return 'br';
  if (value.includes('gzip')) return 'gzip';
  return '';
}

function createStaticCompressionStream(encoding) {
  if (encoding === 'br' && zlib.createBrotliCompress) {
    return zlib.createBrotliCompress({
      params: {
        [zlib.constants.BROTLI_PARAM_QUALITY]: 4
      }
    });
  }
  return zlib.createGzip({ level: 6 });
}

// Only these top-level directories, and this small set of conventional root
// files, are ever served as public static assets. Everything else in the
// project root — server.js, lib/, scripts/, data/ (the JSON DB), package.json,
// vercel.json, supabase/, docs/, config files — must NEVER be downloadable.
// Without this allowlist, `GET /server.js` returned the entire backend source
// (and Vercel bundles server.js + lib/** into the lambda, so the leak reached
// production). See the launch-readiness audit finding on source exposure.
const PUBLIC_STATIC_DIRS = new Set(['pages', 'js', 'css', 'media', 'documents', 'assets']);
const PUBLIC_STATIC_ROOT_FILES = new Set([
  'sw.js', 'manifest.webmanifest', 'favicon.ico', 'robots.txt', 'sitemap.xml',
  'apple-touch-icon.png', 'apple-touch-icon-precomposed.png'
]);

function isPubliclyServablePath(filePath) {
  const rel = path.relative(process.cwd(), filePath);
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return false;
  const segments = rel.split(path.sep);
  if (segments.length === 1) return PUBLIC_STATIC_ROOT_FILES.has(segments[0]);
  return PUBLIC_STATIC_DIRS.has(segments[0]);
}

// ── Friendly error page for GPs (launch triage BUILD 1) ──────────────────────
//
// pages/error.html exists and is public, but nothing routed to it: a doctor who
// hit a bad link or a server fault got a bare "Not found" / raw JSON. These
// helpers serve that page for PAGE navigations only.
//
// The three hard rules:
//   1. /api/* is NEVER touched. API 404s are the normal "no such record" answer
//      in hundreds of places and MUST stay JSON, or every caller breaks.
//   2. Asset requests (scripts, stylesheets, images, fonts) never get HTML —
//      a <script src> that receives an HTML page is a worse failure than a 404.
//   3. The HTTP status is preserved exactly. 404 stays 404, 500 stays 500.
//      Returning 200 with an apology page is what breaks uptime monitoring.

// Is this request a top-level page navigation that a human is looking at?
function isHtmlPageNavigation(req, pathname) {
  const p = String(pathname || '');
  if (p.startsWith('/api/')) return false;                       // rule 1
  const method = String((req && req.method) || 'GET').toUpperCase();
  if (method !== 'GET') return false;                            // a POST gets no apology page
  const ext = path.extname(p).toLowerCase();
  if (ext && ext !== '.html') return false;                      // rule 2: .js/.css/.png/... are assets
  // Sec-Fetch-Dest is the authoritative signal where the browser sends it:
  // 'document' (address bar / link) or 'iframe' (the app shell loads pages in
  // an iframe). 'script', 'style', 'image', 'font', 'empty' (fetch/XHR) are not
  // navigations and must not receive HTML.
  const dest = String((req && req.headers && req.headers['sec-fetch-dest']) || '').toLowerCase();
  if (dest === 'document' || dest === 'iframe' || dest === 'frame') return true;
  // Known subresource destinations never get HTML (rule 2). Anything else —
  // including 'empty' — falls through to the Accept sniff below: the service
  // worker's pass-through fetch of a page navigation reaches us with
  // Sec-Fetch-Dest: empty (the navigation destination does not survive
  // fetch(event.request)), while the original Accept: text/html header does.
  // Rejecting on 'empty' alone served every sw-installed browser the bare
  // plain-text 404 (live repro 2026-07-21).
  if (dest && dest !== 'empty') return false;
  const accept = String((req && req.headers && req.headers['accept']) || '');
  return /\btext\/html\b/i.test(accept);
}

// Serves pages/error.html at the ORIGINAL url with the ORIGINAL status.
//
// The page's Refresh button reads ?from= and retries the attempted path. We are
// answering in place (not redirecting — a 302 would throw the status code
// away), so the query string is not ours to set; a tiny injected script stamps
// it in with history.replaceState. That both gives the page its ?from= and
// stops Refresh from reloading the URL we just rewrote.
function serveGpErrorPage(req, res, statusCode, attemptedPath) {
  if (res.headersSent) return true;
  let html;
  try {
    html = fs.readFileSync(path.join(process.cwd(), 'pages', 'error.html'), 'utf8');
  } catch (err) {
    return false; // page missing from the bundle — caller falls back to plain text
  }
  let from = String(attemptedPath || '/');
  // Only ever an internal path. Never a protocol-relative or absolute URL, so
  // this can't be turned into an open redirect from the Refresh button.
  if (from.charAt(0) !== '/' || from.charAt(1) === '/' || from.charAt(1) === '\\') from = '/';
  const inject = '<script>(function(){try{if(window.history&&history.replaceState){'
    + 'history.replaceState(null,"",location.pathname+"?from="+' + JSON.stringify(encodeURIComponent(from))
    + ');}}catch(e){}})();</script>';
  // Injected into <head> so it runs before the page's own script reads ?from=.
  html = html.includes('</head>') ? html.replace('</head>', inject + '</head>') : inject + html;
  res.writeHead(statusCode, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
    'Cache-Control': 'no-store',
    'X-Robots-Tag': 'noindex, nofollow'
  });
  res.end(html);
  return true;
}

// 404 for a not-found path: friendly page for navigations, plain text for
// everything else (assets, HEAD probes, non-GET).
function respondNotFound(req, res, pathname) {
  if (isHtmlPageNavigation(req, pathname) && serveGpErrorPage(req, res, 404, (req && req.url) || pathname)) return;
  res.writeHead(404);
  res.end('Not found');
}

function serveStatic(req, res, pathname) {
  const filePath = sanitizeFilePath(pathname);
  if (!filePath) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }
  if (!filePath.startsWith(process.cwd() + path.sep) && filePath !== process.cwd()) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }
  // Allowlist gate: reject anything outside the public static roots with a 404
  // (the same 404 a missing file gets, so we don't confirm which backend
  // files exist).
  if (!isPubliclyServablePath(filePath)) {
    respondNotFound(req, res, pathname);
    return;
  }

  fs.stat(filePath, (err, stat) => {
    if (err || !stat.isFile()) {
      respondNotFound(req, res, pathname);
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const mime = MIME[ext] || 'application/octet-stream';
    const isVideo = ext === '.mp4';
    const cacheControl = getStaticCacheControl(req, pathname, ext);
    const etag = buildStaticEtag(stat);
    const lastModified = stat.mtime.toUTCString();
    const range = req.headers.range;

    if (isVideo && typeof range === 'string') {
      const match = range.match(/bytes=(\d*)-(\d*)/);
      if (match) {
        const start = match[1] === '' ? 0 : Number(match[1]);
        const end = match[2] === '' ? stat.size - 1 : Number(match[2]);

        if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || end < start || end >= stat.size) {
          res.writeHead(416, {
            'Content-Range': `bytes */${stat.size}`
          });
          res.end();
          return;
        }

        res.writeHead(206, {
          'Content-Type': mime,
          'Content-Length': String(end - start + 1),
          'Content-Range': `bytes ${start}-${end}/${stat.size}`,
          'Accept-Ranges': 'bytes',
          'Cache-Control': cacheControl,
          ETag: etag,
          'Last-Modified': lastModified,
          ...SECURITY_HEADERS,
          ...(NODE_ENV === 'production' ? { 'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload' } : {})
        });
        const rangedStream = fs.createReadStream(filePath, { start, end });
        rangedStream.pipe(res);
        rangedStream.on('error', () => {
          res.writeHead(500);
          res.end('Server error');
        });
        return;
      }
    }

    const headers = {
      'Content-Type': mime,
      'Content-Length': stat.size,
      'Cache-Control': cacheControl,
      ETag: etag,
      'Last-Modified': lastModified,
      ...SECURITY_HEADERS
    };
    if (NODE_ENV === 'production') headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains; preload';
    if (isVideo) headers['Accept-Ranges'] = 'bytes';
    if (!pathname.startsWith('/media/') && isCompressibleType(ext)) headers['Vary'] = 'Accept-Encoding';

    if (!range && isNotModified(req, etag, stat)) {
      delete headers['Content-Length'];
      res.writeHead(304, headers);
      res.end();
      return;
    }

    const compressionEncoding = getStaticCompressionEncoding(req);
    const shouldCompress = !pathname.startsWith('/media/') && !range && compressionEncoding && isCompressibleType(ext) && stat.size > 1024;

    if (shouldCompress) {
      delete headers['Content-Length'];
      headers['Content-Encoding'] = compressionEncoding;
      res.writeHead(200, headers);

      const stream = fs.createReadStream(filePath);
      const compressed = createStaticCompressionStream(compressionEncoding);
      stream.pipe(compressed).pipe(res);
      stream.on('error', () => {
        res.writeHead(500);
        res.end('Server error');
      });
      return;
    }

    res.writeHead(200, headers);

    const stream = fs.createReadStream(filePath);
    stream.pipe(res);
    stream.on('error', () => {
      res.writeHead(500);
      res.end('Server error');
    });
  });
}

function sanitizeProfileInput(body) {
  const profile = body && typeof body === 'object' ? body : {};
  const clean = {
    firstName: sanitizeUserString(profile.firstName, 80),
    lastName: sanitizeUserString(profile.lastName, 80),
    email: typeof profile.email === 'string' ? profile.email.trim().toLowerCase().slice(0, 120) : '',
    phone: sanitizeUserString(profile.phone, 40),
    registrationNumber: sanitizeUserString(profile.registrationNumber, 40),
    gmcNumber: sanitizeUserString(profile.gmcNumber, 30),
    specialistCountry: sanitizeUserString(profile.specialistCountry, 30),
    profilePhotoName: sanitizeUserString(profile.profilePhotoName, 180),
    profilePhotoDataUrl: typeof profile.profilePhotoDataUrl === 'string' ? profile.profilePhotoDataUrl.slice(0, 4 * 1024 * 1024) : '',
    idCopyName: sanitizeUserString(profile.idCopyName, 180),
    idCopyDataUrl: typeof profile.idCopyDataUrl === 'string' ? profile.idCopyDataUrl.slice(0, 4 * 1024 * 1024) : '',
    cvFileName: sanitizeUserString(profile.cvFileName, 180),
    updatedAt: new Date().toISOString()
  };

  if (clean.profilePhotoDataUrl && !clean.profilePhotoDataUrl.startsWith('data:image/')) {
    clean.profilePhotoDataUrl = '';
  }
  if (clean.idCopyDataUrl && !clean.idCopyDataUrl.startsWith('data:image/')) {
    clean.idCopyDataUrl = '';
  }

  return clean;
}

function sanitizeUserStateInput(body) {
  const incoming = body && typeof body === 'object' && body.state && typeof body.state === 'object'
    ? body.state
    : {};

  const out = {};
  for (const key of USER_STATE_KEYS) {
    if (!(key in incoming)) continue;
    const value = incoming[key];
    if (value === null || typeof value === 'undefined') {
      out[key] = null;
      continue;
    }

    if (typeof value === 'string') {
      out[key] = value.length > 4 * 1024 * 1024 ? value.slice(0, 4 * 1024 * 1024) : value;
      continue;
    }

    try {
      const serialized = JSON.stringify(value);
      out[key] = serialized.length > 4 * 1024 * 1024 ? serialized.slice(0, 4 * 1024 * 1024) : serialized;
    } catch (err) {
      continue;
    }
  }

  return out;
}

function parseJsonLike(value) {
  if (value === null || typeof value === 'undefined') return null;
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (err) {
    return null;
  }
}

async function getAdminRoleFromSupabaseUserId(userId) {
  const normalizedUserId = String(userId || '').trim();
  if (!normalizedUserId || !isSupabaseDbConfigured()) return '';
  const result = await supabaseDbRequest(
    'user_roles',
    `select=role&user_id=eq.${encodeURIComponent(normalizedUserId)}&limit=1`
  );
  if (!result.ok || !Array.isArray(result.data) || result.data.length === 0) return '';
  return normalizeAdminRole(result.data[0] && result.data[0].role);
}

// ── Consultant allow-list (env + runtime_kv) ────────────────────────────────
// Consultants can be granted/revoked WITHOUT a deploy: the runtime_kv key
// 'ats_consultants' holds a JSON array of lowercase emails (managed from the
// CEO dashboard Team card). The kv read is cached in a module var for ~60s so
// login/reset flows don't hit the DB on every call. Env CONSULTANT_EMAILS
// entries are merged in (and also resolve synchronously via
// getConfiguredAdminRoleForEmail).
const ATS_CONSULTANTS_KV_KEY = 'ats_consultants';
const ATS_CONSULTANTS_KV_CACHE_MS = 60 * 1000;
let atsConsultantsKvCache = { emails: null, fetchedAt: 0 };

// Normalize every historical kv value shape into rich entries
// [{email, name, added_at, added_by}]. Tolerated shapes:
//   ['a@b.c', ...]                          (Task A write shape)
//   { emails: ['a@b.c', ...] }              (Task A also tolerated this)
//   { consultants: [{email, name, ...}] }   (Task E standardized write shape)
function normalizeConsultantKvValue(value) {
  const out = [];
  const seen = new Set();
  const push = (email, entry) => {
    const normalized = String(email || '').trim().toLowerCase();
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    out.push({
      email: normalized,
      name: entry && typeof entry === 'object' ? String(entry.name || '').trim() : '',
      added_at: entry && typeof entry === 'object' ? (entry.added_at || entry.created_at || null) : null,
      added_by: entry && typeof entry === 'object' ? String(entry.added_by || '').trim() : ''
    });
  };
  if (Array.isArray(value)) {
    value.forEach((item) => (item && typeof item === 'object') ? push(item.email, item) : push(item, null));
  } else if (value && typeof value === 'object') {
    if (Array.isArray(value.consultants)) {
      value.consultants.forEach((item) => (item && typeof item === 'object') ? push(item.email, item) : push(item, null));
    }
    if (Array.isArray(value.emails)) value.emails.forEach((item) => push(item, null));
  }
  return out;
}

// Full (uncached) read of the consultant list as rich entries. Local-JSON mode
// (no Supabase) keeps the list in dbState.atsConsultants instead of runtime_kv.
async function loadKvConsultantEntries() {
  if (!isSupabaseDbConfigured()) {
    return normalizeConsultantKvValue({ consultants: dbState.atsConsultants || [] });
  }
  try {
    const row = await getRuntimeKv(ATS_CONSULTANTS_KV_KEY);
    return normalizeConsultantKvValue(row ? row.value : null);
  } catch (err) {
    return [];
  }
}

// Persist the consultant list. Writes the Task E standardized richer shape
// { consultants: [{email,name,added_at,added_by}] } — normalizeConsultantKvValue
// keeps reads compatible with the older array shapes already in prod.
async function saveKvConsultantEntries(entries) {
  const list = Array.isArray(entries) ? entries : [];
  let saved;
  if (!isSupabaseDbConfigured()) {
    dbState.atsConsultants = list;
    saveDbState();
    saved = true;
  } else {
    saved = await setRuntimeKv(ATS_CONSULTANTS_KV_KEY, { consultants: list }, null);
  }
  // Invalidate the ~60s login/reset cache so a just-added consultant can sign
  // in (and a just-removed one is refused) immediately.
  atsConsultantsKvCache = { emails: null, fetchedAt: 0 };
  return saved;
}

async function loadKvConsultantEmails() {
  const nowMs = Date.now();
  if (Array.isArray(atsConsultantsKvCache.emails)
    && (nowMs - atsConsultantsKvCache.fetchedAt) < ATS_CONSULTANTS_KV_CACHE_MS) {
    return atsConsultantsKvCache.emails;
  }
  let emails = [];
  try {
    const entries = await loadKvConsultantEntries();
    emails = entries.map((entry) => entry.email).filter(Boolean);
  } catch (err) {
    emails = [];
  }
  atsConsultantsKvCache = { emails, fetchedAt: nowMs };
  return emails;
}

// Async because the runtime_kv list requires a DB read (cached ~60s). Sync
// call sites (session-cookie role checks) rely on the adminRole stamped into
// the session at login instead of calling this.
async function isConsultantEmail(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return false;
  if (CONSULTANT_EMAILS.has(normalizedEmail)) return true;
  const kvEmails = await loadKvConsultantEmails();
  return kvEmails.includes(normalizedEmail);
}

async function resolveAdminRoleForSupabaseUser(supaUser, fallbackEmail = '') {
  const userId = String(supaUser && supaUser.id ? supaUser.id : '').trim();
  const email = String((supaUser && supaUser.email) || fallbackEmail || '').trim().toLowerCase();
  const dbRole = await getAdminRoleFromSupabaseUserId(userId);
  if (dbRole) return dbRole;
  const configuredRole = getConfiguredAdminRoleForEmail(email);
  if (configuredRole) return configuredRole;
  // Runtime-granted consultants (runtime_kv 'ats_consultants') resolve last.
  if (await isConsultantEmail(email)) return 'consultant';
  return '';
}

function buildAdminSessionProfile(userProfile, adminRole) {
  return {
    ...(userProfile && typeof userProfile === 'object' ? userProfile : {}),
    adminRole: normalizeAdminRole(adminRole)
  };
}

function isAdminEmail(email) {
  return hasAdminPortalAccess(getConfiguredAdminRoleForEmail(email));
}

// Shared host + session + role-vs-host resolution for admin-cookie guards.
// Returns the admin context or writes the 404/401/403 response and returns null.
// NOTE: this admits consultants on the super-admin host — the role fencing
// (consultant = ATS only) happens in requireAdminSession / requireAtsSession.
function resolveAdminRequestContext(req, res) {
  const hostScope = getAdminHostScope(req);
  if (!hostScope) {
    sendJson(res, 404, { ok: false, message: 'Not found' });
    return null;
  }
  const session = getAdminSession(req);
  if (!session) {
    // `message` matters: this was the ONLY admin error body without one, so every
    // caller that shows `d.message` rendered an expired sign-in as a blank/generic
    // failure (e.g. the candidate-document upload's bare "Upload failed").
    // `authenticated:false` stays put — existing callers branch on it.
    sendJson(res, 401, { ok: false, authenticated: false, message: 'Your admin sign-in has expired. Please sign in again.' });
    return null;
  }
  const email = getSessionEmail(session);
  const role = getAdminRoleFromSession(session);
  if (!doesAdminRoleMatchHost(role, hostScope)) {
    sendJson(res, 403, {
      ok: false,
      message: hostScope === 'super_admin'
        ? 'Super admin access required on this host.'
        : 'Admin access required.'
    });
    return null;
  }
  return {
    session,
    email,
    role,
    roleLabel: getAdminRoleLabel(role),
    hostScope,
    hostLabel: getAdminHostLabel(hostScope)
  };
}

function requireAdminSession(req, res) {
  const adminCtx = resolveAdminRequestContext(req, res);
  if (!adminCtx) return null;
  // Consultants are ATS-only: they authenticate like admins on the super-admin
  // host, but every generic admin route stays closed to them. Only
  // requireAtsSession admits the consultant role.
  if (normalizeAdminRole(adminCtx.role) === 'consultant') {
    sendJson(res, 403, { ok: false, message: 'Admin access required.' });
    return null;
  }
  return adminCtx;
}

function requireIntegrationAdminSession(req, res) {
  const session = requireSession(req, res);
  if (!session) return null;
  const email = getSessionEmail(session);
  const role = getConfiguredAdminRoleForEmail(email);
  // Consultants are ATS-only — integration management stays admin/super-admin.
  if (!hasAdminPortalAccess(role) || normalizeAdminRole(role) === 'consultant') {
    sendJson(res, 403, { ok: false, message: 'Admin access required.' });
    return null;
  }
  return { session, email, role, roleLabel: getAdminRoleLabel(role) };
}

function requireSuperAdminSession(req, res) {
  const adminCtx = requireAdminSession(req, res);
  if (!adminCtx) return null;
  if (!isSuperAdminRole(adminCtx.role)) {
    sendJson(res, 403, { ok: false, message: 'Super admin access required.' });
    return null;
  }
  return adminCtx;
}

// CEO access is super-admin access: it requires the super-admin host scope AND a
// super-admin role (same gate as requireSuperAdminSession). The legacy CEO_EMAIL-only
// branch was unreachable on the super-admin host (requireAdminSession 403s non-super
// roles there) and contradictory on the employee host, so it is removed (#70).
function requireCeoSession(req, res) {
  return requireSuperAdminSession(req, res);
}

// ATS access: the ATS surface (jobs, candidates, pipeline, interviews,
// practices) is shared by the CEO (super_admin) and recruitment consultants.
// Uses resolveAdminRequestContext directly (NOT requireAdminSession, which
// deliberately rejects consultants) so consultants pass ONLY the routes that
// opt into this guard. Everything else on the CEO dashboard stays
// super-admin-only via requireCeoSession.
function requireAtsSession(req, res) {
  const adminCtx = resolveAdminRequestContext(req, res);
  if (!adminCtx) return null;
  const role = normalizeAdminRole(adminCtx.role);
  if (role !== 'super_admin' && role !== 'consultant') {
    sendJson(res, 403, { ok: false, message: 'ATS access required.' });
    return null;
  }
  return adminCtx;
}

// Soft (non-responding) equivalent of requireAtsSession — returns the admin
// context or null WITHOUT ever writing a 401/403/404 response, unlike
// resolveAdminRequestContext/requireAtsSession which send one on failure.
// Used ONLY to decide whether an incoming request is ALSO carrying a valid
// admin/ATS session before honoring an optional flag like the job-preview
// `?preview=1` param (2026-07-18 admin-only job preview) — a request that
// fails this check must fall through to normal, unprivileged behavior rather
// than getting its own error response. Mirrors resolveAdminRequestContext +
// requireAtsSession's exact validation (host scope -> session -> role-vs-host
// match -> super_admin/consultant role) so the two checks can never drift.
function getAtsSessionSoft(req) {
  const hostScope = getAdminHostScope(req);
  if (!hostScope) return null;
  const session = getAdminSession(req);
  if (!session) return null;
  const role = getAdminRoleFromSession(session);
  if (!doesAdminRoleMatchHost(role, hostScope)) return null;
  const normalizedRole = normalizeAdminRole(role);
  if (normalizedRole !== 'super_admin' && normalizedRole !== 'consultant') return null;
  return {
    session,
    email: getSessionEmail(session),
    role: normalizedRole,
    roleLabel: getAdminRoleLabel(normalizedRole),
    hostScope,
    hostLabel: getAdminHostLabel(hostScope)
  };
}

// Routes that are BOTH admin-ops tooling and ATS-functional (currently only
// submit-to-practice) accept every requireAdminSession-passing role AND the
// consultant role. resolveAdminRequestContext already enforces the host↔role
// match (consultants only ever match the super-admin host; RSO admins keep
// their employee-host access unchanged), so this union is exactly that check
// without requireAdminSession's explicit consultant rejection.
function requireAdminOrAtsSession(req, res) {
  return resolveAdminRequestContext(req, res);
}

// Must NEVER throw. If the filesystem is read-only the agent tooling simply has
// no scratch space — that is a tooling limitation, not a product error, and it
// must not bubble up into the request handler (which would record it in
// client_errors and drown the owner's Technical tab).
function ensureAgentOutputRoot() {
  try {
    ensureDirSync(AGENT_OUTPUT_ROOT);
    return true;
  } catch (agentDirErr) {
    console.warn('[agents] output root unavailable (ignored):', agentDirErr && agentDirErr.message);
    return false;
  }
}

function readJsonFileSafe(filePath) {
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function writeJsonFileSafe(filePath, value) {
  ensureDirSync(path.dirname(filePath));
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

function tailFile(filePath, maxBytes = 12000) {
  try {
    const stat = fs.statSync(filePath);
    const start = Math.max(0, stat.size - maxBytes);
    const fd = fs.openSync(filePath, 'r');
    try {
      const buffer = Buffer.alloc(stat.size - start);
      fs.readSync(fd, buffer, 0, buffer.length, start);
      return buffer.toString('utf8');
    } finally {
      fs.closeSync(fd);
    }
  } catch {
    return '';
  }
}

function sanitizeAgentRunId(value) {
  return String(value || '')
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function getHybridAgentRunDir(runId) {
  return path.join(AGENT_OUTPUT_ROOT, sanitizeAgentRunId(runId));
}

function getHybridAgentRunSummary(runId) {
  const safeRunId = sanitizeAgentRunId(runId);
  if (!safeRunId) return null;
  const runDir = getHybridAgentRunDir(safeRunId);
  const runState = readJsonFileSafe(path.join(runDir, 'run-state.json')) || {};
  const registry = hybridAgentControlState.runs[safeRunId] || {};
  const launch = readJsonFileSafe(path.join(runDir, 'launch.json')) || {};
  const reportPath = path.join(runDir, 'REPORT.md');
  const stdoutLogPath = path.join(runDir, 'orchestrator.stdout.log');
  const stderrLogPath = path.join(runDir, 'orchestrator.stderr.log');

  return {
    runId: safeRunId,
    task: runState.task || registry.task || '',
    status: runState.status || registry.status || 'unknown',
    phase: runState.phase || registry.phase || '',
    profile: runState.profile || registry.profile || '',
    collaborationMode: runState.collaborationMode || registry.collaborationMode || '',
    complexityMode: runState.complexityMode || registry.complexityMode || 'auto',
    taskComplexity: runState.taskComplexity || registry.taskComplexity || 'standard',
    startedAt: runState.startedAt || registry.startedAt || '',
    finishedAt: runState.finishedAt || registry.finishedAt || '',
    requestedBy: runState.requestedBy || registry.requestedBy || launch.requestedBy || '',
    currentSubtask: runState.currentSubtask || registry.currentSubtask || null,
    completedSubtasks: Array.isArray(runState.completedSubtasks) ? runState.completedSubtasks : [],
    planSummary: runState.planSummary || '',
    outputDir: path.relative(process.cwd(), runDir),
    reportExists: fs.existsSync(reportPath),
    reportPath: fs.existsSync(reportPath) ? path.relative(process.cwd(), reportPath) : '',
    reportPreview: fs.existsSync(reportPath) ? tailFile(reportPath, 10000) : '',
    stdoutTail: tailFile(stdoutLogPath, 8000),
    stderrTail: tailFile(stderrLogPath, 4000),
  };
}

function listHybridAgentRuns(limit = 12) {
  ensureAgentOutputRoot();
  let dirEntries = [];
  try {
    dirEntries = fs.readdirSync(AGENT_OUTPUT_ROOT, { withFileTypes: true })
      .filter(entry => entry.isDirectory())
      .map(entry => entry.name)
      .sort()
      .reverse();
  } catch {
    dirEntries = [];
  }

  const runs = [];
  for (const runId of dirEntries) {
    const summary = getHybridAgentRunSummary(runId);
    if (summary) runs.push(summary);
    if (runs.length >= limit) break;
  }

  const activeRunId = hybridAgentControlState.activeRunId;
  if (activeRunId && !runs.find(run => run.runId === activeRunId)) {
    const live = getHybridAgentRunSummary(activeRunId);
    if (live) runs.unshift(live);
  }

  return runs.slice(0, limit);
}

function hasActiveHybridAgentRun() {
  const activeRunId = hybridAgentControlState.activeRunId;
  if (!activeRunId) return false;
  const record = hybridAgentControlState.runs[activeRunId];
  return !!(record && record.status === 'running');
}

function updateHybridAgentRegistry(runId, patch) {
  const safeRunId = sanitizeAgentRunId(runId);
  if (!safeRunId) return null;
  hybridAgentControlState.runs[safeRunId] = {
    ...(hybridAgentControlState.runs[safeRunId] || {}),
    ...patch,
    runId: safeRunId
  };
  return hybridAgentControlState.runs[safeRunId];
}

function getHybridAgentBridgeRequestToken(req) {
  const bearer = getBearerToken(req);
  if (bearer) return bearer;
  return String(req && req.headers && req.headers['x-agent-bridge-token'] ? req.headers['x-agent-bridge-token'] : '').trim();
}

function createHybridAgentWorkerRegistration(store, email, options) {
  const nextStore = normalizeHybridAgentBridgeStore(store);
  const tokenValue = crypto.randomBytes(24).toString('hex');
  const tokenHash = crypto.createHash('sha256').update(tokenValue).digest('hex');
  const workerCount = Object.keys(nextStore.workers).length + 1;
  const workerId = sanitizeHybridAgentWorkerId(options && options.workerId)
    || sanitizeHybridAgentWorkerId(`worker-${Date.now().toString(36)}-${workerCount}`);
  const workerName = sanitizeHybridAgentWorkerName(options && options.name) || `Agent Host ${workerCount}`;
  const currentIso = new Date().toISOString();

  nextStore.workers[workerId] = normalizeHybridAgentWorkerRecord(workerId, {
    id: workerId,
    name: workerName,
    tokenHash,
    createdAt: currentIso,
    updatedAt: currentIso,
    createdBy: String(email || '').trim().toLowerCase(),
    enabled: true,
    lastSeenAt: '',
    providers: null,
    providerStatusRefreshedAt: '',
    runs: [],
    activeRunId: '',
    bridgeInfo: null,
    relayOrigin: '',
    lastCommandResultAt: '',
    meta: {}
  });
  if (!nextStore.primaryWorkerId) nextStore.primaryWorkerId = workerId;

  return {
    store: nextStore,
    workerId,
    workerName,
    token: tokenValue
  };
}

function getSelectedHybridAgentWorker(store) {
  const source = normalizeHybridAgentBridgeStore(store);
  if (source.primaryWorkerId && source.workers[source.primaryWorkerId] && source.workers[source.primaryWorkerId].enabled !== false) {
    return source.workers[source.primaryWorkerId];
  }
  return Object.values(source.workers).find(function (worker) { return worker && worker.enabled !== false; }) || null;
}

function isHybridAgentWorkerConnected(worker) {
  if (!worker || !worker.lastSeenAt) return false;
  const seenAtMs = Date.parse(worker.lastSeenAt);
  if (!Number.isFinite(seenAtMs)) return false;
  return (now() - seenAtMs) <= HYBRID_AGENT_BRIDGE_STALE_MS;
}

function getActiveHybridAgentRelay(store) {
  const worker = getSelectedHybridAgentWorker(store);
  if (!worker || !isHybridAgentWorkerConnected(worker)) return null;
  return {
    workerId: worker.id,
    workerName: worker.name,
    lastSeenAt: worker.lastSeenAt,
    providers: worker.providers,
    providerStatusRefreshedAt: worker.providerStatusRefreshedAt || '',
    runs: Array.isArray(worker.runs) ? worker.runs : [],
    activeRunId: worker.activeRunId || '',
    bridgeInfo: worker.bridgeInfo || null,
    relayOrigin: worker.relayOrigin || '',
    lastCommandResultAt: worker.lastCommandResultAt || '',
    meta: worker.meta || {},
    connected: true,
    mode: 'relay'
  };
}

function getTargetHybridAgentWorkerId(store) {
  const worker = getSelectedHybridAgentWorker(store);
  return worker ? worker.id : '';
}

function listHybridAgentWorkers(store) {
  const source = normalizeHybridAgentBridgeStore(store);
  return Object.values(source.workers)
    .map(function (worker) {
      const connected = isHybridAgentWorkerConnected(worker);
      const providers = worker.providers && typeof worker.providers === 'object' ? worker.providers : null;
      const availableProviderCount = providers ? Object.values(providers).filter(function (entry) { return entry && entry.available; }).length : 0;
      return {
        id: worker.id,
        name: worker.name || worker.id,
        primary: source.primaryWorkerId === worker.id,
        enabled: worker.enabled !== false,
        connected,
        createdAt: worker.createdAt || '',
        updatedAt: worker.updatedAt || '',
        lastSeenAt: worker.lastSeenAt || '',
        relayOrigin: worker.relayOrigin || '',
        bridgeInfo: worker.bridgeInfo || null,
        activeRunId: worker.activeRunId || '',
        providerStatusRefreshedAt: worker.providerStatusRefreshedAt || '',
        availableProviderCount,
        meta: worker.meta || {}
      };
    })
    .sort(function (a, b) {
      if (a.primary && !b.primary) return -1;
      if (!a.primary && b.primary) return 1;
      if (a.connected && !b.connected) return -1;
      if (!a.connected && b.connected) return 1;
      return String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''));
    });
}

function findHybridAgentWorkerByCredentials(store, workerId, tokenValue) {
  const source = normalizeHybridAgentBridgeStore(store);
  const safeWorkerId = sanitizeHybridAgentWorkerId(workerId || '');
  const worker = safeWorkerId ? source.workers[safeWorkerId] : null;
  if (!worker || worker.enabled === false || !worker.tokenHash) return null;
  const tokenHash = crypto.createHash('sha256').update(String(tokenValue || '')).digest('hex');
  if (tokenHash !== worker.tokenHash) return null;
  return worker;
}

function buildHybridAgentBridgeStatus(req, store) {
  const source = normalizeHybridAgentBridgeStore(store);
  const relay = getActiveHybridAgentRelay(source);
  const workers = listHybridAgentWorkers(source);
  const selectedWorker = getSelectedHybridAgentWorker(source);
  if (!relay) {
    return {
      connected: false,
      mode: 'remote',
      relayUrl: getRequestOrigin(req),
      lastSeenAt: selectedWorker && selectedWorker.lastSeenAt ? selectedWorker.lastSeenAt : '',
      workerId: selectedWorker ? selectedWorker.id : '',
      workerName: selectedWorker ? selectedWorker.name : '',
      workerCount: workers.length
    };
  }
  return {
    connected: true,
    mode: 'relay',
    relayUrl: getRequestOrigin(req),
    lastSeenAt: relay.lastSeenAt,
    providerStatusRefreshedAt: relay.providerStatusRefreshedAt || '',
    baseUrl: relay.bridgeInfo && relay.bridgeInfo.baseUrl ? relay.bridgeInfo.baseUrl : '',
    host: relay.bridgeInfo && relay.bridgeInfo.host ? relay.bridgeInfo.host : '',
    port: relay.bridgeInfo && relay.bridgeInfo.port ? relay.bridgeInfo.port : '',
    workerId: relay.workerId,
    workerName: relay.workerName || relay.workerId,
    workerCount: workers.length,
    meta: relay.meta || {}
  };
}

function queueHybridAgentBridgeCommand(store, workerId, type, payload, requestedBy) {
  const nextStore = normalizeHybridAgentBridgeStore(store);
  const safeWorkerId = sanitizeHybridAgentWorkerId(workerId || '');
  if (!safeWorkerId || !nextStore.workers[safeWorkerId]) return { store: nextStore, command: null };
  nextStore.commandSeq += 1;
  const command = {
    id: `bridge-${Date.now()}-${nextStore.commandSeq}`,
    workerId: safeWorkerId,
    type: String(type || '').trim(),
    payload: payload && typeof payload === 'object' ? payload : {},
    requestedBy: String(requestedBy || '').trim(),
    createdAt: new Date().toISOString(),
    status: 'queued',
    sentAt: '',
    completedAt: '',
    deliveryCount: 0,
    result: null,
    message: ''
  };
  nextStore.commands.push(command);
  if (nextStore.commands.length > 200) nextStore.commands = nextStore.commands.slice(-200);
  return { store: nextStore, command };
}

function takePendingHybridAgentBridgeCommands(store, workerId, limit = 8) {
  const nextStore = normalizeHybridAgentBridgeStore(store);
  const safeWorkerId = sanitizeHybridAgentWorkerId(workerId || '');
  const currentIso = new Date().toISOString();
  const resendBeforeMs = now() - 30 * 1000;
  const commands = nextStore.commands
    .filter(function (command) {
      if (!command || command.workerId !== safeWorkerId) return false;
      if (command.status === 'queued') return true;
      if (command.status !== 'sent') return false;
      const sentAtMs = Date.parse(command.sentAt || '');
      return !Number.isFinite(sentAtMs) || sentAtMs < resendBeforeMs;
    })
    .slice(0, limit)
    .map(function (command) {
      command.status = 'sent';
      command.sentAt = currentIso;
      command.deliveryCount = (command.deliveryCount || 0) + 1;
      return {
        id: command.id,
        workerId: command.workerId,
        type: command.type,
        payload: command.payload,
        createdAt: command.createdAt
      };
    });

  return { store: nextStore, commands };
}

function applyHybridAgentBridgeCommandUpdates(store, workerId, updates) {
  const nextStore = normalizeHybridAgentBridgeStore(store);
  const safeWorkerId = sanitizeHybridAgentWorkerId(workerId || '');
  if (!Array.isArray(updates) || !updates.length || !safeWorkerId) return nextStore;
  const currentIso = new Date().toISOString();
  updates.forEach(function (update) {
    if (!update || typeof update !== 'object' || !update.id) return;
    const command = nextStore.commands.find(function (candidate) {
      return candidate.id === update.id && candidate.workerId === safeWorkerId;
    });
    if (!command) return;
    command.status = String(update.status || 'completed').trim() || 'completed';
    command.completedAt = currentIso;
    command.message = typeof update.message === 'string' ? update.message : command.message;
    command.result = update.result && typeof update.result === 'object' ? update.result : command.result;
  });
  const worker = nextStore.workers[safeWorkerId];
  if (worker) worker.lastCommandResultAt = currentIso;
  return nextStore;
}

function updateHybridAgentBridgeSnapshot(store, workerId, payload, req) {
  const nextStore = normalizeHybridAgentBridgeStore(store);
  const safeWorkerId = sanitizeHybridAgentWorkerId(workerId || '');
  const worker = nextStore.workers[safeWorkerId];
  if (!worker) return nextStore;

  const currentIso = new Date().toISOString();
  const bridgeInfo = payload && payload.bridge && typeof payload.bridge === 'object' ? payload.bridge : null;
  const runs = Array.isArray(payload && payload.runs)
    ? payload.runs.filter(function (run) { return run && typeof run === 'object' && run.runId; }).slice(0, 20)
    : [];
  const activeRun = typeof payload.activeRunId === 'string' && payload.activeRunId
    ? payload.activeRunId
    : ((runs.find(function (run) { return run.status === 'running' || run.status === 'starting' || run.status === 'launching'; }) || {}).runId || '');
  const workerMeta = payload && payload.worker && typeof payload.worker === 'object' ? payload.worker : {};
  const derivedName = sanitizeHybridAgentWorkerName(workerMeta.name || workerMeta.hostname || worker.name || worker.id) || worker.name || worker.id;

  nextStore.workers[safeWorkerId] = normalizeHybridAgentWorkerRecord(safeWorkerId, {
    ...worker,
    name: derivedName,
    updatedAt: currentIso,
    lastSeenAt: currentIso,
    providers: payload && payload.providers && typeof payload.providers === 'object' ? payload.providers : null,
    providerStatusRefreshedAt: typeof (payload && payload.providerStatusRefreshedAt) === 'string' ? payload.providerStatusRefreshedAt : currentIso,
    runs,
    activeRunId: activeRun,
    bridgeInfo,
    relayOrigin: getRequestOrigin(req),
    lastCommandResultAt: worker.lastCommandResultAt || '',
    meta: {
      hostname: typeof workerMeta.hostname === 'string' ? workerMeta.hostname : '',
      platform: typeof workerMeta.platform === 'string' ? workerMeta.platform : '',
      user: typeof workerMeta.user === 'string' ? workerMeta.user : '',
      pid: workerMeta.pid || ''
    }
  });

  if (!nextStore.primaryWorkerId || !nextStore.workers[nextStore.primaryWorkerId]) {
    nextStore.primaryWorkerId = safeWorkerId;
  }

  return nextStore;
}

async function getCachedHybridAgentProviderStatus(force = false) {
  const nowMs = Date.now();
  if (!force && hybridAgentControlState.providerStatusCache.data && hybridAgentControlState.providerStatusCache.expiresAt > nowMs) {
    return hybridAgentControlState.providerStatusCache.data;
  }
  if (!force && hybridAgentControlState.providerStatusCache.inFlight) {
    return hybridAgentControlState.providerStatusCache.inFlight;
  }

  const promise = hybridAgents.inspectProviders()
    .then(function (data) {
      hybridAgentControlState.providerStatusCache.data = data;
      hybridAgentControlState.providerStatusCache.expiresAt = Date.now() + 10000;
      hybridAgentControlState.providerStatusCache.refreshedAt = new Date().toISOString();
      hybridAgentControlState.providerStatusCache.inFlight = null;
      return data;
    })
    .catch(function (error) {
      hybridAgentControlState.providerStatusCache.inFlight = null;
      throw error;
    });

  hybridAgentControlState.providerStatusCache.inFlight = promise;
  return promise;
}

function buildHybridAgentChildEnv() {
  const env = {};
  const allowList = [
    'PATH',
    'HOME',
    'USER',
    'LOGNAME',
    'SHELL',
    'TMPDIR',
    'TMP',
    'TEMP',
    'LANG',
    'LC_ALL',
    'TERM',
    'COLORTERM',
    'XDG_CONFIG_HOME',
    'XDG_DATA_HOME',
    'XDG_STATE_HOME',
    'XDG_CACHE_HOME',
    'NODE_ENV',
    'CODEX_CLI_PATH',
    'CLAUDE_CLI_PATH',
    'AGENT_PROFILE',
    'AGENT_COLLABORATION_MODE',
    'AGENT_COMPLEXITY_MODE',
    'AGENT_ENABLE_CLAUDE_BROWSER_USE_MCP',
    'AGENT_MAX_FILE_CONTEXT_CHARS',
    'AGENT_MAX_PLANNER_FILES',
    'AGENT_MAX_SUBTASKS',
    'AGENT_MAX_DEPENDENCY_CONTEXT_CHARS',
    'AGENT_MAX_SHARED_MEMORY_ITEMS',
    'CLAUDE_BROWSER_MCP_NAME',
    'OPENAI_AGENT_MODEL',
    'OPENAI_REVIEW_MODEL',
    'OPENAI_COMPLEX_MODEL',
    'OPENAI_STANDARD_MODEL',
    'OPENAI_SIMPLE_MODEL',
    'OPENAI_COMPLEX_REVIEW_MODEL',
    'OPENAI_STANDARD_REVIEW_MODEL',
    'ANTHROPIC_AGENT_MODEL',
    'ANTHROPIC_RESEARCH_MODEL',
    'ANTHROPIC_COMPLEX_MODEL',
    'ANTHROPIC_STANDARD_MODEL',
    'ANTHROPIC_SIMPLE_MODEL'
  ];

  allowList.forEach(function (key) {
    if (typeof process.env[key] === 'string' && process.env[key]) {
      env[key] = process.env[key];
    }
  });

  env.PATH = process.env.PATH || env.PATH || '';
  env.HOME = process.env.HOME || env.HOME || '';
  env.NODE_ENV = NODE_ENV;
  env.AGENT_SKIP_DOTENV = 'true';
  return env;
}

function buildHybridAgentDashboardState(taskText, options) {
  const task = String(taskText || '').trim();
  const profile = options && options.profile ? options.profile : 'balanced';
  const collaborationMode = options && options.collaborationMode ? options.collaborationMode : 'paired';
  const complexityMode = options && options.complexityMode ? options.complexityMode : 'auto';
  const bridgeStore = options && options.bridgeStore ? options.bridgeStore : createEmptyHybridAgentBridgeStore();
  const relay = options && options.bridgeState ? options.bridgeState : getActiveHybridAgentRelay(bridgeStore);
  const providerStates = options && options.providerStates
    ? options.providerStates
    : (relay && relay.providers ? relay.providers : hybridAgentControlState.providerStatusCache.data);
  const providerEntries = providerStates ? Object.values(providerStates) : [];
  const availableProviders = providerEntries.filter(function (state) { return state && state.available; });
  const warnings = [];

  if (!availableProviders.length) {
    warnings.push('Neither Codex nor Claude is currently connected. Use the connect help buttons before starting a run.');
  } else if (collaborationMode === 'paired' && availableProviders.length < 2) {
    warnings.push('Only one provider is connected right now, so paired mode will automatically fall back to routed execution.');
  }
  if (
    task &&
    hybridAgents.inferBrowserUseNeed &&
    hybridAgents.inferBrowserUseNeed(task) &&
    !(providerStates && providerStates.anthropic && providerStates.anthropic.browserUse && providerStates.anthropic.browserUse.available)
  ) {
    warnings.push('This task looks like a browser/computer walkthrough, but Claude browser-use MCP is not currently connected.');
  }
  if (task && task.length < 12) {
    warnings.push('Short prompts produce weaker plans. Give the agent a concrete, repo-specific task.');
  }

  return {
    policy: hybridAgents.getModelPolicy(task, complexityMode, profile, collaborationMode),
    activeRunId: relay && relay.activeRunId ? relay.activeRunId : (hybridAgentControlState.activeRunId || ''),
    runs: relay && Array.isArray(relay.runs) ? relay.runs.slice(0, 12) : listHybridAgentRuns(12),
    workers: listHybridAgentWorkers(bridgeStore),
    primaryWorkerId: bridgeStore && bridgeStore.primaryWorkerId ? bridgeStore.primaryWorkerId : '',
    providerStatusRefreshedAt: relay && relay.providerStatusRefreshedAt
      ? relay.providerStatusRefreshedAt
      : (hybridAgentControlState.providerStatusCache.refreshedAt || ''),
    warnings,
    security: {
      superAdminOnly: true,
      sameOriginRequired: ENFORCE_SAME_ORIGIN,
      singleActiveRun: true,
      subscriptionCliOnly: true,
      secretsPassedToChild: false,
      bridgeRelayAvailable: true,
    }
  };
}

function startHybridAgentRun(options) {
  const task = String(options && options.task ? options.task : '').trim();
  if (!task) throw new Error('Task is required.');
  if (hasActiveHybridAgentRun()) throw new Error('An agent run is already in progress.');

  const profile = ['balanced', 'codex-heavy', 'claude-heavy'].includes(options.profile) ? options.profile : 'balanced';
  const collaboration = ['single', 'routed', 'paired'].includes(options.collaborationMode) ? options.collaborationMode : 'paired';
  const complexity = ['auto', 'simple', 'standard', 'complex'].includes(options.complexity) ? options.complexity : 'auto';
  const runId = sanitizeAgentRunId(options.runId || `agent-${new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)}`);
  const requestedBy = typeof options.requestedBy === 'string' ? options.requestedBy.trim() : '';
  const runDir = getHybridAgentRunDir(runId);
  ensureDirSync(runDir);

  const stdoutLogPath = path.join(runDir, 'orchestrator.stdout.log');
  const stderrLogPath = path.join(runDir, 'orchestrator.stderr.log');
  const stdoutStream = fs.createWriteStream(stdoutLogPath, { flags: 'a' });
  const stderrStream = fs.createWriteStream(stderrLogPath, { flags: 'a' });
  const args = [
    'scripts/agents.js',
    '--task', task,
    '--profile', profile,
    '--collaboration', collaboration,
    '--complexity', complexity,
    '--run-id', runId
  ];
  const child = spawn(process.execPath, args, {
    cwd: process.cwd(),
    env: buildHybridAgentChildEnv(),
    stdio: ['ignore', 'pipe', 'pipe']
  });

  hybridAgentControlState.activeRunId = runId;
  updateHybridAgentRegistry(runId, {
    status: 'running',
    phase: 'launching',
    startedAt: new Date().toISOString(),
    task,
    profile,
    collaborationMode: collaboration,
    complexityMode: complexity,
    taskComplexity: hybridAgents.resolveTaskComplexity(task, complexity),
    requestedBy,
    pid: child.pid,
    stdoutLogPath,
    stderrLogPath
  });

  writeJsonFileSafe(path.join(runDir, 'launch.json'), {
    runId,
    task,
    profile,
    collaborationMode: collaboration,
    complexityMode: complexity,
    requestedBy,
    pid: child.pid,
    startedAt: new Date().toISOString()
  });

  child.stdout.on('data', function (chunk) {
    stdoutStream.write(chunk);
  });
  child.stderr.on('data', function (chunk) {
    stderrStream.write(chunk);
  });
  child.on('close', function (code, signal) {
    stdoutStream.end();
    stderrStream.end();
    const existingState = readJsonFileSafe(path.join(runDir, 'run-state.json')) || {};
    updateHybridAgentRegistry(runId, {
      status: code === 0 ? 'completed' : (signal ? 'cancelled' : 'failed'),
      phase: code === 0 ? 'completed' : (signal ? 'cancelled' : 'error'),
      finishedAt: new Date().toISOString(),
      exitCode: code,
      signal: signal || '',
      currentSubtask: null
    });
    if (!existingState || !existingState.status || existingState.status === 'running' || existingState.status === 'starting') {
      writeJsonFileSafe(path.join(runDir, 'run-state.json'), {
        ...existingState,
        runId,
        task,
        profile,
        collaborationMode: collaboration,
        complexityMode: complexity,
        taskComplexity: hybridAgents.resolveTaskComplexity(task, complexity),
        requestedBy: existingState.requestedBy || requestedBy,
        status: code === 0 ? 'completed' : (signal ? 'cancelled' : 'failed'),
        phase: code === 0 ? 'completed' : (signal ? 'cancelled' : 'error'),
        startedAt: existingState.startedAt || new Date().toISOString(),
        finishedAt: new Date().toISOString(),
        outputDir: path.relative(process.cwd(), runDir),
        error: code === 0 ? '' : `Process exited with code ${code}${signal ? ` (signal ${signal})` : ''}`
      });
    }
    if (hybridAgentControlState.activeRunId === runId) {
      hybridAgentControlState.activeRunId = '';
    }
  });
  child.on('error', function (error) {
    stdoutStream.end();
    stderrStream.end();
    updateHybridAgentRegistry(runId, {
      status: 'failed',
      phase: 'error',
      finishedAt: new Date().toISOString(),
      error: error && error.message ? error.message : 'Failed to launch agent run.'
    });
    writeJsonFileSafe(path.join(runDir, 'run-state.json'), {
      runId,
      task,
      profile,
      collaborationMode: collaboration,
      complexityMode: complexity,
      taskComplexity: hybridAgents.resolveTaskComplexity(task, complexity),
      requestedBy,
      status: 'failed',
      phase: 'error',
      startedAt: new Date().toISOString(),
      finishedAt: new Date().toISOString(),
      outputDir: path.relative(process.cwd(), runDir),
      error: error && error.message ? error.message : 'Failed to launch agent run.'
    });
    if (hybridAgentControlState.activeRunId === runId) {
      hybridAgentControlState.activeRunId = '';
    }
  });

  return { runId, task, profile, collaborationMode: collaboration, complexityMode: complexity, pid: child.pid };
}

function cancelHybridAgentRun(runId) {
  const safeRunId = sanitizeAgentRunId(runId);
  const record = hybridAgentControlState.runs[safeRunId];
  if (!record || !record.pid || record.status !== 'running') return false;
  try {
    process.kill(record.pid, 'SIGTERM');
    updateHybridAgentRegistry(safeRunId, { status: 'cancelling', phase: 'cancelling' });
    return true;
  } catch {
    return false;
  }
}

function timingSafeEqualStrings(left, right) {
  const a = Buffer.from(String(left || ''));
  const b = Buffer.from(String(right || ''));
  if (a.length !== b.length) return false;
  try {
    return crypto.timingSafeEqual(a, b);
  } catch (err) {
    return false;
  }
}

function hasOwn(obj, key) {
  return !!obj && Object.prototype.hasOwnProperty.call(obj, key);
}

function getUserStateObject(email) {
  const source = dbState.userState[email];
  if (!source || typeof source !== 'object') return {};
  const out = {};
  for (const key of USER_STATE_KEYS) {
    if (hasOwn(source, key)) {
      out[key] = parseJsonLike(source[key]);
    }
  }
  out.updatedAt = source.updatedAt || null;
  return out;
}

function getProgressSummary(userStateObj) {
  const epic = userStateObj.gp_epic_progress && typeof userStateObj.gp_epic_progress === 'object'
    ? userStateObj.gp_epic_progress
    : {};
  const amc = userStateObj.gp_amc_progress && typeof userStateObj.gp_amc_progress === 'object'
    ? userStateObj.gp_amc_progress
    : {};
  const ahpra = userStateObj.gp_ahpra_progress && typeof userStateObj.gp_ahpra_progress === 'object'
    ? userStateObj.gp_ahpra_progress
    : {};
  const docs = userStateObj.gp_documents_prep && typeof userStateObj.gp_documents_prep === 'object'
    ? userStateObj.gp_documents_prep
    : {};

  const steps = [
    { id: 'profile_setup', label: 'Profile setup', done: false },
    { id: 'epic_verification', label: 'EPIC verification', done: false },
    { id: 'amc_portfolio', label: 'AMC portfolio', done: false },
    { id: 'documents', label: 'Documents prepared', done: false },
    { id: 'ahpra_setup', label: 'AHPRA account setup', done: false },
    { id: 'ahpra_submission', label: 'AHPRA submission', done: false },
    { id: 'ahpra_assessment', label: 'AHPRA assessment', done: false },
    { id: 'registration_outcome', label: 'Registration outcome', done: false }
  ];

  steps[0].done = !!(epic && epic.completed && epic.completed.create_account === true);
  steps[1].done = !!(epic && epic.completed && epic.completed.verification_issued === true);
  steps[2].done = !!(amc && amc.completed && amc.completed.qualifications_verified === true);

  const docEntries = docs && docs.docs && typeof docs.docs === 'object' ? Object.values(docs.docs) : [];
  const preparedByYou = docEntries.filter((item) => item && typeof item === 'object' && hasOwn(item, 'uploaded'));
  const uploadedPrepared = preparedByYou.filter((item) => item.uploaded === true);
  steps[3].done = preparedByYou.length > 0 && uploadedPrepared.length === preparedByYou.length;

  steps[4].done = !!(ahpra && ahpra.stage_1 && ahpra.stage_1.completedAt);
  steps[5].done = !!(ahpra && ahpra.stage_2 && ahpra.stage_2.completedAt);
  steps[6].done = !!(ahpra && ahpra.stage_3 && (ahpra.stage_3.completedAt || ahpra.stage_3.applicationOpenedAt));
  steps[7].done = !!(ahpra && ahpra.stage_4 && ahpra.stage_4.completedAt);

  const doneCount = steps.filter((step) => step.done).length;
  const currentIndex = steps.findIndex((step) => !step.done);
  const currentStepIndex = currentIndex === -1 ? steps.length : currentIndex + 1;
  const currentStepLabel = currentIndex === -1 ? 'Completed' : steps[currentIndex].label;
  const percent = Math.round((doneCount / steps.length) * 100);

  const assessmentStatus = ahpra && ahpra.stage_3 && typeof ahpra.stage_3.assessmentStatus === 'string'
    ? ahpra.stage_3.assessmentStatus
    : '';
  const pendingVerification = !steps[1].done || !steps[2].done || assessmentStatus === 'under_review' || assessmentStatus === 'further_info_requested';

  const actionRequired = !!(
    (ahpra && ahpra.adminFlags && ahpra.adminFlags.actionRequired === true) ||
    assessmentStatus === 'further_info_requested'
  );

  const documentsPending = docEntries.filter((item) => item && typeof item === 'object' && (item.status === 'under_review' || item.status === 'rejected')).length;

  return {
    steps,
    currentStepIndex,
    totalSteps: steps.length,
    currentStepLabel,
    percent,
    pendingVerification,
    actionRequired,
    documentsPending
  };
}

function toStatusLabel(value, uploaded) {
  const raw = typeof value === 'string' ? value : '';
  if (raw === 'accepted' || raw === 'approved') return 'accepted';
  if (raw === 'rejected') return 'rejected';
  if (raw === 'under_review') return 'under_review';
  if (raw === 'pending') return uploaded ? 'under_review' : 'pending';
  return uploaded ? 'under_review' : 'pending';
}

function getDocMetaForCountry(countryCode) {
  const code = (typeof countryCode === 'string' ? countryCode : 'uk').toLowerCase();
  const shared = GP_DOCUMENT_META.shared || [];
  const countrySpecific = GP_DOCUMENT_META[code] || GP_DOCUMENT_META.uk || [];
  return [...shared, ...countrySpecific];
}

function getCandidateDocuments(userStateObj) {
  const docsState = userStateObj.gp_documents_prep && typeof userStateObj.gp_documents_prep === 'object'
    ? userStateObj.gp_documents_prep
    : {};
  const preparedDocsState = userStateObj.gp_prepared_docs && typeof userStateObj.gp_prepared_docs === 'object'
    ? userStateObj.gp_prepared_docs
    : {};
  const docs = docsState.docs && typeof docsState.docs === 'object' ? docsState.docs : {};
  const preparedDocs = preparedDocsState.docs && typeof preparedDocsState.docs === 'object' ? preparedDocsState.docs : {};

  const docCountry = docsState.country || 'uk';
  const docMeta = getDocMetaForCountry(docCountry);

  const fromState = docMeta.map((meta) => {
    const source = docs[meta.key] && typeof docs[meta.key] === 'object' ? docs[meta.key] : {};
    const uploaded = source.uploaded === true;
    const status = toStatusLabel(source.status, uploaded);
    return {
      key: meta.key,
      label: meta.label,
      source: meta.source,
      uploaded,
      status,
      fileName: typeof source.fileName === 'string' ? source.fileName : ''
    };
  });

  const gpLinkPrepared = GP_LINK_DOCUMENT_META.map((meta) => {
    const source = preparedDocs[meta.key] && typeof preparedDocs[meta.key] === 'object' ? preparedDocs[meta.key] : {};
    const uploaded = source.ready === true || (typeof source.url === 'string' && source.url.trim().length > 0);
    const status = toStatusLabel(source.status, uploaded);
    return {
      key: meta.key,
      label: meta.label,
      source: meta.source,
      uploaded,
      status,
      fileName: typeof source.fileName === 'string' ? source.fileName : ''
    };
  });

  const items = [...fromState, ...gpLinkPrepared];
  const uploadedCount = items.filter((item) => item.uploaded).length;
  const pendingCount = items.filter((item) => !item.uploaded || item.status === 'under_review' || item.status === 'rejected' || item.status === 'pending').length;

  return {
    items,
    summary: {
      total: items.length,
      uploaded: uploadedCount,
      pending: pendingCount
    }
  };
}

function buildStepSubStatus(allKeys, completedMap, currentKey) {
  const doneSet = new Set(
    allKeys.filter((key) => completedMap && completedMap[key] === true)
  );
  return allKeys.map((key) => ({
    key,
    status: doneSet.has(key) ? 'done' : (key === currentKey ? 'current' : 'pending')
  }));
}

function buildCandidatePathway(userStateObj, documents) {
  const epic = userStateObj.gp_epic_progress && typeof userStateObj.gp_epic_progress === 'object'
    ? userStateObj.gp_epic_progress
    : {};
  const amc = userStateObj.gp_amc_progress && typeof userStateObj.gp_amc_progress === 'object'
    ? userStateObj.gp_amc_progress
    : {};
  const ahpra = userStateObj.gp_ahpra_progress && typeof userStateObj.gp_ahpra_progress === 'object'
    ? userStateObj.gp_ahpra_progress
    : {};

  const epicKeys = EPIC_STAGE_META.map((item) => item.key);
  const epicCurrent = epicKeys.includes(epic.stage)
    ? epic.stage
    : epicKeys.find((key) => !(epic.completed && epic.completed[key] === true)) || epicKeys[epicKeys.length - 1];
  const epicSubRaw = buildStepSubStatus(epicKeys, epic.completed || {}, epicCurrent);
  const epicDone = epicSubRaw.every((item) => item.status === 'done');

  const amcKeys = AMC_STAGE_META.map((item) => item.key);
  const amcCurrent = amcKeys.includes(amc.stage)
    ? amc.stage
    : amcKeys.find((key) => !(amc.completed && amc.completed[key] === true)) || amcKeys[amcKeys.length - 1];
  const amcSubRaw = buildStepSubStatus(amcKeys, amc.completed || {}, amcCurrent);
  const amcDone = amcSubRaw.every((item) => item.status === 'done');

  const ahpraSubRaw = [
    { key: 'stage_1', label: 'Stage 1: Account setup', done: !!(ahpra.stage_1 && ahpra.stage_1.completedAt) },
    { key: 'stage_2', label: 'Stage 2: Submission', done: !!(ahpra.stage_2 && ahpra.stage_2.completedAt) },
    { key: 'stage_3', label: 'Stage 3: Assessment', done: !!(ahpra.stage_3 && (ahpra.stage_3.completedAt || ahpra.stage_3.applicationOpenedAt)) },
    { key: 'stage_4', label: 'Stage 4: Outcome', done: !!(ahpra.stage_4 && ahpra.stage_4.completedAt) }
  ];
  const ahpraCurrentIdx = ahpraSubRaw.findIndex((item) => !item.done);
  const ahpraDone = ahpraCurrentIdx === -1;

  const preparedByYou = documents.items.filter((item) => item.source === 'prepared_by_you');
  const institutionDocs = documents.items.filter((item) => item.source === 'institution_docs');
  const gpLinkPack = documents.items.filter((item) => item.source === 'gplink_pack');
  const preparedDone = preparedByYou.length > 0 && preparedByYou.every((item) => item.uploaded);
  const institutionDone = institutionDocs.length > 0 && institutionDocs.every((item) => item.uploaded);
  const gpLinkDone = gpLinkPack.length > 0 && gpLinkPack.every((item) => item.uploaded);
  const docsDone = preparedDone && institutionDone && gpLinkDone;
  const docsCurrent = !preparedDone ? 'prepared_by_you' : (!institutionDone ? 'institution_docs' : (!gpLinkDone ? 'gplink_pack' : ''));

  return [
    {
      id: 'myintealth',
      label: 'MyIntealth Account',
      status: epicDone ? 'done' : 'current',
      substeps: epicSubRaw.map((item) => {
        const meta = EPIC_STAGE_META.find((entry) => entry.key === item.key);
        return { key: item.key, label: meta ? meta.label : item.key, status: item.status };
      })
    },
    {
      id: 'amc',
      label: 'AMC Portfolio',
      status: amcDone ? 'done' : (epicDone ? 'current' : 'pending'),
      substeps: amcSubRaw.map((item) => {
        const meta = AMC_STAGE_META.find((entry) => entry.key === item.key);
        const status = epicDone ? item.status : 'pending';
        return { key: item.key, label: meta ? meta.label : item.key, status };
      })
    },
    {
      id: 'documents',
      label: 'Documents',
      status: docsDone ? 'done' : (amcDone ? 'current' : 'pending'),
      substeps: [
        { key: 'prepared_by_you', label: 'Prepared by you', status: amcDone ? (preparedDone ? 'done' : (docsCurrent === 'prepared_by_you' ? 'current' : 'pending')) : 'pending' },
        { key: 'institution_docs', label: 'Institution documents', status: amcDone ? (institutionDone ? 'done' : (docsCurrent === 'institution_docs' ? 'current' : 'pending')) : 'pending' },
        { key: 'gplink_pack', label: 'GP Link prepared pack', status: amcDone ? (gpLinkDone ? 'done' : (docsCurrent === 'gplink_pack' ? 'current' : 'pending')) : 'pending' }
      ]
    },
    {
      id: 'ahpra',
      label: 'AHPRA Registration',
      status: ahpraDone ? 'done' : ((epicDone && amcDone) ? 'current' : 'pending'),
      substeps: ahpraSubRaw.map((item, idx) => ({
        key: item.key,
        label: item.label,
        status: (epicDone && amcDone)
          ? (item.done ? 'done' : (idx === ahpraCurrentIdx ? 'current' : 'pending'))
          : 'pending'
      }))
    }
  ];
}

function normalizeSupportCase(rawCase) {
  if (!rawCase || typeof rawCase !== 'object') return null;
  const createdAt = typeof rawCase.createdAt === 'string' ? rawCase.createdAt : new Date().toISOString();
  const updatedAt = typeof rawCase.updatedAt === 'string' ? rawCase.updatedAt : createdAt;
  const thread = Array.isArray(rawCase.thread) ? rawCase.thread : [];
  const latest = thread.length ? thread[thread.length - 1] : null;
  const lastMessage = latest && typeof latest.text === 'string' ? latest.text : '';
  const lastFrom = latest && (latest.from || latest.by) ? String(latest.from || latest.by) : '';
  const rawPriority = typeof rawCase.priority === 'string' ? rawCase.priority : 'normal';
  const priority = rawPriority === 'time_sensitive' ? 'urgent' : rawPriority === 'blocked' ? 'high' : 'normal';

  return {
    id: String(rawCase.id || `case_${Date.now()}`),
    title: typeof rawCase.title === 'string' && rawCase.title.trim() ? rawCase.title.trim() : 'Support request',
    category: typeof rawCase.category === 'string' ? rawCase.category : 'Other',
    status: rawCase.status === 'closed' ? 'closed' : 'open',
    priority,
    unread: !!rawCase.unread,
    createdAt,
    updatedAt,
    messagesCount: thread.length,
    lastMessage,
    lastFrom,
    thread
  };
}

function getSupportCasesFromState(userStateObj) {
  const directCases = Array.isArray(userStateObj.gpLinkSupportCases) ? userStateObj.gpLinkSupportCases : null;
  if (directCases && directCases.length) return directCases.map(normalizeSupportCase).filter(Boolean);

  const messageDb = userStateObj.gpLinkMessageDB && typeof userStateObj.gpLinkMessageDB === 'object'
    ? userStateObj.gpLinkMessageDB
    : null;
  const dbCases = messageDb && Array.isArray(messageDb.supportCases) ? messageDb.supportCases : [];
  return dbCases.map(normalizeSupportCase).filter(Boolean);
}

function getParsedUserState(rawState, updatedAt = null) {
  const source = rawState && typeof rawState === 'object' ? rawState : {};
  const out = {};
  for (const key of USER_STATE_KEYS) {
    if (hasOwn(source, key)) {
      out[key] = parseJsonLike(source[key]);
    }
  }
  out.updatedAt = updatedAt || source.updatedAt || null;
  return out;
}

function invalidateAdminDashboardCache() {
  adminDashboardCache.expiresAt = 0;
  adminDashboardCache.data = null;
}

// ══════ Registration Case & Task Automation ══════

function _parseStateVal(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch { return {}; } }
  return {};
}

function _deriveStageFromState(state) {
  const epic = _parseStateVal(state.gp_epic_progress);
  const amc = _parseStateVal(state.gp_amc_progress);
  const ahpra = _parseStateVal(state.gp_ahpra_progress);
  const career = _parseStateVal(state.gp_career_state);
  const ec = epic && epic.completed ? epic.completed : {};
  const ac = amc && amc.completed ? amc.completed : {};
  const hc = ahpra && ahpra.completed ? ahpra.completed : {};
  if (ec.verification_issued !== true) return 'myintealth';
  if (ac.qualifications_verified !== true) return 'amc';
  let careerSecured = career.career_secured === true || career.secured === true;
  if (!careerSecured && Array.isArray(career.applications)) {
    for (const a of career.applications) { if (a && a.isPlacementSecured === true) { careerSecured = true; break; } }
  }
  if (!careerSecured) return 'career';
  if (hc.verification_issued !== true) return 'ahpra';
  return 'visa';
}

function _deriveSubstageFromState(state, stage) {
  if (stage === 'myintealth') {
    const epic = _parseStateVal(state.gp_epic_progress);
    return (epic && epic.stage) || 'create_account';
  }
  if (stage === 'amc') {
    const amc = _parseStateVal(state.gp_amc_progress);
    return (amc && amc.stage) || 'create_portfolio';
  }
  if (stage === 'ahpra') {
    const ahpra = _parseStateVal(state.gp_ahpra_progress);
    return (ahpra && ahpra.stage) || 'create_account';
  }
  return null;
}

// ── Admin/VA user detection (cached) ──
// Returns a Set of user_ids that are admin/VA (not GPs). Cached for 2 minutes.
var _adminUserIdsCache = { set: null, expiresAt: 0 };
async function getAdminUserIdSet() {
  var now = Date.now();
  if (_adminUserIdsCache.set && _adminUserIdsCache.expiresAt > now) {
    return _adminUserIdsCache.set;
  }
  var ids = new Set();
  if (isSupabaseDbConfigured()) {
    var rolesRes = await supabaseDbRequest('user_roles', 'select=user_id&role=in.(admin,super_admin)');
    if (rolesRes.ok && Array.isArray(rolesRes.data)) {
      for (var ri = 0; ri < rolesRes.data.length; ri++) {
        if (rolesRes.data[ri] && rolesRes.data[ri].user_id) ids.add(rolesRes.data[ri].user_id);
      }
    }
    // Also match by email against env-based admin + VA lists
    var allExcludeEmails = new Set([...ADMIN_EMAILS, ...SUPER_ADMIN_EMAILS]);
    for (var vi = 0; vi < MONITORED_VA_EMAILS.length; vi++) {
      allExcludeEmails.add(MONITORED_VA_EMAILS[vi]);
    }
    if (allExcludeEmails.size > 0) {
      var profileRes = await supabaseDbRequest('user_profiles', 'select=user_id,email');
      if (profileRes.ok && Array.isArray(profileRes.data)) {
        for (var pi = 0; pi < profileRes.data.length; pi++) {
          var pe = String(profileRes.data[pi].email || '').trim().toLowerCase();
          if (allExcludeEmails.has(pe)) ids.add(profileRes.data[pi].user_id);
        }
      }
    }
  }
  _adminUserIdsCache.set = ids;
  _adminUserIdsCache.expiresAt = now + 120000;
  return ids;
}

function invalidateAdminUserIdCache() {
  _adminUserIdsCache.set = null;
  _adminUserIdsCache.expiresAt = 0;
}

async function isAdminOrVAUser(userId) {
  var ids = await getAdminUserIdSet();
  return ids.has(userId);
}

// Launch handoff: for the first GP rollout the owner personally handles all
// document-checking and support (to catch bugs), so a brand-new registration
// case is assigned to the "GP Link Admin" mailbox (hello@) rather than left
// unassigned (which would default GP-facing RSO / calls / doc-check routing to
// Hazel). Overridable via env WITHOUT a deploy: set LAUNCH_DEFAULT_RSO_EMAIL to
// hazel@mygplink.com.au to hand new GPs to Hazel, or to 'none' to restore the
// pre-launch behaviour of leaving new cases unassigned. Pure so it's unit-tested.
function pickDefaultCaseRsoUserId(rosterRows, rawEmail) {
  var raw = String(rawEmail == null ? GP_OWNER_EMAIL : rawEmail).trim().toLowerCase();
  if (!raw || raw === 'none' || raw === 'unassigned' || raw === 'off') return null;
  var rows = Array.isArray(rosterRows) ? rosterRows : [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (r && r.email && String(r.email).trim().toLowerCase() === raw) return r.user_id || null;
  }
  return null;
}
async function resolveDefaultCaseRsoUserId() {
  try {
    var roster = await loadRsoTeam({ includeInactive: true });
    var id = pickDefaultCaseRsoUserId(roster, process.env.LAUNCH_DEFAULT_RSO_EMAIL);
    if (!id && String(process.env.LAUNCH_DEFAULT_RSO_EMAIL || '').trim() &&
        !/^(none|unassigned|off)$/i.test(String(process.env.LAUNCH_DEFAULT_RSO_EMAIL).trim())) {
      console.warn('[RegCase] LAUNCH_DEFAULT_RSO_EMAIL not found in rso_team — new case left unassigned');
    }
    return id;
  } catch (e) { return null; }
}

async function _ensureRegCase(userId) {
  if (!isSupabaseDbConfigured()) return null;
  // Admin/VA accounts are staff, not GPs — never create or surface a GP registration case for them.
  if (await isAdminOrVAUser(userId)) return null;
  const q = await supabaseDbRequest('registration_cases', 'select=*&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  if (q.ok && Array.isArray(q.data) && q.data.length > 0) return q.data[0];
  const _defaultRso = await resolveDefaultCaseRsoUserId();
  const _caseBody = { user_id: userId, stage: 'myintealth', status: 'active' };
  if (_defaultRso) { _caseBody.assigned_va = _defaultRso; _caseBody.assigned_rso = _defaultRso; }
  const ins = await supabaseDbRequest('registration_cases', '', {
    method: 'POST', headers: { Prefer: 'return=representation' },
    body: [_caseBody]
  });
  const newCase = ins.ok && Array.isArray(ins.data) && ins.data.length > 0 ? ins.data[0] : null;
  // Eagerly create the GP's Google Drive folder at registration so it always exists from day one.
  if (newCase && newCase.id && isGoogleDriveConfigured()) {
    try {
      const _rcProfRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
      const _rcProf = (_rcProfRes.ok && Array.isArray(_rcProfRes.data) && _rcProfRes.data[0]) ? _rcProfRes.data[0] : {};
      const _rcFolderId = await ensureGPDriveFolder(newCase.id, _rcProf.first_name || '', _rcProf.last_name || '');
      if (_rcFolderId) newCase.google_drive_folder_id = _rcFolderId;
    } catch (_rcErr) { console.error('[RegCase] Drive folder create failed (non-fatal):', _rcErr.message); }
  }
  return newCase;
}

// Auto-assign due_date based on task type when not explicitly set
function _autoAssignDueDate(payload) {
  if (payload.due_date) return; // already set explicitly
  var now = new Date();
  var type = payload.task_type || '';
  // Support / help tasks: 24h SLA
  if (type === 'whatsapp_help' || type === 'email_triage' || type === 'blocker' || type === 'qualification_help' || type === 'nudge_reply') {
    payload.due_date = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
    return;
  }
  // Practice pack tasks: 4-week SLA
  if (type === 'practice_pack_child') {
    payload.due_date = new Date(now.getTime() + 28 * 24 * 60 * 60 * 1000).toISOString();
    return;
  }
}

async function _createRegTask(caseId, data) {
  if (!isSupabaseDbConfigured()) return null;
  const actor = data._actor || 'system';
  const payload = { case_id: caseId };
  for (const [k, v] of Object.entries(data)) { if (k !== '_actor') payload[k] = v; }
  _autoAssignDueDate(payload);
  const r = await supabaseDbRequest('registration_tasks', '', {
    method: 'POST', headers: { Prefer: 'return=representation' }, body: [payload]
  });
  const task = r.ok && Array.isArray(r.data) && r.data.length > 0 ? r.data[0] : null;
  if (task) {
    await supabaseDbRequest('task_timeline', '', {
      method: 'POST', body: [{ task_id: task.id, case_id: caseId, event_type: 'created', title: 'Task created', detail: task.title, actor: actor }]
    });
    return task;
  }
  // createDocReviewTask/createFlaggedDocTask dedupe with a read-then-insert
  // SELECT, which can race under serverless burst load (observed in prod:
  // three identical open doc_review tasks created ~18 minutes apart by
  // concurrent upload pipelines whose dedupe SELECTs and task_timeline writes
  // silently failed). supabase/migrations/20260713100000_unique_open_doc_review_tasks.sql
  // makes the duplicate insert impossible at the DB level (23505 -> PostgREST
  // 409) for the two document-check task types. Degrade gracefully here:
  // find the task the index says already exists, reopen it, and hand it back
  // instead of losing the upload's review entirely.
  // Accepted edge: this branch runs for EVERY caller of _createRegTask, so
  // manual creators (e.g. POST /api/admin/tasks with a guarded task_type +
  // document key) also get idempotent reuse instead of a second task. That is
  // deliberate — two open review tasks for the same document are never
  // wanted, however they're created.
  const guardedType = payload.task_type === 'doc_review' || payload.task_type === 'flagged_doc';
  if (r.status === 409 && payload.related_document_key && guardedType) {
    const existingRes = await supabaseDbRequest('registration_tasks',
      'select=*&case_id=eq.' + encodeURIComponent(caseId) +
      '&task_type=eq.' + encodeURIComponent(payload.task_type) +
      '&related_document_key=eq.' + encodeURIComponent(payload.related_document_key) +
      '&status=in.(open,in_progress,waiting)&limit=1');
    const existing = existingRes.ok && Array.isArray(existingRes.data) && existingRes.data[0] ? existingRes.data[0] : null;
    if (existing) {
      const nowIso = new Date().toISOString();
      await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(existing.id), {
        method: 'PATCH', body: { status: 'open', updated_at: nowIso }
      });
      existing.status = 'open';
      existing.updated_at = nowIso;
      await supabaseDbRequest('task_timeline', '', {
        method: 'POST', body: [{ task_id: existing.id, case_id: caseId, event_type: 'system', title: 'Duplicate task creation blocked — existing task reused', detail: payload.title, actor: actor }]
      });
      return existing;
    }
  }
  return null;
}

// ── Support ticket identity + grouping helpers ─────────────────────────────
// Label shown in the Support list's GP column when the sender is NOT a GP
// registered in the app. Known GPs (matched by phone or email) show their name.
const EXTERNAL_SUPPORT_LABEL = 'EXTERNAL (Not on App)';
// Sliding-window size for grouping same-person, same-channel support messages
// into a single ticket. Each new message bumps the ticket's updated_at, so an
// ongoing conversation stays one ticket until there is a full 24h of silence.
const SUPPORT_GROUP_WINDOW_MS = 24 * 60 * 60 * 1000;

// Extract a bare lower-cased email address from a "Name <addr@x>" sender string.
function extractEmailAddress(sender) {
  const m = String(sender || '').match(/[\w.+-]+@[\w.-]+\.\w+/);
  return m ? m[0].toLowerCase() : '';
}

// Look up a user_profile by phone: exact match across common AU/int'l formats,
// then a fuzzy last-9-digit suffix match. Returns the profile row or null.
// (Extracted from the DoubleTick webhook's inline matcher so display + ingestion
// resolve identity the same way.)
async function findUserProfileByPhone(phone) {
  if (!phone || !isSupabaseDbConfigured()) return null;
  const normalizedPhone = normalizePhone(phone);
  const localPhone = normalizedPhone.startsWith('+61') ? '0' + normalizedPhone.slice(3) : null;
  const phoneDigits = String(phone).replace(/[^0-9]/g, '');
  const bareNumber = phoneDigits.length > 9 ? phoneDigits.slice(-9) : phoneDigits;
  const sel = 'select=user_id,first_name,last_name,email,phone_number,phone';
  for (const pv of [...new Set([normalizedPhone, phone, localPhone, bareNumber, '0' + bareNumber].filter(Boolean))]) {
    for (const col of ['phone_number', 'phone']) {
      const r = await supabaseDbRequest('user_profiles', sel + '&' + col + '=eq.' + encodeURIComponent(pv) + '&limit=1');
      if (r.ok && Array.isArray(r.data) && r.data.length > 0) return r.data[0];
    }
  }
  if (phoneDigits.length >= 9) {
    const suffix = phoneDigits.slice(-9);
    const r = await supabaseDbRequest('user_profiles', sel + '&or=(phone.ilike.*' + suffix + ',phone_number.ilike.*' + suffix + ')&limit=1');
    if (r.ok && Array.isArray(r.data) && r.data.length > 0) return r.data[0];
  }
  return null;
}

// Look up a user_profile by email (case-insensitive, EXACT). Returns the profile
// or null. The `_` in an address is a LIKE single-char wildcard, so we verify the
// returned rows' address matches exactly in JS rather than trusting the ilike.
async function findUserProfileByEmail(email) {
  const addr = extractEmailAddress(email);
  if (!addr || !isSupabaseDbConfigured()) return null;
  const r = await supabaseDbRequest('user_profiles', 'select=user_id,first_name,last_name,email,phone_number,phone&email=ilike.' + encodeURIComponent(addr) + '&limit=10');
  if (r.ok && Array.isArray(r.data)) {
    const exact = r.data.find(p => String(p.email || '').toLowerCase() === addr);
    if (exact) return exact;
  }
  return null;
}

// Pull a phone number out of a support item: the registered GP's profile phone,
// else the "Name (+phone)" prefix stored in an unregistered WhatsApp task's body.
function phoneFromSupportItem(item, profile) {
  const p = profile || {};
  const profPhone = p.phone || p.phone_number || '';
  if (profPhone) return profPhone;
  const m = String((item && item.body) || '').match(/\((\+?\d[\d\s\-]+)\)/);
  return m ? m[1].trim() : '';
}

// Display name for a support ticket's GP column. A known in-app GP → their full
// name. Never "Unknown": when there is no name we either fall back to the email
// (in-app tickets, whose sender is always a registered user) or clearly mark the
// sender EXTERNAL (Not on App). Returns { name, isExternal }.
function supportDisplayName(profile, opts) {
  const p = profile || {};
  const knownName = [(p.first_name || ''), (p.last_name || '')].join(' ').trim();
  if (knownName) return { name: knownName, isExternal: false };
  if (opts && opts.allowEmailFallback && p.email) return { name: p.email, isExternal: false };
  return { name: EXTERNAL_SUPPORT_LABEL, isExternal: true };
}

// Sliding-window test for grouping: is an existing same-person, same-channel
// ticket recent enough to fold a new message into it? Epoch-ms inputs.
function isWithinGroupingWindow(updatedAtMs, nowMs, windowMs) {
  if (!updatedAtMs || !nowMs) return false;
  return (nowMs - updatedAtMs) <= (windowMs || SUPPORT_GROUP_WINDOW_MS);
}

// Contact name carried on a WhatsApp support item (the DoubleTick contact name),
// stored as the "<name> (phone)" prefix of an unregistered task's description,
// or in the "WhatsApp enquiry from <name>" title.
function contactNameFromSupportItem(item) {
  const body = String((item && item.body) || '');
  const m = body.match(/^([^\n(]+?)\s*\(\+?\d/);
  if (m && m[1].trim()) return m[1].trim();
  const title = String((item && item.title) || '');
  const tm = title.match(/enquiry from\s+(.+)$/i);
  return tm ? tm[1].trim() : '';
}

// Match a free-text full name to a known GP profile. Returns a profile ONLY when
// EXACTLY ONE GP has that first + last (case-insensitive). An absent or ambiguous
// match returns null, so a name is never pinned onto the wrong person. Used as a
// last-resort fallback for a known GP who messaged from an unregistered number.
async function findUserProfileByFullName(fullName) {
  const name = String(fullName || '').trim();
  if (!name || !isSupabaseDbConfigured()) return null;
  const parts = name.split(/\s+/);
  if (parts.length < 2) return null;
  const first = parts[0];
  const last = parts.slice(1).join(' ');
  const r = await supabaseDbRequest('user_profiles',
    'select=user_id,first_name,last_name,email,phone_number,phone&first_name=ilike.' +
    encodeURIComponent(first) + '&last_name=ilike.' + encodeURIComponent(last) + '&limit=2');
  if (r.ok && Array.isArray(r.data) && r.data.length === 1) return r.data[0];
  return null;
}

// ─────────────────────────────────────────────────────────────
// Account deletion / reinstatement (soft-delete → reinstate → purge)
// ─────────────────────────────────────────────────────────────
const ACCOUNT_ARCHIVE_GRACE_MS = 90 * 24 * 60 * 60 * 1000; // 90 days

// Short-lived signed token that authorizes reinstating a specific archived account.
function createReinstateToken(email, supabaseUserId) {
  const expiresAt = now() + 15 * 60 * 1000; // 15 minutes
  const payload = base64UrlEncode(JSON.stringify({
    reinstate: true,
    email: String(email || '').trim().toLowerCase(),
    supabaseUserId: String(supabaseUserId || '').trim(),
    expiresAt
  }));
  return `${payload}.${hmacSign(payload)}`;
}

function parseReinstateToken(token) {
  const raw = String(token || '');
  const dotIdx = raw.lastIndexOf('.');
  if (dotIdx <= 0) return null;
  const payload = raw.slice(0, dotIdx);
  const signature = raw.slice(dotIdx + 1);
  const expected = hmacSign(payload);
  if (signature.length !== expected.length ||
      !crypto.timingSafeEqual(Buffer.from(signature, 'utf8'), Buffer.from(expected, 'utf8'))) {
    return null;
  }
  try {
    const parsed = JSON.parse(base64UrlDecode(payload));
    if (!parsed || parsed.reinstate !== true) return null;
    if (typeof parsed.expiresAt !== 'number' || parsed.expiresAt <= now()) return null;
    return { email: String(parsed.email || ''), supabaseUserId: String(parsed.supabaseUserId || '') };
  } catch (e) {
    return null;
  }
}

// Look up archive status by user_id (preferred) or email. Returns the profile row or null.
async function getAccountArchiveStatus(opts) {
  if (!isSupabaseDbConfigured()) return null;
  const sel = 'select=user_id,email,first_name,last_name,account_status,archived_at,purge_after';
  let q;
  if (opts && opts.userId) q = sel + '&user_id=eq.' + encodeURIComponent(opts.userId) + '&limit=1';
  else if (opts && opts.email) q = sel + '&email=eq.' + encodeURIComponent(String(opts.email).trim().toLowerCase()) + '&limit=1';
  else return null;
  const r = await supabaseDbRequest('user_profiles', q);
  return r.ok && Array.isArray(r.data) && r.data[0] ? r.data[0] : null;
}

async function resolveCeoUserId() {
  if (!CEO_EMAIL || !isSupabaseDbConfigured()) return null;
  const r = await supabaseDbRequest('user_profiles', 'select=user_id&email=eq.' + encodeURIComponent(CEO_EMAIL) + '&limit=1');
  return r.ok && Array.isArray(r.data) && r.data[0] ? r.data[0].user_id : null;
}

// A doctor "has an active placement" when a gp_applications row is marked hired.
async function userHasActivePlacement(userId) {
  if (!isSupabaseDbConfigured() || !userId) return false;
  const r = await supabaseDbRequest('gp_applications', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&status=eq.hired&limit=1');
  return r.ok && Array.isArray(r.data) && r.data.length > 0;
}

async function archiveUserAccount(userId, reason) {
  const purgeAfter = new Date(now() + ACCOUNT_ARCHIVE_GRACE_MS).toISOString();
  await supabaseDbRequest('user_profiles', 'user_id=eq.' + encodeURIComponent(userId), {
    method: 'PATCH',
    body: {
      account_status: 'archived',
      archived_at: new Date().toISOString(),
      purge_after: purgeAfter,
      archived_reason: reason || 'user_requested',
      updated_at: new Date().toISOString()
    }
  });
  try {
    const _arcCase = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    if (_arcCase.ok && _arcCase.data && _arcCase.data[0]) await reconcileGpDrive(_arcCase.data[0].id);
  } catch (e) { console.error('[archive] drive reconcile failed:', e.message); }
  return purgeAfter;
}

async function reinstateUserAccount(userId) {
  await supabaseDbRequest('user_profiles', 'user_id=eq.' + encodeURIComponent(userId), {
    method: 'PATCH',
    body: {
      account_status: 'active',
      archived_at: null,
      purge_after: null,
      archived_reason: null,
      updated_at: new Date().toISOString()
    }
  });
  // Resolve any open "account deleted with active placement" CEO task.
  try {
    const caseRes = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
    if (gpCase) {
      const taskRes = await supabaseDbRequest('registration_tasks',
        'select=id&case_id=eq.' + encodeURIComponent(gpCase.id) +
        '&task_type=eq.account_deleted_active_placement&status=in.(open,in_progress,waiting,escalated,deferred,blocked)');
      if (taskRes.ok && Array.isArray(taskRes.data)) {
        for (const t of taskRes.data) { await _completeRegTask(t.id, gpCase.id, 'system'); }
      }
    }
  } catch (e) { console.error('[reinstate] task resolve failed:', e && e.message); }
  try {
    const _reCase = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    if (_reCase.ok && _reCase.data && _reCase.data[0]) await reconcileGpDrive(_reCase.data[0].id);
  } catch (e) { console.error('[reinstate] drive reconcile failed:', e.message); }
}

// When an active-placement doctor deletes, raise an urgent CEO task to find out why.
async function createAccountDeletionCeoTask(userId, email) {
  try {
    const caseRes = await supabaseDbRequest('registration_cases', 'select=id,practice_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
    if (!gpCase) return null;
    const profRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const prof = profRes.ok && Array.isArray(profRes.data) && profRes.data[0] ? profRes.data[0] : {};
    const name = [prof.first_name || '', prof.last_name || ''].join(' ').trim() || email;
    const practice = gpCase.practice_name ? (' at ' + gpCase.practice_name) : '';
    const ceoId = await resolveCeoUserId();
    const data = {
      task_type: 'account_deleted_active_placement',
      title: 'Account deleted with active placement — find out why',
      description: name + ' (' + email + ') deleted their GP Link account while holding an active placement' + practice +
        '. Reach out to understand the reason and whether to reinstate (their account is archived and recoverable for 90 days).',
      priority: 'urgent',
      status: 'escalated',
      escalated_reason: 'GP deleted account while holding an active placement',
      escalated_at: new Date().toISOString(),
      related_stage: 'career',
      _actor: 'system'
    };
    if (ceoId && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(ceoId)) {
      data.escalated_to = ceoId;
    }
    return await _createRegTask(gpCase.id, data);
  } catch (e) {
    console.error('[delete] CEO task creation failed:', e && e.message);
    return null;
  }
}

// Hard-delete the Supabase auth user (cascades user_profiles + user_state via FK on delete cascade).
async function supabaseAuthAdminDeleteUser(userId) {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY || !userId) return false;
  // Raw fetch — bypasses both transports above, so invalidate explicitly.
  invalidateSupabaseUserIdCache();
  const resp = await fetch(`${SUPABASE_URL}/auth/v1/admin/users/${encodeURIComponent(userId)}`, {
    method: 'DELETE',
    headers: {
      apikey: SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`
    }
  });
  return resp.ok;
}

function inferStageFromDocKey(docKey) {
  // The review stage for a document depends on WHERE it was uploaded (the onboarding
  // wizard vs the later "prepare my documents" page), which the upload entry point
  // passes explicitly as `reviewStage` into createDocReviewTask / createFlaggedDocTask:
  // genuine onboarding-wizard uploads pass 'onboarding'. This key-only inference is
  // just the fallback when no explicit stage is supplied. RULE: a document uploaded
  // during onboarding is filed under 'onboarding' (set explicitly by that upload path);
  // every OTHER reviewable document belongs to the AHPRA document set (certified
  // qualification copies, the signed CV, IE/NZ confirmation letters, criminal history),
  // so the default here is 'ahpra' — NOT 'career'. The only genuine career-lane documents
  // that reach this fallback are the CV and (optional) cover letter the GP uploads on the
  // Career page (career_cv / career_cover_letter) — those stay in 'career'.
  const docToStage = {
    'sppa_00': 'ahpra', 'section_g': 'ahpra', 'position_description': 'ahpra',
    'offer_contract': 'ahpra', 'supervisor_cv': 'ahpra',
    'career_cv': 'career', 'career_cover_letter': 'career'
  };
  if (isQualificationDocKey(docKey)) return 'ahpra';
  return docToStage[docKey] || 'ahpra';
}

async function _completeRegTask(taskId, caseId, actor) {
  if (!isSupabaseDbConfigured()) return;
  await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(taskId), {
    method: 'PATCH', body: { status: 'completed', completed_at: new Date().toISOString(), completed_by: actor || 'system' }
  });
  await supabaseDbRequest('task_timeline', '', {
    method: 'POST', body: [{ task_id: taskId, case_id: caseId, event_type: 'completed', title: 'Task completed', actor: actor || 'system' }]
  });
  // If this completes an SPPA-00 prerequisite (supervisor_cv / offer_contract), (re)check whether to
  // run the AI conflict scan that unlocks the deferred SPPA-00 task. Covers every completion path
  // that goes through this helper. Fire-and-forget + idempotent so it never delays/blocks completion.
  try {
    var _ct = await supabaseDbRequest('registration_tasks', 'select=related_document_key&id=eq.' + encodeURIComponent(taskId) + '&limit=1');
    var _ctDk = (_ct.ok && Array.isArray(_ct.data) && _ct.data[0]) ? _ct.data[0].related_document_key : null;
    if (_ctDk === 'supervisor_cv' || _ctDk === 'offer_contract') {
      var _ctCase = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
      var _ctUid = (_ctCase.ok && Array.isArray(_ctCase.data) && _ctCase.data[0]) ? _ctCase.data[0].user_id : null;
      _maybeRunSppaConflictScan(caseId, _ctUid).catch(function (e) { console.error('[SPPA-00] completeRegTask trigger error:', e.message); });
    }
  } catch (e) { console.error('[SPPA-00] completeRegTask trigger lookup error:', e.message); }
}

async function _logCaseEvent(caseId, taskId, eventType, title, detail, actor, metadata) {
  if (!isSupabaseDbConfigured()) return;
  var entry = { case_id: caseId, task_id: taskId || null, event_type: eventType, title: title, detail: detail || null, actor: actor || 'system' };
  if (metadata) entry.metadata = metadata;
  await supabaseDbRequest('task_timeline', '', {
    method: 'POST', body: [entry]
  });
}

// Idempotency wrapper: dedupes concurrent triggers (e.g. supervisor_cv and offer_contract
// completing near-simultaneously, or the same completion firing the scan from more than one path)
// so the AI conflict scan runs at most once per case at a time. The inner function also guards on
// metadata.conflict_scan_completed for cross-request idempotency.
var _sppaScanInflight = {};
async function _maybeRunSppaConflictScan(caseId, userId) {
  if (!caseId) return;
  if (_sppaScanInflight[caseId]) { try { await _sppaScanInflight[caseId]; } catch (e) {} return; }
  var run = _runSppaConflictScanInner(caseId, userId);
  _sppaScanInflight[caseId] = run;
  try { await run; } catch (e) { console.error('[SPPA-00] scan wrapper error:', e.message); }
  finally { delete _sppaScanInflight[caseId]; }
}

/**
 * Check if both supervisor_cv and offer_contract are complete for a case,
 * then fire the AI conflict scan and fill Q7 on the SPPA-00 PDF.
 */
async function _runSppaConflictScanInner(caseId, userId) {
  try {
    // 1. Check both prerequisite tasks are complete
    var siblingRes = await supabaseDbRequest('registration_tasks',
      'select=id,related_document_key,status&case_id=eq.' + encodeURIComponent(caseId) +
      '&related_document_key=in.(supervisor_cv,offer_contract)&task_type=eq.practice_pack_child');
    if (!siblingRes.ok || !Array.isArray(siblingRes.data)) return;
    var tasks = siblingRes.data;
    var svDone = tasks.some(function (t) { return t.related_document_key === 'supervisor_cv' && t.status === 'completed'; });
    var ocDone = tasks.some(function (t) { return t.related_document_key === 'offer_contract' && t.status === 'completed'; });
    if (!svDone || !ocDone) return;

    // 2. Find the SPPA-00 task
    var sppaRes = await supabaseDbRequest('registration_tasks',
      'select=id,status,metadata&case_id=eq.' + encodeURIComponent(caseId) +
      '&related_document_key=eq.sppa_00&task_type=eq.practice_pack_child&limit=1');
    if (!sppaRes.ok || !sppaRes.data || !sppaRes.data[0]) return;
    var sppaTask = sppaRes.data[0];

    // Skip if already scanned (idempotency)
    var existingMeta = sppaTask.metadata;
    if (typeof existingMeta === 'string') try { existingMeta = JSON.parse(existingMeta); } catch (e) { existingMeta = {}; }
    if (existingMeta && existingMeta.conflict_scan_completed) return;

    console.log('[SPPA-00] Both supervisor_cv + offer_contract complete for case ' + caseId + ' — running conflict scan');

    // 3. Gather document buffers
    function decodeDataUrl(dataUrl) {
      var commaIdx = dataUrl.indexOf(',');
      var mimeMatch = dataUrl.substring(0, commaIdx).match(/data:([^;]+)/);
      var mime = mimeMatch ? mimeMatch[1] : 'application/octet-stream';
      var b64 = dataUrl.substring(commaIdx + 1).replace(/-/g, '+').replace(/_/g, '/');
      while (b64.length % 4 !== 0) b64 += '=';
      return { buffer: Buffer.from(b64, 'base64'), mimeType: mime };
    }

    // 3a. Supervisor CV
    var svTask = tasks.find(function (t) { return t.related_document_key === 'supervisor_cv'; });
    var svDocRes = await supabaseDbRequest('task_documents',
      'select=attachment_url,mime_type&task_id=eq.' + encodeURIComponent(svTask.id) + '&is_current=eq.true&limit=1');
    var svDoc = svDocRes.ok && svDocRes.data && svDocRes.data[0] ? svDocRes.data[0] : null;

    // 3b. Offer/Contract
    var ocTask = tasks.find(function (t) { return t.related_document_key === 'offer_contract'; });
    var ocDocRes = await supabaseDbRequest('task_documents',
      'select=attachment_url,mime_type&task_id=eq.' + encodeURIComponent(ocTask.id) + '&is_current=eq.true&limit=1');
    var ocDoc = ocDocRes.ok && ocDocRes.data && ocDocRes.data[0] ? ocDocRes.data[0] : null;

    if (!svDoc || !svDoc.attachment_url || !ocDoc || !ocDoc.attachment_url) {
      console.error('[SPPA-00] Missing document attachments for conflict scan');
      return;
    }

    var svDecoded = decodeDataUrl(svDoc.attachment_url);
    var ocDecoded = decodeDataUrl(ocDoc.attachment_url);

    // 3c. MRCGP certificate from user_documents via Supabase storage
    var mrcgpBuffer = null;
    var mrcgpMime = null;
    try {
      var mrcgpDocRes = await supabaseDbRequest('user_documents',
        'select=storage_path,file_url,mime_type&user_id=eq.' + encodeURIComponent(userId) +
        '&document_key=eq.mrcgp_certified&limit=1');
      var mrcgpDoc = mrcgpDocRes.ok && mrcgpDocRes.data && mrcgpDocRes.data[0] ? mrcgpDocRes.data[0] : null;
      if (mrcgpDoc) {
        var storagePath = mrcgpDoc.storage_path || mrcgpDoc.file_url || '';
        if (storagePath) {
          var downloaded = await supabaseStorageDownloadObject(SUPABASE_DOCUMENT_BUCKET, storagePath);
          if (downloaded && downloaded.buffer) {
            mrcgpBuffer = downloaded.buffer;
            mrcgpMime = downloaded.mimeType || mrcgpDoc.mime_type || 'application/pdf';
          }
        }
      }
    } catch (mrcgpErr) {
      console.error('[SPPA-00] MRCGP cert fetch error (non-fatal):', mrcgpErr.message);
    }

    // 3d. Candidate profile name
    var profRes = await supabaseDbRequest('user_profiles',
      'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    var prof = (profRes.ok && profRes.data && profRes.data[0]) ? profRes.data[0] : {};
    var candidateName = ((prof.first_name || '') + ' ' + (prof.last_name || '')).trim();

    // 4. Run AI conflict scan
    var scanResult = await scanForConflict({
      supervisorCvBuffer: svDecoded.buffer,
      supervisorCvMime: svDecoded.mimeType,
      contractBuffer: ocDecoded.buffer,
      contractMime: ocDecoded.mimeType,
      mrcgpBuffer: mrcgpBuffer,
      mrcgpMime: mrcgpMime,
      candidateName: candidateName
    });

    console.log('[SPPA-00] Conflict scan result:', JSON.stringify({
      is_conflict: scanResult.is_conflict,
      confidence: scanResult.confidence,
      supervisor: scanResult.supervisor_name,
      owner: scanResult.practice_owner_name,
      _error: scanResult._error || null
    }));

    // 5. Fill SPPA-00 PDF with Q7
    var filledPdfBuffer = await fillSppaQ7({ isConflict: scanResult.is_conflict });

    // 6. Store the filled PDF as a task_document on the SPPA-00 task
    var pdfDataUrl = 'data:application/pdf;base64,' + filledPdfBuffer.toString('base64');
    await supabaseDbRequest('task_documents', '', {
      method: 'POST',
      body: [{
        task_id: sppaTask.id,
        case_id: caseId,
        filename: 'SPPA-00.pdf',
        mime_type: 'application/pdf',
        size_bytes: filledPdfBuffer.length,
        version: 1,
        is_current: true,
        uploaded_by: 'system_conflict_scan',
        attachment_url: pdfDataUrl
      }]
    });

    // 7. Update the SPPA-00 task — unlock it + store scan metadata
    var meta = {
      conflict_scan_completed: true,
      conflict_scan_at: new Date().toISOString(),
      is_conflict: scanResult.is_conflict,
      confidence: scanResult.confidence,
      supervisor_name: scanResult.supervisor_name,
      practice_owner_name: scanResult.practice_owner_name,
      candidate_name: scanResult.candidate_name,
      reasoning: scanResult.reasoning,
      sppa_state: 'ready_to_send'
    };
    await supabaseDbRequest('registration_tasks',
      'id=eq.' + encodeURIComponent(sppaTask.id),
      { method: 'PATCH', body: { status: 'in_progress', metadata: meta, updated_at: new Date().toISOString() } });

    // 8. Update practice_doc_ops to under_review
    try {
      await _ensurePracticeDocOps(caseId);
      await supabaseDbRequest('practice_doc_ops', 'case_id=eq.' + encodeURIComponent(caseId) + '&document_key=eq.sppa_00',
        { method: 'PATCH', body: { ops_status: 'under_review' } });
    } catch (e) {}

    // 9. Log timeline event
    await _logCaseEvent(caseId, sppaTask.id, 'system',
      'AI conflict scan complete — Q7 marked ' + (scanResult.is_conflict ? 'YES' : 'NO'),
      scanResult.reasoning,
      'system',
      { is_conflict: scanResult.is_conflict, confidence: scanResult.confidence });

    // Trigger B (scan): officer already assigned when scan completes (rare but possible) → wire for completeness.
    if (scanResult.is_conflict) {
      var _cflScanCase = await supabaseDbRequest('registration_cases',
        'select=ahpra_officer_email,ahpra_officer_name&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
      var _cflScanRow = (_cflScanCase.ok && _cflScanCase.data && _cflScanCase.data[0]) ? _cflScanCase.data[0] : {};
      if (_cflScanRow.ahpra_officer_email) {
        _ensureAhpraConflictLetter(caseId, { officerEmail: _cflScanRow.ahpra_officer_email, officerName: _cflScanRow.ahpra_officer_name || '' }).catch(function(e) { console.error('[ahpra-conflict-letter] trigger B scan:', e.message); });
      }
    }

  } catch (err) {
    console.error('[SPPA-00] Conflict scan orchestrator error:', err.message);
  }
}

// ── GP-section completeness scan: run when the candidate returns the SPPA-00 ──
// Confirms the candidate completed Section A Q1 (personal details) and signed
// Section I (Supervisee's declaration); stores a plain-English result on the
// task metadata so the admin sees it on the SPPA card. Fail-open: never throws,
// never blocks the flow.
var _sppaSectionScanInflight = {};

async function _maybeRunGpSectionScan(taskId, opts) {
  if (!taskId) return null;
  if (_sppaSectionScanInflight[taskId]) { try { return await _sppaSectionScanInflight[taskId]; } catch (e) { return null; } }
  var run = _runGpSectionScanInner(taskId, opts || {});
  _sppaSectionScanInflight[taskId] = run;
  try { return await run; }
  catch (e) { console.error('[SPPA-00] GP section scan wrapper error:', e.message); return null; }
  finally { delete _sppaSectionScanInflight[taskId]; }
}

async function _runGpSectionScanInner(taskId, opts) {
  opts = opts || {};
  try {
    var taskRes = await supabaseDbRequest('registration_tasks',
      'select=id,case_id,metadata,related_document_key&id=eq.' + encodeURIComponent(taskId) + '&limit=1');
    if (!taskRes.ok || !taskRes.data || !taskRes.data[0]) return null;
    var task = taskRes.data[0];
    if (task.related_document_key !== 'sppa_00') return null;
    var meta = task.metadata;
    if (typeof meta === 'string') try { meta = JSON.parse(meta); } catch (e) { meta = {}; }
    meta = meta || {};

    // Idempotency: skip if already scanned, unless a re-scan is forced.
    if (!opts.force && meta.gp_section_scan_completed) return meta.gp_section_scan || null;

    // Find the candidate-returned document (current version on the task).
    var docRes = await supabaseDbRequest('task_documents',
      'select=attachment_url,mime_type,filename,uploaded_by&task_id=eq.' + encodeURIComponent(taskId) +
      '&is_current=eq.true&order=created_at.desc&limit=1');
    var doc = docRes.ok && docRes.data && docRes.data[0] ? docRes.data[0] : null;
    if (!doc || !doc.attachment_url) {
      console.error('[SPPA-00] GP section scan: no current document for task ' + taskId);
      return null;
    }

    // Decode the returned PDF (data: URL) or fetch it (Drive/http URL).
    var pdfBuffer = null;
    var pdfMime = doc.mime_type || 'application/pdf';
    try {
      if (/^data:/i.test(doc.attachment_url)) {
        var commaIdx = doc.attachment_url.indexOf(',');
        var mimeMatch = doc.attachment_url.substring(0, commaIdx).match(/data:([^;]+)/);
        if (mimeMatch) pdfMime = mimeMatch[1];
        var b64 = doc.attachment_url.substring(commaIdx + 1).replace(/-/g, '+').replace(/_/g, '/');
        while (b64.length % 4 !== 0) b64 += '=';
        pdfBuffer = Buffer.from(b64, 'base64');
      } else {
        var fetched = await fetchAttachmentAsBase64(doc.attachment_url, doc.filename || 'SPPA-00.pdf');
        pdfBuffer = Buffer.from(fetched.content, 'base64');
        pdfMime = fetched.mimeType || pdfMime;
      }
    } catch (decodeErr) {
      console.error('[SPPA-00] GP section scan: could not load returned PDF:', decodeErr.message);
    }

    var scan;
    if (!pdfBuffer || !pdfBuffer.length) {
      scan = { ok: false, error: 'could_not_load_document', overall: 'unclear', confidence: 'low',
        summary: 'Could not read the returned document to scan it. Please review the form manually.',
        section_a_filled: false, section_a_notes: '', section_i_signed: false, section_i_notes: '',
        candidate_name_detected: '', scanned_at: new Date().toISOString() };
    } else {
      console.log('[SPPA-00] Running GP-section completeness scan for task ' + taskId);
      var result = await scanGpSections({ pdfBuffer: pdfBuffer, pdfMime: pdfMime, candidateName: meta.candidate_name || '' });
      scan = {
        ok: !result._error,
        error: result._error || null,
        section_a_filled: result.section_a_filled,
        section_a_notes: result.section_a_notes,
        section_i_signed: result.section_i_signed,
        section_i_notes: result.section_i_notes,
        candidate_name_detected: result.candidate_name_detected,
        overall: result._error ? 'unclear' : result.overall,
        confidence: result._error ? 'low' : result.confidence,
        summary: result._error
          ? 'The automatic check could not run (' + result._error + '). Please review the form manually.'
          : result.summary,
        scanned_at: new Date().toISOString()
      };
      console.log('[SPPA-00] GP section scan result:', JSON.stringify({
        overall: scan.overall, section_a: scan.section_a_filled, section_i: scan.section_i_signed,
        confidence: scan.confidence, error: scan.error
      }));
    }

    // Re-read metadata right before writing so we merge onto the latest state
    // (the gp_returned transition PATCH ran just before this fire-and-forget).
    var freshRes = await supabaseDbRequest('registration_tasks',
      'select=metadata&id=eq.' + encodeURIComponent(taskId) + '&limit=1');
    var freshMeta = (freshRes.ok && freshRes.data && freshRes.data[0]) ? freshRes.data[0].metadata : meta;
    if (typeof freshMeta === 'string') try { freshMeta = JSON.parse(freshMeta); } catch (e) { freshMeta = meta; }
    freshMeta = freshMeta || {};
    freshMeta.gp_section_scan = scan;
    freshMeta.gp_section_scan_completed = true;
    await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(taskId),
      { method: 'PATCH', body: { metadata: freshMeta, updated_at: new Date().toISOString() } });

    try {
      await _logCaseEvent(task.case_id, taskId, 'system',
        'AI checked the GP’s SPPA-00 sections — ' + (scan.overall === 'complete' ? 'sections complete' : (scan.overall === 'incomplete' ? 'sections incomplete' : 'needs manual review')),
        scan.summary, 'system',
        { section_a_filled: scan.section_a_filled, section_i_signed: scan.section_i_signed, confidence: scan.confidence });
    } catch (e) {}

    return scan;
  } catch (err) {
    console.error('[SPPA-00] GP section scan orchestrator error:', err.message);
    return null;
  }
}

/**
 * AI completeness check for a PRACTICE-returned SPPA-00. Gathers the completed
 * form + an inventory of supporting documents GP Link holds, asks the AI (trained
 * on real AHPRA-approved SPPA-00 forms) whether the form is filled out correctly
 * and all required documents are present, then stores the verdict on the task
 * (metadata.completeness_check). Returns the stored verdict object, or null if it
 * could not run. Safe to call fire-and-forget.
 */
async function _runSppaCompletenessCheck(caseId, sppaTaskId) {
  try {
    if (!isSupabaseDbConfigured()) return null;

    // Resolve the SPPA-00 task (by id if given, else by case).
    var taskRes;
    if (sppaTaskId) {
      taskRes = await supabaseDbRequest('registration_tasks',
        'select=id,case_id,metadata&id=eq.' + encodeURIComponent(sppaTaskId) + '&limit=1');
    } else {
      taskRes = await supabaseDbRequest('registration_tasks',
        'select=id,case_id,metadata&case_id=eq.' + encodeURIComponent(caseId) +
        '&related_document_key=eq.sppa_00&task_type=eq.practice_pack_child&limit=1');
    }
    if (!taskRes.ok || !taskRes.data || !taskRes.data[0]) return null;
    var sppaTask = taskRes.data[0];
    caseId = caseId || sppaTask.case_id;
    var meta = sppaTask.metadata;
    if (typeof meta === 'string') try { meta = JSON.parse(meta); } catch (e) { meta = {}; }
    if (!meta || typeof meta !== 'object') meta = {};

    // The completed SPPA-00 PDF (exclude alternate supervisor CVs).
    var docRes = await supabaseDbRequest('task_documents',
      'select=attachment_url,mime_type&task_id=eq.' + encodeURIComponent(sppaTask.id) +
      '&is_current=eq.true&category=neq.alt_supervisor_cv&limit=1');
    var doc = (docRes.ok && docRes.data && docRes.data[0]) ? docRes.data[0] : null;
    if (!doc || !doc.attachment_url) return null;
    var commaIdx = doc.attachment_url.indexOf(',');
    var pdfB64 = doc.attachment_url.substring(commaIdx + 1).replace(/-/g, '+').replace(/_/g, '/');
    while (pdfB64.length % 4 !== 0) pdfB64 += '=';
    var pdfBuffer = Buffer.from(pdfB64, 'base64');
    var pdfMime = doc.mime_type || 'application/pdf';

    // Supporting-document inventory.
    var sibRes = await supabaseDbRequest('registration_tasks',
      'select=id,related_document_key,status&case_id=eq.' + encodeURIComponent(caseId) +
      '&related_document_key=in.(supervisor_cv,offer_contract)&task_type=eq.practice_pack_child');
    var sibs = (sibRes.ok && Array.isArray(sibRes.data)) ? sibRes.data : [];
    async function _siblingHasDoc(key) {
      var t = sibs.find(function (s) { return s.related_document_key === key; });
      if (!t) return false;
      var dr = await supabaseDbRequest('task_documents',
        'select=id&task_id=eq.' + encodeURIComponent(t.id) + '&is_current=eq.true&limit=1');
      return !!(dr.ok && dr.data && dr.data[0]);
    }
    var supCvPresent = await _siblingHasDoc('supervisor_cv');
    var offerPresent = await _siblingHasDoc('offer_contract');

    var altCvRes = await supabaseDbRequest('task_documents',
      'select=id,filename&task_id=eq.' + encodeURIComponent(sppaTask.id) + '&category=eq.alt_supervisor_cv&is_current=eq.true');
    var altCvDocs = (altCvRes.ok && Array.isArray(altCvRes.data)) ? altCvRes.data : [];
    var altNames = Array.isArray(meta.alt_supervisor_names) ? meta.alt_supervisor_names : [];
    // Also recognise alternate-supervisor CVs already delivered to the GP's profile (user_documents)
    // — a CV collected via the request/match flow lives there, NOT as a task_document on the SPPA
    // task, so without this an already-collected CV would be reported as still missing and the
    // "missing CV" flag would never clear. Match by NAME against the alternates named on THIS form,
    // so a stale profile CV from an earlier version (a removed/different alternate) can't falsely
    // satisfy the check.
    try {
      var _ccCaseRow = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
      var _ccUserId = (_ccCaseRow.ok && _ccCaseRow.data && _ccCaseRow.data[0]) ? _ccCaseRow.data[0].user_id : null;
      if (_ccUserId && altNames.length) {
        var _ccProfileCvs = await supabaseDbRequest('user_documents',
          'select=file_name&user_id=eq.' + encodeURIComponent(_ccUserId) + '&document_key=like.alt_supervisor_cv_%25&status=in.(approved,uploaded)');
        if (_ccProfileCvs.ok && Array.isArray(_ccProfileCvs.data)) {
          var _ccAltLower = altNames.map(function (n) { return String(n || '').trim().toLowerCase(); });
          for (var _pcv of _ccProfileCvs.data) {
            var _pcvName = String(_pcv.file_name || '').replace(/\s*[—-]\s*CV\s*$/i, '').trim();
            if (_pcvName && _ccAltLower.indexOf(_pcvName.toLowerCase()) >= 0) {
              altCvDocs.push({ filename: _pcvName + ' — CV (on GP profile)' });
            }
          }
        }
      }
    } catch (e) { console.error('[SPPA] completeness alt-CV profile lookup error:', e.message); }

    var inventory = [
      'Primary supervisor CV (Q3): ' + (supCvPresent ? 'PRESENT on file' : 'NOT on file'),
      'Proof of employment — signed offer letter / contract / position description (Q10): ' + (offerPresent ? 'PRESENT on file' : 'NOT on file'),
      'Alternate supervisor CVs held by GP Link: ' + altCvDocs.length +
        (altCvDocs.length ? ' (' + altCvDocs.map(function (d) { return d.filename || 'CV'; }).join('; ') + ')' : ''),
      'Alternate supervisor name(s) auto-detected on the form: ' + (altNames.length ? altNames.join('; ') : 'none detected')
    ].join('\n');

    var verdict = await checkSppaCompleteness({
      sppaPdfBuffer: pdfBuffer,
      sppaPdfMime: pdfMime,
      inventoryText: inventory,
      altSupervisorNames: altNames
    });

    var stored = {
      is_complete: verdict.is_complete,
      confidence: verdict.confidence,
      missing_fields: verdict.missing_fields,
      missing_signatures: verdict.missing_signatures,
      missing_documents: verdict.missing_documents,
      issues: verdict.issues,
      summary: verdict.summary,
      alternate_supervisors_on_form: verdict.alternate_supervisors_on_form,
      // True when the form is otherwise complete/signed and the ONLY gap is an alternate-supervisor
      // CV — that has its own task, so the UI reframes it as a reminder and the submit gate allows it.
      only_alt_cv_outstanding: isOnlyAltCvOutstanding(verdict),
      checked_at: new Date().toISOString(),
      model: verdict._model || null,
      error: verdict._error || null,
      inventory: { supervisor_cv: supCvPresent, offer_contract: offerPresent, alt_cv_count: altCvDocs.length, alt_names: altNames }
    };

    // Re-read metadata immediately before writing so we don't clobber a concurrent
    // state transition that happened while the (slow) AI call was in flight.
    var freshRes = await supabaseDbRequest('registration_tasks',
      'select=metadata&id=eq.' + encodeURIComponent(sppaTask.id) + '&limit=1');
    var freshMeta = (freshRes.ok && freshRes.data && freshRes.data[0]) ? freshRes.data[0].metadata : meta;
    if (typeof freshMeta === 'string') try { freshMeta = JSON.parse(freshMeta); } catch (e) { freshMeta = meta; }
    if (!freshMeta || typeof freshMeta !== 'object') freshMeta = {};
    freshMeta.completeness_check = stored;
    await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(sppaTask.id),
      { method: 'PATCH', body: { metadata: freshMeta, updated_at: new Date().toISOString() } });

    await _logCaseEvent(caseId, sppaTask.id, 'system',
      'AI completeness check: ' + (verdict.is_complete ? 'ready to submit' : 'needs attention'),
      verdict.summary, 'system',
      { is_complete: verdict.is_complete, confidence: verdict.confidence });

    return stored;
  } catch (err) {
    console.error('[SPPA] Completeness check error:', err.message);
    return null;
  }
}

/**
 * Process an inbound AHPRA officer email: classify it and create an admin task.
 */
// AHPRA triage: only bind an officer email to a GP case on a high-confidence match. True only when
// the model matched a GP, is confident (>= 0.7), and is not flagging needs_triage. Mirrors the
// inline triage guard so a low-confidence best-guess never cross-contaminates the wrong GP's record.
function ahpraConfidentMatch(triage) {
  if (!triage || !triage.matched_gp_user_id) return false;
  if (triage.needs_triage) return false;
  return (Number(triage.confidence) || 0) >= 0.7;
}

// Build the GP-facing s80 action-item payload from an AHPRA card, for delivery to the GP's own
// AHPRA page (upload box + deadline + plain-English instruction). Pure: takes the card row, its
// parsed metadata, and an ISO timestamp; returns the _createRegTask data object (minus _actor).
function buildAhpraGpDeliveryItem(card, cardMeta, nowIso) {
  card = card || {};
  cardMeta = cardMeta || {};
  var gpInstructions = String(cardMeta.summary || card.description || card.title || 'AHPRA has requested information for your application.').slice(0, 2000);
  var ahpraDeadline = cardMeta.ahpra_deadline || card.due_date || null;
  var officer = (cardMeta.ahpra_officer_email || cardMeta.ahpra_officer_name)
    ? { name: cardMeta.ahpra_officer_name || '', email: cardMeta.ahpra_officer_email || '' } : null;
  var cleanTitle = String(card.title || 'AHPRA requested item')
    .replace(/\s*\((direct reply|practice needed|RSO fix|GP correction|practice correction)\)\s*$/i, '').slice(0, 200);
  return {
    task_type: 'ahpra_action_item',
    title: cleanTitle,
    description: gpInstructions,
    priority: 'high',
    status: 'waiting_on_gp',
    due_date: ahpraDeadline,
    source_trigger: 'ahpra_card_delivery',
    related_stage: 'ahpra',
    ahpra_deadline: ahpraDeadline,
    metadata: {
      s80: true,
      review_status: 'active',
      released_at: nowIso,
      owner: 'gp',
      mode: 'upload',
      kind: 'ahpra_request',
      detail: String(card.description || gpInstructions).slice(0, 4000),
      gp_instructions: gpInstructions,
      how_to_steps: [],
      deadline: ahpraDeadline,
      source_card_task_id: card.id,
      officer: officer,
      ingest_source: 'ahpra_card_delivery'
    }
  };
}

async function _processAhpraEmail(emailMeta, sourceMsgId, preMatchedCase) {
  try {
    var gpRes = await supabaseDbRequest('registration_cases',
      'select=id,user_id,stage,status&status=in.(active,in_progress)&stage=in.(ahpra,career,pbs,commencement)&limit=200');
    var gpCandidates = [];
    if (gpRes.ok && Array.isArray(gpRes.data)) {
      for (var c of gpRes.data) {
        var profRes = await supabaseDbRequest('user_profiles',
          'select=first_name,last_name,email&user_id=eq.' + encodeURIComponent(c.user_id) + '&limit=1');
        var prof = (profRes.ok && profRes.data && profRes.data[0]) ? profRes.data[0] : {};
        gpCandidates.push({
          user_id: c.user_id,
          case_id: c.id,
          name: ((prof.first_name || '') + ' ' + (prof.last_name || '')).trim(),
          email: prof.email || '',
          stage: c.stage
        });
      }
    }

    var triage = await triageAhpraEmail(emailMeta, gpCandidates);
    console.log('[AHPRA Email]', JSON.stringify({ category: triage.category, matched: triage.matched_gp_user_id, confidence: triage.confidence, summary: triage.summary }));

    // Idempotency: never create a second AHPRA task for the same officer email
    // (the realtime watch and the hourly cron can both deliver the same message).
    if (sourceMsgId) {
      var _existingAhpra = await supabaseDbRequest('registration_tasks',
        'select=id&task_type=eq.ahpra_correspondence&source_gmail_message_id=eq.' + encodeURIComponent(sourceMsgId) + '&limit=1');
      if (_existingAhpra.ok && Array.isArray(_existingAhpra.data) && _existingAhpra.data.length) {
        console.log('[AHPRA Email] Already processed message', sourceMsgId, '— skipping duplicate task');
        return;
      }
    }

    // If this thread already has an AHPRA card, this is a follow-up/reply — don't open a second
    // card. The inline response-matching path attaches the reply to the existing task instead.
    if (emailMeta.threadId) {
      var _threadTask = await supabaseDbRequest('registration_tasks',
        'select=id&task_type=eq.ahpra_correspondence&gmail_thread_id=eq.' + encodeURIComponent(emailMeta.threadId) + '&limit=1');
      if (_threadTask.ok && Array.isArray(_threadTask.data) && _threadTask.data.length) {
        console.log('[AHPRA Email] Thread already has an AHPRA card — reply will attach via response-matching; skipping new card');
        return;
      }
    }

    // Only bind to a GP case on a HIGH-CONFIDENCE match. triageAhpraEmail returns a best-guess
    // user_id even for ambiguous/unrelated mail (flagged via needs_triage / low confidence); binding
    // those guesses cross-contaminates the wrong GP's record. This mirrors the inline triage guard
    // (require confidence >= 0.7 and not needs_triage). Anything else → an unmatched triage task
    // (case_id null → Support page, no GP case touched).
    // Prefer the strong inline match (CC / application number / thread / officer-email) that the
    // caller already computed; fall back to the LLM triage match only when it is confident (>= 0.7
    // and not needs_triage). This stops a definite match being downgraded to "unmatched" by a
    // cautious model, while still gating the LLM-only path against cross-contamination.
    var matchedGp = null;
    var caseId = null;
    if (preMatchedCase && preMatchedCase.id) {
      caseId = preMatchedCase.id;
      matchedGp = { user_id: preMatchedCase.user_id, case_id: preMatchedCase.id };
    } else if (ahpraConfidentMatch(triage)) {
      matchedGp = gpCandidates.find(function (g) { return g.user_id === triage.matched_gp_user_id; }) || null;
      caseId = matchedGp ? matchedGp.case_id : null;
    }

    if (!caseId) {
      console.log('[AHPRA Email] No confident GP match — creating unmatched triage task');
      await supabaseDbRequest('registration_tasks', '', {
        method: 'POST',
        body: [{
          task_type: 'ahpra_correspondence',
          title: 'AHPRA email — unmatched GP',
          priority: 'high',
          status: 'open',
          source_trigger: 'ahpra_email',
          related_stage: 'ahpra',
          source_gmail_message_id: sourceMsgId || null,
          gmail_thread_id: emailMeta.threadId || null,
          email_sender: triage.officer_email || emailMeta.sender || null,
          metadata: {
            ahpra_officer_name: triage.officer_name,
            ahpra_officer_email: triage.officer_email || emailMeta.sender,
            category: triage.category,
            summary: triage.summary,
            email_subject: emailMeta.subject,
            email_date: emailMeta.date,
            needs_triage: true
          }
        }]
      });
      return;
    }

    if (triage.officer_email) {
      try {
        var caseMetaRes = await supabaseDbRequest('registration_cases',
          'select=metadata&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
        var caseMeta = (caseMetaRes.ok && caseMetaRes.data && caseMetaRes.data[0]) ? caseMetaRes.data[0].metadata : {};
        if (typeof caseMeta === 'string') try { caseMeta = JSON.parse(caseMeta); } catch (e) { caseMeta = {}; }
        if (!caseMeta) caseMeta = {};
        caseMeta.ahpra_officer_name = triage.officer_name || caseMeta.ahpra_officer_name;
        caseMeta.ahpra_officer_email = triage.officer_email || caseMeta.ahpra_officer_email;
        await supabaseDbRequest('registration_cases',
          'id=eq.' + encodeURIComponent(caseId),
          { method: 'PATCH', body: { metadata: caseMeta } });
      } catch (e) {
        console.error('[AHPRA Email] case metadata update error:', e.message);
      }
    }

    // Task 5: Route officer conflict requests to the single ahpra_conflict_letter task.
    // If the triage flags this as a conflict followup, ensure/return the conflict-letter task
    // and suppress the generic ahpra_correspondence creation below.
    var isConflictFollowup = triage.category === 'conflict_followup' || triage.response_type === 'request_from_practice';
    var suppressedByConflictLetter = false;
    if (isConflictFollowup) {
      try {
        var _clRouteTask = await _ensureAhpraConflictLetter(caseId, {
          officerName: triage.officer_name || '',
          officerEmail: triage.officer_email || emailMeta.sender,
          officerRequestMessageId: sourceMsgId || emailMeta.messageId || null
        });
        if (_clRouteTask) {
          suppressedByConflictLetter = true;
          console.log('[AHPRA Email] Conflict followup — routed to conflict-letter task', _clRouteTask.id, '(suppressed ahpra_correspondence)');
        }
      } catch (_clRouteErr) {
        console.error('[AHPRA Email] conflict-letter route check error:', _clRouteErr.message);
      }
    }

    // ── Option A: an AHPRA "provide documents / further information" notice (request_from_gp) is
    // AI-split into the editable Who/How review tray (s80 pending_review, renderS80Tray) — NOT a
    // single lumped correspondence card. The RSO edits Who (GP/Team) + How (upload/request/team) per
    // box, removes any, then "Release to GP & team". The other 5 response types keep their card below.
    // extractAhpraActionItems now runs on the fast model, so this is safe to do synchronously at
    // inbound. _createAhpraS80Bundle's fail-loud path always leaves at least one tray entry, so a
    // notice is never lost; we only fall through to a card if the bundle genuinely created nothing.
    if (!suppressedByConflictLetter && triage.response_type === 'request_from_gp') {
      try {
        var _s80Country = await _resolveGpCountry(matchedGp.user_id);
        var _s80Officer = (triage.officer_name || triage.officer_email || emailMeta.sender)
          ? { name: triage.officer_name || '', email: triage.officer_email || emailMeta.sender || '' } : null;
        var _s80Extraction = await extractAhpraActionItems(emailMeta, { officer: _s80Officer, country: _s80Country });
        var _s80Bundle = await _createAhpraS80Bundle({ id: caseId, user_id: matchedGp.user_id }, emailMeta, sourceMsgId, _s80Extraction,
          { sourceTrigger: 'ahpra_officer_email', officer: _s80Officer, country: _s80Country });
        if (_s80Bundle && (_s80Bundle.created > 0 || _s80Bundle.skipped)) {
          console.log('[AHPRA Email] request_from_gp -> s80 Who/How review tray:', JSON.stringify(_s80Bundle));
          await _logCaseEvent(caseId, null, 'system', 'AHPRA email received — documents requested',
            triage.summary, 'ahpra_email_pipeline', { officer_email: triage.officer_email || emailMeta.sender });
          return; // tray created — do NOT also create the lumped ahpra_correspondence card
        }
        console.warn('[AHPRA Email] request_from_gp s80 bundle created nothing — falling back to a correspondence card');
      } catch (_s80Err) {
        console.error('[AHPRA Email] request_from_gp s80-tray creation failed, falling back to a correspondence card:', _s80Err.message);
      }
    }

    var taskTitle = '';
    var taskDetail = '';
    var taskMeta = {
      ahpra_officer_name: triage.officer_name,
      ahpra_officer_email: triage.officer_email || emailMeta.sender,
      category: triage.category,
      response_type: triage.response_type || 'request_from_gp',
      summary: triage.summary,
      email_subject: emailMeta.subject,
      email_date: emailMeta.date,
      amend_target: triage.amend_target || null,
      on_file_documents: triage.on_file_documents || [],
      draft_response: triage.draft_response || null
    };

    // application_update category is always a status_update — correct AI misclassification
    if (triage.category === 'application_update' && triage.response_type !== 'status_update') {
      triage.response_type = 'status_update';
      taskMeta.response_type = 'status_update';
    }

    var taskPriority = 'normal';
    if (triage.response_type === 'escalation') taskPriority = 'urgent';
    else if (triage.category === 'conflict_followup') taskPriority = 'high';
    else if (triage.response_type === 'amend_document') taskPriority = 'high';

    if (triage.response_type === 'direct_reply') {
      taskTitle = 'AHPRA ' + triage.category.replace(/_/g, ' ') + ' (direct reply)';
      taskDetail = triage.summary + (triage.draft_response ? '\n\nSuggested response: ' + triage.draft_response : '');
    } else if (triage.response_type === 'amend_document') {
      var owner = triage.amend_target ? triage.amend_target.owner : 'unknown';
      var ownerLabel = owner === 'rso' ? 'RSO fix' : owner === 'gp' ? 'GP correction' : 'practice correction';
      taskTitle = 'AHPRA amendment request (' + ownerLabel + ')';
      taskDetail = triage.summary;
      if (triage.amend_target) taskDetail += '\n\nDocument: ' + triage.amend_target.document + ', Section/Field: ' + (triage.amend_target.section || triage.amend_target.field || '?') + ', Owner: ' + owner;
    } else if (triage.response_type === 'request_from_practice') {
      taskTitle = 'AHPRA ' + triage.category.replace(/_/g, ' ') + ' (practice needed)';
      taskDetail = triage.summary;
    } else if (triage.response_type === 'status_update') {
      taskTitle = 'AHPRA application update';
      taskDetail = triage.summary;
    } else if (triage.response_type === 'escalation') {
      taskTitle = 'AHPRA ESCALATION';
      taskDetail = triage.summary;
      taskMeta.escalated = true;
    } else {
      taskTitle = 'AHPRA ' + triage.category.replace(/_/g, ' ');
      taskDetail = triage.summary;
      if (triage.requested_documents.length) taskDetail += '\n\nRequested: ' + triage.requested_documents.join(', ');
    }

    // Calculate due date: 1 week before AHPRA deadline, or 10 days from now as fallback
    var ahpraDueDate = null;
    var extractedDeadline = triage.response_deadline || null;
    if (extractedDeadline && /^\d{4}-\d{2}-\d{2}$/.test(extractedDeadline)) {
      var deadlineDate = new Date(extractedDeadline + 'T00:00:00Z');
      if (!isNaN(deadlineDate.getTime())) {
        // Due date = 1 week before AHPRA's deadline so we have buffer
        var oneWeekBefore = new Date(deadlineDate.getTime() - 7 * 86400000);
        // But never in the past — floor to tomorrow
        var tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1);
        ahpraDueDate = (oneWeekBefore > tomorrow ? oneWeekBefore : tomorrow).toISOString().slice(0, 10);
        taskMeta.ahpra_deadline = extractedDeadline;
      }
    }
    if (!ahpraDueDate) {
      var tenDaysOut = new Date(); tenDaysOut.setDate(tenDaysOut.getDate() + 10);
      ahpraDueDate = tenDaysOut.toISOString().slice(0, 10);
    }

    if (!suppressedByConflictLetter) {
    var _ahpraTaskRes = await supabaseDbRequest('registration_tasks', '', {
      method: 'POST',
      headers: { Prefer: 'return=representation' },
      body: [{
        case_id: caseId,
        task_type: 'ahpra_correspondence',
        title: taskTitle,
        description: taskDetail,
        priority: taskPriority,
        status: 'open',
        due_date: ahpraDueDate,
        source_trigger: 'ahpra_email',
        related_stage: 'ahpra',
        source_gmail_message_id: sourceMsgId || null,
        gmail_thread_id: emailMeta.threadId || null,
        email_sender: triage.officer_email || emailMeta.sender || null,
        email_body_snippet: (emailMeta.bodyText || '').slice(0, 500) || null,
        metadata: taskMeta
      }]
    });
    var newTaskId = (_ahpraTaskRes.ok && _ahpraTaskRes.data && _ahpraTaskRes.data[0]) ? _ahpraTaskRes.data[0].id : null;
    if (!newTaskId) {
      console.error('[AHPRA Email] FAILED to create ahpra_correspondence task — DB rejected insert:',
        _ahpraTaskRes.status, JSON.stringify((_ahpraTaskRes.data && _ahpraTaskRes.data.message) || _ahpraTaskRes.data || ''));
      return;
    }

    // Persist the officer's email as an inbound task_message so the card shows the request
    // ("Open full email") and so reply-matching/threading can find the thread later.
    try {
      await supabaseDbRequest('task_messages', '', {
        method: 'POST',
        body: [{
          task_id: newTaskId, case_id: caseId, direction: 'inbound', channel: 'email',
          sender: triage.officer_email || emailMeta.sender || '',
          recipient: emailMeta.to || null,
          subject: emailMeta.subject || '',
          body_text: (emailMeta.bodyText || '').substring(0, 50000),
          gmail_message_id: sourceMsgId || null, gmail_thread_id: emailMeta.threadId || null,
          rfc822_message_id: emailMeta.rfc822MessageId || null, rfc822_references: emailMeta.rfc822References || null,
          cc: emailMeta.cc || null
        }]
      });
    } catch (mErr) { console.error('[AHPRA Email] inbound task_message insert error:', mErr.message); }

    await _logCaseEvent(caseId, null, 'system',
      'AHPRA email received — ' + triage.category,
      triage.summary,
      'ahpra_email_pipeline',
      { officer_email: triage.officer_email || emailMeta.sender });

    // For direct_reply tasks, auto-attach on-file documents
    if (newTaskId && triage.response_type === 'direct_reply' && triage.on_file_documents.length > 0) {
      try {
        var _gpUserId = matchedGp.user_id;
        var _practiceDocKeys = ['sppa_00', 'position_description', 'offer_contract', 'supervisor_cv', 'section_g'];
        for (var _ofk of triage.on_file_documents) {
          if (_practiceDocKeys.indexOf(_ofk) >= 0) {
            // Find the completed practice_pack_child task with this doc key, then get its current doc
            var _srcTaskRes = await supabaseDbRequest('registration_tasks',
              'select=id&case_id=eq.' + encodeURIComponent(caseId) + '&related_document_key=eq.' + encodeURIComponent(_ofk) + '&status=eq.completed&limit=1');
            if (_srcTaskRes.ok && _srcTaskRes.data && _srcTaskRes.data[0]) {
              var _srcDocs = await supabaseDbRequest('task_documents',
                'select=filename,attachment_url,mime_type,google_drive_file_id,google_drive_url&task_id=eq.' + encodeURIComponent(_srcTaskRes.data[0].id) + '&is_current=eq.true&limit=1');
              if (_srcDocs.ok && _srcDocs.data && _srcDocs.data[0]) {
                var _srcDoc = _srcDocs.data[0];
                await supabaseDbRequest('task_documents', '', {
                  method: 'POST', body: [{
                    task_id: newTaskId, case_id: caseId,
                    filename: _srcDoc.filename || (_ofk + '.pdf'), mime_type: _srcDoc.mime_type || 'application/pdf',
                    google_drive_file_id: _srcDoc.google_drive_file_id || null,
                    google_drive_url: _srcDoc.google_drive_url || null,
                    attachment_url: _srcDoc.attachment_url || null,
                    version: 1, is_current: true, uploaded_by: 'auto_on_file',
                    category: 'on_file'
                  }]
                });
              }
            }
          } else {
            // User documents (qualification docs like primary_medical_degree, mrcgp_certificate, etc.)
            var _userDocRes = await supabaseDbRequest('user_documents',
              'select=file_name,file_url,google_drive_file_id&user_id=eq.' + encodeURIComponent(_gpUserId) +
              '&document_key=eq.' + encodeURIComponent(_ofk) + '&status=eq.approved&limit=1');
            if (_userDocRes.ok && _userDocRes.data && _userDocRes.data[0]) {
              var _ud = _userDocRes.data[0];
              var _driveUrl = _ud.google_drive_file_id ? 'https://drive.google.com/file/d/' + _ud.google_drive_file_id + '/view' : '';
              await supabaseDbRequest('task_documents', '', {
                method: 'POST', body: [{
                  task_id: newTaskId, case_id: caseId,
                  filename: _ud.file_name || (_ofk + '.pdf'), mime_type: 'application/pdf',
                  google_drive_file_id: _ud.google_drive_file_id || null,
                  google_drive_url: _driveUrl || null,
                  attachment_url: _ud.file_url || null,
                  version: 1, is_current: true, uploaded_by: 'auto_on_file',
                  category: 'on_file'
                }]
              });
            }
          }
        }
        console.log('[AHPRA] Auto-attached', triage.on_file_documents.length, 'on-file doc(s) to task', newTaskId);
      } catch (docErr) { console.error('[AHPRA] Auto-attach on-file docs error:', docErr.message); }
    }

    console.log('[AHPRA Email] Created task: ' + taskTitle);
    } else {
      // Suppressed: conflict followup is handled by the ahpra_conflict_letter task.
      // Still log to the case timeline so the email arrival is visible.
      await _logCaseEvent(caseId, null, 'system',
        'AHPRA conflict followup — handled via conflict-letter task',
        triage.summary, 'ahpra_email_pipeline',
        { officer_email: triage.officer_email || emailMeta.sender });
    }
  } catch (err) {
    console.error('[AHPRA Email] processing error:', err.message);
  }
}

async function _hasOpenTask(caseId, stage, type) {
  if (!isSupabaseDbConfigured()) return false;
  const q = await supabaseDbRequest('registration_tasks',
    'select=id&case_id=eq.' + encodeURIComponent(caseId) + '&related_stage=eq.' + encodeURIComponent(stage) + '&task_type=eq.' + encodeURIComponent(type) + '&status=in.(open,in_progress,waiting,waiting_on_gp,waiting_on_practice,waiting_on_external,escalated,deferred,completed)&limit=1');
  return q.ok && Array.isArray(q.data) && q.data.length > 0;
}

async function _hasDoubleTickBeenSent(caseId, stageTitle) {
  if (!isSupabaseDbConfigured()) return false;
  const exactTitle = stageTitle + ' started — WhatsApp template sent';
  const titles = [exactTitle];
  // Backward compat: AHPRA was previously logged as "unlocked" instead of "started"
  if (stageTitle === 'AHPRA stage') titles.push('AHPRA stage unlocked — WhatsApp template sent');
  const titleFilter = titles.length === 1
    ? 'title=eq.' + encodeURIComponent(titles[0])
    : 'title=in.(' + titles.map(t => '"' + t.replace(/[\\"]/g, '\\$&') + '"').join(',') + ')';
  const q = await supabaseDbRequest('task_timeline',
    'select=id&case_id=eq.' + encodeURIComponent(caseId) + '&event_type=eq.system&' + titleFilter + '&limit=1');
  return q.ok && Array.isArray(q.data) && q.data.length > 0;
}

async function _hasOpenTaskForDoc(caseId, docKey) {
  if (!isSupabaseDbConfigured()) return false;
  const q = await supabaseDbRequest('registration_tasks',
    'select=id&case_id=eq.' + encodeURIComponent(caseId) + '&related_document_key=eq.' + encodeURIComponent(docKey) + '&status=in.(open,in_progress,waiting,waiting_on_gp,waiting_on_practice,waiting_on_external,escalated,deferred,completed)&limit=1');
  return q.ok && Array.isArray(q.data) && q.data.length > 0;
}

