      { key: "st joseph's college banora point", sector: 'Catholic', sectorGroup: 'catholic', rating: 'Above Average', rankLabel: 'Above Average', rankingScore: 81, starRating: 4.1, coords: { lat: -28.2124, lng: 153.5369 } }
