async function buildCareerPlacementPayload({
  zoho,
  applicationRecord,
  roleRow,
  jobOpeningRecord,
  startDateIso,
  practiceContacts,
  providerRoleId,
  profile,
  zohoCandidateId,
  applicationId,
  skipContractCache
}) {
  // Zoho is decommissioned, so applicationRecord (the old live Zoho fetch) is now
  // null — take the id from the local gp_applications row's zoho_application_id
  // instead, so the contract-extract / placement caches keyed on it still resolve.
  const appId = sanitizeZohoText(applicationRecord && applicationRecord.id) || String(applicationId || '').trim();
  const placementCacheKey = appId ? `placement_payload:${appId}` : '';

  if (placementCacheKey && !skipContractCache) {
    const cached = await getRuntimeKv(placementCacheKey).catch(() => null);
    if (cached && cached.value && typeof cached.value === 'object' && cached.value.practiceName) {
      // Payloads cached while Zoho was live may carry a contractUrl pointing at the
      // now-dead /api/career/contract streamer (always 404s). Strip it so the front
      // end hides the button instead of offering a broken download.
      if (typeof cached.value.contractUrl === 'string' && cached.value.contractUrl.indexOf('/api/career/contract') === 0) {
        cached.value.contractUrl = '';
        cached.value.contractFileName = '';
      }
      return applyGpShareToPlacementPayload(cached.value);
    }
  }

  const practiceName = getZohoApplicationPracticeName(applicationRecord)
    || getZohoField(jobOpeningRecord, ['Posting_Title', 'Job_Opening_Name', 'Title'])
    || (roleRow && roleRow.practice_name)
    || 'Medical Centre';
  const roleTitle = derivePlacementRoleTitle(roleRow, jobOpeningRecord, practiceName);
  const location = getZohoPlacementLocation(jobOpeningRecord, roleRow);
  // Zoho Recruit decommissioned — the LIVE contract-term extraction ran off Zoho
  // attachments and is no longer produced. BUT terms extracted while Zoho was live
  // are still cached in runtime_kv (career_contract_extract:<appId>) and remain the
  // real agreed figures for already-placed GPs (split %, relocation package, contract
  // length). Read them back so the placement view keeps showing the true values
  // instead of collapsing every field to "Pending". (In-app offers don't use this
  // path — they build their payload via buildInAppPlacementPayload.)
  let contractTerms = null;
  if (appId) {
    const contractCached = await getRuntimeKv(buildCareerContractCacheKey(appId)).catch(() => null);
    if (contractCached && contractCached.value && typeof contractCached.value === 'object') {
      contractTerms = contractCached.value;
    }
  }
  const fallbackTerms = extractPlacementTermsFromJobOpening(jobOpeningRecord, roleRow, applicationRecord);
  const billingLabel = normalizeCareerBillingLabel(getZohoField(jobOpeningRecord, ['Billing_Model', 'Billing_Type', 'Remuneration_Model', 'Fee_Model', 'Billing']))
    || normalizeCareerBillingLabel(getZohoField(applicationRecord, ['Billing_Model', 'Billing_Type', 'Remuneration_Model', 'Fee_Model', 'Billing']))
    || normalizeCareerBillingLabel(roleRow && roleRow.billing_model)
    || 'Billing pending';
  // Always surface the GP's share (the higher number), even for values cached before
  // this rule existed or extracted by the heuristic without flipping the practice's cut.
  const splitDisplay = ensureGpShareSplitDisplay((contractTerms && contractTerms.splitDisplay) || fallbackTerms.splitDisplay) || 'Pending';
  const relocationDisplay = (contractTerms && contractTerms.relocationPackageDisplay) || fallbackTerms.relocationPackageDisplay || 'Pending';
  const contractLengthDisplay = (contractTerms && contractTerms.contractLengthDisplay) || fallbackTerms.contractLengthDisplay || 'Pending';
  const roleClient = roleRow ? mapCareerRoleRowToClient(roleRow) : null;
  const practiceContactRecord = Array.isArray(practiceContacts) && practiceContacts.length > 0
    ? practiceContacts.slice().sort(sortZohoRecordsByRecent)[0]
    : null;
  // With Zoho gone there's usually no live contact record. Pull the practice's real
  // contact from the app's Practices section (the source of truth the team edits) so
  // Call/Email/WhatsApp reach the CORRECT practice for every placed GP — never a demo
  // number. Sources in precedence order: the linked practices row → the hired
  // application's saved contact (name/email) → the registration case → empty.
  const gpUserIdForContact = (profile && profile.user_id) || '';
  let practiceRow = null;
  if (!practiceContactRecord && roleRow && roleRow.practice_id && isSupabaseDbConfigured()) {
    try { practiceRow = await atsGetPracticeRow(roleRow.practice_id); } catch (e) { practiceRow = null; }
  }
  let appContact = null;
  if (!practiceContactRecord && gpUserIdForContact && isSupabaseDbConfigured()) {
    try {
      const acRow = await resolvePlacedPracticeContact(gpUserIdForContact);
      if (acRow) appContact = { practice_contact_name: acRow.name, practice_contact_email: acRow.email };
    } catch (e) { appContact = null; }
  }
  let casePracticeContact = null;
  if (!practiceContactRecord && gpUserIdForContact && isSupabaseDbConfigured()) {
    try {
      const caseRes = await supabaseDbRequest('registration_cases', 'select=practice_contact&user_id=eq.' + encodeURIComponent(gpUserIdForContact) + '&limit=1');
      const caseRow = (caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0]) ? caseRes.data[0] : null;
      if (caseRow && caseRow.practice_contact) {
        casePracticeContact = typeof caseRow.practice_contact === 'string' ? JSON.parse(caseRow.practice_contact) : caseRow.practice_contact;
      }
    } catch (e) { casePracticeContact = null; }
  }
  let practiceContact;
  if (practiceContactRecord) {
    practiceContact = buildPracticeContactPayload(practiceContactRecord, practiceName);
  } else {
    const pr = (practiceRow && typeof practiceRow === 'object') ? practiceRow : {};
    const ac = (appContact && typeof appContact === 'object') ? appContact : {};
    const cc = (casePracticeContact && typeof casePracticeContact === 'object') ? casePracticeContact : {};
    const cName = String(pr.contact_name || ac.practice_contact_name || cc.name || cc.contactName || '').trim();
    const cEmail = String(pr.contact_email || ac.practice_contact_email || cc.email || cc.contactEmail || '').trim();
    const cPhone = String(pr.contact_phone || cc.phone || cc.contactPhone || '').trim();
    // Practices carry one contact number; use it for WhatsApp too (AU practice
    // mobiles are WhatsApp-reachable). An explicit WhatsApp field wins if present.
    const cWhatsapp = String(pr.contact_whatsapp || cc.whatsapp || cc.contactWhatsapp || cPhone || '').trim();
    if (cName || cEmail || cPhone || cWhatsapp) {
      const displayName = cName || (practiceName ? practiceName + ' Team' : 'Medical Centre Team');
      practiceContact = {
        name: displayName,
        initials: buildInitials(displayName),
        role: 'Medical centre contact',
        meta: (cEmail || cPhone || cWhatsapp) ? 'Reach out directly to the practice' : 'Direct contact details will appear here once synced',
        phone: cPhone,
        email: cEmail,
        whatsapp: cWhatsapp
      };
    } else {
      practiceContact = buildPlacementFallbackPracticeContact(jobOpeningRecord, practiceName, providerRoleId);
    }
  }
  const resolvedStartDateIso = getPlacementStartDate(startDateIso, applicationRecord, jobOpeningRecord, roleRow);
  const lifestyle = await resolvePracticeLifestylePayload({
    applicationId: sanitizeZohoText(applicationRecord && applicationRecord.id),
    practiceName,
    location,
    roleRow,
    profile
  }).catch(function (e) { console.error('[buildPlacement] lifestyle failed:', e && e.message); return null; });

  // Contract download. The old Zoho attachment stream (/api/career/contract) is
  // decommissioned and always 404s, and the original Zoho contract PDFs were never
  // migrated — so we must NOT link that route (it would hand the GP a broken
  // download). Only surface a download when a REAL, servable contract document
  // exists in the GP's documents (offer_contract), served by the live
  // /api/prepared-documents/download route. If none exists, leave the URL empty so
  // the front end hides the button rather than offering a dead link.
  let contractUrl = '';
  let contractFileName = '';
  const gpUserId = (profile && profile.user_id) || '';
  if (gpUserId && isSupabaseDbConfigured()) {
    try {
      const contractRow = await getOfferDocumentRow(gpUserId, 'offer_contract');
      const contractStatus = contractRow ? String(contractRow.status || '') : '';
      if (contractRow && (contractStatus === 'approved' || contractStatus === 'uploaded' || contractStatus === 'received')) {
        const documentCountry = normalizeDocumentCountry((profile && (profile.registration_country || profile.country)) || '') || 'uk';
        contractUrl = buildPreparedDocumentDownloadUrl(documentCountry, 'offer_contract');
        contractFileName = contractRow.file_name || '';
      }
    } catch (e) { contractUrl = ''; contractFileName = ''; }
  }

  const placementResult = {
    practiceName,
    roleTitle,
    location,
    statusLabel: 'Placement confirmed',
    startDateIso: resolvedStartDateIso,
    contractUrl,
    contractFileName,
    quickStats: [
      { label: 'Billing', value: billingLabel.replace(/\s+Billing$/i, '') || billingLabel },
      { label: 'Split', value: splitDisplay },
      { label: 'Relocation Package', value: relocationDisplay }
    ],
    story: {
      title: location.replace(/,\s*Australia\s*$/i, ''),
      text: (roleRow && roleRow.summary) || (roleClient && roleClient.summary) || 'Your medical centre placement is now secured.',
      imageUrl: roleClient && roleClient.heroImageUrl ? roleClient.heroImageUrl : '',
      mapQuery: roleClient && roleClient.mapQuery ? roleClient.mapQuery : location
    },
    lifestyle,
    practiceContact,
    compensation: {
      range: filterZeroCompensation(getZohoField(jobOpeningRecord, ['Salary_Range', 'Salary', 'Compensation', 'Estimated_Earnings', 'Package']))
        || filterZeroCompensation(getZohoField(applicationRecord, ['Offered_CTC', 'Offered_Salary', 'Expected_Salary', 'Offer_Amount', 'Salary_Range', 'Salary', 'Compensation', 'Package']))
        || filterZeroCompensation(roleRow && roleRow.source_payload && roleRow.source_payload.billing_range)
        || filterZeroCompensation(roleRow && roleRow.source_payload && roleRow.source_payload.earnings)
        || filterZeroCompensation(roleRow && roleRow.earnings_text)
        || 'Pending',
      unit: 'Per Day',
      note: 'Expected income',
      facts: [
        { label: 'Billing type', value: billingLabel || 'Pending' },
        { label: 'Billing split', value: splitDisplay || 'Pending' },
        { label: 'Relocation package', value: relocationDisplay || 'Pending' },
        {
          label: 'Contract length',
          value: contractLengthDisplay
        }
      ]
    }
  };

  if (placementCacheKey) {
    setRuntimeKv(placementCacheKey, placementResult, Date.now() + PLACEMENT_PAYLOAD_CACHE_TTL_MS).catch(() => {});
  }

  return placementResult;
}

// ── In-app placement payload (standalone-ATS Task C) ─────────────────────────
// buildCareerPlacementPayload above speaks Zoho — it enriches from Zoho
// application/job-opening records and the contract-extraction cache. An in-app
// offer already carries the agreed terms as first-class fields, so accepting
// one builds this LOCAL payload instead: the same minimal field set
// career.html's secured view reads (resolveSecuredPlacement), no Zoho needed.
// The Split shown is always the GP's (majority) share — see
// ensureGpShareSplitDisplay / applyGpShareToPlacementPayload.
function buildInAppPlacementPayload(roleRow, offer, practiceRow, casePracticeContact, extras) {
  const opts = extras && typeof extras === 'object' ? extras : {};
  const o = offer && typeof offer === 'object' ? offer : {};
  const role = roleRow && typeof roleRow === 'object' ? roleRow : {};
  const practice = practiceRow && typeof practiceRow === 'object' ? practiceRow : {};

  const practiceName = String(o.practice_name || role.practice_name || practice.name || 'Medical Centre').trim() || 'Medical Centre';
  const roleTitle = String(o.job_title || role.title || 'General Practitioner').trim() || 'General Practitioner';
  const location = [role.location_city, role.location_state].filter(Boolean).join(', ');
  const billingLabel = normalizeCareerBillingLabel(role.billing_model) || 'Billing pending';
  const splitDisplay = ensureGpShareSplitDisplay(o.billing_split) || (String(o.billing_split || '').trim() || 'Pending');
  const sessionsDisplay = String(o.sessions_per_week || '').trim();
  // Relocation package: a concrete perk (e.g. "$10,000") is more meaningful to an
  // incoming GP than a "Sessions per week" tile that is usually still Pending, so
  // when the offer records a relocation package we surface it in that third slot.
  const relocationDisplay = normalizeContractCurrencyDisplay(String(o.relocation_package || '').trim())
    || String(o.relocation_package || '').trim();
  const sessionsStat = { label: 'Sessions', value: sessionsDisplay ? (/week/i.test(sessionsDisplay) ? sessionsDisplay : sessionsDisplay + ' / week') : 'Pending' };
  const thirdQuickStat = relocationDisplay ? { label: 'Relocation', value: relocationDisplay } : sessionsStat;
  const startDateIso = normalizePlacementStartDate(o.start_date) || '';
  const roleClient = roleRow ? mapCareerRoleRowToClient(roleRow) : null;

  // Practice contact precedence: the registration case's saved contact →
  // the practice record → a friendly practice-team fallback.
  const cc = casePracticeContact && typeof casePracticeContact === 'object' ? casePracticeContact : {};
  const contactName = String(cc.name || cc.contactName || practice.contact_name || '').trim() || (practiceName + ' Team');
  const contactEmail = String(cc.email || cc.contactEmail || practice.contact_email || '').trim();
  const contactPhone = String(cc.phone || cc.contactPhone || practice.contact_phone || '').trim();

  const contractUrl = opts.contractAvailable
    ? buildPreparedDocumentDownloadUrl(normalizeDocumentCountry(opts.documentCountry) || 'uk', 'offer_contract')
    : '';

  // The hired GP's own clinic website. Same precedence as the match card and
  // the revealed job page: the practice record first, then the role's own URL —
  // which is the only per-clinic value when the practice row is a corporate
  // group. Empty stays empty; career.html hides the link rather than inventing
  // one, the same honesty rule the contact channels follow.
  const practiceWebsite = sanitizeHttpUrl(practice.website) || resolveCareerRoleWebsiteUrl(roleRow);

  const placementResult = {
    practiceName,
    roleTitle,
    location,
    website: practiceWebsite,
    statusLabel: 'Placement confirmed',
    startDateIso,
    contractUrl,
    contractFileName: opts.contractFileName || '',
    quickStats: [
      { label: 'Billing', value: billingLabel.replace(/\s+Billing$/i, '') || billingLabel },
      { label: 'Split', value: splitDisplay },
      thirdQuickStat
    ],
    story: {
      title: (location || practiceName).replace(/,\s*Australia\s*$/i, ''),
      text: (role.summary) || (roleClient && roleClient.summary) || 'Your medical centre placement is now secured.',
      imageUrl: roleClient && roleClient.heroImageUrl ? roleClient.heroImageUrl : '',
      mapQuery: roleClient && roleClient.mapQuery ? roleClient.mapQuery : (location || practiceName)
    },
    lifestyle: opts.lifestyle || null,
    practiceContact: {
      name: contactName,
      initials: buildInitials(contactName),
      role: String(cc.role || '').trim() || 'Medical centre contact',
      meta: (contactEmail || contactPhone) ? 'Reach out directly to the practice' : 'Direct contact details will appear here once confirmed',
      phone: contactPhone,
      email: contactEmail,
      whatsapp: contactPhone
    },
    compensation: {
      range: String(o.compensation_range || '').trim() || 'Pending',
      unit: 'Per Year',
      note: String(o.compensation_note || '').trim() || 'Estimated income',
      facts: [
        { label: 'Billing type', value: billingLabel || 'Pending' },
        { label: 'Billing split', value: splitDisplay || 'Pending' },
        ...(relocationDisplay ? [{ label: 'Relocation package', value: relocationDisplay }] : []),
        { label: 'Sessions per week', value: sessionsDisplay || 'Pending' },
        { label: 'Start date', value: startDateIso || 'Pending' }
      ]
    }
  };
  return applyGpShareToPlacementPayload(placementResult);
}

// Resolve everything buildInAppPlacementPayload needs from a gp_applications
// row + its offer record: the role, practice, the registration case's saved
// practice contact, contract availability and the GP's document country. Used
// by BOTH the accept endpoint and /api/career/applications so the secured view
// gets the same payload wherever it's read from.
async function resolveInAppPlacementForApplication(appRow, offer, profile, options) {
  const app = appRow && typeof appRow === 'object' ? appRow : {};
  const opts = options && typeof options === 'object' ? options : {};
  let roleRow = opts.roleRow || null;
  if (!roleRow && app.career_role_id) {
    roleRow = isSupabaseDbConfigured()
      ? await getCareerRoleRowById(app.career_role_id)
      : ((dbState.atsJobs || []).find((j) => String(j.id) === String(app.career_role_id)) || null);
  }
  let practiceRow = null;
  const placementPracticeId = (offer && offer.practice_id) || (roleRow && roleRow.practice_id) || null;
  if (placementPracticeId) {
    try { practiceRow = await atsGetPracticeRow(placementPracticeId); } catch (e) { practiceRow = null; }
  }

  let casePracticeContact = null;
  if (app.user_id && isSupabaseDbConfigured()) {
    try {
      const caseRes = await supabaseDbRequest('registration_cases', 'select=practice_contact&user_id=eq.' + encodeURIComponent(app.user_id) + '&limit=1');
      const caseRow = (caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0]) ? caseRes.data[0] : null;
      if (caseRow && caseRow.practice_contact) {
        casePracticeContact = typeof caseRow.practice_contact === 'string' ? JSON.parse(caseRow.practice_contact) : caseRow.practice_contact;
      }
    } catch (e) { casePracticeContact = null; }
  }

  // Contract availability mirrors the my-offer check: the offer recorded a
  // delivered contract, or an offer_contract doc already sits in the GP's docs.
  let contractAvailable = !!(offer && offer.contract_document_key);
  let contractFileName = '';
  if (app.user_id && isSupabaseDbConfigured()) {
    try {
      const contractRow = await getOfferDocumentRow(app.user_id, 'offer_contract');
      const contractStatus = contractRow ? String(contractRow.status || '') : '';
      if (contractRow && (contractStatus === 'approved' || contractStatus === 'uploaded' || contractStatus === 'received')) {
        contractAvailable = true;
        contractFileName = contractRow.file_name || '';
      }
    } catch (e) { /* keep the offer-record answer */ }
  }

  const documentCountry = normalizeDocumentCountry(
    (profile && (profile.registration_country || profile.country)) || (opts.gpCountry || '')
  ) || 'uk';

  const practiceName = (offer && offer.practice_name) || (roleRow && roleRow.practice_name) || (practiceRow && practiceRow.name) || '';
  const location = roleRow ? [roleRow.location_city, roleRow.location_state].filter(Boolean).join(', ') : '';
  let lifestyle = null;
  try {
    lifestyle = await resolvePracticeLifestylePayload({
      applicationId: String(app.id || ''),
      practiceName,
      location,
      roleRow,
      profile: profile || {}
    });
  } catch (e) { lifestyle = null; }

  return buildInAppPlacementPayload(roleRow, offer, practiceRow, casePracticeContact, {
    contractAvailable,
    contractFileName,
    documentCountry,
    lifestyle
  });
}

function mergeCareerApplications(localApplications, liveApplications) {
  const locals = Array.isArray(localApplications) ? localApplications : [];
  const lives = Array.isArray(liveApplications) ? liveApplications : [];
  const liveByZohoId = new Map();
  const liveByRoleId = new Map();

  lives.forEach((record) => {
    const appId = sanitizeZohoText(record.id);
    const roleId = getZohoApplicationJobOpeningId(record);
    if (appId) liveByZohoId.set(appId, record);
    if (roleId && !liveByRoleId.has(roleId)) liveByRoleId.set(roleId, record);
  });

  const consumedLiveIds = new Set();
  const merged = locals.map((localApp) => {
    let liveRecord = null;
    const zohoAppId = String(localApp && localApp.zoho_application_id || '').trim();
    const providerRoleId = String(localApp && localApp.provider_role_id || '').trim();
    if (zohoAppId && liveByZohoId.has(zohoAppId)) {
      liveRecord = liveByZohoId.get(zohoAppId) || null;
    } else if (providerRoleId && liveByRoleId.has(providerRoleId)) {
      liveRecord = liveByRoleId.get(providerRoleId) || null;
    }
    if (liveRecord && sanitizeZohoText(liveRecord.id)) consumedLiveIds.add(sanitizeZohoText(liveRecord.id));
    return { localApp, liveRecord };
  });

  lives.forEach((record) => {
    const liveId = sanitizeZohoText(record.id);
    if (!liveId || consumedLiveIds.has(liveId)) return;
    merged.push({ localApp: null, liveRecord: record });
  });

  return merged.sort((left, right) => {
    const leftDate = Date.parse(
      (left.localApp && left.localApp.applied_at)
      || getZohoField(left.liveRecord, ['Modified_Time', 'Updated_On', 'Created_Time'])
      || ''
    ) || 0;
    const rightDate = Date.parse(
      (right.localApp && right.localApp.applied_at)
      || getZohoField(right.liveRecord, ['Modified_Time', 'Updated_On', 'Created_Time'])
      || ''
    ) || 0;
    return rightDate - leftDate;
  });
}

// The single hottest query in the app — see the cache notes above supabaseDbRequest.
// Layered: request memo → 60 s process cache → in-flight coalescing → database.
async function getSupabaseUserIdByEmail(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return null;

  const scope = getGpRequestScope();
  if (scope && scope.userIdByEmail.has(normalizedEmail)) {
    return scope.userIdByEmail.get(normalizedEmail);
  }

  const cached = _supabaseUserIdCache.get(normalizedEmail);
  if (cached && cached.expiresAt > Date.now()) {
    if (scope) scope.userIdByEmail.set(normalizedEmail, cached.userId);
    return cached.userId;
  }
  if (cached) _supabaseUserIdCache.delete(normalizedEmail);

  let pending = _supabaseUserIdInflight.get(normalizedEmail);
  if (!pending) {
    pending = (async () => {
      const result = await supabaseDbRequest(
        'user_profiles',
        `select=user_id&email=eq.${encodeURIComponent(normalizedEmail)}&limit=1`
      );
      if (!result.ok) return null;
      if (!Array.isArray(result.data) || result.data.length === 0) return null;
      return result.data[0] && typeof result.data[0].user_id === 'string'
        ? result.data[0].user_id
        : null;
    })().finally(() => {
      _supabaseUserIdInflight.delete(normalizedEmail);
    });
    _supabaseUserIdInflight.set(normalizedEmail, pending);
  }

  const userId = await pending;

  // Positive results only — a null here can mean "row not created yet" (signup)
  // or a transient DB failure, and caching either would be wrong.
  if (userId) {
    if (_supabaseUserIdCache.size >= SUPABASE_USER_ID_CACHE_MAX) _supabaseUserIdCache.clear();
    _supabaseUserIdCache.set(normalizedEmail, {
      userId,
      expiresAt: Date.now() + SUPABASE_USER_ID_CACHE_TTL_MS
    });
    if (scope) scope.userIdByEmail.set(normalizedEmail, userId);
  }
  return userId;
}

// user_state DOES change mid-session (state-sync pushes, stage advances), so this
// is memoized for the CURRENT REQUEST ONLY — never across requests. Any write to
// user_state clears the memo via the hook in supabaseDbRequest, so a handler that
// reads, writes, then reads again still sees its own write.
// Callers routinely read the state object, mutate it, and write it back, so every
// caller must get its OWN copy — handing out the memoized object itself would let
// one handler's edits leak into the next read within the same request.
function _cloneUserStateRow(value) {
  if (!value) return value;
  return {
    userId: value.userId,
    state: value.state && typeof value.state === 'object'
      ? JSON.parse(JSON.stringify(value.state))
      : {},
    updatedAt: value.updatedAt
  };
}

async function getSupabaseUserStateByUserId(userId) {
  const key = String(userId || '').trim();
  if (!key) return null;

  const scope = getGpRequestScope();
  if (scope && scope.userStateByUserId.has(key)) {
    return _cloneUserStateRow(scope.userStateByUserId.get(key));
  }

  const result = await supabaseDbRequest(
    'user_state',
    `select=state,updated_at&user_id=eq.${encodeURIComponent(key)}&limit=1`
  );
  if (!result.ok) return null;

  const row = Array.isArray(result.data) && result.data.length > 0 ? result.data[0] : null;
  const value = (!row || typeof row !== 'object')
    ? { userId: key, state: {}, updatedAt: null }
    : {
      userId: key,
      state: row.state && typeof row.state === 'object' ? row.state : {},
      updatedAt: typeof row.updated_at === 'string' ? row.updated_at : null
    };

  if (scope) {
    scope.userStateByUserId.set(key, value);
    return _cloneUserStateRow(value);
  }
  return value;
}

async function getSupabaseUserStateByEmail(email) {
  const userId = await getSupabaseUserIdByEmail(email);
  if (!userId) return null;
  return getSupabaseUserStateByUserId(userId);
}

async function upsertSupabaseUserState(userId, state, updatedAt) {
  if (!userId) return false;

  const result = await supabaseDbRequest(
    'user_state',
    'on_conflict=user_id',
    {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
      body: [{
        user_id: userId,
        state: state && typeof state === 'object' ? state : {},
        updated_at: updatedAt || new Date().toISOString()
      }]
    }
  );
  return result.ok;
}

async function pushVisaNotificationToOwner(caseId, notification) {
  if (!caseId) return;
  try {
    const caseRes = await supabaseDbRequest('visa_applications', `select=user_id&id=eq.${encodeURIComponent(caseId)}&limit=1`);
    if (!caseRes.ok || !Array.isArray(caseRes.data) || caseRes.data.length === 0) return;
    const userId = caseRes.data[0].user_id;
    if (!userId) return;
    const stateRes = await supabaseDbRequest('user_state', `select=state,updated_at&user_id=eq.${encodeURIComponent(userId)}&limit=1`);
    const row = stateRes.ok && Array.isArray(stateRes.data) && stateRes.data.length > 0 ? stateRes.data[0] : null;
    const state = (row && row.state && typeof row.state === 'object') ? { ...row.state } : {};
    const updates = Array.isArray(state.gp_link_updates) ? [...state.gp_link_updates] : [];
    updates.unshift({ type: notification.type || 'info', title: notification.title || 'Visa update', detail: notification.detail || '', ts: Date.now() });
    if (updates.length > 50) updates.length = 50;
    state.gp_link_updates = updates;
    await upsertSupabaseUserState(userId, state, new Date().toISOString());
  } catch (_) { /* non-critical */ }
}

