// 14. Candidate Hired Email — sent to Zoho Recruit candidates when status changes to "Hired"
// This goes to candidates who may NOT have a GP Link account yet, so it uses sendEmail() directly.
/* ───────── Push notifications — standards-based Web Push (RFC 8291/8292, VAPID) ─────────
   Phase 6 J1. Replaces the legacy FCM path (fcm.googleapis.com/fcm/send was shut
   down by Google in 2024). Subscriptions live in public.push_subscriptions —
   one row per browser PushSubscription (endpoint + p256dh + auth), created by
   POST /api/push/subscribe. Push is a NON-CRITICAL channel: sends respect the
   per-GP `push` notification preference (F4), and a push failure must never
   fail the action that triggered it. If VAPID keys are unset, sending is a
   logged no-op (generate keys with `npx web-push generate-vapid-keys`). */

let vapidMissingWarned = false;
let webPushSendImpl = null; // test hook — overrides webPush.sendNotification

function getVapidConfig() {
  const publicKey = String(process.env.VAPID_PUBLIC_KEY || '').trim();
  const privateKey = String(process.env.VAPID_PRIVATE_KEY || '').trim();
  if (!publicKey || !privateKey) return null;
  const subject = String(process.env.VAPID_SUBJECT || '').trim() || 'mailto:hello@mygplink.com.au';
  return { subject, publicKey, privateKey };
}

async function getPushSubscriptionsForUser(userId) {
  if (isSupabaseDbConfigured()) {
    const r = await supabaseDbRequest('push_subscriptions',
      `select=endpoint,p256dh,auth,email&user_id=eq.${encodeURIComponent(userId)}&limit=10`);
    return r.ok && Array.isArray(r.data) ? r.data : [];
  }
  const list = Array.isArray(dbState.pushSubscriptions) ? dbState.pushSubscriptions : [];
  return list.filter((s) => s && s.user_id === userId);
}

async function deletePushSubscriptionByEndpoint(endpoint, userId) {
  if (!endpoint) return;
  if (isSupabaseDbConfigured()) {
    let query = 'endpoint=eq.' + encodeURIComponent(endpoint);
    if (userId) query += '&user_id=eq.' + encodeURIComponent(userId);
    await supabaseDbRequest('push_subscriptions', query, { method: 'DELETE' });
    return;
  }
  const list = Array.isArray(dbState.pushSubscriptions) ? dbState.pushSubscriptions : [];
  dbState.pushSubscriptions = list.filter((s) => !(s && s.endpoint === endpoint && (!userId || s.user_id === userId)));
  saveDbState();
}

async function sendPushNotification(userId, { title, body, data, url } = {}) {
  try {
    if (!userId) return;
    const vapid = getVapidConfig();
    if (!vapid) {
      if (!vapidMissingWarned) {
        console.log('[web-push] VAPID keys not set (VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY) — push notifications are disabled.');
        vapidMissingWarned = true;
      }
      return;
    }

    const subscriptions = await getPushSubscriptionsForUser(userId);
    if (!subscriptions.length) return;

    // Non-critical channel: skip entirely when the GP has opted out of push.
    const prefEmail = (subscriptions.find((s) => s && s.email) || {}).email || '';
    if (prefEmail && !(await allowsNonCriticalNotification(prefEmail, 'push'))) return;

    const payload = JSON.stringify({
      title: title || 'GP Link',
      body: body || '',
      url: url || (data && data.url) || '/pages/index.html',
      data: data || {}
    });

    for (const sub of subscriptions) {
      if (!sub || !sub.endpoint || !sub.p256dh || !sub.auth) continue;
      try {
        const subscription = { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } };
        const sendFn = webPushSendImpl || webPush.sendNotification.bind(webPush);
        await sendFn(subscription, payload, { vapidDetails: vapid, TTL: 24 * 60 * 60 });
      } catch (err) {
        const status = err && (err.statusCode || err.status);
        if (status === 404 || status === 410) {
          // The push service says this subscription is gone — clean it up.
          await deletePushSubscriptionByEndpoint(sub.endpoint).catch(() => {});
        }
      }
    }
  } catch {}
}

// Render plain text (an RSO's rejection reason, a templated notification body) as email
// HTML that keeps the formatting the writer typed: a blank line starts a new paragraph, a
// single newline becomes a line break, lines starting with "-", "*" or "•" become dot
// points, and **text** renders bold. The text is HTML-escaped first, so nothing an admin
// types can inject markup into the email.
function formatPlainTextEmailHtml(text) {
  // Escape & only when it isn't already an entity (&lt; &amp; &#39; …) — some callers
  // pass bodies whose interpolated values are esc()'d upstream, and re-escaping those
  // would render literal "&lt;" text in the email.
  var escaped = String(text == null ? '' : text)
    .replace(/&(?!#\d{1,7};|#x[0-9a-fA-F]{1,6};|[a-zA-Z][a-zA-Z0-9]{1,31};)/g, '&amp;')
    .replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  var blocks = escaped.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').split(/\n{2,}/);
  var html = blocks.map(function (block) {
    var out = [], para = [], list = [];
    var flushPara = function () { if (para.length) { out.push('<p style="margin:0 0 12px">' + para.join('<br>') + '</p>'); para = []; } };
    var flushList = function () { if (list.length) { out.push('<ul style="margin:0 0 12px;padding-left:22px">' + list.map(function (li) { return '<li style="margin:0 0 4px">' + li + '</li>'; }).join('') + '</ul>'); list = []; } };
    block.split('\n').forEach(function (line) {
      var bullet = line.match(/^\s*(?:[-*•])\s+(.*)$/);
      if (bullet) { flushPara(); list.push(bullet[1]); }
      else if (line.trim()) { flushList(); para.push(line); }
    });
    flushPara(); flushList();
    return out.join('');
  }).join('');
  return '<div style="font-size:15px;color:#334155;line-height:1.6;margin:0 0 24px">' + html + '</div>';
}

function buildCareerEmailHtml({ title, body, bodyHtml, ctaText, ctaUrl, secondaryCtaText, secondaryCtaUrl, signatureHtml, footer }) {
  // Plain-text bodies (no HTML tags) get their typed formatting converted — newlines,
  // dot points, **bold** — instead of collapsing into one wall-of-text paragraph.
  // Bodies that already contain HTML keep the legacy single-<p> wrap untouched.
  var bodyBlock = bodyHtml
    ? bodyHtml
    : (/<[a-z][^>]*>/i.test(String(body || ''))
      ? '<p style="font-size:15px;color:#334155;line-height:1.6;margin:0 0 24px">' + (body || '') + '</p>'
      : formatPlainTextEmailHtml(body));
  var ctaHtml = '';
  if (ctaText && ctaUrl) {
    ctaHtml += '<div style="text-align:center;margin:24px 0">';
    ctaHtml += '<a href="' + ctaUrl + '" style="display:inline-block;padding:14px 32px;background:#2563eb;color:#fff;font-weight:700;font-size:15px;text-decoration:none;border-radius:12px">' + ctaText + '</a>';
    if (secondaryCtaText && secondaryCtaUrl) {
      ctaHtml += '<br><a href="' + secondaryCtaUrl + '" style="display:inline-block;margin-top:12px;padding:12px 28px;background:#fff;color:#2563eb;font-weight:600;font-size:14px;text-decoration:none;border-radius:12px;border:2px solid #2563eb">' + secondaryCtaText + '</a>';
    }
    ctaHtml += '</div>';
  }
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f0f4fa;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif">
<div style="max-width:560px;margin:0 auto;padding:32px 16px">
<div style="background:#fff;border-radius:16px;padding:32px;box-shadow:0 4px 16px rgba(2,6,23,0.08)">
<div style="text-align:center;margin-bottom:24px">
<span style="font-size:22px;font-weight:800;color:#0f172a">GP Link</span>
</div>
${title ? '<h1 style="font-size:20px;font-weight:700;color:#0f172a;margin:0 0 12px">' + title + '</h1>' : ''}
${bodyBlock}
${ctaHtml}
${signatureHtml || ''}
${footer ? '<p style="font-size:13px;color:#64748b;margin:24px 0 0;border-top:1px solid #e2e8f0;padding-top:16px">' + footer + '</p>' : ''}
</div>
<p style="text-align:center;font-size:12px;color:#94a3b8;margin:16px 0 0">GP Link Australia &middot; <a href="${APP_BASE_URL}" style="color:#64748b">app.mygplink.com.au</a></p>
</div></body></html>`;
}

// A practice-facing recommendation must NEVER be an AI refusal or meta-comment.
// Those only appear when the model balks — most often because the name printed
// on the CV differs from the GP's account name (a name change, marriage, or a
// different professional name). We detect that shape and drop it so the email
// omits the block, exactly as it does on any other AI failure, rather than
// showing a practice "I'm sorry, the CV is for someone else".
function looksLikeAiRefusal(text) {
  var t = String(text || '').toLowerCase();
  return /\bi(?:['’]| a)?m sorry\b/.test(t)
    || /\bi apologi[sz]e\b/.test(t)
    || /\bi (?:cannot|can ?not|can['’]t|am unable to|am not able to|won['’]t be able to)\b/.test(t)
    || /\bas an ai\b/.test(t)
    || /\bthe cv (?:provided|above|attached|supplied) (?:is|belongs|appears)\b/.test(t)
    || /\bno (?:cv|information|details?) (?:is |are |was )?(?:available|provided|supplied)\b/.test(t)
    || /\bcannot (?:invent|attribute|write a summary|create a summary|provide a summary)\b/.test(t);
}

// 3-sentence, highly-recommending summary of the GP's experience, written by
// AI from the verified careers CV. Returns '' on ANY failure — the email
// simply omits the recommendation block (submit-to-practice must never be
// blocked on this being available). The name PRINTED on the CV is deliberately
// ignored (GPs change names); the candidate is always referred to by their GP
// Link account name.
async function generateCandidateRecommendation({ buffer, mimeType, fileName, gpName }) {
  try {
    if (!process.env.ANTHROPIC_API_KEY || !(await checkAnthropicBudget())) return '';
    var mime = String(mimeType || '').toLowerCase();
    var blocks = [];
    if (mime === 'application/pdf') blocks.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buffer.toString('base64') } });
    else if (/^image\//.test(mime)) blocks.push({ type: 'image', source: { type: 'base64', media_type: mime === 'image/jpg' ? 'image/jpeg' : mime, data: buffer.toString('base64') } });
    else if (mime.includes('wordprocessingml')) {
      var text = await extractDocxTextWithMammoth(buffer);
      if (!text) return '';
      blocks.push({ type: 'text', text: 'CV TEXT:\n\n' + text.slice(0, 30000) });
    } else return '';
    var recName = String(gpName || '').trim();
    blocks.push({ type: 'text', text: 'You are writing on behalf of GP Link, a medical recruitment agency, to a practice manager. This CV belongs to a doctor whose GP Link account name is Dr ' + recName + '. IMPORTANT: the name printed on the CV itself may be different from "' + recName + '" — doctors often change their name (marriage, a new professional name, and so on). This is completely normal and expected. You MUST treat the CV as Dr ' + recName + '\'s own record, and you MUST NOT mention, question, compare, or flag any difference between the name on the CV and Dr ' + recName + '. Never refuse. Based ONLY on the CV above, write EXACTLY three sentences summarising Dr ' + recName + '\'s experience and strengths, framed as a strong recommendation and referring to the doctor throughout as Dr ' + recName + '. Mention years of experience and standout clinical/leadership strengths if the CV shows them. Do not invent facts other than the name (always use Dr ' + recName + '). Plain professional English, no bullet points, no preamble — respond with the three sentences only.' });
    var resp = await fetch(ANTHROPIC_MESSAGES_URL, {
      method: 'POST',
      headers: { 'x-api-key': process.env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: 400, messages: [{ role: 'user', content: blocks }] })
    });
    if (!resp.ok) return '';
    var json = await resp.json();
    if (json && json.usage) recordAnthropicSpend(json.usage.input_tokens, json.usage.output_tokens, json.usage.cache_read_input_tokens, json.usage.cache_creation_input_tokens);
    var out = (json && json.content && json.content[0] && json.content[0].text || '').trim();
    // Belt-and-braces: even with the prompt above, never let a stray refusal or
    // meta-comment reach a practice — drop it so the email omits the block.
    if (looksLikeAiRefusal(out)) return '';
    return out.length > 20 && out.length < 1200 ? out : '';
  } catch (err) {
    console.warn('[submit-to-practice] recommendation generation failed (email sends without it):', err && err.message);
    return '';
  }
}

// Body of the submit-to-practice introduction email (wrapped by
// buildCareerEmailHtml). Email-safe inline styles; structure follows the
// approved mockup (docs/mockups/career-cv-gate-practice-email.html, Section 2):
// greeting -> "About Dr X" card (intro paragraph + fact chips) -> optional AI
// recommendation -> attachment line -> big green Approve button + small
// "Turn down" link -> footer note. `hasCv`/`hasCoverLetter` describe what was
// ACTUALLY attached (not just requested) so the copy never claims an
// attachment that isn't really there.
function buildCandidateSubmissionEmailHtml({ gpName, roleTitle, practiceName, intro, recommendation, approveUrl, turnDownUrl, hasCv, hasCoverLetter }) {
  // No shared escapeHtml export exists in this file (every email builder
  // defines its own inline one-liner — see e.g. the escHtml consts near
  // sendEmailConfirmationViaResend/the site-enquiry admin email); follow that
  // same established convention here rather than adding a new shared helper.
  var esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  var safeIntro = intro || {};
  var displayName = /^dr\b/i.test(String(gpName || '')) ? gpName : 'Dr ' + gpName;
  var factsHtml = (safeIntro.facts || []).map(function (f) {
    return '<span style="display:inline-block;background:#ffffff;border:1px solid #d6e2fb;color:#173da6;font-size:12.5px;font-weight:600;padding:6px 12px;border-radius:999px;margin:4px 6px 0 0">' + esc(f.icon + ' ' + f.label) + '</span>';
  }).join('');
  var recHtml = recommendation ? (
    '<div style="border-left:4px solid #2563eb;background:#eff4ff;border-radius:0 16px 16px 0;padding:16px 20px;margin:20px 0">' +
    '<div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#173da6;margin-bottom:8px">⭐ Why we recommend ' + esc(displayName) + '</div>' +
    '<p style="font-size:14.5px;color:#22376b;font-style:italic;margin:0">&ldquo;' + esc(recommendation) + '&rdquo;</p></div>'
  ) : '';
  // Attach-line copy must match reality: only claim an attachment that was
  // actually fetched (hasCv/hasCoverLetter), never assume the request means
  // the download succeeded — same "graceful, honest fallback" rule the old
  // in-app branch followed.
  var attachLine = hasCv
    ? (hasCoverLetter ? 'Their CV and cover letter are attached.' : 'Their CV is attached.')
    : (hasCoverLetter ? 'Their cover letter is attached — we’ll follow up with their CV shortly.' : 'We’ll follow up with their CV shortly.');
  // "Dear <practice> team," per the approved mockup; when we have no practice
  // name, fall back to a plain "Dear team," (never "Dear team team,").
  var greeting = practiceName ? ('Dear ' + esc(practiceName) + ' team,') : 'Dear team,';
  return (
    '<p style="font-size:14.5px;color:#1f2b43;margin:0 0 14px">' + greeting + '</p>' +
    '<p style="font-size:14.5px;color:#1f2b43;margin:0 0 14px">We&rsquo;re delighted to introduce <b>' + esc(displayName) + '</b> for your <b>' + esc(roleTitle || 'GP') + '</b> position.</p>' +
    '<div style="border:1px solid #e3e9f4;border-radius:16px;padding:18px 20px;margin:18px 0;background:#f8fafd">' +
    '<div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#173da6;margin-bottom:8px">About ' + esc(displayName) + '</div>' +
    '<p style="font-size:14.5px;color:#1f2b43;margin:0">' + esc(safeIntro.paragraph) + '</p>' +
    '<div style="margin-top:10px">' + factsHtml + '</div></div>' +
    recHtml +
    '<p style="font-size:13px;color:#64748b;margin:16px 0 4px">' + attachLine + '</p>' +
    '<div style="text-align:center;margin:28px 0 6px">' +
    '<a href="' + approveUrl + '" style="display:inline-block;padding:15px 44px;background:#16a34a;color:#ffffff;font-weight:700;font-size:16px;text-decoration:none;border-radius:14px">Approve ' + esc(displayName) + '<br><span style="font-size:11.5px;font-weight:500;opacity:.9">and choose interview times</span></a><br>' +
    '<a href="' + turnDownUrl + '" style="display:inline-block;margin-top:12px;font-size:12px;color:#a5b0c2;text-decoration:underline">Turn down this candidate</a></div>' +
    '<p style="font-size:12px;color:#64748b;text-align:center;margin:16px 0 0;border-top:1px solid #e3e9f4;padding-top:14px">Approving opens a page where you pick interview times that suit you &mdash; ' + esc(displayName) + ' then confirms one. Questions? Just reply to this email.</p>'
  );
}

