// Registration rail used by the candidate profile + the intent "registration
// progress" signal. Ordered to match ceoMetrics.DB_STAGE_ORDER.
var ATS_REG_RAIL = [
  { key: 'myintealth', label: 'MyIntealth' },
  { key: 'amc', label: 'AMC' },
  { key: 'career', label: 'Secure Placement' },
  { key: 'ahpra', label: 'AHPRA' },
  { key: 'pbs', label: 'PBS & Medicare' },
  { key: 'commencement', label: 'Commencement' }
];
var ATS_REG_STAGE_MAX = 6; // 'complete' = fully done (DB_STAGE_ORDER.complete)

function atsNowIso() { return new Date().toISOString(); }
function atsLocalId(prefix) {
  return (prefix || '') + Date.now().toString(36) + Math.random().toString(36).slice(2, 9);
}
function atsRegStageIndex(stage) {
  var key = String(stage || '').trim().toLowerCase();
  if (ceoMetrics.DB_STAGE_ORDER && ceoMetrics.DB_STAGE_ORDER[key] !== undefined) {
    return ceoMetrics.DB_STAGE_ORDER[key];
  }
  // Allow a display label (e.g. 'Secure Placement') from local seed rows.
  for (var i = 0; i < ATS_REG_RAIL.length; i++) {
    if (ATS_REG_RAIL[i].label.toLowerCase() === key) return ceoMetrics.DB_STAGE_ORDER[ATS_REG_RAIL[i].key];
  }
  return 0;
}
function atsRailLabel(stage) {
  var key = String(stage || '').trim().toLowerCase();
  for (var i = 0; i < ATS_REG_RAIL.length; i++) {
    if (ATS_REG_RAIL[i].key === key || ATS_REG_RAIL[i].label.toLowerCase() === key) return ATS_REG_RAIL[i].label;
  }
  if (key === 'complete') return 'Complete';
  if (key === 'visa') return 'Visa';
  return stage ? String(stage) : '—';
}

// ---- Practices -------------------------------------------------------------
async function atsListPracticeRows() {
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practices', 'select=*&order=name.asc&limit=1000');
    return (r.ok && Array.isArray(r.data)) ? r.data : [];
  }
  return (dbState.atsPractices || []).slice();
}
async function atsGetPracticeRow(id) {
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practices', 'select=*&id=eq.' + encodeURIComponent(id) + '&limit=1');
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  return (dbState.atsPractices || []).find(function (p) { return String(p.id) === String(id); }) || null;
}

// Task 6 (2026-07-11 matching-board): resolves a practice row's street
// address the SAME way /api/career/role does for revealedMapQuery (address
// column, falling back to a legacy intake-only metadata.intake.address).
function resolveCareerPracticeAddress(practiceRow) {
  if (!practiceRow) return '';
  if (practiceRow.address) return String(practiceRow.address);
  if (practiceRow.metadata && practiceRow.metadata.intake && practiceRow.metadata.intake.address) {
    return String(practiceRow.metadata.intake.address);
  }
  return '';
}

// Builds the Google-Maps query string the GP match card's map embed + "Open
// in Maps" link use. Same [address, city, state] shape /api/career/role
// exposes as revealedMapQuery when a street address is on file; falls back to
// the practice name + city/state so the map/link is never blank for a
// practice whose intake hasn't captured an address yet.
function buildCareerMatchMapQuery(practiceAddress, practiceName, city, state) {
  const address = String(practiceAddress || '').trim();
  const parts = address ? [address, city, state] : [practiceName, city, state];
  return parts.filter(Boolean).join(', ');
}
async function atsInsertPracticeRow(row) {
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practices', '', { method: 'POST', headers: { Prefer: 'return=representation' }, body: [row] });
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  var local = Object.assign({ id: atsLocalId('prac_'), created_at: atsNowIso() }, row, { updated_at: atsNowIso() });
  dbState.atsPractices = dbState.atsPractices || [];
  dbState.atsPractices.push(local); saveDbState();
  return local;
}
async function atsUpdatePracticeRow(id, patch) {
  patch.updated_at = atsNowIso();
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practices', 'id=eq.' + encodeURIComponent(id), { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: patch });
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  var p = (dbState.atsPractices || []).find(function (x) { return String(x.id) === String(id); });
  if (!p) return null;
  Object.assign(p, patch); saveDbState(); return p;
}

// Normalizes a practice name for duplicate matching: case, surrounding
// whitespace and internal runs of spaces/punctuation are all noise when
// deciding "have we already got these people?".
function normalizePracticeNameForMatch(name) {
  return String(name == null ? '' : name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/**
 * Duplicate suppression for the website practice flow.
 *
 * A practice already in the system must not create a second prospect row or
 * be sent a second intake email. Matches on contact email first, then on a
 * normalized practice name — one practice submitting the form twice is far
 * more likely than two unrelated clinics sharing an exact name.
 *
 * Names are compared in JS rather than in the query because a practice name
 * can contain commas and parentheses, which are PostgREST filter syntax.
 */
async function findExistingPracticeForLead(email, name) {
  var cleanEmail = String(email || '').trim().toLowerCase();
  var cleanName = normalizePracticeNameForMatch(name);
  var blocks = practicePipeline.practiceBlocksNewLead;

  // Archived/declined rows are history, not clients — they must never
  // suppress a fresh lead. Several candidates are fetched rather than one,
  // so a dead row can't hide a live one behind `limit=1`.
  function pickLive(rows, predicate) {
    return (Array.isArray(rows) ? rows : []).find(function (p) {
      return p && blocks(p) && predicate(p);
    }) || null;
  }

  if (isSupabaseDbConfigured()) {
    if (cleanEmail) {
      var byEmail = await supabaseDbRequest(
        'practices',
        'select=id,name,stage,contact_email,agreement_status,intake_token,metadata&contact_email=ilike.'
          + encodeURIComponent(cleanEmail) + '&limit=20'
      );
      if (byEmail.ok) {
        var emailHit = pickLive(byEmail.data, function () { return true; });
        if (emailHit) return { practice: emailHit, matchedBy: 'email' };
      }
    }
    if (cleanName) {
      var all = await supabaseDbRequest(
        'practices',
        'select=id,name,stage,contact_email,agreement_status,intake_token,metadata&limit=2000'
      );
      if (all.ok) {
        var nameHit = pickLive(all.data, function (p) {
          return normalizePracticeNameForMatch(p.name) === cleanName;
        });
        if (nameHit) return { practice: nameHit, matchedBy: 'name' };
      }
    }
    return null;
  }

  var localRows = dbState.atsPractices || [];
  var localEmail = cleanEmail && pickLive(localRows, function (p) {
    return String(p.contact_email || '').trim().toLowerCase() === cleanEmail;
  });
  if (localEmail) return { practice: localEmail, matchedBy: 'email' };

  var localName = cleanName && pickLive(localRows, function (p) {
    return normalizePracticeNameForMatch(p.name) === cleanName;
  });
  if (localName) return { practice: localName, matchedBy: 'name' };

  return null;
}

/**
 * Optional Cloudflare Turnstile verification.
 *
 * Deliberately inert until TURNSTILE_SECRET_KEY is configured, so the captcha
 * can be switched on later purely through environment variables with no code
 * change. When it IS configured, a missing or rejected token fails closed.
 */
async function verifyTurnstileToken(token, ip) {
  var secret = String(process.env.TURNSTILE_SECRET_KEY || '').trim();
  if (!secret) return { ok: true, skipped: true };
  if (!token) return { ok: false, reason: 'missing_token' };
  try {
    var params = new URLSearchParams();
    params.set('secret', secret);
    params.set('response', String(token));
    if (ip) params.set('remoteip', String(ip));
    var r = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString()
    });
    var json = await r.json().catch(function () { return null; });
    if (json && json.success === true) return { ok: true };
    return { ok: false, reason: 'rejected' };
  } catch (e) {
    // A Cloudflare outage must not silently disable the captcha we were
    // explicitly asked to enforce.
    console.error('[turnstile] verification error:', e && e.message);
    return { ok: false, reason: 'verify_error' };
  }
}

// ---- Practice groups (Task 7: corporate-group intake) ---------------------
// A corporate group can sign once for several clinics. One `practice_groups`
// row anchors the shared entity/ABN/agreement; every practices row (one per
// clinic) points at it via group_id. A lone practice is a "group of one" —
// same shape, so callers never need an is-this-a-group branch. Dual-mode,
// mirrors atsInsertPracticeRow/atsUpdatePracticeRow exactly.
async function findPracticeGroupByToken(token) {
  if (!token) return null;
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practice_groups', 'select=*&intake_token=eq.' + encodeURIComponent(token) + '&limit=1');
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  return (dbState.practiceGroups || []).find(function (g) { return g.intake_token === token; }) || null;
}
async function insertPracticeGroupRow(row) {
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practice_groups', '', { method: 'POST', headers: { Prefer: 'return=representation' }, body: [row] });
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  var local = Object.assign({ id: atsLocalId('pgrp_'), created_at: atsNowIso() }, row, { updated_at: atsNowIso() });
  dbState.practiceGroups = dbState.practiceGroups || [];
  dbState.practiceGroups.push(local); saveDbState();
  return local;
}
async function updatePracticeGroupRow(id, patch) {
  patch.updated_at = atsNowIso();
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practice_groups', 'id=eq.' + encodeURIComponent(id), { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: patch });
    return (r.ok && Array.isArray(r.data) && r.data[0]) ? r.data[0] : null;
  }
  var g = (dbState.practiceGroups || []).find(function (x) { return String(x.id) === String(id); });
  if (!g) return null;
  Object.assign(g, patch); saveDbState(); return g;
}
async function listPracticesByGroupId(groupId) {
  if (!groupId) return [];
  if (isSupabaseDbConfigured()) {
    var r = await supabaseDbRequest('practices', 'select=*&group_id=eq.' + encodeURIComponent(groupId));
    return (r.ok && Array.isArray(r.data)) ? r.data : [];
  }
  return (dbState.atsPractices || []).filter(function (p) { return p.group_id && String(p.group_id) === String(groupId); });
}

// Resolve a practices-table row id for a free-text practice name
// (case-insensitive match, same lower(name) key as the unique index).
// Creates the row when it doesn't exist yet — source 'backfill', which the
// practices CHECK constraint allows — so gp_applications can carry a
// first-class practice_id link. Returns the row id or null. Dual-mode.
async function atsEnsurePracticeIdByName(name, extras) {
  var trimmed = String(name || '').trim();
  if (!trimmed) return null;
  var key = trimmed.toLowerCase();
  var rows = await atsListPracticeRows();
  var match = rows.find(function (p) { return String(p.name || '').trim().toLowerCase() === key; });
  if (match && match.id) return match.id;
  var created = await atsInsertPracticeRow(Object.assign({ name: trimmed, source: 'backfill' }, extras || {}));
  if (created && created.id) return created.id;
  // The insert can lose a race against the lower(name) unique index — re-read.
  rows = await atsListPracticeRows();
  match = rows.find(function (p) { return String(p.name || '').trim().toLowerCase() === key; });
  return (match && match.id) ? match.id : null;
}

// Practice id for a career_roles row: the explicit practice_id when set
// (CEO-created ATS jobs), else ensure/lookup by practice_name (Zoho + manual
// roles, whose practice only exists as denormalised text).
async function atsResolvePracticeIdForRole(roleRow) {
  if (!roleRow) return null;
  if (roleRow.practice_id) return roleRow.practice_id;
  return atsEnsurePracticeIdByName(roleRow.practice_name, {
    location_city: roleRow.location_city || '',
    location_state: roleRow.location_state || '',
    location_country: roleRow.location_country || 'Australia',
    created_by: 'system:career_apply'
  });
}

// gp_applications.practice_id ships in migration 20260702090000, which may not
// be applied yet. Detect the missing column ONCE per process and stop sending
// it, so the apply path never pays for a second failing insert.
var _gpApplicationsPracticeIdMissing = false;
// gp_applications.origin ships alongside the practice-client-pipeline work and
// may not be applied yet either — same detect-once-and-stop-sending pattern.
var _gpApplicationsOriginMissing = false;
// gp_applications.revealed (Task 12, same migration 20260705100000) — same
// detect-once guard, shared across atsInsertApplicationRow and any PATCH path
// that also tries to set it.
var _gpApplicationsRevealedMissing = false;
function isMissingColumnInsertError(result, column) {
  var d = result ? result.data : null;
  if (!d) return false;
  var code = (typeof d === 'object') ? String(d.code || '') : '';
  var msg = (typeof d === 'string') ? d : String(d.message || '');
  if (msg.indexOf(column) === -1) return false;
  // Postgres 42703 = undefined column; PGRST204 = column missing from schema cache.
  return code === '42703' || code === 'PGRST204' || /column/i.test(msg);
}

// A practice is identified either by a real practices-table row id, or — when it
// only exists as a denormalised name on jobs (like the Medical Centres view) — by
// a synthetic "name:<encoded>" id.
function atsPracticeNameId(name) { return 'name:' + encodeURIComponent(String(name || '').trim()); }
function atsParsePracticeId(id) {
  var s = String(id || '');
  if (s.indexOf('name:') === 0) return { name: decodeURIComponent(s.slice(5)) };
  return { rowId: s };
}
function atsIsRejectedApp(a) {
  var st = String((a && a.ats_stage) || '');
  var stat = String((a && a.status) || '').toLowerCase();
  return st === 'not_proceeding' || stat.indexOf('reject') !== -1 || stat.indexOf('withdraw') !== -1;
}
// "Waiting on practice" needs BOTH halves to be true: the practice hasn't
// accepted or declined yet, AND the candidate is still actually in the running
// for that opening. Only the first half was ever checked, and because NOTHING
// clears practice_submission_status when a candidate drops out, terminal rows
// never left the tracker — they just kept ageing.
//
// Seen live 2026-07-31 on the two rows the tile was counting: a doctor who
// withdrew the day after being submitted still read "11 days waiting", and a
// doctor whose opening had been filled by someone else read "24 days waiting"
// against a role that had already been detached from his application (which is
// why that row rendered with no practice name and no location).
//
// The day-3/5/7 reminder cron was never fooled — it selects
// ats_stage=in.(submitted,reviewing), i.e. it already had the liveness check
// this predicate is restoring — so no practice was ever chased about a
// withdrawn candidate. The damage was confined to the CEO's own view: phantom
// work in the queue and a day-7 "chase personally" banner crying wolf.
function atsApplicationAwaitsPracticeDecision(a) {
  if (!a) return false;
  if (normalizeCareerPracticeSubmissionStatus(a.practice_submission_status) !== 'submitted_to_practice') return false;
  if (a.practice_decision) return false;
  // Withdrawal stamps status='withdrawn' + withdrawn_at and drops the kanban
  // card to 'not_proceeding'; the on-hire fan-out stamps
  // match_outcome='position_filled'. Each is checked on its own rather than
  // trusting one to imply the others — they are written by different handlers.
  if (a.withdrawn_at) return false;
  if (a.match_outcome === 'position_filled') return false;
  var st = String(a.ats_stage || '');
  if (st === 'not_proceeding' || st === 'hired') return false;
  var stat = normalizeCareerApplicationStatusKey(a.status);
  if (stat === 'withdrawn' || stat === 'not_proceeding' || stat === 'rejected') return false;
  if (isCareerPlacementSecuredStatus(stat)) return false;
  return true;
}
// Contact/location from a career_roles row's Zoho source_payload (mirrors the Medical Centres view).
function atsPracticeContactFromJob(job) {
  var sp = (job && job.source_payload && typeof job.source_payload === 'object') ? job.source_payload : {};
  var z = (sp.zoho && typeof sp.zoho === 'object') ? sp.zoho : {};
  var name = '', email = '', phone = '';
  try { name = sanitizeZohoText(z.Contact_Name || z.contact_name || '') || buildZohoDisplayName(z) || ''; } catch (e) {}
  try { email = getZohoField(z, ['Email', 'Contact_Email', 'Secondary_Email', 'Account_Email']) || ''; } catch (e) {}
  try { phone = choosePreferredZohoPhone(z) || getZohoField(z, ['Contact_Phone', 'Account_Phone']) || ''; } catch (e) {}
  return { contact_name: name, contact_email: email, contact_phone: phone };
}
// Build the practice directory by grouping jobs (career_roles) on practice_name and
// merging in any practices-table rows. Each practice carries its matching .jobs[].
// This makes the Practices tab populated from existing job data even before any
// practices-table rows are backfilled (it is the same source as Medical Centres).
async function atsListPracticesDerived() {
  var jobs = await atsListJobRows();
  // atsListJobRows() returns is_active=true rows only, so a freshly-signed
  // practice's intake job (is_active:false, approval_status:'pending') would
  // never appear on its own practice card/detail — the exact page the "new
  // signed practice" notify email deep-links to, which then showed "No jobs
  // yet". Merge pending jobs in here (deduped by id), same as /api/ats/jobs.
  var pendingJobs = [];
  if (isSupabaseDbConfigured()) {
    var pendingR = await supabaseDbRequest('career_roles', 'select=*&approval_status=eq.pending&order=updated_at.desc&limit=1000');
    if (pendingR.ok && Array.isArray(pendingR.data)) pendingJobs = pendingR.data;
  } else {
    pendingJobs = (dbState.atsJobs || []).filter(function (j) { return j.approval_status === 'pending'; });
  }
  var seenJobIds = {}; jobs.forEach(function (j) { seenJobIds[String(j.id)] = true; });
  pendingJobs.forEach(function (j) { if (!seenJobIds[String(j.id)]) { seenJobIds[String(j.id)] = true; jobs.push(j); } });
  var stored = await atsListPracticeRows();
  var byKey = {};
  jobs.forEach(function (j) {
    var name = String(j.practice_name || '').trim();
    if (!name) return;
    var k = name.toLowerCase();
    if (!byKey[k]) {
      var ct = atsPracticeContactFromJob(j);
      byKey[k] = {
        id: atsPracticeNameId(name), name: name,
        location_city: j.location_city || '', location_state: j.location_state || '',
        location_country: j.location_country || 'Australia',
        practice_type: j.practice_type || j.billing_model || '',
        contact_name: ct.contact_name, contact_email: ct.contact_email, contact_phone: ct.contact_phone,
        ahpra_number: '', source: (j.provider === 'internal_ats' ? 'internal_ats' : 'zoho_sync'), jobs: [],
        // Derived (name-only) practices have no practices-table row at all, so
        // they cannot be "prospective" (no intake pipeline has ever run for
        // them) — they always report as an existing/mainstream practice.
        stage: 'active', agreement_status: 'unsigned', website: '', dpa: null,
        suburb: '', nearest_city: '', intro_text: '', intro_video_url: '',
        agreement_signed_pdf_key: '', intake_token: '', metadata: {},
        // Phase 3: name-only practices have no row, so no org_type column and
        // no manually uploaded contract — always plain 'practice' defaults.
        // (Same for the Phase 6 parent-corporation link: link-less.)
        org_type: 'practice', parent_corporation_id: null,
        agreement_manual_pdf_key: '', agreement_manual_uploaded_at: '', agreement_manual_uploaded_by: ''
      };
    }
    var e = byKey[k];
    e.jobs.push(j);
    if (!e.location_city && j.location_city) e.location_city = j.location_city;
    if (!e.location_state && j.location_state) e.location_state = j.location_state;
    if (!e.practice_type && (j.practice_type || j.billing_model)) e.practice_type = j.practice_type || j.billing_model;
    if (!e.contact_name) { var ct2 = atsPracticeContactFromJob(j); if (ct2.contact_name) { e.contact_name = ct2.contact_name; e.contact_email = e.contact_email || ct2.contact_email; e.contact_phone = e.contact_phone || ct2.contact_phone; } }
  });
  stored.forEach(function (p) {
    var name = String(p.name || '').trim(); if (!name) return;
    var k = name.toLowerCase();
    if (!byKey[k]) byKey[k] = { id: p.id, name: name, location_country: 'Australia', jobs: [] };
    var e = byKey[k];
    e.id = p.id; // a real practices-table row id wins over the synthetic name-id
    e.location_city = p.location_city || e.location_city || '';
    e.location_state = p.location_state || e.location_state || '';
    e.practice_type = p.practice_type || e.practice_type || '';
    e.contact_name = p.contact_name || e.contact_name || '';
    e.contact_email = p.contact_email || e.contact_email || '';
    e.contact_phone = p.contact_phone || e.contact_phone || '';
    e.ahpra_number = p.ahpra_number || e.ahpra_number || '';
    e.source = p.source || e.source || 'internal_ats';
    // A real practices-table row is the source of truth for pipeline/lifecycle
    // fields — overwrite the derived defaults set above (rather than falling
    // back with `||`, since e.g. an empty string dpa/website is a real value).
    e.stage = p.stage || 'active';
    e.agreement_status = p.agreement_status || 'unsigned';
    e.website = p.website || '';
    e.dpa = (typeof p.dpa === 'boolean') ? p.dpa : null;
    e.suburb = p.suburb || '';
    e.nearest_city = p.nearest_city || '';
    e.intro_text = p.intro_text || '';
    e.intro_video_url = p.intro_video_url || '';
    e.agreement_signed_pdf_key = p.agreement_signed_pdf_key || '';
    e.intake_token = p.intake_token || '';
    e.metadata = (p.metadata && typeof p.metadata === 'object') ? p.metadata : {};
    e.org_type = (p.org_type === 'corporation') ? 'corporation' : 'practice';
    e.parent_corporation_id = p.parent_corporation_id || null;
    e.agreement_manual_pdf_key = p.agreement_manual_pdf_key || '';
    e.agreement_manual_uploaded_at = p.agreement_manual_uploaded_at || '';
    e.agreement_manual_uploaded_by = p.agreement_manual_uploaded_by || '';
  });
  return Object.keys(byKey).map(function (k) { return byKey[k]; });
}
// Resolve one practice (by name-id or row-id) with its jobs attached.
async function atsResolvePractice(id) {
  var all = await atsListPracticesDerived();
  var parsed = atsParsePracticeId(id);
  if (parsed.name) {
    var nk = parsed.name.toLowerCase();
    return all.find(function (p) { return String(p.name || '').toLowerCase() === nk; }) || null;
  }
  var byId = all.find(function (p) { return String(p.id) === String(parsed.rowId); });
  if (byId) return byId;
  var row = await atsGetPracticeRow(parsed.rowId);
  if (!row) return null;
  var rk = String(row.name || '').toLowerCase();
  return all.find(function (p) { return String(p.name || '').toLowerCase() === rk; }) || {
    id: row.id, name: row.name, location_city: row.location_city, location_state: row.location_state,
    practice_type: row.practice_type, contact_name: row.contact_name, contact_email: row.contact_email,
    contact_phone: row.contact_phone, ahpra_number: row.ahpra_number, source: row.source, jobs: [],
    stage: row.stage || 'active', agreement_status: row.agreement_status || 'unsigned',
    website: row.website || '', dpa: (typeof row.dpa === 'boolean') ? row.dpa : null,
    suburb: row.suburb || '', nearest_city: row.nearest_city || '',
    intro_text: row.intro_text || '', intro_video_url: row.intro_video_url || '',
    agreement_signed_pdf_key: row.agreement_signed_pdf_key || '', intake_token: row.intake_token || '',
    metadata: (row.metadata && typeof row.metadata === 'object') ? row.metadata : {},
    org_type: (row.org_type === 'corporation') ? 'corporation' : 'practice',
    parent_corporation_id: row.parent_corporation_id || null,
    agreement_manual_pdf_key: row.agreement_manual_pdf_key || '',
    agreement_manual_uploaded_at: row.agreement_manual_uploaded_at || '',
    agreement_manual_uploaded_by: row.agreement_manual_uploaded_by || ''
  };
}

// Phase 6 I2: validate a parent_corporation_id write (POST + PATCH share it).
// Returns { ok:true, value } — value null means "clear the link" — or
// { ok:false, message }. The parent must be a real practices-table row whose
// org_type is 'corporation', and an org can never be its own parent (enforced
// logically here rather than as a DB constraint — see the migration comment).
async function atsValidateParentCorporation(rawValue, selfRowId) {
  var v = (rawValue === undefined || rawValue === null) ? '' : String(rawValue).trim();
  if (!v) return { ok: true, value: null };
  if (selfRowId && String(selfRowId) === v) return { ok: false, message: 'An organisation cannot be its own parent.' };
  var parentRow = await atsGetPracticeRow(v);
  if (!parentRow) return { ok: false, message: 'Parent corporation not found.' };
  if (parentRow.org_type !== 'corporation') return { ok: false, message: 'The selected parent is not a corporation.' };
  return { ok: true, value: parentRow.id };
}

